INSERT OR REPLACE INTO quizzes (id, title, description, duration_minutes, total_marks, pass_percentage, shuffle_questions, shuffle_options, enable_anti_cheat, status, questions, created_at) VALUES ('pyq-2017-mat', 'NMMS 2017 - MAT (மனத்திறன் தேர்வு - Mental Ability Test)', 'Official NMMS 2017 Mental Ability Test (MAT) with 90 official previous year questions.', 90, 90, 40, 0, 0, 1, 'draft', '[{"id":"pyq-2017-mat-q1","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"53, 59, 61, 67, ?","options":[{"id":"A","text":"74"},{"id":"B","text":"69"},{"id":"C","text":"71"},{"id":"D","text":"68"}],"correctOption":"C","explanation":"இவை தொடர்ச்சியான பகா எண்கள் (Prime numbers). 67-க்கு அடுத்த பகா எண் 71.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q2","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"9, 19, 39, 79, 159, ?, 639","options":[{"id":"A","text":"139"},{"id":"B","text":"309"},{"id":"C","text":"259"},{"id":"D","text":"319"}],"correctOption":"D","explanation":"தொடர் அமைப்பு: முந்தைய எண்ணை 2 ஆல் பெருக்கி 1 கூட்டப்பட்டுள்ளது (×2 + 1).\n159 × 2 + 1 = 318 + 1 = 319.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q3","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"12, 15, 36, 45, 108, ?, 324","options":[{"id":"A","text":"100"},{"id":"B","text":"135"},{"id":"C","text":"125"},{"id":"D","text":"110"}],"correctOption":"B","explanation":"இது இரட்டைத் தொடர்.\nமுதல் தொடர்: 12, 36, 108, 324 (×3).\nஇரண்டாம் தொடர்: 15, 45, ? (×3) ⇒ 45 × 3 = 135.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q4","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படத்தில் விடுபட்ட எண்ணைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2017/q4.png","options":[{"id":"A","text":"20"},{"id":"B","text":"24"},{"id":"C","text":"12"},{"id":"D","text":"22"}],"correctOption":"A","explanation":"படத்தில் உள்ள எண்களுக்கு இடையேயான தர்க்க அமைப்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q5","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படத்தில் விடுபட்ட எண்ணைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2017/q5.png","options":[{"id":"A","text":"16"},{"id":"B","text":"22"},{"id":"C","text":"24"},{"id":"D","text":"23"}],"correctOption":"D","explanation":"படங்களை உற்று நோக்கி சரியான தர்க்க அமைப்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q6","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படத்தில் விடுபட்ட எண்ணைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2017/q6.png","options":[{"id":"A","text":"7"},{"id":"B","text":"4"},{"id":"C","text":"8"},{"id":"D","text":"3"}],"correctOption":"B","explanation":"கீழே உள்ள இரு எண்களின் கூடுதலின் கனம் (Cube) மேலே உள்ளது.\n(2+3)³ = 125. (1+3)³ = 64. (2+?)³ = 216 ⇒ 2+4 = 6. எனவே விடை 4.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q7","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படத்தில் விடுபட்ட எண்ணைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2017/q7.png","options":[{"id":"A","text":"63"},{"id":"B","text":"42"},{"id":"C","text":"50"},{"id":"D","text":"100"}],"correctOption":"A","explanation":"படத்தில் உள்ள எண்களின் கணிதத் தொடர்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q8","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட தொடரில் தொடர்பில்லாதவற்றைக் கண்டறியவும்: 41, 43, 47, 51, 53, 59","options":[{"id":"A","text":"47"},{"id":"B","text":"51"},{"id":"C","text":"53"},{"id":"D","text":"59"}],"correctOption":"B","explanation":"51 தவிர மற்ற அனைத்து எண்களும் பகா எண்கள் (Prime numbers). 51 என்பது 3 மற்றும் 17 ஆல் வகுபடும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q9","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட தொடரில் தொடர்பில்லாதவற்றைக் கண்டறியவும்: 19, 37, 73, 145, 217, 285","options":[{"id":"A","text":"19"},{"id":"B","text":"73"},{"id":"C","text":"285"},{"id":"D","text":"145"}],"correctOption":"D","explanation":"கொடுக்கப்பட்ட எண்களின் தர்க்க அமைப்பின்படி மாறுபட்ட எண் 145 ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q10","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட தொடரில் தொடர்பில்லாதவற்றைக் கண்டறியவும்: 1, 4, 27, 16, 25, 36","options":[{"id":"A","text":"27"},{"id":"B","text":"16"},{"id":"C","text":"25"},{"id":"D","text":"36"}],"correctOption":"A","explanation":"1, 4, 16, 25, 36 ஆகியவை வர்க்க எண்கள் (Squares). ஆனால் 27 என்பது கன எண் (Cube).","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q11","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடரின் அடுத்த எண்ணைக் கண்டுபிடிக்கவும்: 7, 13, 17, 13, 13, 27, 13, 13, 13, 37, ?","options":[{"id":"A","text":"23"},{"id":"B","text":"17"},{"id":"C","text":"13"},{"id":"D","text":"11"}],"correctOption":"C","explanation":"தொடரின் எண்கள் 7, 17, 27, 37 என கூடுகிறது. இவற்றுக்கிடையே முறையே ஒன்று, இரண்டு, மூன்று என 13-கள் வருகின்றன. அடுத்தும் 13 தான் வர வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q12","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடரின் அடுத்த எழுத்தைக் கண்டுபிடிக்கவும்: Z, W, T, Q, N, ?, ?","options":[{"id":"A","text":"K, L"},{"id":"B","text":"K, H"},{"id":"C","text":"K, J"},{"id":"D","text":"J, K"}],"correctOption":"B","explanation":"எழுத்துக்கள் 3 இடங்கள் பின்னோக்கி (-3) செல்கின்றன. N-3 = K. K-3 = H. எனவே K, H.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q13","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடரின் அடுத்த உறுப்பைக் கண்டுபிடிக்கவும்: 4A, 7B, 13D, 25G, ?","options":[{"id":"A","text":"37J"},{"id":"B","text":"29K"},{"id":"C","text":"49K"},{"id":"D","text":"27K"}],"correctOption":"C","explanation":"எண்கள்: +3, +6, +12, +24 எனக் கூடுகிறது. 25 + 24 = 49.\nஎழுத்துக்கள்: +1, +2, +3, +4 எனத் தாவுகிறது. G + 4 = K.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q14","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடரின் அடுத்த உறுப்பைக் கண்டுபிடிக்கவும்: BDG, GIL, LNQ, ?","options":[{"id":"A","text":"QTU"},{"id":"B","text":"QTV"},{"id":"C","text":"QVS"},{"id":"D","text":"QSV"}],"correctOption":"D","explanation":"ஒவ்வொரு எழுத்தும் +5 இடங்கள் தள்ளி அமைகிறது. G+5=L, L+5=Q; I+5=N, N+5=S; L+5=Q, Q+5=V. விடை QSV.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q15","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட எழுத்துக்களைக் கண்டுபிடிக்கவும்: aab_aa_bbb_aaa_bbb","options":[{"id":"A","text":"abab"},{"id":"B","text":"baab"},{"id":"C","text":"aaab"},{"id":"D","text":"abba"}],"correctOption":"B","explanation":"தொடர் அமைப்பைக் கொண்டு சரியான விடையைத் தேர்ந்தெடுக்கவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q16","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படத்தில் விடுபட்ட எழுத்தைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2017/q16.png","options":[{"id":"A","text":"65"},{"id":"B","text":"64"},{"id":"C","text":"75"},{"id":"D","text":"74"}],"correctOption":"A","explanation":"படங்களை உற்று நோக்கி சரியான தர்க்க அமைப்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q17","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படத்தில் விடுபட்ட எழுத்தைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2017/q17.png","options":[{"id":"A","text":"Q"},{"id":"B","text":"T"},{"id":"C","text":"R"},{"id":"D","text":"S"}],"correctOption":"D","explanation":"படங்களை உற்று நோக்கி சரியான தர்க்க அமைப்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q18","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Newspaper : Printing Press :: Cloth : ?","options":[{"id":"A","text":"Mill"},{"id":"B","text":"Textile"},{"id":"C","text":"Fibre"},{"id":"D","text":"Yarn"}],"correctOption":"A","explanation":"செய்தித்தாள் அச்சகத்தில் (Printing Press) தயாராவது போல, துணி ஆலையில் (Mill) தயாராகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q19","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Island : Water :: Oasis : ?","options":[{"id":"A","text":"gravel"},{"id":"B","text":"sand"},{"id":"C","text":"clay"},{"id":"D","text":"brick"}],"correctOption":"B","explanation":"தீவைச் சுற்றி நீர் (Water) இருக்கும். பாலைவனச் சோலையைச் (Oasis) சுற்றி மணல் (Sand) இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q20","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Mathematics : numbers :: History : ?","options":[{"id":"A","text":"events"},{"id":"B","text":"people"},{"id":"C","text":"geography"},{"id":"D","text":"mountains"}],"correctOption":"A","explanation":"கணிதம் எண்களைப் (numbers) பற்றியது. வரலாறு கடந்த கால நிகழ்வுகளைப் (events) பற்றியது.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q21","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Bouquet : flowers :: Sentence : ?","options":[{"id":"A","text":"words"},{"id":"B","text":"letters"},{"id":"C","text":"paragraphs"},{"id":"D","text":"passages"}],"correctOption":"A","explanation":"பூங்கொத்து பூக்களால் (flowers) ஆனது. வாக்கியம் வார்த்தைகளால் (words) ஆனது.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q22","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Volume : litre :: Force : ?","options":[{"id":"A","text":"Joule"},{"id":"B","text":"Watt"},{"id":"C","text":"Radian"},{"id":"D","text":"Newton"}],"correctOption":"D","explanation":"கனஅளவின் அலகு லிட்டர் (litre). விசையின் அலகு நியூட்டன் (Newton).","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q23","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Virat Kohli : Cricket :: P.V. Sindhu : ?","options":[{"id":"A","text":"Squash"},{"id":"B","text":"Table-tennis"},{"id":"C","text":"Badminton"},{"id":"D","text":"Tennis"}],"correctOption":"C","explanation":"விராட் கோலி கிரிக்கெட் வீரர். பி.வி.சிந்து பூப்பந்து (Badminton) வீராங்கனை.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q24","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Candle : melt :: Water : ?","options":[{"id":"A","text":"freeze"},{"id":"B","text":"condense"},{"id":"C","text":"boil"},{"id":"D","text":"decompose"}],"correctOption":"C","explanation":"மெழுகுவர்த்தி உருகுவது போல, நீர் கொதிக்கிறது (Boil) அல்லது உறைகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q25","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாததைத் தேர்ந்தெடுக்கவும்:","options":[{"id":"A","text":"Lions : roar"},{"id":"B","text":"Cat : mew"},{"id":"C","text":"Dogs : bark"},{"id":"D","text":"Snakes : twitter"}],"correctOption":"D","explanation":"பாம்புகள் சீறும் (Hiss). Twitter என்பது பறவைகளின் ஒலியாகும். எனவே இது பொருந்தாது.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q26","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாததைத் தேர்ந்தெடுக்கவும்:","options":[{"id":"A","text":"ராஜஸ்தான்"},{"id":"B","text":"பஞ்சாப்"},{"id":"C","text":"ஹரியானா"},{"id":"D","text":"சண்டிகார்"}],"correctOption":"D","explanation":"சண்டிகார் என்பது ஒரு யூனியன் பிரதேசம். மற்றவை அனைத்தும் மாநிலங்கள்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q27","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாததைத் தேர்ந்தெடுக்கவும்:","options":[{"id":"A","text":"behind"},{"id":"B","text":"under"},{"id":"C","text":"and"},{"id":"D","text":"from"}],"correctOption":"C","explanation":"''and'' என்பது ஒரு இணைப்புச் சொல் (Conjunction). மற்றவை அனைத்தும் முன்விடைச் சொற்கள் (Prepositions).","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q28","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"CREDITORS என்ற வார்த்தையிலுள்ள எழுத்துக்களை கொண்டு உருவாக்க இயலாத வார்த்தை:","options":[{"id":"A","text":"ROSE"},{"id":"B","text":"EDITOR"},{"id":"C","text":"DIRECTOR"},{"id":"D","text":"STEP"}],"correctOption":"D","explanation":"STEP என்ற வார்த்தையில் உள்ள ''P'' என்ற எழுத்து CREDITORS-ல் இல்லை.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q29","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"AMPLIFICATION என்ற வார்த்தையிலுள்ள எழுத்துக்களை கொண்டு உருவாக்க இயலாத வார்த்தை:","options":[{"id":"A","text":"FICTION"},{"id":"B","text":"ACTION"},{"id":"C","text":"FILTER"},{"id":"D","text":"MAP"}],"correctOption":"C","explanation":"FILTER என்ற வார்த்தையில் உள்ள ''E'' மற்றும் ''R'' ஆகிய எழுத்துக்கள் AMPLIFICATION-ல் இல்லை.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q30","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"MAGNITUDE என்ற வார்த்தையிலுள்ள எழுத்துக்களை கொண்டு உருவாக்கக் கூடிய வார்த்தை:","options":[{"id":"A","text":"GRIND"},{"id":"B","text":"MAGNET"},{"id":"C","text":"TUBE"},{"id":"D","text":"NUMBER"}],"correctOption":"B","explanation":"MAGNET என்ற வார்த்தையில் உள்ள அனைத்து எழுத்துக்களும் MAGNITUDE-ல் உள்ளன.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q31","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"DEMONSTRATION என்ற வார்த்தையிலுள்ள எழுத்துக்களை கொண்டு உருவாக்கக் கூடிய வார்த்தை:","options":[{"id":"A","text":"MONSTER"},{"id":"B","text":"STATIC"},{"id":"C","text":"TRAINING"},{"id":"D","text":"DRINK"}],"correctOption":"A","explanation":"MONSTER என்ற வார்த்தையில் உள்ள அனைத்து எழுத்துக்களும் DEMONSTRATION-ல் உள்ளன.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q32","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ORANGE என்பது ANEORG எனக் குறிப்பிடப்பட்டால், GRAPES என்பது:","options":[{"id":"A","text":"RAPESA"},{"id":"B","text":"APSGRE"},{"id":"C","text":"APGSER"},{"id":"D","text":"RASGPE"}],"correctOption":"B","explanation":"குறியீடு இடமாற்றம்: 123456 -> 346125. அதே முறையில் GRAPES -> APSGRE.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q33","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"LILLY என்பது NKNNA எனக் குறிப்பிடப்பட்டால், LOTUS என்பது:","options":[{"id":"A","text":"WQNUV"},{"id":"B","text":"NQUWV"},{"id":"C","text":"WOVQN"},{"id":"D","text":"NQVWU"}],"correctOption":"D","explanation":"ஒவ்வொரு எழுத்தும் +2 இடங்கள் முன்னேறுகிறது. L(+2)=N, O(+2)=Q, T(+2)=V, U(+2)=W, S(+2)=U. விடை NQVWU.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q34","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வார்த்தைகளை அவற்றின் பொருளின் அடிப்படையில் வரிசைப்படுத்தவும்: (a) நாற்காலி (b) மரம் (c) மரப்பலகை (d) விதை (e) செடி","options":[{"id":"A","text":"(a), (b), (c), (d), (e)"},{"id":"B","text":"(a), (c), (b), (d), (e)"},{"id":"C","text":"(d), (e), (b), (c), (a)"},{"id":"D","text":"(d), (c), (e), (b), (a)"}],"correctOption":"C","explanation":"விதை (d) -> செடி (e) -> மரம் (b) -> மரப்பலகை (c) -> நாற்காலி (a).","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q35","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வார்த்தைகளை அவற்றின் பொருளின் அடிப்படையில் வரிசைப்படுத்தவும்: (a) வாக்கியம் (b) கட்டுரை (c) வார்த்தை (d) எழுத்து (e) பத்தி","options":[{"id":"A","text":"(d), (a), (c), (b), (e)"},{"id":"B","text":"(d), (c), (a), (e), (b)"},{"id":"C","text":"(b), (a), (c), (e), (d)"},{"id":"D","text":"(c), (a), (d), (e), (b)"}],"correctOption":"B","explanation":"எழுத்து (d) -> வார்த்தை (c) -> வாக்கியம் (a) -> பத்தி (e) -> கட்டுரை (b).","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q36","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்தில் உள்ள செவ்வகங்களின் எண்ணிக்கை:","questionImage":"/assets/pyq/image/mat_2017/q36.png","options":[{"id":"A","text":"26"},{"id":"B","text":"28"},{"id":"C","text":"27"},{"id":"D","text":"25"}],"correctOption":"A","explanation":"படத்தை உற்றுநோக்கி சரியான செவ்வகங்களைக் கணக்கிடவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q37","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்தில் உள்ள முக்கோணங்களின் எண்ணிக்கை:","questionImage":"/assets/pyq/image/mat_2017/q37.png","options":[{"id":"A","text":"14"},{"id":"B","text":"15"},{"id":"C","text":"13"},{"id":"D","text":"12"}],"correctOption":"A","explanation":"படத்தை உற்றுநோக்கி சரியான முக்கோணங்களைக் கணக்கிடவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q38","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"நேரம் 9 மணி 30 நிமிடங்களாக இருக்கும்போது கடிகாரத்தின் இரு முட்களுக்கும் இடைப்பட்ட கோணம்:","options":[{"id":"A","text":"$105^{\\circ}$"},{"id":"B","text":"$95^{\\circ}$"},{"id":"C","text":"$100^{\\circ}$"},{"id":"D","text":"$110^{\\circ}$"}],"correctOption":"A","explanation":"கோணம் = |30H - 5.5M| = |30(9) - 5.5(30)| = |270 - 165| = 105°.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q39","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"1 லிருந்து 30 வரையிலுள்ள எண்களில், 3 ஆல் வகுபடுவது மட்டுமல்லாமல், 3 என்ற எண்ணையும் கொண்டிருக்கும் எண்களின் எண்ணிக்கை:","options":[{"id":"A","text":"3"},{"id":"B","text":"1"},{"id":"C","text":"4"},{"id":"D","text":"2"}],"correctOption":"D","explanation":"3 ஆல் வகுபடும் மற்றும் 3-ஐ கொண்ட எண்கள்: 3 மற்றும் 30. எனவே மொத்தம் 2 எண்கள்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q40","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு குடும்பத்தில் கணவன், மனைவி, 4 மகன்கள், 4 மருமகள்கள் வசிக்கின்றனர். ஒவ்வொரு மகனுக்கும் 3 மகன்களும் 1 மகளும் உள்ளனர். குடும்பத்தில் உள்ள மொத்த ஆண் உறுப்பினர்கள்:","options":[{"id":"A","text":"4"},{"id":"B","text":"8"},{"id":"C","text":"12"},{"id":"D","text":"17"}],"correctOption":"D","explanation":"ஆண்கள் = 1 (கணவன்) + 4 (மகன்கள்) + 12 (பேரன்கள்) = 17.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q41","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Health - worship - strength'' என்பதன் குறியீடு:","questionImage":"/assets/pyq/image/mat_2017/q41.png","options":[{"id":"A","text":"810"},{"id":"B","text":"018"},{"id":"C","text":"108"},{"id":"D","text":"180"}],"correctOption":"D","explanation":"Health=1, worship=8, strength=0. எனவே 180.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q42","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தவறான இணையைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2017/q41.png","options":[{"id":"A","text":"(a), (d)"},{"id":"B","text":"(a), (c)"},{"id":"C","text":"(b), (d)"},{"id":"D","text":"(b), (c)"}],"correctOption":"C","explanation":"Time gold = 45 ஆக இருக்க வேண்டும் (48 தவறு). Work worship = 68 ஆக இருக்க வேண்டும் (65 தவறு). எனவே (b), (d) தவறானவை.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q43","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருத்துக: (a) Health worship (b) Time wealth (c) Union gold (d) Work strength","questionImage":"/assets/pyq/image/mat_2017/q41.png","options":[{"id":"A","text":"(a)-(iv), (b)-(i), (c)-(ii), (d)-(iii)"},{"id":"B","text":"(a)-(iv), (b)-(iii), (c)-(i), (d)-(ii)"},{"id":"C","text":"(a)-(iii), (b)-(ii), (c)-(iv), (d)-(i)"},{"id":"D","text":"(a)-(ii), (b)-(i), (c)-(iv), (d)-(iii)"}],"correctOption":"B","explanation":"Health worship = 18 (iv). Time wealth = 43 (iii). Union gold = 95 (i). Work strength = 60 (ii).","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q44","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"523 என்ற குறியீடு எதனைக் குறிக்கும்?","questionImage":"/assets/pyq/image/mat_2017/q41.png","options":[{"id":"A","text":"Time is gold"},{"id":"B","text":"Health is wealth"},{"id":"C","text":"Gold is wealth"},{"id":"D","text":"Time is strength"}],"correctOption":"C","explanation":"5=Gold, 2=is, 3=wealth. எனவே Gold is wealth.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q45","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"''Worship'' என்பதனைக் குறிக்கும் குறியீடு:","questionImage":"/assets/pyq/image/mat_2017/q41.png","options":[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"5"},{"id":"D","text":"8"}],"correctOption":"D","explanation":"Work is worship = 628. இதில் worship என்பதன் குறியீடு 8.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q46","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"20 சிறுமிகளில், தீபா இடமிருந்து 5-வது, பூஜா வலமிருந்து 10-வது. பூஜா, தீபாவை நோக்கி 5 இடங்கள் நகர்ந்தால், இடமிருந்து பூஜாவின் இடம்:","options":[{"id":"A","text":"ஏழாவது"},{"id":"B","text":"ஐந்தாவது"},{"id":"C","text":"நான்காவது"},{"id":"D","text":"ஆறாவது"}],"correctOption":"D","explanation":"பூஜா வலமிருந்து 10 = இடமிருந்து 11-வது. தீபாவை (5வது) நோக்கி 5 இடங்கள் நகர்ந்தால், 11 - 5 = 6-வது இடம்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q47","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ரோஹன் இடமிருந்து 6-வது, ஆதித்யா வலமிருந்து 8-வது. இடையில் எவரும் இல்லை எனில், மொத்த மாணவர்கள்:","options":[{"id":"A","text":"12"},{"id":"B","text":"14"},{"id":"C","text":"13"},{"id":"D","text":"16"}],"correctOption":"B","explanation":"6 + 8 = 14 மாணவர்கள்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q48","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"35 மாணவர்கள் உள்ள வகுப்பில் நேத்ரா மேலிருந்து 19-வது. கீழிருந்து அவரது தரவரிசை:","options":[{"id":"A","text":"21"},{"id":"B","text":"17"},{"id":"C","text":"18"},{"id":"D","text":"16"}],"correctOption":"B","explanation":"கீழிருந்து நிலை = 35 - 19 + 1 = 17.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q49","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"சஷாங்க் மேலிருந்து 8-வது, கீழிருந்து 23-வது. 5 மாணவர்கள் தேர்வெழுதவில்லை. மொத்த மாணவர்கள்:","options":[{"id":"A","text":"34"},{"id":"B","text":"32"},{"id":"C","text":"33"},{"id":"D","text":"35"}],"correctOption":"D","explanation":"தேர்வெழுதியவர்கள் = 8 + 23 - 1 = 30. மொத்த மாணவர்கள் = 30 + 5 = 35.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q50","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ராம் மற்றும் ரோகன் இருவருக்குமிடையில் வட்ட மேசையில் அமர்ந்திருப்பவர் யார்?","questionImage":"/assets/pyq/image/mat_2017/q50.png","options":[{"id":"A","text":"ராபின்"},{"id":"B","text":"ரமேஷ்"},{"id":"C","text":"ராகுல்"},{"id":"D","text":"ரஹிம்"}],"correctOption":"A","explanation":"கொடுக்கப்பட்ட இருக்கை அமைப்பின்படி, ராம் மற்றும் ரோகன் இடையே ராபின் உள்ளார்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q51","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ராம் என்பார் அமர்ந்திருப்பது:","questionImage":"/assets/pyq/image/mat_2017/q50.png","options":[{"id":"A","text":"ரமேஷின் இடதுபுறம்"},{"id":"B","text":"ராபின்னின் வலதுபுறம்"},{"id":"C","text":"ராபின்னின் இடதுபுறம்"},{"id":"D","text":"ரஹிம்-ன் வலதுபுறம்"}],"correctOption":"C","explanation":"இருக்கை அமைப்பின்படி, ராம் என்பவர் ராபின்னின் இடதுபுறம் அமர்ந்துள்ளார்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q52","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ரமேஷ் மற்றும் ரஹிம் இருவருக்கும் மேசையின் மையத்திலிருந்து உள்ள கோண அளவு:","questionImage":"/assets/pyq/image/mat_2017/q50.png","options":[{"id":"A","text":"$60^{\\circ}$"},{"id":"B","text":"$120^{\\circ}$"},{"id":"C","text":"$90^{\\circ}$"},{"id":"D","text":"$180^{\\circ}$"}],"correctOption":"B","explanation":"அவர்கள் இருவருக்கும் இடையே 2 இடங்கள் இடைவெளி உள்ளது. ஒரு இடம் = 60°. இரு இடங்கள் = 120°.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q53","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"உயர வரிசையில் P மற்றும் R இருவருக்கிடையில் உள்ளவர்கள் யார்?","questionImage":"/assets/pyq/image/mat_2017/q53.png","options":[{"id":"A","text":"Q, T"},{"id":"B","text":"R, T"},{"id":"C","text":"P, Q"},{"id":"D","text":"R, Q"}],"correctOption":"A","explanation":"உயர வரிசை: S > R > Q > T > P > U. P மற்றும் R க்கு இடையே Q மற்றும் T உள்ளனர்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q54","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வலது புறத்திலிருந்து (குள்ளமானவர்) P-ன் நிலை என்ன?","questionImage":"/assets/pyq/image/mat_2017/q53.png","options":[{"id":"A","text":"ஐந்தாவது"},{"id":"B","text":"இரண்டாவது"},{"id":"C","text":"மூன்றாவது"},{"id":"D","text":"ஆறாவது"}],"correctOption":"B","explanation":"U தான் மிகவும் குள்ளமானவர் (வலமிருந்து 1வது). அவருக்கு அடுத்து P உள்ளார். எனவே 2-வது.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q55","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பின்வரும் கூற்றுகளில் தவறான கூற்று எது?","questionImage":"/assets/pyq/image/mat_2017/q53.png","options":[{"id":"A","text":"P என்பவர் T-யைவிட குள்ளமானவர்."},{"id":"B","text":"P என்பவர் U-யைவிட உயரமானவர்."},{"id":"C","text":"R என்பவர் உயரத்தின் அடிப்படையில் நடுவில் உள்ளார்."},{"id":"D","text":"T வலதுபுறத்திலிருந்து 3-வது நிலையிலுள்ளார்."}],"correctOption":"C","explanation":"R என்பவர் 2-வது உயரமானவர், நடுவில் இல்லை. எனவே இதுவே தவறான கூற்று.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q56","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"BANGLE=123456, LEADERS=5627689 எனில் GANGES என்பதன் குறியீடு:","options":[{"id":"A","text":"432649"},{"id":"B","text":"423469"},{"id":"C","text":"243469"},{"id":"D","text":"342649"}],"correctOption":"B","explanation":"எழுத்துக்களின் எண்களைப் பிரதியிட: G(4) A(2) N(3) G(4) E(6) S(9) = 423469.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q57","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"BANGLE=123456, LEADERS=5627689 எனில் LEANDER என்பதன் குறியீடு:","options":[{"id":"A","text":"5263768"},{"id":"B","text":"5267368"},{"id":"C","text":"5267386"},{"id":"D","text":"5623768"}],"correctOption":"D","explanation":"L(5) E(6) A(2) N(3) D(7) E(6) R(8) = 5623768.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q58","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"BANGLE=123456, LEADERS=5627689 எனில் BEADS என்பதன் குறியீடு:","options":[{"id":"A","text":"12679"},{"id":"B","text":"16279"},{"id":"C","text":"12697"},{"id":"D","text":"16297"}],"correctOption":"B","explanation":"B(1) E(6) A(2) D(7) S(9) = 16279.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q59","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பகடையின் மேற்பரப்பு 1 ஆக இருக்கும்போது கீழ்ப்பகுதியில் உள்ள எண் என்ன?","questionImage":"/assets/pyq/image/mat_2017/q59.png","options":[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"4"},{"id":"D","text":"1"}],"correctOption":"C","explanation":"பகடைகளின் அமைப்பைக் கொண்டு பார்க்கும்போது 1-க்கு எதிரே 4 வரும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q60","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"நீட்டா மேற்கு நோக்கி 8 மீ நடந்தாள். தெற்கு திரும்பி 12 மீ நடந்தாள். கிழக்கு நோக்கி 8 மீ நடந்தாள். அவள் வீட்டிலிருந்து எவ்வளவு தூரத்தில் உள்ளார்?","options":[{"id":"A","text":"8 மீ"},{"id":"B","text":"12 மீ"},{"id":"C","text":"10 மீ"},{"id":"D","text":"20 மீ"}],"correctOption":"B","explanation":"அவள் ஒரு செவ்வகப் பாதையில் நடந்துள்ளாள். புறப்பட்ட இடத்திற்கு நேர் தெற்கே 12 மீ தொலைவில் இருப்பாள்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q61","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"20 நபர்கள் பங்குபெறும் விளையாட்டில், ஒவ்வொரு முறையும் ஒருவர் விலக்கப்படுகிறார். வெற்றியாளரை அறிவிக்க எத்தனை முறை இசை ஒலிக்க வேண்டும்?","options":[{"id":"A","text":"9"},{"id":"B","text":"20"},{"id":"C","text":"19"},{"id":"D","text":"10"}],"correctOption":"C","explanation":"19 பேரை விலக்கினால் தான் 1 வெற்றியாளர் கிடைப்பார். எனவே 19 முறை இசை ஒலிக்க வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q62","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒருவர் தலைகீழாக நின்று யோகா செய்கிறார். முகம் வடக்கு நோக்கியுள்ளது எனில், வலது கை எத்திசையில் இருக்கும்?","options":[{"id":"A","text":"தென்கிழக்கு"},{"id":"B","text":"வடக்கு"},{"id":"C","text":"கிழக்கு"},{"id":"D","text":"மேற்கு"}],"correctOption":"D","explanation":"சாதாரணமாக வடக்கு நோக்கினால் வலதுகை கிழக்கு. தலைகீழாக நிற்கும் போது வலது கை மேற்கு நோக்கி இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q63","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"அப்பாவின் வயது 34. மகனின் வயது 8. இன்னும் எத்தனை வருடங்களில் தந்தையின் வயது மகனின் வயதைப் போன்று 3 மடங்காகும்?","options":[{"id":"A","text":"6 வருடங்கள்"},{"id":"B","text":"5 வருடங்கள்"},{"id":"C","text":"4 வருடங்கள்"},{"id":"D","text":"3 வருடங்கள்"}],"correctOption":"B","explanation":"5 வருடங்களில் அப்பா=39, மகன்=13. 13 × 3 = 39. எனவே 5 வருடங்கள்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q64","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுதிகளில் எந்த இரண்டு விடுதிகள் காலியாக உள்ளன?","questionImage":"/assets/pyq/image/mat_2017/q64_68.png","options":[{"id":"A","text":"இரண்டாவது மற்றும் மூன்றாவது"},{"id":"B","text":"மூன்றாவது மற்றும் நான்காவது"},{"id":"C","text":"முதல் மற்றும் இரண்டாவது"},{"id":"D","text":"முதல் மற்றும் மூன்றாவது"}],"correctOption":"C","explanation":"குறிப்புகளின்படி விடுதிகளை வரிசைப்படுத்தினால் 1 மற்றும் 2-வது விடுதிகள் காலியாக இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q65","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"அர்விந்திற்கும், திலீப்பிற்கும் இடையில் உள்ள விடுதியில் தங்குபவர் யார்?","questionImage":"/assets/pyq/image/mat_2017/q64_68.png","options":[{"id":"A","text":"பிரதீப்"},{"id":"B","text":"ரோஹன்"},{"id":"C","text":"பிரணவ்"},{"id":"D","text":"எவருமில்லை"}],"correctOption":"B","explanation":"திலீப்(5) மற்றும் அர்விந்த்(7) இருவருக்கும் இடையில் 6-வது விடுதியில் ரோஹன் தங்கியுள்ளார்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q66","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"அதிகபட்சமாக தொடர்ச்சியாக தங்கவைக்கப்பட்ட விடுதிகளின் எண்ணிக்கை யாது?","questionImage":"/assets/pyq/image/mat_2017/q64_68.png","options":[{"id":"A","text":"4"},{"id":"B","text":"3"},{"id":"C","text":"2"},{"id":"D","text":"5"}],"correctOption":"D","explanation":"3, 4, 5, 6, 7 ஆகிய 5 விடுதிகளில் ஆட்கள் தொடர்ச்சியாகத் தங்கியுள்ளனர்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q67","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"திலீப்பிற்கு இடப்பக்கத்தில் அமைந்த விடுதியில் தங்க வைக்கப்பட்ட நபர் யார்?","questionImage":"/assets/pyq/image/mat_2017/q64_68.png","options":[{"id":"A","text":"ரோஹன்"},{"id":"B","text":"அர்விந்த்"},{"id":"C","text":"பிரதீப்"},{"id":"D","text":"எவருமில்லை"}],"correctOption":"C","explanation":"திலீப் (5) விடுதிக்கு இடதுபுறம் (4) பிரதீப் தங்கியுள்ளார்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q68","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தங்கவைக்கப்பட்டவர்களில் வலது ஓரத்திலிருந்து முதலாவதாக உள்ள நபர் யார்?","questionImage":"/assets/pyq/image/mat_2017/q64_68.png","options":[{"id":"A","text":"பிரணவ்"},{"id":"B","text":"பிரதீப்"},{"id":"C","text":"திலீப்"},{"id":"D","text":"ரோஹன்"}],"correctOption":"A","explanation":"காலியாக உள்ளவற்றைத் தவிர்த்துப் பார்த்தால் பிரணவ் தான் முதலில் உள்ளார்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q69","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கடிகாரத்தில் மணி 3:00. இதன் பிரதிபலிப்பு கண்ணாடியில் எவ்வாறு தோன்றும்?","options":[{"id":"A","text":"3 மணி"},{"id":"B","text":"6 மணி"},{"id":"C","text":"9 மணி"},{"id":"D","text":"8 மணி"}],"correctOption":"C","explanation":"கண்ணாடி பிம்பம் = 12:00 - 3:00 = 9:00.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q70","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"சரியான கண்ணாடி பிம்பத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2017/q70.png","options":[{"id":"A","text":"படம் 1"},{"id":"B","text":"படம் 2"},{"id":"C","text":"படம் 3"},{"id":"D","text":"படம் 4"}],"correctOption":"A","explanation":"படங்களை உற்று நோக்கி சரியான தர்க்க அமைப்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q71","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"சரியான கண்ணாடி பிம்பத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2017/q71.png","options":[{"id":"A","text":"படம் 1"},{"id":"B","text":"படம் 2"},{"id":"C","text":"படம் 3"},{"id":"D","text":"படம் 4"}],"correctOption":"B","explanation":"படங்களை உற்று நோக்கி சரியான தர்க்க அமைப்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q72","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"(X) என்ற படத்தை ஒரு பகுதியாகக் கொண்ட படம் எது?","questionImage":"/assets/pyq/image/mat_2017/q72.png","options":[{"id":"A","text":"படம் 1"},{"id":"B","text":"படம் 2"},{"id":"C","text":"படம் 3"},{"id":"D","text":"படம் 4"}],"correctOption":"A","explanation":"உள்ளடங்கிய உருவத்தைக் (Embedded figure) கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2017-mat-q73","subject