ks":0},{"id":"pyq-2023-mat-q86","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"C-க்கு இணையான D படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2023/q86.png","options":[{"id":"A","text":"படம் 1"},{"id":"B","text":"படம் 2"},{"id":"C","text":"படம் 3"},{"id":"D","text":"படம் 4"}],"correctOption":"C","explanation":"படங்களை உற்று நோக்கி சரியான தர்க்க அமைப்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2023-mat-q87","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"C-க்கு இணையான D படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2023/q87.png","options":[{"id":"A","text":"படம் 1"},{"id":"B","text":"படம் 2"},{"id":"C","text":"படம் 3"},{"id":"D","text":"படம் 4"}],"correctOption":"C","explanation":"படங்களை உற்று நோக்கி சரியான தர்க்க அமைப்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2023-mat-q88","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"C-க்கு இணையான D படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2023/q88.png","options":[{"id":"A","text":"படம் 1"},{"id":"B","text":"படம் 2"},{"id":"C","text":"படம் 3"},{"id":"D","text":"படம் 4"}],"correctOption":"B","explanation":"படங்களை உற்று நோக்கி சரியான தர்க்க அமைப்பைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2023-mat-q89","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"REFER என்ற வார்த்தையின் கண்ணாடி பிம்பம்:","questionImage":"/assets/pyq/image/mat_2023/q88.png","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}],"correctOption":"A","explanation":"கண்ணாடியில் எழுத்துக்கள் வலது-இடமாக (Left-Right inverse) மாறும்.","marks":1,"negativeMarks":0},{"id":"pyq-2023-mat-q90","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படத்தின் தண்ணீர் பிம்பம்:","questionImage":"/assets/pyq/image/mat_2023/q90.png","options":[{"id":"A","text":"படம் 1"},{"id":"B","text":"படம் 2"},{"id":"C","text":"படம் 3"},{"id":"D","text":"படம் 4"}],"correctOption":"C","explanation":"தண்ணீரில் பிம்பம் தலைகீழாக (Top-Bottom inverted) மாறும்.","marks":1,"negativeMarks":0}]', '2023-01-01T00:00:00.000Z');
INSERT OR REPLACE INTO quizzes (id, title, description, duration_minutes, total_marks, pass_percentage, shuffle_questions, shuffle_options, enable_anti_cheat, status, questions, created_at) VALUES ('pyq-2024-mat', 'NMMS 2024 - MAT (மனத்திறன் தேர்வு - Mental Ability Test)', 'Official NMMS 2024 Mental Ability Test (MAT) with 90 official previous year questions.', 90, 90, 40, 0, 0, 1, 'draft', '[{"id":"pyq-2024-mat-q1","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பின்வரும் தொடர் வரிசையில் அடுத்து வரும் உறுப்பைக் கண்டறியவும்: 3, 5, 5, 19, 7, 41, 9, ?","options":[{"id":"A","text":"71"},{"id":"B","text":"61"},{"id":"C","text":"79"},{"id":"D","text":"69"}],"correctOption":"A","explanation":"இது இரு தொடர்கள் கலந்த தொடர் (Alternate Series): 1வது தொடர்: 3, 5, 7, 9 (ஒற்றை எண்கள்). 2வது தொடர்: 5 (2²+1), 19 (4²+3), 41 (6²+5). அடுத்ததாக வர வேண்டியது 8²+7 = 64+7 = 71.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q2","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"125, 80, 45, 20, 5, ?","options":[{"id":"A","text":"1"},{"id":"B","text":"0"},{"id":"C","text":"-5"},{"id":"D","text":"-10"}],"correctOption":"B","explanation":"எண்களுக்கு இடையிலான வித்தியாசம்: -45, -35, -25, -15. எனவே அடுத்த வித்தியாசம் -5 ஆக இருக்க வேண்டும். 5 - 5 = 0.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q3","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"8, 15, 28, 53, 102, ?","options":[{"id":"A","text":"204"},{"id":"B","text":"199"},{"id":"C","text":"195"},{"id":"D","text":"189"}],"correctOption":"B","explanation":"தர்க்கம்: (n * 2) - 1, (n * 2) - 2, (n * 2) - 3... \n 8*2-1 = 15; \n 15*2-2 = 28; \n 28*2-3 = 53; \n 53*2-4 = 102; \n எனவே, 102*2-5 = 204 - 5 = 199.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q4","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"2, 2, 3, 4, 5, 6, 7, 8, 11, 10, ?","options":[{"id":"A","text":"12"},{"id":"B","text":"9"},{"id":"C","text":"13"},{"id":"D","text":"14"}],"correctOption":"C","explanation":"இது மாற்றுத் தொடர் வரிசை: 1வது தொடர் பகா எண்கள் (2, 3, 5, 7, 11, 13). 2வது தொடர் இரட்டை எண்கள் (2, 4, 6, 8, 10). அடுத்த எண் பகா எண் தொடரில் 13 ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q5","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"3, 7, 13, 21, 31, ?","options":[{"id":"A","text":"34"},{"id":"B","text":"37"},{"id":"C","text":"42"},{"id":"D","text":"43"}],"correctOption":"D","explanation":"வித்தியாசம்: 4, 6, 8, 10 என கூடிக்கொண்டே செல்கிறது. அடுத்த வித்தியாசம் 12 ஆக இருக்க வேண்டும். எனவே, 31 + 12 = 43.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q6","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A, B, C, E, H, M, ?","options":[{"id":"A","text":"S"},{"id":"B","text":"R"},{"id":"C","text":"U"},{"id":"D","text":"V"}],"correctOption":"C","explanation":"எழுத்துக்களின் ஆங்கில இடமதிப்புகள் ஃபைபோனாச்சி (Fibonacci) தொடரில் அமைந்துள்ளன: 1 (A), 2 (B), 3 (C), 5 (E), 8 (H), 13 (M), 21. 21-வது எழுத்து U.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q7","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"BAT, DCV, FEX, ?","options":[{"id":"A","text":"HGI"},{"id":"B","text":"HGZ"},{"id":"C","text":"HIJ"},{"id":"D","text":"HGY"}],"correctOption":"B","explanation":"ஒவ்வொரு எழுத்தும் ஆங்கில அகர வரிசையில் +2 படிகள் நகர்கிறது. F+2=H, E+2=G, X+2=Z. எனவே HGZ.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q8","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"12, 9, 5, 0, ?","options":[{"id":"A","text":"-5"},{"id":"B","text":"-4"},{"id":"C","text":"-6"},{"id":"D","text":"-8"}],"correctOption":"C","explanation":"வித்தியாசம்: -3, -4, -5. எனவே அடுத்த வித்தியாசம் -6 ஆக இருக்க வேண்டும். 0 - 6 = -6.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q9","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"C4X, F9U, I16R, ?","options":[{"id":"A","text":"K25P"},{"id":"B","text":"L25P"},{"id":"C","text":"L25O"},{"id":"D","text":"L27P"}],"correctOption":"C","explanation":"முதல் எழுத்து +3 (C->F->I->L). நடுத்தர எண் வர்க்கங்கள் (2², 3², 4², அடுத்தது 5²=25). கடைசி எழுத்து -3 (X->U->R->O). எனவே L25O.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q10","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Z, L, X, J, V, H, T, F, ?","options":[{"id":"A","text":"A"},{"id":"B","text":"R"},{"id":"C","text":"C"},{"id":"D","text":"J"}],"correctOption":"B","explanation":"இரண்டு தொடர்கள்: Z, X, V, T, R (-2) மற்றும் L, J, H, F (-2). அடுத்த எழுத்து முதல் தொடரின் T-க்கு முந்தைய R ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q11","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"AB 2, EF 30, IJ 90, OP 240, ?","options":[{"id":"A","text":"TU 720"},{"id":"B","text":"UV 480"},{"id":"C","text":"VW 368"},{"id":"D","text":"UV 462"}],"correctOption":"D","explanation":"எழுத்துக்களின் இடமதிப்பை பெருக்க வேண்டும்: A(1)*B(2)=2, E(5)*F(6)=30, I(9)*J(10)=90, O(15)*P(16)=240. அடுத்த தொடர் UV (21, 22). 21*22 = 462. எனவே UV 462.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q12","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட எண்ணைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2024/q12.png","options":[{"id":"A","text":"125"},{"id":"B","text":"216"},{"id":"C","text":"1000"},{"id":"D","text":"343"}],"correctOption":"B","explanation":"படத்திலுள்ள எண்களுக்கு இடையேயான தர்க்கம்: இரு எண்களின் கூடுதல் அல்லது பெருக்கலின் கனமூலம் (Cube) அல்லது வர்க்கம் (Square) மையத்தில் வரும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q13","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட எண்ணைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2024/q13.png","options":[{"id":"A","text":"11"},{"id":"B","text":"12"},{"id":"C","text":"13"},{"id":"D","text":"15"}],"correctOption":"A","explanation":"வெளியே உள்ள எண்களைக் கூட்டி குறிப்பிட்ட எண்ணால் வகுக்க மைய எண் கிடைக்கும் தர்க்கம் இதில் பயன்படுத்தப்பட்டுள்ளது.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q14","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட எண்ணைக் கண்டறியவும்:","questionImage":"/assets/pyq/image/mat_2024/q14.png","options":[{"id":"A","text":"-46"},{"id":"B","text":"0"},{"id":"C","text":"-32"},{"id":"D","text":"26"}],"correctOption":"B","explanation":"மனித வடிவில் உள்ள எண்களில், கைகள் மற்றும் கால்களில் உள்ள எண்களைப் பெருக்கி/கழித்து தலைப்பகுதியில் உள்ள எண் கணக்கிடப்படுகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q15","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தவறான உறுப்பைக் கண்டறியவும்:","options":[{"id":"A","text":"Fry"},{"id":"B","text":"Boil"},{"id":"C","text":"Peel"},{"id":"D","text":"Bake"}],"correctOption":"C","explanation":"Peel (உரித்தல்) என்பது சமைக்கும் முறை அல்ல, அது ஒரு தயாரிப்பு வேலை. மற்றவை அனைத்தும் நேரடியாக நெருப்பைப் பயன்படுத்தும் சமைக்கும் முறைகள்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q16","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தவறான உறுப்பைக் கண்டறியவும்:","options":[{"id":"A","text":"Zebra"},{"id":"B","text":"Horse"},{"id":"C","text":"Tiger"},{"id":"D","text":"Lion"}],"correctOption":"B","explanation":"Horse (குதிரை) ஒரு வீட்டு விலங்கு (Domestic Animal). மற்றவை அனைத்தும் காட்டில் வாழும் வன விலங்குகள் (Wild Animals).","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q17","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தவறான உறுப்பைக் கண்டறியவும்:","options":[{"id":"A","text":"Tennis"},{"id":"B","text":"Soccer"},{"id":"C","text":"Billiards"},{"id":"D","text":"Cricket"}],"correctOption":"C","explanation":"Billiards என்பது உள்ளரங்கு விளையாட்டு (Indoor Game), மற்றவை அனைத்தும் மைதானத்தில் விளையாடப்படும் வெளியரங்கு (Outdoor) விளையாட்டுகள்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q18","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"8 : 63 :: 12 : ?","options":[{"id":"A","text":"168"},{"id":"B","text":"121"},{"id":"C","text":"143"},{"id":"D","text":"132"}],"correctOption":"C","explanation":"தொடர்பு: x : (x²-1). 8²-1 = 63. அதேபோல் 12²-1 = 144-1 = 143.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q19","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Shout : Whisper :: Strike : ?","options":[{"id":"A","text":"Anger"},{"id":"B","text":"Kick"},{"id":"C","text":"Kill"},{"id":"D","text":"Touch"}],"correctOption":"D","explanation":"Shout (கத்துதல்) - Whisper (முணுமுணுத்தல்) என இரண்டும் எதிர்ப்பதங்கள். அதேபோல் Strike (கடுமையாக தாக்குதல்) என்பதற்கு எதிர்ப்பதம் மென்மையாக Touch (தொடுதல்).","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q20","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Plants, Animals, Men - இவற்றுக்கு இடையேயான சரியான வென் படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q20-24.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"மனிதர்கள் (Men) விலங்குகள் (Animals) பிரிவுக்குள் வருவார்கள் (உள் வட்டம்). தாவரங்கள் (Plants) முற்றிலும் மாறுபட்டவை என்பதால் தனியாக ஒரு வட்டம் இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q21","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Mothers, Doctors, Women - இவற்றுக்கு இடையேயான சரியான வென் படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q20-24.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"அனைத்து தாய்மார்களும் பெண்கள் ஆவர் (உள் வட்டம்). தாய்மார்கள் மற்றும் பெண்களில் சிலர் மருத்துவர்களாக இருக்கலாம் (வெட்டும் வட்டம்).","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q22","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Minutes, Days, Months - இவற்றுக்கு இடையேயான சரியான வென் படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q20-24.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"நிமிடங்கள் நாட்களுக்குள்ளும், நாட்கள் மாதங்களுக்குள்ளும் அடங்கும் (ஒன்றினுள் ஒன்றாக அமைந்த மூன்று வட்டங்கள்).","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q23","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Star, Sun, Moon - இவற்றுக்கு இடையேயான சரியான வென் படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q20-24.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"சூரியன் (Sun) ஒரு விண்மீன் (Star) ஆகும் (உள் வட்டம்). சந்திரன் (Moon) ஒரு துணைக்கோள், எனவே அது முற்றிலும் தனியாக இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q24","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"Whales, Fish, Crocodiles - இவற்றுக்கு இடையேயான சரியான வென் படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q20-24.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"திமிங்கலம் ஒரு பாலூட்டி, மீன் என்பது நீர்ப்பறவை இனம், முதலை என்பது ஊர்வன இனம். மூன்றும் முற்றிலும் வேறுபட்டவை (மூன்று தனித்தனி வட்டங்கள்).","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q25","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"2AB + AB1 = B18 எனில், A = ?, B = ?","options":[{"id":"A","text":"4, 7"},{"id":"B","text":"7, 4"},{"id":"C","text":"6, 7"},{"id":"D","text":"7, 6"}],"correctOption":"A","explanation":"ஒன்றாம் இலக்கங்களை கூட்டுகையில் B + 1 = 8 என்பதால் B = 7. பத்தாம் இலக்கங்களை கூட்டுகையில் A + B = 1, அதாவது A + 7 = 11 (1 மீதம்) என்பதால் A = 4.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q26","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"PEN = 32, CHALK = 30 எனில், DESK = ?","options":[{"id":"A","text":"34"},{"id":"B","text":"35"},{"id":"C","text":"36"},{"id":"D","text":"39"}],"correctOption":"B","explanation":"தர்க்கம்: எழுத்துகளின் இடமதிப்பு கூடுதல் - (மொத்த எழுத்துக்களின் எண்ணிக்கை). DESK = 4+5+19+11 = 39. நான்கு எழுத்துக்கள் என்பதால் 39 - 4 = 35.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q27","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"EXAMINATION = 24681365173 எனில், TIME = ?","options":[{"id":"A","text":"5182"},{"id":"B","text":"5812"},{"id":"C","text":"8521"},{"id":"D","text":"6821"}],"correctOption":"A","explanation":"ஒவ்வொரு எழுத்துக்கும் அந்தந்த இடத்தில் உள்ள எண்ணை நேரடியாகப் பிரதியிட வேண்டும். T=5, I=1, M=8, E=2. எனவே 5182.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q28","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்தில் உள்ள இணைகரங்களின் எண்ணிக்கை:","questionImage":"/assets/pyq/image/mat_2024/q28.png","options":[{"id":"A","text":"12"},{"id":"B","text":"20"},{"id":"C","text":"29"},{"id":"D","text":"30"}],"correctOption":"D","explanation":"படத்தில் உள்ள சிறிய மற்றும் பெரிய இணைகரங்களை ஒவ்வொன்றாகக் கணக்கிட்டால் மொத்த எண்ணிக்கை 30 ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q29","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்தை உருவாக்கத் தேவைப்படும் குறைந்தபட்ச நேர்க்கோடுகளின் எண்ணிக்கை:","questionImage":"/assets/pyq/image/mat_2024/q29.png","options":[{"id":"A","text":"15"},{"id":"B","text":"13"},{"id":"C","text":"12"},{"id":"D","text":"14"}],"correctOption":"B","explanation":"படத்தில் உள்ள கிடைமட்டக் கோடுகள், செங்குத்துக் கோடுகள் மற்றும் சாய்வுக் கோடுகளை எண்ணினால் குறைந்தபட்ச நேர்க்கோடுகள் 14 ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q30","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பின்வரும் வார்த்தைகளை அர்த்தமுள்ள தொடராக மாற்றுக: (A) Consultation (B) Illness (C) Doctor (D) Treatment (E) Recovery","options":[{"id":"A","text":"(B), (C), (A), (D), (E)"},{"id":"B","text":"(C), (B), (A), (D), (E)"},{"id":"C","text":"(B), (C), (E), (D), (A)"},{"id":"D","text":"(A), (C), (D), (B), (E)"}],"correctOption":"A","explanation":"நிகழ்வுகளின் தர்க்கரீதியான வரிசை: முதலில் நோய் (Illness) -> பின்பு மருத்துவரிடம் செல்லுதல் (Doctor) -> ஆலோசனை (Consultation) -> சிகிச்சை (Treatment) -> இறுதியாக குணமடைதல் (Recovery).","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q31","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள ஆங்கில வார்த்தைகளின் சரியான அகர வரிசையைத் தேர்ந்தெடுக்கவும்: (A) General (B) Gentle (C) Gesture (D) Genuine","options":[{"id":"A","text":"(A), (B), (C), (D)"},{"id":"B","text":"(A), (B), (D), (C)"},{"id":"C","text":"(B), (A), (C), (D)"},{"id":"D","text":"(D), (A), (B), (C)"}],"correctOption":"B","explanation":"அகர வரிசை (Alphabetical order): Gene.. -> Gent.. -> Genu.. -> Gest.. எனவே சரியான வரிசை (A), (B), (D), (C).","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q32","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ARTICULATES என்ற வார்த்தையிலுள்ள எழுத்துக்களை எத்தனை முறை வேண்டுமானாலும் பயன்படுத்தி பின்வரும் வார்த்தைகளில் எதை உருவாக்க இயலாது?","options":[{"id":"A","text":"LATER"},{"id":"B","text":"ARTICLE"},{"id":"C","text":"ELECTRIC"},{"id":"D","text":"COURTS"}],"correctOption":"D","explanation":"COURTS என்ற வார்த்தையில் ''O'' என்ற எழுத்து உள்ளது. ஆனால் மூல வார்த்தையான ARTICULATES-ல் ''O'' இல்லை.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q33","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"குறிப்பு: நான் ஒரு 4 இலக்க எண். நான்காவது இலக்கம் 3-ஐ விடக் குறைவான ஒற்றைப்படை எண். 1-வது இலக்கம் 4-வது இலக்கத்தை விட 5 அதிகம். 2-வது இலக்கம் இரட்டைப்படை பகா எண். முதல் 3 இலக்கங்களின் கூடுதல் 12. நான் யார்?","options":[{"id":"A","text":"6421"},{"id":"B","text":"6242"},{"id":"C","text":"6241"},{"id":"D","text":"6124"}],"correctOption":"C","explanation":"4வது இலக்கம் 3ஐ விட குறைவான ஒற்றை எண் = 1. 1வது இலக்கம் = 1+5=6. 2வது இலக்கம் இரட்டை பகா எண் = 2. முதல் 3 இலக்க கூடுதல் = 6+2+x = 12 => x=4. எனவே அந்த எண் 6241.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q34","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு குறியீட்டு மொழியில்: 1729=all problems are serious, 4367=men have many problems, 1385=some men are happy and, 8069=some have serious ailments எனில், ''Serious men'' என்பதன் குறியீடு:","options":[{"id":"A","text":"93"},{"id":"B","text":"23"},{"id":"C","text":"13"},{"id":"D","text":"98"}],"correctOption":"A","explanation":"''Serious'' என்ற சொல் 1 மற்றும் 4 ஆகிய தொடர்களில் பொதுவானது. அவற்றில் பொதுவான எண் 9. ''Men'' என்ற சொல் 2 மற்றும் 3 ஆகிய தொடர்களில் பொதுவானது. அவற்றின் பொதுவான எண் 3. எனவே விடை 93.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q35","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"KAVERI என்பதை VBKISE எனவும், THANKS என்பதை AITSLN எனவும் குறித்தால் SPIDER என்பதன் குறியீடு:","options":[{"id":"A","text":"ISPRDE"},{"id":"B","text":"IQTRFE"},{"id":"C","text":"IQSRFD"},{"id":"D","text":"IPSRED"}],"correctOption":"C","explanation":"வார்த்தையை இரு பாதியாகப் பிரிக்கவும். SPIDER -> SPI மற்றும் DER. முதல் பாதியைச் சுழற்றி நடு எழுத்துக்கு +1 சேர்க்கவும் (I, P+1=Q, S) -> IQS. இரண்டாம் பாதியைச் சுழற்றி நடு எழுத்துக்கு +1 சேர்க்கவும் (R, E+1=F, D) -> RFD.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q36","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A என்பவர் இடமிருந்து 10-வது இடத்திலும், B என்பவர் வலமிருந்து 9-வது இடத்திலும் உள்ளனர். இருவரும் இடத்தை மாற்றிக் கொண்டதில் A இடமிருந்து 15-வது இடத்தில் உள்ளார். வரிசையில் எத்தனை சிறுவர்கள் உள்ளனர்?","options":[{"id":"A","text":"23"},{"id":"B","text":"31"},{"id":"C","text":"27"},{"id":"D","text":"28"}],"correctOption":"A","explanation":"மொத்த நபர்கள் = (A-ன் புதிய இடம்) + (B-ன் பழைய இடம்) - 1 = 15 + 9 - 1 = 23.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q37","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கீழே கொடுக்கப்பட்டுள்ள தகவல்களை கவனமாகப் படித்து வினாக்களுக்கு விடையளிக்கவும்.\n(i) A, B, C, D, E மற்றும் F ஆகிய ஆறு நண்பர்கள் வட்ட வடிவில் சம தொலைவில் அமர்ந்துள்ளனர்.\n(ii) A என்பார் B -க்கு வலப்பக்கமாக இரண்டாமிடத்தில் அமர்ந்துள்ளார். அதே நேரத்தில் B என்பார் C -க்கு நேர் எதிராக அமர்ந்துள்ளார்.\n(iii) C என்பார் D -க்கு இடப்பக்கமாக அவரைத் தொடர்ந்து உள்ளார். மேலும் E -க்கு நேர் எதிராக D உள்ளார்.\n(iv) $F$ என்பவரும் வட்டத்தில் அமர்ந்துள்ளார்.\n\n எனில், A-ன் இடப்பக்கம் அமர்ந்திருப்பவர் யார்?","options":[{"id":"A","text":"B"},{"id":"B","text":"E"},{"id":"C","text":"F"},{"id":"D","text":"C"}],"correctOption":"B","explanation":"வட்ட வரிசை: C, D, F, B, E, A. இதன் அடிப்படையில் A-க்கு இடப்புறம் அமைந்திருப்பவர் E ஆவார்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q38","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கீழே கொடுக்கப்பட்டுள்ள தகவல்களை கவனமாகப் படித்து வினாக்களுக்கு விடையளிக்கவும்.\n(i) A, B, C, D, E மற்றும் F ஆகிய ஆறு நண்பர்கள் வட்ட வடிவில் சம தொலைவில் அமர்ந்துள்ளனர்.\n(ii) A என்பார் B -க்கு வலப்பக்கமாக இரண்டாமிடத்தில் அமர்ந்துள்ளார். அதே நேரத்தில் B என்பார் C -க்கு நேர் எதிராக அமர்ந்துள்ளார்.\n(iii) C என்பார் D -க்கு இடப்பக்கமாக அவரைத் தொடர்ந்து உள்ளார். மேலும் E -க்கு நேர் எதிராக D உள்ளார்.\n(iv) $F$ என்பவரும் வட்டத்தில் அமர்ந்துள்ளார்.\n\n எனில், D-யிலிருந்து கடிகார முள் திசையில் அமர்ந்துள்ளவர்களின் வரிசை:","options":[{"id":"A","text":"DCAEBF"},{"id":"B","text":"DFBEAC"},{"id":"C","text":"DCEBFA"},{"id":"D","text":"DAFBEC"}],"correctOption":"A","explanation":"உருவாக்கப்பட்ட வட்ட வரிசையின் அடிப்படையில், D-யிலிருந்து கடிகாரத் திசையில் பார்த்தால் வரிசை D -> F -> B -> E -> A -> C என இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q39","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஜனவரி 1, 2006 ஞாயிற்றுக்கிழமை எனில், ஜனவரி 1, 2010 என்ன கிழமை?","options":[{"id":"A","text":"வியாழக்கிழமை"},{"id":"B","text":"சனிக்கிழமை"},{"id":"C","text":"வெள்ளிக்கிழமை"},{"id":"D","text":"புதன்கிழமை"}],"correctOption":"C","explanation":"ஆண்டுகளில் உள்ள ஒற்றை நாட்கள் (Odd days) = 1 (2006) + 1 (2007) + 2 (லீப் ஆண்டு 2008) + 1 (2009) = 5 நாட்கள். எனவே ஞாயிறு + 5 நாட்கள் = வெள்ளிக்கிழமை.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q40","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"30 நாட்கள் கொண்ட ஒரு மாதத்தில் சனிக்கிழமை முதல் நாள் ஆகிறது. 2வது, 4வது சனிக்கிழமை மற்றும் அனைத்து ஞாயிற்றுக்கிழமைகளும் விடுமுறை எனில் வேலைநாட்கள் எத்தனை?","options":[{"id":"A","text":"20"},{"id":"B","text":"21"},{"id":"C","text":"23"},{"id":"D","text":"22"}],"correctOption":"C","explanation":"சனிக்கிழமை: 1, 8, 15, 22, 29. ஞாயிறு: 2, 9, 16, 23, 30 (5 நாட்கள்). 2வது சனி(8), 4வது சனி(22). மொத்த விடுமுறை: 5 ஞாயிறு + 2 சனி = 7. வேலை நாட்கள் = 30-7=23.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q41","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு குழுவில் பசுக்கள், கோழிகள் உள்ளன. கால்களின் எண்ணிக்கை தலைகளின் இரு மடங்கை விட 14 அதிகம் எனில் பசுக்களின் எண்ணிக்கை:","options":[{"id":"A","text":"5"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"10"}],"correctOption":"C","explanation":"பசு (C), கோழி (H). 4C + 2H = 2(C+H) + 14. இதை சுருக்கினால், 4C + 2H = 2C + 2H + 14 => 2C = 14 => C = 7. எனவே பசுக்களின் எண்ணிக்கை 7.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q42","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"237965320184 என்ற எண்ணின் ஒவ்வொரு இலக்கத்தையும் ஏறுவரிசையில் எழுதும்போது எத்தனை இலக்கங்கள் மீண்டும் அதே இடத்தில் அமையும்?","options":[{"id":"A","text":"4"},{"id":"B","text":"3"},{"id":"C","text":"2"},{"id":"D","text":"1"}],"correctOption":"D","explanation":"பழைய எண்ணையும், அதனை ஏறுவரிசையில் அமைத்த எண்ணையும் ஒப்பிட்டுப் பார்த்தால், 11வது இடத்தில் மட்டுமே ''8'' இரண்டு முறை சரியாகப் பொருந்தும். எனவே 1 இலக்கம் மட்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q43","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"50 வினாக்களுக்கு சரியான விடைக்கு +2 மதிப்பெண், தவறான விடைக்கு -1 மதிப்பெண் வழங்கப்படுகிறது. ஒரு மாணவர் 55 மதிப்பெண்கள் பெற்றார் எனில் அவர் தவறாக விடையளித்த வினாக்கள் எத்தனை?","options":[{"id":"A","text":"20"},{"id":"B","text":"15"},{"id":"C","text":"25"},{"id":"D","text":"28"}],"correctOption":"B","explanation":"சரியான விடை (C), தவறான விடை (W). C + W = 50. 2C - W = 55. இரண்டையும் கூட்டினால் 3C = 105 => C = 35. மொத்தம் 50 கேள்விகள் என்பதால், தவறானவை W = 50 - 35 = 15.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q44","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட எழுத்துக்களைத் தேர்ந்தெடுக்கவும்: abc_abc_ bbcca_c_aaabc ","options":[{"id":"A","text":"aabc"},{"id":"B","text":"abca"},{"id":"C","text":"abbc"},{"id":"D","text":"abcc"}],"correctOption":"B","explanation":"எழுத்துக்கள் ஒரு குறிப்பிட்ட சுழற்சி முறையில் (Cyclic pattern - எ.கா aab, bbc, cca) மீண்டும் மீண்டும் வருவதைக் கொண்டு விடுபட்டதைக் கண்டறியலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q45","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"சமன்பாடு சரியாக அமையும் வகையில் குறியீடுகளின் சரியான வரிசையைத் தேர்ந்தெடுக்கவும்: 5 = 15 ÷ 9 x 84","options":[{"id":"A","text":"x, +, ="},{"id":"B","text":"+, x, ÷"},{"id":"C","text":"÷, x, +"},{"id":"D","text":"x, =, +"}],"correctOption":"A","explanation":"BODMAS விதியைப் பயன்படுத்தி கொடுக்கப்பட்ட குறியீடுகளைப் பிரதியிட்டால் சமன்பாடு சரியாக அமையும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q46","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"''+'' என்பது ''÷'' எனவும், ''÷'' என்பது ''x'' எனவும், ''x'' என்பது ''-'' எனவும், ''-'' என்பது ''+'' எனவும் கொண்டால், பின்வருவனவற்றுள் எது சரியானது?","options":[{"id":"A","text":"18 ÷ 6 - 7 + 5 x 2 = 20"},{"id":"B","text":"18 + 6 ÷ 7 x 5 - 2 = 18"},{"id":"C","text":"18 x 6 + 7 ÷ 5 - 2 = 16"},{"id":"D","text":"18 ÷ 6 x 7 + 5 - 2 = 22"}],"correctOption":"B","explanation":"இரண்டாவது விருப்பத்தில் குறியீடுகளை மாற்றினால்: 18 ÷ 6 x 7 - 5 + 2 = 3 * 7 - 5 + 2 = 21 - 5 + 2 = 18. இது சரியாக பொருந்துகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q47","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"''p'' என்பது ''-'', ''q'' என்பது ''+'', ''r'' என்பது ''x'' மற்றும் ''s'' என்பது ''÷'' எனில், 18 p 4 r 6 s 2 q 3 = ?","options":[{"id":"A","text":"6"},{"id":"B","text":"8"},{"id":"C","text":"9"},{"id":"D","text":"10"}],"correctOption":"C","explanation":"குறியீடுகளை மாற்றினால்: 18 - 4 x 6 ÷ 2 + 3. BODMAS விதியின்படி: 18 - 4 x 3 + 3 = 18 - 12 + 3 = 9.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q48","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"16*9=12, 81*49=63 மற்றும் 25*16=20 எனில், 36*9 = ?","options":[{"id":"A","text":"16"},{"id":"B","text":"18"},{"id":"C","text":"20"},{"id":"D","text":"24"}],"correctOption":"B","explanation":"தர்க்கம்: எண்களைப் பெருக்கி அதன் வர்க்கமூலம் காணுதல் (அல்லது தனித்தனியாக வர்க்கமூலம் கண்டு பெருக்குதல்). √(36*9) = √324 = 18. (அல்லது √36 * √9 = 6 * 3 = 18).","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q49","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"1+2=3, 2+3=17 மற்றும் 2+4=32 எனில், 3+4 = ?","options":[{"id":"A","text":"73"},{"id":"B","text":"91"},{"id":"C","text":"155"},{"id":"D","text":"145"}],"correctOption":"D","explanation":"தர்க்கம்: (a^b) + (b^a). முதல் எண்களுக்கு: 1² + 2¹ = 1+2 = 3. இரண்டாவது: 2³ + 3² = 8+9 = 17. அதேபோல் 3+4 = 3⁴ + 4³ = 81 + 64 = 145.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q50","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்தில் முக்கோணம் தொழிற்சாலை பணியாளர்களையும், வட்டம் தொழிற்சங்க உறுப்பினர்களையும், சதுரம் கடின உழைப்பாளர்களையும் குறிக்கிறது எனில், பின்வரும் வினாக்களுக்கு விடையளிக்கவும். படத்தில் தொழிற்சாலை பணியாளர்களில் தொழிற்சங்க உறுப்பினர்களாக இருந்து, கடின உழைப்பாளர்கள் அல்லாதவர்கள் யார்?","questionImage":"/assets/pyq/image/mat_2024/q50-54.png","options":[{"id":"A","text":"g"},{"id":"B","text":"f"},{"id":"C","text":"d"},{"id":"D","text":"b"}],"correctOption":"A","explanation":"தொழிற்சாலை பணியாளர்கள் (முக்கோணம்) மற்றும் தொழிற்சங்க உறுப்பினர் (வட்டம்) ஆகிய இரண்டுக்கும் பொதுவானதும், சதுரத்திற்கு (கடின உழைப்பாளர்) வெளியே உள்ளதும் ''g'' ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q51","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்தில் முக்கோணம் தொழிற்சாலை பணியாளர்களையும், வட்டம் தொழிற்சங்க உறுப்பினர்களையும், சதுரம் கடின உழைப்பாளர்களையும் குறிக்கிறது எனில், பின்வரும் வினாக்களுக்கு விடையளிக்கவும். படத்தில் தொழிற்சாலை பணியாளர்களல்லாத, கடினமாக உழைக்கும், தொழிற்சங்க உறுப்பினர்கள்:","questionImage":"/assets/pyq/image/mat_2024/q50-54.png","options":[{"id":"A","text":"d"},{"id":"B","text":"f"},{"id":"C","text":"c"},{"id":"D","text":"e"}],"correctOption":"A","explanation":"வட்டம் (தொழிற்சங்க உறுப்பினர்) மற்றும் சதுரத்திற்குப் (கடின உழைப்பாளர்) பொதுவானதும், முக்கோணத்திற்கு (பணியாளர்கள்) வெளியே உள்ளதும் ''d'' ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q52","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்தில் முக்கோணம் தொழிற்சாலை பணியாளர்களையும், வட்டம் தொழிற்சங்க உறுப்பினர்களையும், சதுரம் கடின உழைப்பாளர்களையும் குறிக்கிறது எனில், பின்வரும் வினாக்களுக்கு விடையளிக்கவும். கடினமாக உழைக்காத, தொழிற்சங்க உறுப்பினரல்லாத தொழிற்சாலை பணியாளர்கள்:","questionImage":"/assets/pyq/image/mat_2024/q50-54.png","options":[{"id":"A","text":"c"},{"id":"B","text":"d"},{"id":"C","text":"b"},{"id":"D","text":"a"}],"correctOption":"D","explanation":"முக்கோணத்தில் (தொழிற்சாலை பணியாளர்) மட்டும் இருப்பதும், வட்டம் மற்றும் சதுரத்திற்குத் தொடர்பில்லாததும் ''a'' ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q53","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்தில் முக்கோணம் தொழிற்சாலை பணியாளர்களையும், வட்டம் தொழிற்சங்க உறுப்பினர்களையும், சதுரம் கடின உழைப்பாளர்களையும் குறிக்கிறது எனில், பின்வரும் வினாக்களுக்கு விடையளிக்கவும். தொழிற்சாலை பணியாளர்களில் தொழிற்சங்க உறுப்பினர்களாக இருக்கும் கடின உழைப்பாளர்கள்:","questionImage":"/assets/pyq/image/mat_2024/q50-54.png","options":[{"id":"A","text":"a"},{"id":"B","text":"f"},{"id":"C","text":"c"},{"id":"D","text":"b"}],"correctOption":"B","explanation":"முக்கோணம், வட்டம் மற்றும் சதுரம் ஆகிய மூன்றிற்கும் பொதுவாக மையத்தில் அமைந்த பகுதி ''f'' ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q54","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்தில் முக்கோணம் தொழிற்சாலை பணியாளர்களையும், வட்டம் தொழிற்சங்க உறுப்பினர்களையும், சதுரம் கடின உழைப்பாளர்களையும் குறிக்கிறது எனில், பின்வரும் வினாக்களுக்கு விடையளிக்கவும். கடின உழைப்பாளரல்லாத, தொழிற்சாலை பணியாளரல்லாத தொழிற்சங்க உறுப்பினர்கள்:","questionImage":"/assets/pyq/image/mat_2024/q50-54.png","options":[{"id":"A","text":"f"},{"id":"B","text":"h"},{"id":"C","text":"b"},{"id":"D","text":"d"}],"correctOption":"C","explanation":"வட்டத்தில் (தொழிற்சங்க உறுப்பினர்) மட்டும் இருப்பதும், முக்கோணம் மற்றும் சதுரத்திற்கு வெளியே உள்ளதும் ''b'' ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q55","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A, B, C, D மற்றும் E என்னும் 5 நண்பர்களில், A என்பவர் B-யை விட உயரம் குறைவானவர் ஆனால் E-யை விட உயரமானவர். C என்பவர் மிகவும் உயரமானவர். D என்பவர் B-ஐ விட உயரம் குறைவாகவும் A-ஐ விட உயரமாகவும் உள்ளார். உயரம் ஏறுவரிசையில் நடுவில் இருப்பவர் யார்?","options":[{"id":"A","text":"E"},{"id":"B","text":"D"},{"id":"C","text":"B"},{"id":"D","text":"A"}],"correctOption":"B","explanation":"கொடுக்கப்பட்ட தகவல்களின் அடிப்படையில் ஏறுவரிசை: E < A < D < B < C. இதில் 5 பேரில் நடுவில் இருப்பது D ஆவார்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q56","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A, B, C, D மற்றும் E என்னும் 5 நண்பர்களில், A என்பவர் B-யை விட உயரம் குறைவானவர் ஆனால் E-யை விட உயரமானவர். C என்பவர் மிகவும் உயரமானவர். D என்பவர் B-ஐ விட உயரம் குறைவாகவும் A-ஐ விட உயரமாகவும் உள்ளார். A-ஐ விட உயரமாகவும் C-ஐ விட உயரம் குறைவாகவும் உள்ளவர்(கள்):","options":[{"id":"A","text":"B"},{"id":"B","text":"B, E"},{"id":"C","text":"D, E"},{"id":"D","text":"B, D"}],"correctOption":"D","explanation":"உருவாக்கப்பட்ட ஏறுவரிசையில் (E < A < D < B < C) A-க்கும் C-க்கும் இடையில் D மற்றும் B உள்ளனர்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q57","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A, B, C, D மற்றும் E என்னும் 5 நண்பர்களில், A என்பவர் B-யை விட உயரம் குறைவானவர் ஆனால் E-யை விட உயரமானவர். C என்பவர் மிகவும் உயரமானவர். D என்பவர் B-ஐ விட உயரம் குறைவாகவும் A-ஐ விட உயரமாகவும் உள்ளார். ஏறுவரிசையில் A-யும் C-யும் தங்களது இடத்தை மாற்றிக் கொள்கின்றனர் எனில் C-ன் தற்போதைய நிலை:","options":[{"id":"A","text":"நடுவில்"},{"id":"B","text":"இடமிருந்து இரண்டாமிடம்"},{"id":"C","text":"வலமிருந்து இரண்டாமிடம்"},{"id":"D","text":"இறுதியில்"}],"correctOption":"B","explanation":"A மற்றும் C இடத்தை மாற்றினால் வரிசை: E < C < D < B < A என்றாகும். எனவே C இடமிருந்து இரண்டாமிடத்திற்கு வந்துவிடுவார்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q58","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பகடையின் அடிப்பக்கம் 2 எனில், மேல் பக்கத்தில் உள்ள எண்:","questionImage":"/assets/pyq/image/mat_2024/q58.png","options":[{"id":"A","text":"4"},{"id":"B","text":"3"},{"id":"C","text":"6"},{"id":"D","text":"1"}],"correctOption":"D","explanation":"பகடையின் படங்களை ஒப்பிட்டுப் பார்க்கும்போது, 2-க்கு எதிரான (மேல்) பக்கத்தில் 1 இருக்கும் என்பதை அறியலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q59","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A என்பவர் B-ஐ விட 2 வயது மூத்தவர். B-ன் வயது C-ஐ போல் இருமடங்காகும். மூவரின் வயதுகளின் கூடுதல் 27 எனில், B-ன் வயது என்ன?","options":[{"id":"A","text":"10"},{"id":"B","text":"7"},{"id":"C","text":"8"},{"id":"D","text":"9"}],"correctOption":"A","explanation":"A = B + 2, B = 2C. இதனை பிரதியிட்டால்: (2C+2) + 2C + C = 27. 5C = 25 -> C=5. எனவே B = 2*5 = 10.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q60","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு சந்திப்பின் போது 11 பேர் ஒவ்வொருவரும் ஒருமுறை கை குலுக்கிக் கொள்கின்றனர் எனில், மொத்தம் எத்தனை கைகுலுக்கல்கள் நிகழும்?","options":[{"id":"A","text":"44"},{"id":"B","text":"45"},{"id":"C","text":"50"},{"id":"D","text":"55"}],"correctOption":"D","explanation":"கைகுலுக்கல்களின் எண்ணிக்கையை அறிய வாய்ப்பாடு: n(n-1)/2. இங்கு n=11. எனவே 11*10/2 = 110/2 = 55.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q61","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"புகைப்படத்திலுள்ள பெண்ணைக்காட்டி, சாந்தி ''அவளின் மகனின் தந்தை என் தாயின் மருமகன்'' என்றார். அந்தப் பெண் சாந்திக்கு என்ன உறவு?","options":[{"id":"A","text":"அத்தை"},{"id":"B","text":"சகோதரி"},{"id":"C","text":"தாய்"},{"id":"D","text":"சகோதரனின் மகள்"}],"correctOption":"B","explanation":"சாந்தியின் தாயின் மருமகன் என்பது சாந்தியின் கணவராகவோ அல்லது சகோதரியின் கணவராகவோ இருக்கலாம். புகைப்படத்தில் உள்ள பெண் சாந்தியாகவோ அல்லது அவரது சகோதரியாகவோ இருக்கலாம். (விருப்பங்களில் சகோதரி உள்ளது).","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q62","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"நான் கிழக்கு திசையை நோக்கி உள்ளேன். கடிகாரத் திசையில் 100° திரும்பி, பின்னர் 145° எதிர்த்திசையில் திரும்புகிறேன். நான் தற்போது எத்திசையை நோக்கி உள்ளேன்?","options":[{"id":"A","text":"கிழக்கு"},{"id":"B","text":"வட கிழக்கு"},{"id":"C","text":"வடக்கு"},{"id":"D","text":"தென் மேற்கு"}],"correctOption":"B","explanation":"நிகர கோண சுழற்சி = 100° (கடிகார திசை) - 145° (எதிர்த்திசை) = -45° (அதாவது 45° கடிகார எதிர்த்திசை). கிழக்கு திசையிலிருந்து 45° எதிர்த்திசை என்பது வட கிழக்கு (North-East) ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q63","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ரவி மேற்கு நோக்கி 2 கி.மீ நடக்கிறார். தெற்கு திசையில் திரும்பி 4 கி.மீ பயணிக்கிறார். மீண்டும் 3 கி.மீ கிழக்கிலும் 1 கி.மீ மேற்கிலும் நடந்தால், அவர் ஆரம்பித்த இடத்திலிருந்து எவ்வளவு தொலைவில் உள்ளார்?","options":[{"id":"A","text":"10 கி.மீ"},{"id":"B","text":"4 கி.மீ"},{"id":"C","text":"2 கி.மீ"},{"id":"D","text":"5 கி.மீ"}],"correctOption":"B","explanation":"மேற்கு-கிழக்கு நகர்வுகள்: -2 (மேற்கு) + 3 (கிழக்கு) - 1 (மேற்கு) = 0. எனவே அவர் கிழக்கு/மேற்கு திசையில் நகரவில்லை. தெற்கு நகர்வு மட்டும் 4 கி.மீ. எனவே அவர் புறப்பட்ட இடத்திலிருந்து நேர்கீழாக 4 கி.மீ தொலைவில் உள்ளார்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q64","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கடிகாரத்தில் நிமிட முள் 12 மணிக்கு கிழக்கு திசையை நோக்கி உள்ளது எனில் 4.30 மணிக்கு மணி முள் எத்திசையை நோக்கி இருக்கும்?","options":[{"id":"A","text":"வட மேற்கு"},{"id":"B","text":"தென் கிழக்கு"},{"id":"C","text":"தென் மேற்கு"},{"id":"D","text":"தெற்கு"}],"correctOption":"C","explanation":"சாதாரண கடிகாரத்தில் 12 மணி முள் வடக்கு நோக்கி இருக்கும். ஆனால் இங்கு கிழக்கு நோக்கி உள்ளதாகக் கூறப்பட்டுள்ளது (அதாவது அனைத்து திசைகளும் 90° வலப்புறம் திரும்பியுள்ளன). சாதாரணமாக 4.30 மணி முள் தென்கிழக்கில் இருக்கும். அதனை 90° வலப்புறம் திருப்பினால் அது தென் மேற்கு திசையாகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q65","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"6.30 மணி அளவில் மணி முள்ளிற்கும், நிமிட முள்ளிற்கும் இடைப்பட்ட கோணம்:","options":[{"id":"A","text":"180°"},{"id":"B","text":"30°"},{"id":"C","text":"0°"},{"id":"D","text":"15°"}],"correctOption":"D","explanation":"முட்களுக்கு இடைப்பட்ட கோணத்தைக் காணும் சூத்திரம்: |30H - 5.5M|. இங்கு H=6, M=30. |30*6 - 5.5*30| = |180 - 165| = 15°.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q66","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தவறான எண்ணைக் கண்டறியவும்: 7, 28, 63, 124, 215, 342, 511","options":[{"id":"A","text":"342"},{"id":"B","text":"28"},{"id":"C","text":"124"},{"id":"D","text":"215"}],"correctOption":"B","explanation":"தொடரின் தர்க்கம்: n³-1. அதாவது 2³-1=7, 4³-1=63, 5³-1=124. ஆனால் 3³-1 = 26 வரவேண்டும், இங்கு 28 உள்ளது. எனவே 28 தவறானது.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q67","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வார்த்தைகளை அகர வரிசைப்படுத்தினால் வலதுபுறத்திலிருந்து இரண்டாவதாக வரும் வார்த்தை: page, pagan, palisade, pageant, palace","options":[{"id":"A","text":"Pageant"},{"id":"B","text":"Palisade"},{"id":"C","text":"Palace"},{"id":"D","text":"Pagan"}],"correctOption":"C","explanation":"அகர வரிசையில் அமைத்தால்: 1. pagan, 2. page, 3. pageant, 4. palace, 5. palisade. வலமிருந்து (பின்புறமிருந்து) இரண்டாவதாக வருவது 4-வது வார்த்தையான palace.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q68","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"(56)^75 என்னும் எண்ணின் விரிவில் அமையும் ஒன்றாம் இலக்க எண்:","options":[{"id":"A","text":"6"},{"id":"B","text":"3"},{"id":"C","text":"4"},{"id":"D","text":"2"}],"correctOption":"A","explanation":"எண் 6-ல் முடியும் எந்த ஒரு எண்ணின் அடுக்காக (Power) எந்த எண் வந்தாலும், அதன் விடையின் ஒன்றாம் இலக்கம் எப்போதும் 6-ஆகவே இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q69","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடர்ந்து வரவேண்டிய படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q69.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"படங்களில் உள்ள அமைப்புகள் ஒரு குறிப்பிட்ட கோணத்தில் கடிகாரத் திசையில் அல்லது எதிர்த்திசையில் சுழல்வதைக் கவனித்து அடுத்த படத்தைத் தேர்ந்தெடுக்க வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q70","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடர்ந்து வரவேண்டிய படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q70.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"ஒவ்வொரு கட்டத்திலும் குறியீடுகளின் எண்ணிக்கை மாறுபடுவதையோ அல்லது அவற்றின் திசை மாறுவதையோ கவனித்து விடை காண வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q71","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடர்ந்து வரவேண்டிய படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q71.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"வரிசையாகப் பார்க்கும்போது குறியீடுகள் மேல்நோக்கி அல்லது கீழ்நோக்கி நகர்ந்து புதிய குறியீடுகள் தோன்றுவதைப் புரிந்துகொண்டு அடுத்ததைக் கணிக்கலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q72","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடர்ந்து வரவேண்டிய படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q72.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"கிடைமட்ட மற்றும் செங்குத்து வரிசைகளில் உள்ள குறியீடுகளை கவனித்தால், ஒவ்வொரு நிரலிலும் குறிப்பிட்ட அமைப்புகள் மீண்டும் வருவது தெரியும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q73","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடர்ந்து வரவேண்டிய படத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q73.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"வடிவங்களின் பக்கங்களின் எண்ணிக்கை மற்றும் கொடுக்கப்பட்ட எண்களுக்கு இடையேயான கணிதத் தொடர்பைக் கண்டறிய வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q74","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடர்பின் அடிப்படையில் விடுபட்ட ஒன்றைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q74.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"முதல் படத்திற்கும் இரண்டாம் படத்திற்கும் உள்ள தர்க்க ரீதியான மாற்றத்தை (சுழற்சி, இடமாற்றம், புதிய வடிவம்) மூன்றாவது படத்திற்குப் பயன்படுத்தினால் விடை கிடைக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q75","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடர்பின் அடிப்படையில் விடுபட்ட ஒன்றைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q75.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"முதல் இரண்டு படங்களுக்கிடையே உள்ள வடிவ மாற்றத் தொடர்பைப் புரிந்து கொண்டு, விடுபட்ட 4-வது படத்தைக் கணிக்க வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q76","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடர்பின் அடிப்படையில் விடுபட்ட ஒன்றைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q76.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"படங்களின் சுழற்சி மற்றும் உள்ளே இருக்கும் சிறு குறியீடுகளின் இடமாற்றங்களை கவனித்து விடையளிக்க வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q77","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தொடர்பின் அடிப்படையில் விடுபட்ட ஒன்றைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q77.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"ஒப்புமை (Analogy) தர்க்கத்தின்படி, மூன்றாம் படத்தில் அதே மாற்றத்தை அப்ளை செய்து சரியான விடையைத் தேர்க.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q78","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட முழுமையாக்கும் பகுதியினைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q78.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"கொடுக்கப்பட்ட படத்தின் அமைப்பை முழுமையாக்க, விடுபட்ட பகுதியில் உள்ள கோடுகள் மற்றும் வடிவங்கள் எவ்வாறு பொருந்த வேண்டும் எனப் பார்க்க வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q79","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட முழுமையாக்கும் பகுதியினைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q79.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"சமச்சீர் (Symmetry) தர்க்கத்தின் அடிப்படையில் மற்ற மூன்று கால்பகுதிகளைக் கொண்டு விடுபட்ட கால்பகுதியைக் கணிக்க வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q80","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட முழுமையாக்கும் பகுதியினைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q80.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"மையப்பகுதியை இணைக்கும் கோடுகளின் வடிவமைப்பைப் பொறுத்து எந்தப் படம் சரியாகப் பொருந்தும் எனக் கண்டறியலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q81","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கண்ணாடி பிம்பத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q81.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"ஒரு பொருளைக் கண்ணாடியில் பார்க்கும்போது அதன் இடது மற்றும் வலது புறங்கள் இடம் மாறியிருக்கும். அதன்படி விடையைத் தேர்ந்தெடுக்கவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q82","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கண்ணாடி பிம்பத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q82.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"கண்ணாடிப் பிம்பத்தில் எழுத்துக்கள் அல்லது குறியீடுகள் இடவலமாக (Lateral inversion) மாறியிருப்பதை கவனிக்கவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q83","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தண்ணீர் பிம்பத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q83.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"தண்ணீர்ப் பிம்பத்தில் ஒரு பொருளின் மேல் பகுதி கீழாகவும், கீழ் பகுதி மேலாகவும் தலைகீழாகத் (Vertical inversion) தெரியும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q84","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தண்ணீர் பிம்பத்தைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q84.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"படத்தின் அடியில் உள்ள கோடுகள் மேல்நோக்கியும், மேல் உள்ளவை கீழ்நோக்கியும் தோன்றுவதைக் கொண்டு சரியான பிம்பத்தைக் கண்டறியலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q85","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q85.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"நான்கு படங்களில் மூன்று படங்கள் ஒரு குறிப்பிட்ட பண்பில் ஒத்திருக்கும். விடைப் படம் மட்டும் வேறுபட்ட தர்க்கத்தைக் கொண்டிருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q86","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q86.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"படங்களில் உள்ள கோடுகளின் எண்ணிக்கை அல்லது சுழற்சியைக் கவனித்தால், ஒன்று மட்டும் அந்த பொதுவான விதியைப் பின்பற்றாது.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q87","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q87.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"வடிவமைப்புகளுக்கு உள்ளேயும் வெளியேயும் உள்ள குறியீடுகளின் தொடர்பைக் கொண்டு பொருந்தாததைக் கண்டுபிடிக்கலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q88","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q88.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"படத்தில் கருப்படிக்கப்பட்ட (Shaded) பகுதிகள் எந்த வரிசையில் அமைந்துள்ளன என்பதைக் கவனித்தால் மாறுபட்ட ஒன்றைக் கண்டறியலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q89","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q89.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"இதுவும் ஒரு Odd-One-Out கேள்வி. மூன்று படங்கள் சுழற்சி மூலம் ஒன்றையொன்று ஒத்திருக்கும், ஒன்று மட்டும் எதிர்ப்புறமாக இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2024-mat-q90","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படம் (X) எந்தப் படத்தில் பதிக்கப்பட்டுள்ளது என்பதைத் தேர்ந்தெடுக்கவும்:","questionImage":"/assets/pyq/image/mat_2024/q90.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"கேள்வியில் உள்ள (X) படமானது, கொடுக்கப்பட்டுள்ள நான்கு விடைப் படங்களில் ஏதேனும் ஒன்றிற்குள் உள்ளடக்கமாக (மறைந்து/Embedded) காணப்படுகிறது.","marks":1,"negativeMarks":0}]', '2024-01-01T00:00:00.000Z');
INSERT OR REPLACE INTO quizzes (id, title, description, duration_minutes, total_marks, pass_percentage, shuffle_questions, shuffle_options, enable_anti_cheat, status, questions, created_at) VALUES ('pyq-2025-mat', 'NMMS 2025 - MAT (மனத்திறன் தேர்வு - Mental Ability Test)', 'Official NMMS 2025 Mental Ability Test (MAT) with 90 official previous year questions.', 90, 90, 40, 0, 0, 1, 'draft', '[{"id":"pyq-2025-mat-q1","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தங்கம், உலோகம், துத்தநாகம் - இவற்றுக்கு இடையேயான தொடர்பைக் குறிக்கும் வென் படம் எது?","questionImage":"/assets/pyq/image/mat_2025/q1-5.png","options":[{"id":"A","text":"A"},{"id":"B","text":"B"},{"id":"C","text":"C"},{"id":"D","text":"D"}],"correctOption":"A","explanation":"தங்கம் மற்றும் துத்தநாகம் ஆகிய இரண்டும் உலோகங்கள். ஆனால், அவை இரண்டும் வெவ்வேறானவை. எனவே, ஒரு பெரிய வட்டத்தினுள் (உலோகம்) இரண்டு சிறிய தனித்தனி வட்டங்கள் (தங்கம், துத்தநாகம்) அமையும் (படம் C).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q2","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தேர்வுகள், வினாக்கள், பயிற்சிகள் - இவற்றுக்கு இடையேயான தொடர்பைக் குறிக்கும் வென் படம் எது?","questionImage":"/assets/pyq/image/mat_2025/q1-5.png","options":[{"id":"A","text":"A"},{"id":"B","text":"B"},{"id":"C","text":"C"},{"id":"D","text":"D"}],"correctOption":"D","explanation":"வினாக்கள் என்பது தேர்வுகள் மற்றும் பயிற்சிகள் ஆகிய இரண்டிலும் இடம்பெறும். எனவே, மூன்று வட்டங்களும் ஒன்றையொன்று வெட்டிக்கொள்ளும் அமைப்பாகும் (படம் B).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q3","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விகிதமுறு எண்கள், பின்னங்கள், முழுக்கள் - இவற்றுக்கு இடையேயான தொடர்பைக் குறிக்கும் வென் படம் எது?","questionImage":"/assets/pyq/image/mat_2025/q1-5.png","options":[{"id":"A","text":"A"},{"id":"B","text":"E"},{"id":"C","text":"C"},{"id":"D","text":"D"}],"correctOption":"B","explanation":"பின்னங்கள் மற்றும் முழுக்கள் ஆகிய இரண்டும் விகிதமுறு எண்கள் ஆகும். ஆனால் பின்னங்கள் வேறு, முழுக்கள் வேறு. எனவே, ஒரு பெரிய வட்டத்தினுள் இரு தனித்தனி வட்டங்கள் அமையும் (படம் C).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q4","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"மணல், நீர், காற்று - இவற்றுக்கு இடையேயான தொடர்பைக் குறிக்கும் வென் படம் எது?","questionImage":"/assets/pyq/image/mat_2025/q1-5.png","options":[{"id":"A","text":"B"},{"id":"B","text":"D"},{"id":"C","text":"C"},{"id":"D","text":"E"}],"correctOption":"C","explanation":"மணல், நீர், காற்று ஆகிய மூன்றும் தங்களுக்குள் எந்தத் தொடர்பும் இல்லாத முற்றிலும் வெவ்வேறான பொருட்கள். எனவே, மூன்று தனித்தனி வட்டங்கள் அமையும் (படம் E).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q5","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வகுப்பறை, கரும்பலகை, பள்ளி - இவற்றுக்கு இடையேயான தொடர்பைக் குறிக்கும் வென் படம் எது?","questionImage":"/assets/pyq/image/mat_2025/q1-5.png","options":[{"id":"A","text":"A"},{"id":"B","text":"C"},{"id":"C","text":"D"},{"id":"D","text":"B"}],"correctOption":"D","explanation":"பள்ளிக்குள் வகுப்பறை இருக்கும், வகுப்பறையினுள் கரும்பலகை இருக்கும். எனவே, ஒன்றனுள் ஒன்றாக அமைந்த மூன்று வட்டங்கள் அமையும் (படம் A).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q6","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைக் கண்டறியவும்: 7:22, 8:33, 12:37, 15:46","options":[{"id":"A","text":"7:22"},{"id":"B","text":"8:33"},{"id":"C","text":"12:37"},{"id":"D","text":"15:46"}],"correctOption":"B","explanation":"தர்க்கம்: (முதல் எண் × 3) + 1 = இரண்டாம் எண். (7×3+1=22), (12×3+1=37), (15×3+1=46). ஆனால் 8×3+1 = 25 வர வேண்டும், இங்கு 33 உள்ளது. எனவே 8:33 பொருந்தாதது.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q7","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைக் கண்டறியவும்: 113, 123, 157, 139","options":[{"id":"A","text":"113"},{"id":"B","text":"123"},{"id":"C","text":"157"},{"id":"D","text":"139"}],"correctOption":"B","explanation":"113, 157, 139 ஆகியவை பகா எண்கள் (Prime numbers). ஆனால் 123 என்பது 3-ஆல் வகுபடும் ஒரு பகு எண் (Composite number).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q8","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைக் கண்டறியவும்: நிலா, பூமி, கால்பந்து, வளையல்","options":[{"id":"A","text":"நிலா"},{"id":"B","text":"பூமி"},{"id":"C","text":"கால்பந்து"},{"id":"D","text":"வளையல்"}],"correctOption":"D","explanation":"நிலா, பூமி, கால்பந்து ஆகிய மூன்றும் முப்பரிமாணக் கோள வடிவங்கள் (3D Spheres). வளையல் என்பது இருபரிமாண வட்ட வடிவம் (2D Circle).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q9","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைக் கண்டறியவும்: (4, 16, 60), (5, 25, 120), (6, 36, 216), (7, 49, 336)","options":[{"id":"A","text":"(4, 16, 60)"},{"id":"B","text":"(5, 25, 120)"},{"id":"C","text":"(6, 36, 216)"},{"id":"D","text":"(7, 49, 336)"}],"correctOption":"C","explanation":"தர்க்கம்: (x, x², x³-x). 4³-4=60, 5³-5=120, 7³-7=336. ஆனால் 6³-6 = 210 வர வேண்டும், இங்கு 216 உள்ளது.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q10","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைக் கண்டறியவும்: 75%, 0.75, 3/4, 7.5","options":[{"id":"A","text":"75%"},{"id":"B","text":"0.75"},{"id":"C","text":"3/4"},{"id":"D","text":"7.5"}],"correctOption":"D","explanation":"75%, 0.75 மற்றும் 3/4 ஆகிய மூன்றும் ஒரே மதிப்பை (முக்கால் பாகம்) குறிக்கின்றன. 7.5 மட்டும் மாறுபட்டது.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q11","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"43 : 14 :: 54 : ?","options":[{"id":"A","text":"24"},{"id":"B","text":"18"},{"id":"C","text":"16"},{"id":"D","text":"23"}],"correctOption":"B","explanation":"தர்க்கம்: இலக்கங்களின் கூடுதல் × 2. (4+3) × 2 = 14. அதேபோல் (5+4) × 2 = 9 × 2 = 18.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q12","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"M/B : 13/2 :: R/D : ?","options":[{"id":"A","text":"18/4"},{"id":"B","text":"19/4"},{"id":"C","text":"9/23"},{"id":"D","text":"8/24"}],"correctOption":"A","explanation":"ஆங்கில எழுத்துக்களின் இடமதிப்பு: M=13, B=2. அதேபோல் R=18, D=4. எனவே 18/4.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q13","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"தெற்கு : வடமேற்கு :: மேற்கு : ?","options":[{"id":"A","text":"வடக்கு"},{"id":"B","text":"வடகிழக்கு"},{"id":"C","text":"தென்மேற்கு"},{"id":"D","text":"கிழக்கு"}],"correctOption":"B","explanation":"தெற்கிலிருந்து கடிகாரத் திசையில் 135° திரும்பினால் வடமேற்கு கிடைக்கும். மேற்கிலிருந்து 135° கடிகாரத் திசையில் திரும்பினால் வடகிழக்கு கிடைக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q14","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கரும்பு : தண்டு :: இலவங்கம் : ?","options":[{"id":"A","text":"பூ"},{"id":"B","text":"மொட்டு"},{"id":"C","text":"வேர்"},{"id":"D","text":"கனி"}],"correctOption":"B","explanation":"கரும்பு என்பது தாவரத்தின் தண்டுப் பகுதியாகும். இலவங்கம் (Clove) என்பது தாவரத்தின் உலர்ந்த மொட்டு (Bud) பகுதியாகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q15","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"இந்தியா : ஆலமரம் :: தமிழ்நாடு : ?","options":[{"id":"A","text":"பனை மரம்"},{"id":"B","text":"தென்னை மரம்"},{"id":"C","text":"வேப்ப மரம்"},{"id":"D","text":"மாமரம்"}],"correctOption":"A","explanation":"இந்தியாவின் தேசிய மரம் ஆலமரம். தமிழ்நாட்டின் மாநில மரம் பனை மரம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q16","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட உறுப்பைக் கண்டுபிடி: B 12 C, E 15 E, H 18 G, ?, N 24 K","options":[{"id":"A","text":"M 22 J"},{"id":"B","text":"K 21 I"},{"id":"C","text":"K 19 J"},{"id":"D","text":"L 21 I"}],"correctOption":"B","explanation":"முதல் எழுத்து: B, E, H, (+3) -> K. எண்கள்: 12, 15, 18, (+3) -> 21. கடைசி எழுத்து: C(3), E(5), G(7), (+2) -> I(9). எனவே K 21 I.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q17","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட உறுப்பைக் கண்டுபிடி: D I M / E F G H / S ?","questionImage":"/assets/pyq/image/mat_2025/q17.png","options":[{"id":"A","text":"B"},{"id":"B","text":"D"},{"id":"C","text":"G"},{"id":"D","text":"K"}],"correctOption":"C","explanation":"எழுத்துக்களின் இடமதிப்புகளைக் கூட்டினால் ஒரு குறிப்பிட்ட தர்க்கம் கிடைக்கும். (இப்படத்தில் உள்ள தர்க்கத்தின்படி விடை K ஆகும்).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q18","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படத்திலுள்ள விடுபட்ட எண்ணைக் கண்டுபிடி:","questionImage":"/assets/pyq/image/mat_2025/q18.png","options":[{"id":"A","text":"25"},{"id":"B","text":"33"},{"id":"C","text":"27"},{"id":"D","text":"21"}],"correctOption":"D","explanation":"முக்கோணத்தின் வெளிப்புற எண்களைப் பெருக்கி/கூட்டி மைய எண்ணைக் காணும் தர்க்கம் பயன்படுத்தப்பட்டுள்ளது.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q19","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"TEACHER என்பது AETEREH என குறியிடப்பட்டால், PROBLEM என்பது எவ்வாறு குறியிடப்படும்?","options":[{"id":"A","text":"ORPCMEL"},{"id":"B","text":"RPODMEL"},{"id":"C","text":"ORPDMEL"},{"id":"D","text":"RPBUELM"}],"correctOption":"C","explanation":"TEACHER -> முதல் 3 எழுத்துகள் தலைகீழாக (AET), நடு எழுத்து +2 (C+2=E), கடைசி 3 எழுத்துகள் தலைகீழாக (REH). PROBLEM -> முதல் 3 (ORP), நடு எழுத்து B+2=D, கடைசி 3 (MEL). விடை: ORPDMEL.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q20","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வரிசையில் விடுபட்ட எழுத்துக்களைக் காண்க: b c a _ b _ a a b c _ a _ c a a","options":[{"id":"A","text":"acab"},{"id":"B","text":"bcbb"},{"id":"C","text":"cbab"},{"id":"D","text":"ccab"}],"correctOption":"A","explanation":"தொடரை 4, 4 ஆகப் பிரித்தால்: bcaa / bcaa / bcaa / bcaa என வரும். விடுபட்ட இடங்களில் நிரப்ப வேண்டியவை: a, c, a, b.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q21","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"11, 17, 15, 13, 19, ?, 23, 5 தொடரில் விடுபட்ட எண்:","options":[{"id":"A","text":"17"},{"id":"B","text":"11"},{"id":"C","text":"8"},{"id":"D","text":"9"}],"correctOption":"D","explanation":"இது மாற்றுத் தொடர்: 11, 15, 19, 23 (+4 கூடுகிறது). இரண்டாவது தொடர்: 17, 13, ?, 5 (-4 குறைகிறது). 13 - 4 = 9.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q22","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படத்திலுள்ள விடுபட்ட எண்ணைக் காண்க:","questionImage":"/assets/pyq/image/mat_2025/q22.png","options":[{"id":"A","text":"492"},{"id":"B","text":"512"},{"id":"C","text":"496"},{"id":"D","text":"503"}],"correctOption":"D","explanation":"வெளியே உள்ள எண்களின் வர்க்கம் அல்லது கனங்களைக் கூட்டி மைய எண்ணைக் காணும் தர்க்கம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q23","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"565, 112, 27, 8, 3, ?","options":[{"id":"A","text":"2"},{"id":"B","text":"1"},{"id":"C","text":"0"},{"id":"D","text":"3/2"}],"correctOption":"A","explanation":"தர்க்கம்: (n / 5)-1, (n / 4)-1, (n / 3)-1... 565/5-1 = 112. 112/4-1 = 27. 27/3-1 = 8. 8/2-1 = 3. 3/1-1 = 2.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q24","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"2/3, 5/7, 11/13, 17/19, ?","options":[{"id":"A","text":"21/23"},{"id":"B","text":"23/25"},{"id":"C","text":"23/27"},{"id":"D","text":"23/29"}],"correctOption":"D","explanation":"தொகுதிகள் (Numerator): ஒன்றுவிட்ட பகா எண்கள் (2, 5, 11, 17, 23). பகுதிகள் (Denominator): தொகுதிக்குப் பிறகு வரும் அடுத்த பகா எண் (3, 7, 13, 19, 29). எனவே 23/29.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q25","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"6, 0.6, 0.12, 0.036, 0.0144, ?","options":[{"id":"A","text":"0.00720"},{"id":"B","text":"0.0720"},{"id":"C","text":"0.720"},{"id":"D","text":"0.000720"}],"correctOption":"A","explanation":"பெருக்கப்படும் எண்கள்: ×0.1, ×0.2, ×0.3, ×0.4. அடுத்தது 0.0144 × 0.5 = 0.00720.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q26","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A, E, I, M, Q, ?","options":[{"id":"A","text":"S"},{"id":"B","text":"T"},{"id":"C","text":"U"},{"id":"D","text":"V"}],"correctOption":"C","explanation":"ஒவ்வொரு எழுத்தும் ஆங்கில அகர வரிசையில் +4 படிகள் நகர்கிறது. Q(17) + 4 = 21 (U).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q27","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"BC 10, FG 26, JK 42, NO 58, RS 74 என்ற தொடரின் அடுத்த உறுப்பு:","options":[{"id":"A","text":"RS 74"},{"id":"B","text":"ST 78"},{"id":"C","text":"TU 86"},{"id":"D","text":"XY 88"}],"correctOption":"A","explanation":"இது வினாத்தாளில் அச்சுப்பிழையாக RS 74 என்பதை விடையாகக் கொடுத்திருக்கலாம். எழுத்துகள் +4 ஆக நகர்ந்து (B->F->J->N->R) எண்கள் +16 ஆக கூடுகின்றன.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q28","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"7/11, 12/21, 22/41, 42/81, ?","options":[{"id":"A","text":"92/141"},{"id":"B","text":"62/101"},{"id":"C","text":"82/161"},{"id":"D","text":"102/161"}],"correctOption":"C","explanation":"தொகுதிகளின் வித்தியாசம்: 5, 10, 20, 40 (42+40=82). பகுதிகளின் வித்தியாசம்: 10, 20, 40, 80 (81+80=161). விடை 82/161.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q29","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"CAN=21 மற்றும் DEAR=32 எனில் STUDY = ?","options":[{"id":"A","text":"43"},{"id":"B","text":"74"},{"id":"C","text":"89"},{"id":"D","text":"94"}],"correctOption":"D","explanation":"எழுத்துக்களின் இடமதிப்புகளின் கூடுதல் + வார்த்தையிலுள்ள எழுத்துக்களின் எண்ணிக்கை. STUDY = (19+20+21+4+25) = 89. 89 + 5 எழுத்துகள் = 94.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q30","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"SUN=TRVTOM மற்றும் GST=HFTRUS எனில், TEN = ?","options":[{"id":"A","text":"SUFDMO"},{"id":"B","text":"USFDOM"},{"id":"C","text":"UFSDOM"},{"id":"D","text":"SUDFMO"}],"correctOption":"B","explanation":"ஒவ்வொரு எழுத்திற்கும் முன்னும் பின்னும் உள்ள எழுத்துக்களைப் பயன்படுத்துதல். T -> (S, U). E -> (D, F). N -> (M, O). ஆனால் வரிசை மாறி U,S, F,D, O,M என வரும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q31","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"''sweet and sour''=413, ''eat sweet apples''=748, ''apples are sour''=753 எனில் ''eat'' = ?","options":[{"id":"A","text":"4"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"8"}],"correctOption":"D","explanation":"sweet=4, apples=7. ''eat sweet apples'' = 748 என்பதால் eat = 8.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q32","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"HIKE என்பதற்கான குறியீட்டைக் காண்க:","questionImage":"/assets/pyq/image/mat_2025/q32-33.png","options":[{"id":"A","text":"^%?@"},{"id":"B","text":"©^%?"},{"id":"C","text":"?%^©"},{"id":"D","text":"@%^"}],"correctOption":"B","explanation":"கொடுக்கப்பட்ட அட்டவணையிலிருந்து H, I, K, E ஆகிய எழுத்துக்களுக்கான நேர் குறியீடுகளைப் பிரதியிட வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q33","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"குறிப்பிட்ட குறியீட்டிற்கு இணையான வார்த்தையைக் காண்க:","questionImage":"/assets/pyq/image/mat_2025/q32-33.png","options":[{"id":"A","text":"TEACH"},{"id":"B","text":"EATCH"},{"id":"C","text":"HAECT"},{"id":"D","text":"TECHA"}],"correctOption":"A","explanation":"கொடுக்கப்பட்ட குறியீடுகளை அட்டவணையுடன் ஒப்பிட்டு சரியான ஆங்கில வார்த்தையைக் கண்டறிய வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q34","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"அர்த்தத்தின் அடிப்படையில் வரிசைப்படுத்துக: (A) Shoulder (B) Stomach (C) Face (D) Neck (E) Foot","options":[{"id":"A","text":"EDCBA"},{"id":"B","text":"CDABE"},{"id":"C","text":"DCEBA"},{"id":"D","text":"ABCDE"}],"correctOption":"B","explanation":"மனித உடலின் உறுப்புகளை மேலிருந்து கீழாக வரிசைப்படுத்த வேண்டும்: Face (C), Neck (D), Shoulder (A), Stomach (B), Foot (E). எனவே CDABE.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q35","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஆங்கில அகராதி (Dictionary) முறையில் வரிசைப்படுத்துக: (A) Rain (B) Relief (C) Rescue (D) Release (E) Rank","options":[{"id":"A","text":"AEBDC"},{"id":"B","text":"AEDCB"},{"id":"C","text":"EADBC"},{"id":"D","text":"AEDBC"}],"correctOption":"D","explanation":"அகர வரிசைப்படி: Rain (A), Rank (E), Release (D), Relief (B), Rescue (C). எனவே AEDCB.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q36","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A4369Z%37÷PR821Q*YB என்ற தொடரில் வலதுபுறமிருந்து 11-வது குறியீட்டிற்கு வலதுபுறம் 5-ஆவது இடத்தில் இருப்பது:","options":[{"id":"A","text":"@"},{"id":"B","text":"9"},{"id":"C","text":"2"},{"id":"D","text":"8"}],"correctOption":"C","explanation":"வலதுபுறமிருந்து 11-வது குறியீடு ''7''. அதிலிருந்து வலதுபுறம் 5-வது குறியீடு எண்ணிப்பார்த்தால் ''2'' கிடைக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q37","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"மேற்கண்ட தொடரில் அனைத்து எண்களும் நீக்கப்பட்ட பின், மீதமுள்ளவற்றுள் நடுவில் இருப்பது:","options":[{"id":"A","text":"Z"},{"id":"B","text":"%"},{"id":"C","text":"+"},{"id":"D","text":"P"}],"correctOption":"D","explanation":"எண்களை நீக்கினால் மீதமிருப்பது 10 எழுத்துக்கள்/குறியீடுகள். அவற்றின் மையப்பகுதியில் வருவது % குறியீடு ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q38","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"28 _ 6 _ 25 _ 5 _ 4 = 2 என்ற சமன்பாட்டினை நிறைவு செய்யும் குறியீட்டுத் தொகுப்பு எது?","options":[{"id":"A","text":"+, x, ÷, -"},{"id":"B","text":"x, -, ÷, +"},{"id":"C","text":"-, x, ÷, +"},{"id":"D","text":"+, x, -, ÷"}],"correctOption":"C","explanation":"BODMAS விதியின்படி: 28 - 6 * (25 ÷ 5) + 4 = 28 - 6 * 5 + 4 = 28 - 30 + 4 = 2.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q39","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"a*b = a×b மற்றும் a#b = a÷b எனில், (24*7)#(48#8) = ?","options":[{"id":"A","text":"20"},{"id":"B","text":"38"},{"id":"C","text":"26"},{"id":"D","text":"28"}],"correctOption":"D","explanation":"(24×7) ÷ (48÷8) = 168 ÷ 6 = 28.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q40","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"''+'' மற்றும் ''÷'' இடம் மாறுகிறது, மேலும் 3 மற்றும் 6 இடம் மாறுகிறது எனில் சரியான சமன்பாடு எது?","options":[{"id":"A","text":"6+3÷2=1"},{"id":"B","text":"3+6÷2=4"},{"id":"C","text":"6+6÷3=10"},{"id":"D","text":"2+3÷6=5"}],"correctOption":"B","explanation":"3+6÷2=4 என்பதில் எண்கள் மற்றும் குறியீடுகளை மாற்றினால்: 6÷3+2 = 2+2 = 4. இது சரியாகப் பொருந்துகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q41","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A*B = A^B மற்றும் A÷B = B^A எனில், (2*4) ÷ (0÷5) = ?","options":[{"id":"A","text":"0"},{"id":"B","text":"16"},{"id":"C","text":"1"},{"id":"D","text":"5"}],"correctOption":"C","explanation":"(2^4) ÷ (5^0) = 16 ÷ 1. ÷ குறியீட்டிற்குப் பொருள் B^A. எனவே 1^16 = 1.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q42","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"மூன்று போட்டிகளிலும் பங்கு பெறும் மாணவர்களைக் குறிக்கும் பகுதி:","questionImage":"/assets/pyq/image/mat_2025/q42-46.png","options":[{"id":"A","text":"B"},{"id":"B","text":"E"},{"id":"C","text":"D"},{"id":"D","text":"F"}],"correctOption":"B","explanation":"மூன்று வட்டங்களும் (நாடகம், ஓவியம், நடனம்) ஒன்றாக வெட்டிக்கொள்ளும் மையப்பகுதி ''E'' ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q43","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"நாடகத்தில் மட்டும் பங்குபெற்று நடனத்திலோ அல்லது ஓவியத்திலோ பங்கு பெறாத மாணவர்களைக் குறிக்கும் பகுதி:","questionImage":"/assets/pyq/image/mat_2025/q42-46.png","options":[{"id":"A","text":"A"},{"id":"B","text":"C"},{"id":"C","text":"G"},{"id":"D","text":"H"}],"correctOption":"A","explanation":"நாடகம் என்ற வட்டத்தில் மட்டும் இருக்கும் (மற்ற வட்டங்களில் வெட்டாத) பகுதி ''A'' ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q44","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஏதேனும் இரண்டு போட்டிகளில் மட்டும் கலந்துகொள்ளும் மாணவர்களைக் குறிக்கும் பகுதி:","questionImage":"/assets/pyq/image/mat_2025/q42-46.png","options":[{"id":"A","text":"B மற்றும் F"},{"id":"B","text":"B மற்றும் D"},{"id":"C","text":"B, E, D மற்றும் F"},{"id":"D","text":"B, D மற்றும் F"}],"correctOption":"D","explanation":"இரண்டு வட்டங்கள் மட்டும் வெட்டிக்கொள்ளும் பகுதிகள் B, D மற்றும் F ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q45","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"நடனம் மற்றும் ஓவியத்தில் பங்குபெற்று, ஆனால் நாடகத்தில் பங்கு பெறாத மாணவர்களைக் குறிக்கும் பகுதி:","questionImage":"/assets/pyq/image/mat_2025/q42-46.png","options":[{"id":"A","text":"C"},{"id":"B","text":"D"},{"id":"C","text":"G"},{"id":"D","text":"E"}],"correctOption":"B","explanation":"நடனம் மற்றும் ஓவிய வட்டங்கள் மட்டும் வெட்டும் பகுதி (நாடக வட்டத்திற்கு வெளியே உள்ளது) ''D'' ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q46","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"எந்தப் போட்டியிலும் பங்கு பெறாத மாணவர்களைக் குறிக்கும் பகுதி:","questionImage":"/assets/pyq/image/mat_2025/q42-46.png","options":[{"id":"A","text":"A"},{"id":"B","text":"C"},{"id":"C","text":"G"},{"id":"D","text":"H"}],"correctOption":"D","explanation":"மூன்று வட்டங்களுக்கும் வெளியே, ஆனால் கட்டத்திற்குள் உள்ள பகுதி ''H'' ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q47","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒருவரைச் சுட்டிக்காட்டி மோனிகா, ''இவருடைய ஒரே சகோதரி எனது மகனின் அம்மாவின் அம்மா'' என்கிறார். அவர் மோனிகாவிற்கு என்ன உறவு?","options":[{"id":"A","text":"தாய் மாமா"},{"id":"B","text":"தாத்தா"},{"id":"C","text":"அப்பா"},{"id":"D","text":"சகோதரன்/சகோதரியின் மகன்"}],"correctOption":"A","explanation":"மோனிகாவின் மகனின் அம்மா மோனிகா ஆவார். மோனிகாவின் அம்மா தான் அந்த நபரின் ஒரே சகோதரி. எனவே அந்த நபர் மோனிகாவின் தாய் மாமா.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q48","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A, B சகோதரர்கள். C, D சகோதரிகள். C-ன் சகோதரி B-ன் மகள் எனில், D என்பவர் B-க்கு என்ன உறவு?","options":[{"id":"A","text":"மகள்"},{"id":"B","text":"சகோதரி"},{"id":"C","text":"அம்மா"},{"id":"D","text":"மாமியார்"}],"correctOption":"A","explanation":"C-ன் சகோதரி D ஆவார். அவர் B-ன் மகள் எனில், D என்பவரும் B-யின் மகள் தான்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q49","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"LION என்ற சொல் OLRQ எனக் குறியிடப்பட்டால், RISE என்பது எவ்வாறு குறியிடப்படும்?","options":[{"id":"A","text":"QHRD"},{"id":"B","text":"SJTF"},{"id":"C","text":"ULVH"},{"id":"D","text":"TKUG"}],"correctOption":"C","explanation":"ஒவ்வொரு எழுத்தும் ஆங்கில அகர வரிசையில் +3 படிகள் நகர்கிறது. R(+3)=U, I(+3)=L, S(+3)=V, E(+3)=H. விடை ULVH.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q50","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட காகிதத்தை மடிக்கும்போது கிடைக்கும் கனச்சதுரம் எது?","questionImage":"/assets/pyq/image/mat_2025/q50.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"திறந்த கனச்சதுர (Open Cube) விதிகளின்படி, ஒன்றுவிட்ட பக்கங்கள் எதிரெதிர் பக்கங்களாக அமையும். அதனடிப்படையில் மடித்தால் கிடைக்கும் சரியான வடிவம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q51","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"உள்ளீடு: 100 12 65 02 90 எனில் படிநிலை II என்ன?","options":[{"id":"A","text":"02 12 100 65 90"},{"id":"B","text":"02 12 65 90 100"},{"id":"C","text":"02 12 65 100 90"},{"id":"D","text":"02 100 12 65 90"}],"correctOption":"A","explanation":"இயந்திரம் ஒவ்வொரு படிநிலையிலும் மிகச் சிறிய எண்ணை இடதுபுறம் நகர்த்துகிறது. படிநிலை 1: 02 100 12 65 90. படிநிலை 2: 02 12 100 65 90.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q52","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"உள்ளீடு: 20 10 50 70 90 எனில் பின்வருவனவற்றுள் எது இறுதி படிநிலை?","options":[{"id":"A","text":"படிநிலை II"},{"id":"B","text":"படிநிலை III"},{"id":"C","text":"படிநிலை IV"},{"id":"D","text":"படிநிலை I"}],"correctOption":"D","explanation":"படிநிலை 1-ல் ''10'' இடதுபுறம் நகரும்: 10 20 50 70 90. இது முழுமையாக வரிசைப்படுத்தப்பட்டுவிட்டதால் படிநிலை 1 தான் இறுதி.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q53","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"உள்ளீடு: 500 400 300 200 100 எனில் ''100 200 300 500 400'' என்பது எந்த படிநிலை?","options":[{"id":"A","text":"படிநிலை I"},{"id":"B","text":"படிநிலை II"},{"id":"C","text":"படிநிலை III"},{"id":"D","text":"படிநிலை IV"}],"correctOption":"C","explanation":"S1: 100 500 400 300 200. S2: 100 200 500 400 300. S3: 100 200 300 500 400. எனவே இது படிநிலை 3.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q54","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"உள்ளீடு: 9 7 4 5 3 எனில் நான்காவது படிநிலை என்ன?","options":[{"id":"A","text":"3 7 9 5 4"},{"id":"B","text":"3 5 9 7 4"},{"id":"C","text":"3 5 7 9 4"},{"id":"D","text":"3 4 5 7 9"}],"correctOption":"D","explanation":"S1: 3 9 7 4 5. S2: 3 4 9 7 5. S3: 3 4 5 9 7. S4: 3 4 5 7 9.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q55","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"எந்த உள்ளீட்டிற்கு படிநிலை II இறுதி படிநிலையாக அமையும்?","options":[{"id":"A","text":"15  10  20  13  25"},{"id":"B","text":"21  24  30  27  18"},{"id":"C","text":"18  28  65  30  45"},{"id":"D","text":"60  70  65  56  76"}],"correctOption":"A","explanation":"விருப்பம் 1: S1: 10 13 15 25 20. S2: 10 13 15 20 25. இது இரண்டு படிகளில் வரிசையாகிவிடுவதால் இதுவே சரி.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q56","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒருவர் கிழக்கு நோக்கி 10 மீ சென்று, இடதுபுறமாக 7 மீ தூரம் நடக்கிறார். பின் வலப்புறம் திரும்பி 8 மீ தூரம் சென்றால், அவர் தற்போது எத்திசை நோக்கி நிற்கிறார்?","options":[{"id":"A","text":"வடக்கு"},{"id":"B","text":"தெற்கு"},{"id":"C","text":"கிழக்கு"},{"id":"D","text":"மேற்கு"}],"correctOption":"C","explanation":"கிழக்கு நோக்கி சென்று, இடது (வடக்கு) திரும்பி, மீண்டும் வலது திரும்பினால் மீண்டும் கிழக்கு திசையையே நோக்கி நிற்பார்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q57","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ராம் வடக்கு நோக்கி 80 கி.மீ சென்று, அங்கிருந்து கிழக்கு திசையில் 30 கி.மீ சென்று, பின் தெற்கு திசையில் 40 கி.மீ சென்றார். ஆரம்ப இடத்திற்கும் தற்போது இருக்கும் இடத்திற்கும் இடையே உள்ள தூரம்?","options":[{"id":"A","text":"50 கி.மீ"},{"id":"B","text":"60 கி.மீ"},{"id":"C","text":"70 கி.மீ"},{"id":"D","text":"150 கி.மீ"}],"correctOption":"A","explanation":"செங்குத்து நகர்வு = 80 - 40 = 40 கி.மீ. கிடைமட்ட நகர்வு = 30 கி.மீ. பிதாகரஸ் தேற்றப்படி: √(40² + 30²) = √2500 = 50 கி.மீ.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q58","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"படத்தில் உள்ள முக்கோணங்களின் எண்ணிக்கை:","questionImage":"/assets/pyq/image/mat_2025/q58.png","options":[{"id":"A","text":"15"},{"id":"B","text":"14"},{"id":"C","text":"13"},{"id":"D","text":"15-க்கும் மேல்"}],"correctOption":"D","explanation":"படத்தில் உள்ள சிறிய மற்றும் இணைந்த முக்கோணங்களை எண்ணினால் சரியான விடை கிடைக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q59","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"லீப் வருடத்தில் மார்ச் 6-ஆம் தேதிக்கு 19 நாட்களுக்கு முன்னதாக வரும் நாள்:","options":[{"id":"A","text":"பிப்ரவரி 16"},{"id":"B","text":"பிப்ரவரி 18"},{"id":"C","text":"பிப்ரவரி 17"},{"id":"D","text":"பிப்ரவரி 15"}],"correctOption":"A","explanation":"மார்ச் 6-லிருந்து 6 நாட்களைக் கழித்தால் பிப்ரவரி 29 (லீப் ஆண்டு). மீதமுள்ள 13 நாட்களைக் கழித்தால் பிப்ரவரி 16 கிடைக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q60","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"12:30 மணியாக இருக்கும் போது மணிமுள் மற்றும் நிமிட முள்ளிற்கு இடையேயுள்ள கோணம்:","options":[{"id":"A","text":"165°"},{"id":"B","text":"170°"},{"id":"C","text":"175°"},{"id":"D","text":"180°"}],"correctOption":"A","explanation":"கோணம் = |30H - 5.5M|. H=12 (அல்லது 0), M=30. |0 - 5.5×30| = |-165| = 165°.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q61","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வரைபடத்தின்படி 2002-ஆம் ஆண்டில் உள்ள மொத்த மாணவர்களின் எண்ணிக்கை:","questionImage":"/assets/pyq/image/mat_2025/q61-65.png","options":[{"id":"A","text":"10,000"},{"id":"B","text":"20,000"},{"id":"C","text":"30,000"},{"id":"D","text":"15,000"}],"correctOption":"C","explanation":"பட்டை வரைபடத்தில் 2002 ஆம் ஆண்டிற்கான பட்டை 30,000 என்ற அளவை எட்டுகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q62","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"2005-ஆம் ஆண்டில் அரசுப் பள்ளிகளில் உள்ள மாணவர்களின் எண்ணிக்கை:","questionImage":"/assets/pyq/image/mat_2025/q61-65.png","options":[{"id":"A","text":"15,000"},{"id":"B","text":"25,000"},{"id":"C","text":"5,000"},{"id":"D","text":"10,000"}],"correctOption":"A","explanation":"2005-ல் அரசுப் பள்ளிகளைக் குறிக்கும் பகுதியின் அளவைக் கணக்கிட வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q63","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"2001-ஆம் ஆண்டில் அரசு மற்றும் தனியார் பள்ளிகளில் உள்ள மொத்த மாணவர்களின் எண்ணிக்கை:","questionImage":"/assets/pyq/image/mat_2025/q61-65.png","options":[{"id":"A","text":"10,000"},{"id":"B","text":"20,000"},{"id":"C","text":"15,000"},{"id":"D","text":"30,000"}],"correctOption":"B","explanation":"இரண்டு பள்ளிகளின் அளவுகளையும் வரைபடத்திலிருந்து கூட்டி விடை காண வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q64","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"அரசுப் பள்ளிகளில் மாணவர்களின் எண்ணிக்கை மிக அதிகமாக உள்ள வருடம்:","questionImage":"/assets/pyq/image/mat_2025/q61-65.png","options":[{"id":"A","text":"2003"},{"id":"B","text":"2004"},{"id":"C","text":"2005"},{"id":"D","text":"2001"}],"correctOption":"A","explanation":"அரசுப் பள்ளிக்கான பட்டை எந்த வருடத்தில் அதிக உயரத்தைக் கொண்டுள்ளது என்பதை வரைபடத்தில் பார்க்கவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q65","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"2004-ல் அரசு நிதியுதவி பெறும் மற்றும் தனியார் பள்ளிகளில் உள்ள மாணவர்களுக்கு உள்ள வித்தியாசம்:","questionImage":"/assets/pyq/image/mat_2025/q61-65.png","options":[{"id":"A","text":"1,000"},{"id":"B","text":"15,000"},{"id":"C","text":"10,000"},{"id":"D","text":"5,000"}],"correctOption":"D","explanation":"இரண்டு பிரிவுகளின் மதிப்பைக் கழித்து விடையைக் கண்டறியலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q66","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A,B,C,D,E என்ற 5 பளிங்குகளில், A எடை B-ல் பாதி. B எடை C-ஐ போல் 1.5 மடங்கு. C எடை D-ஐ போல் இரு மடங்கு. D-ன் எடை E-ல் 3/4 பங்கு. எடையில் மிகச் சரியாக நடுவில் இருக்கும் பளிங்கு எது?","options":[{"id":"A","text":"D"},{"id":"B","text":"C"},{"id":"C","text":"B"},{"id":"D","text":"A"}],"correctOption":"D","explanation":"மதிப்புகளைக் கணித்தால்: B > C > A > E > D என வரிசை அமையும். எனவே நடுவில் இருப்பது A.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q67","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"மேற்கண்டவற்றில் மிகக் குறைவான எடையுள்ள பளிங்கு எது?","options":[{"id":"A","text":"B"},{"id":"B","text":"C"},{"id":"C","text":"D"},{"id":"D","text":"A"}],"correctOption":"C","explanation":"வரிசையின்படி (B > C > A > E > D) மிகக் குறைந்த எடை D ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q68","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"5 பளிங்குகளில் மிக அதிகமான எடையுடைய பளிங்கு எது?","options":[{"id":"A","text":"A"},{"id":"B","text":"B"},{"id":"C","text":"C"},{"id":"D","text":"D"}],"correctOption":"B","explanation":"வரிசையின்படி மிக அதிக எடை B ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q69","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"E-ஐ விட எடை குறைவாக உள்ள பளிங்கு எது?","options":[{"id":"A","text":"B"},{"id":"B","text":"D"},{"id":"C","text":"A"},{"id":"D","text":"C"}],"correctOption":"B","explanation":"வரிசையின்படி E-க்கு அடுத்து மிகக் குறைந்த எடையாக இருப்பது D.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q70","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"A-ஐ விட எடை அதிகமாகவும், B-ஐ விட எடை குறைவாகவும் உள்ள பளிங்கு எது?","options":[{"id":"A","text":"A"},{"id":"B","text":"D"},{"id":"C","text":"B"},{"id":"D","text":"C"}],"correctOption":"D","explanation":"வரிசையில் A-க்கும் B-க்கும் இடையில் C அமைந்துள்ளது.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q71","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படத்தொடரை பூர்த்தி செய்க:","questionImage":"/assets/pyq/image/mat_2025/q71.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"கோடுகளின் அமைப்பு மற்றும் வடிவங்களின் சுழற்சியைக் கவனித்து அடுத்த படத்தைக் கண்டறியவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q72","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படத்தொடரை பூர்த்தி செய்க:","questionImage":"/assets/pyq/image/mat_2025/q72.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"வடிவங்கள் ஒன்றன்பின் ஒன்றாக எவ்வாறு மாறுகின்றன என்பதைக் கவனிக்கவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q73","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படத்தொடரை பூர்த்தி செய்க:","questionImage":"/assets/pyq/image/mat_2025/q73.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"படத்திலுள்ள குறியீடுகள் இடம் மாறுவதை அடிப்படையாகக் கொண்டது.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q74","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படத்தொடரை பூர்த்தி செய்க:","questionImage":"/assets/pyq/image/mat_2025/q74.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"கோடுகளின் எண்ணிக்கை ஒவ்வொரு படத்திலும் சீராக அதிகரிப்பதைக் காணலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q75","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படத்தொடரை பூர்த்தி செய்க:","questionImage":"/assets/pyq/image/mat_2025/q75.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"வடிவங்களின் சுழற்சியைப் பின்பற்றி விடையளிக்க வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q76","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படங்களில் மாறுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q76.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"மூன்று படங்கள் ஒரே சுழற்சி விதியைப் பின்பற்றும், ஒன்று மட்டும் மாறுபட்டு இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q77","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படங்களில் மாறுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q77.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"உள்ளே இருக்கும் வடிவத்திற்கும் வெளியே இருக்கும் அமைப்பிற்கும் உள்ள தொடர்பு ஒன்றில் மட்டும் வேறுபடும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q78","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படங்களில் மாறுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q78.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"கருப்படிக்கப்பட்ட பகுதிகளின் அமைப்பைக் கொண்டு மாறுபட்டதைக் கண்டறியலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q79","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படங்களில் மாறுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q79.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"வடிவங்களின் சமச்சீர் (Symmetry) தன்மையைக் கொண்டு விடையளிக்கலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q80","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படங்களில் மாறுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q80.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"கோடுகளின் திசை மற்றும் அமைப்பு ஒன்றில் மட்டும் முரணாக இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q81","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படங்களுக்கு இடையேயான தொடர்பின் அடிப்படையில் விடுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q81.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"ஒப்புமை (Analogy) விதிப்படி முதல் இரண்டு படங்களுக்கு உள்ள அதே மாற்றத்தை அடுத்த படத்திற்கும் பயன்படுத்த வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q82","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படங்களுக்கு இடையேயான தொடர்பின் அடிப்படையில் விடுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q82.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"படங்களின் நிற மாற்றம் மற்றும் திசை மாற்றத்தைக் கவனிக்கவும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q83","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படங்களுக்கு இடையேயான தொடர்பின் அடிப்படையில் விடுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q83.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"உள்ளே இருக்கும் வடிவங்கள் வெளியே வருவது போன்ற தர்க்கம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q84","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படங்களுக்கு இடையேயான தொடர்பின் அடிப்படையில் விடுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q84.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"சுழற்சி மற்றும் நிழலிடப்பட்ட பகுதிகளின் இடமாற்றம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q85","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படங்களுக்கு இடையேயான தொடர்பின் அடிப்படையில் விடுபட்டதைத் தேர்ந்தெடு:","questionImage":"/assets/pyq/image/mat_2025/q85.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"கோடுகளின் எண்ணிக்கை குறைதல் அல்லது அதிகரித்தல் தர்க்கம்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q86","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படத்தின் கண்ணாடி பிம்பம் (Mirror Image) எது?","questionImage":"/assets/pyq/image/mat_2025/q86.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"D","explanation":"கண்ணாடி பிம்பத்தில் இடது மற்றும் வலது புறங்கள் இடம் மாறியிருக்கும் (Lateral Inversion).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q87","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட படத்தின் நீர் பிம்பம் (Water Image) எது?","questionImage":"/assets/pyq/image/mat_2025/q87.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"நீர் பிம்பத்தில் மேல் மற்றும் கீழ் பகுதிகள் தலைகீழாக மாறியிருக்கும் (Vertical Inversion).","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q88","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"சரியான படத்தினைத் தேர்வு செய்க (விடுபட்ட பகுதி):","questionImage":"/assets/pyq/image/mat_2025/q88.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"C","explanation":"சமச்சீர் விதியின்படி விடுபட்ட வடிவத்தை நிரப்ப வேண்டும்.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q89","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"சரியான படத்தினைத் தேர்வு செய்க (விடுபட்ட பகுதி):","questionImage":"/assets/pyq/image/mat_2025/q89.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"அனைத்து மூலைகளிலும் உள்ள அமைப்புகளை ஒப்பிட்டு காலியாக உள்ள மூலைக்கான படத்தைத் தேர்க.","marks":1,"negativeMarks":0},{"id":"pyq-2025-mat-q90","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள படத்திலுள்ள சதுரங்களின் எண்ணிக்கை:","questionImage":"/assets/pyq/image/mat_2025/q90.png","options":[{"id":"A","text":"8"},{"id":"B","text":"22"},{"id":"C","text":"32"},{"id":"D","text":"34"}],"correctOption":"C","explanation":"படத்தில் உள்ள 1x1, 2x2, மற்றும் 3x3 சதுரங்களை முறையாக எண்ணி கூட்ட வேண்டும்.","marks":1,"negativeMarks":0}]', '2025-01-01T00:00:00.000Z');
INSERT OR REPLACE INTO quizzes (id, title, description, duration_minutes, total_marks, pass_percentage, shuffle_questions, shuffle_options, enable_anti_cheat, status, questions, created_at) VALUES ('pyq-2026-mat', 'NMMS 2026 - MAT (மனத்திறன் தேர்வு - Mental Ability Test)', 'Official NMMS 2026 Mental Ability Test (MAT) with 90 official previous year questions.', 90, 90, 40, 0, 0, 1, 'draft', '[{"id":"pyq-2026-mat-q1","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"4, 9, 19, 39, ____","options":[{"id":"A","text":"59"},{"id":"B","text":"69"},{"id":"C","text":"79"},{"id":"D","text":"74"}],"correctOption":"C","explanation":"4×2+1=9, 9×2+1=19, 19×2+1=39, 39×2+1=79.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q2","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"8, 4, 15, 5, 22, 6, ____, ____","options":[{"id":"A","text":"29, 7"},{"id":"B","text":"28, 7"},{"id":"C","text":"29, 8"},{"id":"D","text":"27, 8"}],"correctOption":"A","explanation":"இரண்டு தொடர்கள்: (8, 15, 22, 29) மற்றும் (4, 5, 6, 7).","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q3","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"3, 6, 9, 15, 24, 39, ____","options":[{"id":"A","text":"65"},{"id":"B","text":"63"},{"id":"C","text":"53"},{"id":"D","text":"55"}],"correctOption":"B","explanation":"3+6=9, 6+9=15, 9+15=24, 15+24=39, 24+39=63.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q4","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"1, 7, 3, 63, 5, 215, 7, ____","options":[{"id":"A","text":"342"},{"id":"B","text":"511"},{"id":"C","text":"517"},{"id":"D","text":"343"}],"correctOption":"B","explanation":"இரண்டு தொடர்கள்: (1, 3, 5, 7) மற்றும் (2³-1=7, 4³-1=63, 6³-1=215, 8³-1=511).","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q5","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"XYW, UVT, RSQ, OPN, ____","options":[{"id":"A","text":"KLM"},{"id":"B","text":"LMK"},{"id":"C","text":"LKM"},{"id":"D","text":"KML"}],"correctOption":"B","explanation":"ஒவ்வொரு எழுத்தும் முந்தையதிலிருந்து -3 பின்னோக்கி செல்கிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q6","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"(1) (7, 13) (2) (13, 23) (3) (31, 37) (4) (81, 83)","options":[{"id":"A","text":"(7, 13)"},{"id":"B","text":"(13, 23)"},{"id":"C","text":"(31, 37)"},{"id":"D","text":"(81, 83)"}],"correctOption":"D","explanation":"மற்ற அனைத்தும் பகா எண்கள் (Prime numbers). ஆனால் 81 ஒரு பகு எண்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q7","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைக் கண்டறியவும்: (1) PLAY (2) WRITE (3) THINK (4) WALK","options":[{"id":"A","text":"PLAY"},{"id":"B","text":"WRITE"},{"id":"C","text":"THINK"},{"id":"D","text":"WALK"}],"correctOption":"C","explanation":"THINK என்பது மனச் செயல். மற்றவை உடல் சார்ந்த செயல்கள்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q8","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பொருந்தாத ஒன்றைக் கண்டறியவும்.","questionImage":"/assets/pyq/image/mat_2026/q8.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"விருப்பம் (2) மற்ற அமைப்புகளிலிருந்து வேறுபடுகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q9","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"(1) 24 : 33 (2) 83 : 92 (3) 19 : 21 (4) 64 : 73","options":[{"id":"A","text":"24 : 33"},{"id":"B","text":"83 : 92"},{"id":"C","text":"19 : 21"},{"id":"D","text":"64 : 73"}],"correctOption":"C","explanation":"24+9=33, 83+9=92, 64+9=73. ஆனால் 19+2=21.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q10","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"(1) வட்டம் (2) இணைகரம் (3) சாய்சதுரம் (4) சரிவகம்","options":[{"id":"A","text":"வட்டம்"},{"id":"B","text":"இணைகரம்"},{"id":"C","text":"சாய்சதுரம்"},{"id":"D","text":"சரிவகம்"}],"correctOption":"A","explanation":"வட்டம் என்பது நேர்கோடுகளால் ஆனது அல்ல. மற்றவை நாற்கரங்கள்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q11","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கீழ்க்கண்ட வினாக்களுக்குப் பொருத்தமான வென் படத்தைத் தேர்க: தோட்டம், ரோஜா, மல்லிகை","questionImage":"/assets/pyq/image/mat_2026/q11_15.png","options":[{"id":"A","text":"(B)"},{"id":"B","text":"(C)"},{"id":"C","text":"(D)"},{"id":"D","text":"(A)"}],"correctOption":"D","explanation":"ரோஜாவும் மல்லிகையும் தோட்டத்தினுள் தனித்தனியாக இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q12","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"அம்மாக்கள், பாட்டிகள், ஆடவர்","questionImage":"/assets/pyq/image/mat_2026/q11_15.png","options":[{"id":"A","text":"(B)"},{"id":"B","text":"(D)"},{"id":"C","text":"(C)"},{"id":"D","text":"(E)"}],"correctOption":"C","explanation":"அனைத்து பாட்டிகளும் அம்மாக்கள் ஆவர். ஆடவர் தனித்த பிரிவாகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q13","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"உணவு, வாழைப்பழம், பழங்கள்","questionImage":"/assets/pyq/image/mat_2026/q11_15.png","options":[{"id":"A","text":"(A)"},{"id":"B","text":"(D)"},{"id":"C","text":"(E)"},{"id":"D","text":"(B)"}],"correctOption":"B","explanation":"வாழைப்பழம் பழங்கள் பிரிவிலும், பழங்கள் உணவு பிரிவிலும் அடங்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q14","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"மலை, ஆறு, மேகம்","questionImage":"/assets/pyq/image/mat_2026/q11_15.png","options":[{"id":"A","text":"(A)"},{"id":"B","text":"(D)"},{"id":"C","text":"(E)"},{"id":"D","text":"(C)"}],"correctOption":"C","explanation":"மூன்றும் தனித்தனி தொடர்பற்றவை.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q15","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"பகா எண்கள், இயல் எண்கள், ஒற்றை எண்கள்","questionImage":"/assets/pyq/image/mat_2026/q11_15.png","options":[{"id":"A","text":"(A)"},{"id":"B","text":"(B)"},{"id":"C","text":"(D)"},{"id":"D","text":"(E)"}],"correctOption":"B","explanation":"பகா எண்களும் ஒற்றை எண்களும் ஒன்றையொன்று வெட்டும் (2 தவிர பிற பகா எண்கள் ஒற்றை எண்கள்). இரண்டும் இயல் எண்கள் பிரிவில் அடங்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q16","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"முத்து : கழுத்தணி :: பூ : _______","options":[{"id":"A","text":"தோட்டம்"},{"id":"B","text":"செடி"},{"id":"C","text":"இதழ்"},{"id":"D","text":"பூங்கொத்து"}],"correctOption":"D","explanation":"முத்துக்களைக் கோர்த்தால் கழுத்தணி. பூக்களைக் கோர்த்தால் பூங்கொத்து.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q17","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"8 × 9 : 9 × 3 :: 6 × 7 : _______","options":[{"id":"A","text":"8 × 4"},{"id":"B","text":"8 × 3"},{"id":"C","text":"7 × 2"},{"id":"D","text":"7 × 3"}],"correctOption":"B","explanation":"8×9=72, இதனை மாற்றி எழுதினால் 27 (அதாவது 9×3). 6×7=42, இதனை மாற்றி எழுதினால் 24 (அதாவது 8×3).","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q18","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"BIRD : DKVH :: ROAD : _______","options":[{"id":"A","text":"TQCH"},{"id":"B","text":"VPEH"},{"id":"C","text":"SQEH"},{"id":"D","text":"TQEH"}],"correctOption":"D","explanation":"B(+2)D, I(+2)K, R(+4)V, D(+4)H. அதேபோல் R(+2)T, O(+2)Q, A(+4)E, D(+4)H.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q19","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ACE : 15 :: BET : _______","options":[{"id":"A","text":"200"},{"id":"B","text":"120"},{"id":"C","text":"60"},{"id":"D","text":"320"}],"correctOption":"A","explanation":"எழுத்துக்களின் மதிப்புகளைப் பெருக்குக. A=1, C=3, E=5 (1×3×5=15). B=2, E=5, T=20 (2×5×20=200).","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q20","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"செவ்வகம் : கனசெவ்வகம் :: வட்டம் : _______","options":[{"id":"A","text":"உருளை"},{"id":"B","text":"கூம்பு"},{"id":"C","text":"கோளம்"},{"id":"D","text":"கனசதுரம்"}],"correctOption":"A","explanation":"செவ்வகத்தின் முப்பரிமாண நீட்சி கனசெவ்வகம். வட்டத்தின் முப்பரிமாண நீட்சி உருளை என விடைக்குறிப்பில் உள்ளது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q21","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட உறுப்பைக் கண்டுபிடி:","questionImage":"/assets/pyq/image/mat_2026/q21.png","options":[{"id":"A","text":"42"},{"id":"B","text":"33"},{"id":"C","text":"44"},{"id":"D","text":"36"}],"correctOption":"C","explanation":"மூன்றாம் வரிசை × இரண்டாம் வரிசை - முதல் வரிசை = நான்காம் வரிசை. (8×6)-4=44.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q22","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட உறுப்பைக் கண்டுபிடி:","questionImage":"/assets/pyq/image/mat_2026/q22.png","options":[{"id":"A","text":"2G"},{"id":"B","text":"3G"},{"id":"C","text":"2N"},{"id":"D","text":"6G"}],"correctOption":"D","explanation":"எழுத்துக்கள் +3 என மாறுகின்றன (A+3=D, D+3=G). எண்கள்: 9-3=6. எனவே 6G.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q23","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"விடுபட்ட எண்ணைக் காண்க:","questionImage":"/assets/pyq/image/mat_2026/q23.png","options":[{"id":"A","text":"17"},{"id":"B","text":"20"},{"id":"C","text":"21"},{"id":"D","text":"23"}],"correctOption":"B","explanation":"வெளிப்புற எண்களின் வர்க்கமூலங்களின் கூடுதல் மைய எண். √36+√9+√49+√16 = 6+3+7+4 = 20.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q24","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"4 : 64 :: 6 : ____","options":[{"id":"A","text":"144"},{"id":"B","text":"216"},{"id":"C","text":"36"},{"id":"D","text":"196"}],"correctOption":"B","explanation":"n : n³. 4³=64, 6³=216.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q25","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"b _ a _ aab _ ab _","options":[{"id":"A","text":"aabba"},{"id":"B","text":"abaaa"},{"id":"C","text":"ababb"},{"id":"D","text":"babab"}],"correctOption":"B","explanation":"சரியான முறை ''baa a aab a aba'' என்பதாகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q26","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"_ _ 0 1 _ 0 1 0 _ _ 0 0","options":[{"id":"A","text":"10001"},{"id":"B","text":"01110"},{"id":"C","text":"10010"},{"id":"D","text":"10101"}],"correctOption":"A","explanation":"''100'' என்ற தொடர் மீண்டும் மீண்டும் வருகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q27","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஆப்பிள் \"தக்காளி\" எனவும், தக்காளி \"சோப்பு\" எனவும், சோப்பு \"தேன்\" எனவும், தேன் \"மை\" எனவும் அழைக்கப்பட்டால் பின்வருவனவற்றுள் குளிப்பதற்கு பயன்படுவது எது?","options":[{"id":"A","text":"தேன்"},{"id":"B","text":"தக்காளி"},{"id":"C","text":"சோப்பு"},{"id":"D","text":"மை"}],"correctOption":"A","explanation":"குளிப்பதற்கு பயன்படுவது சோப்பு. சோப்பு என்பது தேன் என அழைக்கப்படுகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q28","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு சங்கேத மொழியில் \"WHO\" என்பதை ''16'' எனவும், \"HOW\" என்பதை ''0'' எனவும் குறிக்கப்பட்டால், \"WHY\" என்பதன் குறியீடு","options":[{"id":"A","text":"70"},{"id":"B","text":"5"},{"id":"C","text":"6"},{"id":"D","text":"56"}],"correctOption":"C","explanation":"முதல் இரு எழுத்துக்களின் கூட்டலிலிருந்து மூன்றாம் எழுத்தின் மதிப்பைக் கழிக்க வேண்டும். W(23)+H(8)-Y(25) = 6.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q29","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு குறிப்பிட்ட குறியீட்டு மொழியில் ''TOMB'' என்பதை 3568 மற்றும் ''GOAL'' என்பதை 1572 என குறிப்பிட்டால் ''BOAT'' என்பதை எவ்வாறு குறிப்பர்?","options":[{"id":"A","text":"8357"},{"id":"B","text":"8573"},{"id":"C","text":"5378"},{"id":"D","text":"3758"}],"correctOption":"B","explanation":"ஒவ்வொரு எழுத்திற்கும் நேரடி குறியீடு. B=8, O=5, A=7, T=3.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q30","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு பகடையின் மூன்று நிலைகள் கீழே தரப்பட்டுள்ளன. முக எண் 3 -க்கு எதிர்புறம் உள்ள முகத்தில் எந்த எண் இருக்கும்?","questionImage":"/assets/pyq/image/mat_2026/q30.png","options":[{"id":"A","text":"2"},{"id":"B","text":"1"},{"id":"C","text":"5"},{"id":"D","text":"6"}],"correctOption":"B","explanation":"பகடையின் நிலைகளை ஒப்பிடுகையில் 3-க்கு எதிராக 1 இருக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q31","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 31 - 35) : கொடுக்கப்பட்ட வரைபடத்தில், முக்கோணம் நேர்மையானவர்களையும், செவ்வகம் கடின உழைப்பாளிகளையும் மற்றும் சதுரம் படித்தவர்களையும் குறிக்கிறது. வரைபடத்தை கவனமாக படித்து, பின்வரும் வினாக்களுக்கு விடையளிக்கவும்:\n\nபடிக்காத நேர்மையான மற்றும் கடின உழைப்பாளியை குறிக்கும் எழுத்து எது?","questionImage":"/assets/pyq/image/mat_2026/q31_35.png","options":[{"id":"A","text":"D"},{"id":"B","text":"B"},{"id":"C","text":"E"},{"id":"D","text":"C"}],"correctOption":"C","explanation":"வரைபடத்தின்படி விடை E.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q32","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 31 - 35) : கொடுக்கப்பட்ட வரைபடத்தில், முக்கோணம் நேர்மையானவர்களையும், செவ்வகம் கடின உழைப்பாளிகளையும் மற்றும் சதுரம் படித்தவர்களையும் குறிக்கிறது. வரைபடத்தை கவனமாக படித்து, பின்வரும் வினாக்களுக்கு விடையளிக்கவும்:\n\nபடித்தவர்களை குறிக்காத எழுத்து எது?","questionImage":"/assets/pyq/image/mat_2026/q31_35.png","options":[{"id":"A","text":"B"},{"id":"B","text":"F"},{"id":"C","text":"C"},{"id":"D","text":"G"}],"correctOption":"B","explanation":"வரைபடத்தின்படி விடை F.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q33","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 31 - 35) : கொடுக்கப்பட்ட வரைபடத்தில், முக்கோணம் நேர்மையானவர்களையும், செவ்வகம் கடின உழைப்பாளிகளையும் மற்றும் சதுரம் படித்தவர்களையும் குறிக்கிறது. வரைபடத்தை கவனமாக படித்து, பின்வரும் வினாக்களுக்கு விடையளிக்கவும்:\n\nபடித்த நேர்மையான கடின உழைப்பாளிகளைக் குறிக்கும் எழுத்து எது?","questionImage":"/assets/pyq/image/mat_2026/q31_35.png","options":[{"id":"A","text":"C"},{"id":"B","text":"E"},{"id":"C","text":"B"},{"id":"D","text":"D"}],"correctOption":"D","explanation":"வரைபடத்தின்படி விடை D.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q34","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 31 - 35) : கொடுக்கப்பட்ட வரைபடத்தில், முக்கோணம் நேர்மையானவர்களையும், செவ்வகம் கடின உழைப்பாளிகளையும் மற்றும் சதுரம் படித்தவர்களையும் குறிக்கிறது. வரைபடத்தை கவனமாக படித்து, பின்வரும் வினாக்களுக்கு விடையளிக்கவும்:\n\nநேர்மையானவரை மட்டும் குறிக்கும் எழுத்து எது?","questionImage":"/assets/pyq/image/mat_2026/q31_35.png","options":[{"id":"A","text":"B"},{"id":"B","text":"A"},{"id":"C","text":"D"},{"id":"D","text":"E"}],"correctOption":"B","explanation":"வரைபடத்தின்படி விடை A.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q35","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 31 - 35) : கொடுக்கப்பட்ட வரைபடத்தில், முக்கோணம் நேர்மையானவர்களையும், செவ்வகம் கடின உழைப்பாளிகளையும் மற்றும் சதுரம் படித்தவர்களையும் குறிக்கிறது. வரைபடத்தை கவனமாக படித்து, பின்வரும் வினாக்களுக்கு விடையளிக்கவும்:\n\nநேர்மையானவர் அல்லாத கற்றோர் மற்றும் கடின உழைப்பாளியை குறிக்கும் எழுத்து எது?","questionImage":"/assets/pyq/image/mat_2026/q31_35.png","options":[{"id":"A","text":"D"},{"id":"B","text":"B"},{"id":"C","text":"F"},{"id":"D","text":"C"}],"correctOption":"D","explanation":"வரைபடத்தின்படி விடை C.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q36","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு குறிப்பிட்ட குறியீட்டு மொழியில் ''Kit Mit Fit'' என்பதை ''Some good films'' எனவும் ''Zit Rit Kit'' என்பதை ''Some real stories'' எனவும் ''Sil Fit Rit'' என்பதை ''Many good stories'' எனவும் கொண்டால் ''real'' என்பதை எந்தக் குறியீட்டால் குறிக்கலாம்?","options":[{"id":"A","text":"Zit"},{"id":"B","text":"Sil"},{"id":"C","text":"Rit"},{"id":"D","text":"Kit"}],"correctOption":"A","explanation":"பொதுவான வார்த்தைகளை நீக்கினால் ''real'' என்பது ''Zit'' எனப் பெறப்படும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q37","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள எண் வரிசையில் எத்தனை ''6'' கள் ஒற்றை எண்ணைத் தொடர்ந்தும் இரட்டை எண் தொடராமலும் உள்ளன? 2 5 7 3 6 4 3 4 5 6 8 6 3 4 6 5 3 6 5","options":[{"id":"A","text":"3"},{"id":"B","text":"2"},{"id":"C","text":"4"},{"id":"D","text":"1"}],"correctOption":"D","explanation":"ஒற்றை எண் -> 6 -> ஒற்றை எண் என்ற அமைப்பில் ''3 6 5'' மட்டும் 1 முறை வருகிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q38","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு குறிப்பிட்ட குறியீட்டில் 85+14=18, 96+27=24 என குறிப்பிட்டால் 14+27 -ன் மதிப்பு என்ன?","options":[{"id":"A","text":"14"},{"id":"B","text":"27"},{"id":"C","text":"20"},{"id":"D","text":"26"}],"correctOption":"A","explanation":"இலக்கங்களின் கூடுதல். 1+4+2+7 = 14.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q39","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"அக்டோபர் 14-ன் 5 நாட்களுக்கு முன்னர் சனிக்கிழமை எனில், அந்த மாதத்தின் கடைசி திங்கட்கிழமை எந்த தேதியில் வரும்?","options":[{"id":"A","text":"அக்டோபர் 25"},{"id":"B","text":"அக்டோபர் 26"},{"id":"C","text":"அக்டோபர் 24"},{"id":"D","text":"அக்டோபர் 27"}],"correctOption":"A","explanation":"அக்டோபர் 9 சனிக்கிழமை. அக்டோபர் 11 திங்கட்கிழமை. அதன்பின் 18, 25 திங்கட்கிழமைகள்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q40","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒரு கடிகாரத்தில் 8.36.02 பி.ப. இருந்து 8.36.50 பி.ப. வரை கடக்கும் பொழுது நொடி முள் எத்தனை கோணம் சுழன்று இருக்கும்?","options":[{"id":"A","text":"294"},{"id":"B","text":"288"},{"id":"C","text":"282"},{"id":"D","text":"298"}],"correctOption":"B","explanation":"வித்தியாசம் 48 நொடிகள். ஒரு நொடிக்கு 6 டிகிரி. 48 × 6 = 288.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q41","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 41 - 43) : பின்வரும் தகவல்களை படிக்கவும். எண்கள் மற்றும் அவற்றிற்கான குறியீடுகள் கீழே கொடுக்கப்பட்டுள்ளன.\nஎண்கள்: 1 2 3 4 5 6 7\nகுறியீடுகள்: * A D $ @ # ?\nநிபந்தனைகள்:\n(i) முதல் மற்றும் கடைசி எண்கள் ஒற்றைப்படை எண்ணாக இருந்தால், அவை இரண்டும் X என குறியிடப்பட வேண்டும்.\n(ii) முதல் மற்றும் கடைசி எண்கள் இரட்டைப்படை எண்ணாக இருந்தால், அவற்றின் குறியீடுகள் இடமாற்றம் செய்யப்பட வேண்டும்.\n\n62457 -ன் குறியீடு காண்க.","options":[{"id":"A","text":"# A $ @ ?"},{"id":"B","text":"? A $ @ #"},{"id":"C","text":"X A $ @ X"},{"id":"D","text":"X A $ @ #"}],"correctOption":"A","explanation":"முதல் எண் இரட்டைப்படை, கடைசி எண் ஒற்றைப்படை. நிபந்தனைகள் ஏதும் பொருந்தாது. நேரடி குறியீடு: #A$@?","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q42","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 41 - 43) : பின்வரும் தகவல்களை படிக்கவும். எண்கள் மற்றும் அவற்றிற்கான குறியீடுகள் கீழே கொடுக்கப்பட்டுள்ளன.\nஎண்கள்: 1 2 3 4 5 6 7\nகுறியீடுகள்: * A D $ @ # ?\nநிபந்தனைகள்:\n(i) முதல் மற்றும் கடைசி எண்கள் ஒற்றைப்படை எண்ணாக இருந்தால், அவை இரண்டும் X என குறியிடப்பட வேண்டும்.\n(ii) முதல் மற்றும் கடைசி எண்கள் இரட்டைப்படை எண்ணாக இருந்தால், அவற்றின் குறியீடுகள் இடமாற்றம் செய்யப்பட வேண்டும்.\n\n561323 -ன் குறியீடு காண்க.","options":[{"id":"A","text":"X # * A D X"},{"id":"B","text":"X # * D A X"},{"id":"C","text":"D # * D A @"},{"id":"D","text":"@ # * D A D"}],"correctOption":"B","explanation":"முதல் மற்றும் கடைசி எண்கள் ஒற்றைப்படை. நிபந்தனை (i)-ன்படி இரண்டிற்கும் X குறியிட வேண்டும். விடை: X#*DAX.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q43","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 41 - 43) : பின்வரும் தகவல்களை படிக்கவும். எண்கள் மற்றும் அவற்றிற்கான குறியீடுகள் கீழே கொடுக்கப்பட்டுள்ளன.\nஎண்கள்: 1 2 3 4 5 6 7\nகுறியீடுகள்: * A D $ @ # ?\nநிபந்தனைகள்:\n(i) முதல் மற்றும் கடைசி எண்கள் ஒற்றைப்படை எண்ணாக இருந்தால், அவை இரண்டும் X என குறியிடப்பட வேண்டும்.\n(ii) முதல் மற்றும் கடைசி எண்கள் இரட்டைப்படை எண்ணாக இருந்தால், அவற்றின் குறியீடுகள் இடமாற்றம் செய்யப்பட வேண்டும்.\n\n42536 -ன் குறியீடு காண்க.","options":[{"id":"A","text":"$ A @ D #"},{"id":"B","text":"$ A D @ #"},{"id":"C","text":"# A @ D $"},{"id":"D","text":"X A @ D X"}],"correctOption":"C","explanation":"முதல் மற்றும் கடைசி எண்கள் இரட்டைப்படை. நிபந்தனை (ii)-ன்படி முதல் மற்றும் கடைசி குறியீடுகளை இடமாற்ற வேண்டும். விடை: #A@D$.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q44","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"''×'' என்பது ''-'' எனவும், ''+'' என்பது ''÷'' எனவும், ''-'' என்பது ''+'' எனவும் மற்றும் ''÷'' என்பது ''×'' எனவும் குறிப்பிட்டால் 15 × 16 + 8 - 2 ÷ 4 -ன் மதிப்பைக் காண்க.","options":[{"id":"A","text":"25"},{"id":"B","text":"21"},{"id":"C","text":"5"},{"id":"D","text":"20"}],"correctOption":"B","explanation":"15 - 16 ÷ 8 + 2 × 4 = 15 - 2 + 8 = 21.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q45","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட வரைபடத்தை கனசதுரமாக மடித்தால் எண் 5-க்கு நேர் எதிரே உள்ள எண் எது?","questionImage":"/assets/pyq/image/mat_2026/q45.png","options":[{"id":"A","text":"3"},{"id":"B","text":"2"},{"id":"C","text":"4"},{"id":"D","text":"6"}],"correctOption":"B","explanation":"நேர்க்கோட்டில் உள்ள ஒன்றுவிட்ட முகங்கள் எதிரெதிராக அமையும். அதன்படி 5-க்கு எதிரே 2 அமையும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q46","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 46 - 50) : A, B, C, D, E ஆகிய ஐந்து நண்பர்கள் கிழக்கு நோக்கி ஒரு வரிசையில் நிற்கிறார்கள். C-க்கு வலதுபுறம் உடனடியாக A உள்ளார். B மற்றும் E-க்கு இடையில் D உள்ளார். A மற்றும் D-க்கு இடையில் E உள்ளார்.\n\nஇடப்பக்க ஓரத்தில் இருப்பவர் யார்?","options":[{"id":"A","text":"A"},{"id":"B","text":"C"},{"id":"C","text":"E"},{"id":"D","text":"D"}],"correctOption":"B","explanation":"வரிசை C, A, E, D, B என அமையும். இடப்பக்க ஓரத்தில் இருப்பவர் C.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q47","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 46 - 50) : A, B, C, D, E ஆகிய ஐந்து நண்பர்கள் கிழக்கு நோக்கி ஒரு வரிசையில் நிற்கிறார்கள். C-க்கு வலதுபுறம் உடனடியாக A உள்ளார். B மற்றும் E-க்கு இடையில் D உள்ளார். A மற்றும் D-க்கு இடையில் E உள்ளார்.\n\nநடுவில் இருப்பவர் யார்?","options":[{"id":"A","text":"A"},{"id":"B","text":"C"},{"id":"C","text":"E"},{"id":"D","text":"B"}],"correctOption":"C","explanation":"வரிசை C, A, E, D, B. நடுவில் இருப்பவர் E.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q48","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 46 - 50) : A, B, C, D, E ஆகிய ஐந்து நண்பர்கள் கிழக்கு நோக்கி ஒரு வரிசையில் நிற்கிறார்கள். C-க்கு வலதுபுறம் உடனடியாக A உள்ளார். B மற்றும் E-க்கு இடையில் D உள்ளார். A மற்றும் D-க்கு இடையில் E உள்ளார்.\n\nE என்பவருக்கு உடனடி இடதுபுறத்தில் இருப்பவர் யார்?","options":[{"id":"A","text":"C"},{"id":"B","text":"A"},{"id":"C","text":"D"},{"id":"D","text":"B"}],"correctOption":"B","explanation":"வரிசை C, A, E, D, B. E-க்கு இடதுபுறம் இருப்பவர் A.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q49","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 46 - 50) : A, B, C, D, E ஆகிய ஐந்து நண்பர்கள் கிழக்கு நோக்கி ஒரு வரிசையில் நிற்கிறார்கள். C-க்கு வலதுபுறம் உடனடியாக A உள்ளார். B மற்றும் E-க்கு இடையில் D உள்ளார். A மற்றும் D-க்கு இடையில் E உள்ளார்.\n\nA மற்றும் B இருவரும் இடமாற்றி நின்றால் வலது ஓரம் நிற்பவர் யார்?","options":[{"id":"A","text":"E"},{"id":"B","text":"A"},{"id":"C","text":"D"},{"id":"D","text":"B"}],"correctOption":"B","explanation":"இடமாற்றிய பின் வரிசை: C, B, E, D, A. வலது ஓரம் இருப்பவர் A.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q50","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 46 - 50) : A, B, C, D, E ஆகிய ஐந்து நண்பர்கள் கிழக்கு நோக்கி ஒரு வரிசையில் நிற்கிறார்கள். C-க்கு வலதுபுறம் உடனடியாக A உள்ளார். B மற்றும் E-க்கு இடையில் D உள்ளார். A மற்றும் D-க்கு இடையில் E உள்ளார்.\n\nதெற்கிலிருந்து இரண்டாவதாக நிற்பவர் யார்?","options":[{"id":"A","text":"E"},{"id":"B","text":"A"},{"id":"C","text":"D"},{"id":"D","text":"B"}],"correctOption":"C","explanation":"தெற்கு என்பது வலது ஓரம். வரிசை C, A, E, D, B. வலது ஓரத்திலிருந்து இரண்டாவதாக இருப்பவர் D.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q51","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 51 முதல் 55 வரை) : ஒரு எண் ஒழுங்கமைக்கும் இயந்திரத்தில் எண்கள் உள்ளீடாகக் கொடுக்கப்படும் போது, ஒவ்வொரு படிநிலையிலும் ஒரு குறிப்பிட்ட விதியின்படி அவை மறுசீரமைக்கப்படுகின்றன. உள்ளீடு மற்றும் மறுசீரமைப்பிற்கான ஒரு எடுத்துக்காட்டு கீழே கொடுக்கப்பட்டுள்ளது.\nஉள்ளீடு: 60 54 18 48 12 90\nபடிநிலை I: 60 90 54 12 18 48\nபடிநிலை II: 60 48 90 18 54 12\nபடிநிலை III: 60 12 48 54 90 18\nபடிநிலை IV: 60 18 12 90 48 54\nபடிநிலை V: 60 54 18 48 12 90\nபடிநிலை V என்பது இறுதி படிநிலை ஆகும். மேற்கண்ட விதிகளின்படி, கொடுக்கப்பட்ட வினாக்களுக்கு விடையளிக்கவும்.\n\nஉள்ளீடு: 5 12 18 40 77 82 எனில், பின்வருவனவற்றுள் எது இறுதி படிநிலை?","options":[{"id":"A","text":"82 77 40 18 12 5"},{"id":"B","text":"5 12 18 40 77 82"},{"id":"C","text":"5 82 12 77 18 40"},{"id":"D","text":"5 40 82 18 12 77"}],"correctOption":"B","explanation":"படிநிலை V என்பது இறுதி படிநிலை. இது உள்ளீட்டிற்குச் சமமாகும். எனவே அதே உள்ளீடு தான் விடை.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q52","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 51 முதல் 55 வரை) : ஒரு எண் ஒழுங்கமைக்கும் இயந்திரத்தில் எண்கள் உள்ளீடாகக் கொடுக்கப்படும் போது, ஒவ்வொரு படிநிலையிலும் ஒரு குறிப்பிட்ட விதியின்படி அவை மறுசீரமைக்கப்படுகின்றன. உள்ளீடு மற்றும் மறுசீரமைப்பிற்கான ஒரு எடுத்துக்காட்டு கீழே கொடுக்கப்பட்டுள்ளது.\nஉள்ளீடு: 60 54 18 48 12 90\nபடிநிலை I: 60 90 54 12 18 48\nபடிநிலை II: 60 48 90 18 54 12\nபடிநிலை III: 60 12 48 54 90 18\nபடிநிலை IV: 60 18 12 90 48 54\nபடிநிலை V: 60 54 18 48 12 90\nபடிநிலை V என்பது இறுதி படிநிலை ஆகும். மேற்கண்ட விதிகளின்படி, கொடுக்கப்பட்ட வினாக்களுக்கு விடையளிக்கவும்.\n\nஉள்ளீடு: 101 9 48 60 22 120 எனில், படிநிலை III என்ன?","options":[{"id":"A","text":"101 48 22 120 60 9"},{"id":"B","text":"101 120 9 22 48 60"},{"id":"C","text":"101 22 60 9 120 48"},{"id":"D","text":"120 101 60 48 22 9"}],"correctOption":"C","explanation":"முறைப்படி 3-வது படிநிலையில் 101 22 60 9 120 48 என வரும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q53","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 51 முதல் 55 வரை) : ஒரு எண் ஒழுங்கமைக்கும் இயந்திரத்தில் எண்கள் உள்ளீடாகக் கொடுக்கப்படும் போது, ஒவ்வொரு படிநிலையிலும் ஒரு குறிப்பிட்ட விதியின்படி அவை மறுசீரமைக்கப்படுகின்றன. உள்ளீடு மற்றும் மறுசீரமைப்பிற்கான ஒரு எடுத்துக்காட்டு கீழே கொடுக்கப்பட்டுள்ளது.\nஉள்ளீடு: 60 54 18 48 12 90\nபடிநிலை I: 60 90 54 12 18 48\nபடிநிலை II: 60 48 90 18 54 12\nபடிநிலை III: 60 12 48 54 90 18\nபடிநிலை IV: 60 18 12 90 48 54\nபடிநிலை V: 60 54 18 48 12 90\nபடிநிலை V என்பது இறுதி படிநிலை ஆகும். மேற்கண்ட விதிகளின்படி, கொடுக்கப்பட்ட வினாக்களுக்கு விடையளிக்கவும்.\n\nஉள்ளீடு: 48 40 62 15 17 25 இரண்டாவது படிநிலை என்ன?","options":[{"id":"A","text":"48 40 62 15 17 25"},{"id":"B","text":"15 17 25 40 48 62"},{"id":"C","text":"48 15 25 62 40 17"},{"id":"D","text":"48 17 62 40 15 25"}],"correctOption":"C","explanation":"உள்ளீட்டை முறைப்படி மாற்றுவதன் மூலம் கிடைக்கும் இரண்டாம் படிநிலை 48 15 25 62 40 17.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q54","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 51 முதல் 55 வரை) : ஒரு எண் ஒழுங்கமைக்கும் இயந்திரத்தில் எண்கள் உள்ளீடாகக் கொடுக்கப்படும் போது, ஒவ்வொரு படிநிலையிலும் ஒரு குறிப்பிட்ட விதியின்படி அவை மறுசீரமைக்கப்படுகின்றன. உள்ளீடு மற்றும் மறுசீரமைப்பிற்கான ஒரு எடுத்துக்காட்டு கீழே கொடுக்கப்பட்டுள்ளது.\nஉள்ளீடு: 60 54 18 48 12 90\nபடிநிலை I: 60 90 54 12 18 48\nபடிநிலை II: 60 48 90 18 54 12\nபடிநிலை III: 60 12 48 54 90 18\nபடிநிலை IV: 60 18 12 90 48 54\nபடிநிலை V: 60 54 18 48 12 90\nபடிநிலை V என்பது இறுதி படிநிலை ஆகும். மேற்கண்ட விதிகளின்படி, கொடுக்கப்பட்ட வினாக்களுக்கு விடையளிக்கவும்.\n\nஉள்ளீடு: 48 40 62 15 17 25 எனில், \"48 62 17 25 15 40\" என்பது எந்த படிநிலை?","options":[{"id":"A","text":"படிநிலை I"},{"id":"B","text":"படிநிலை II"},{"id":"C","text":"படிநிலை III"},{"id":"D","text":"படிநிலை IV"}],"correctOption":"D","explanation":"நான்காவது படிநிலையில் (Step IV) இந்த விடை கிடைக்கிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q55","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 51 முதல் 55 வரை) : ஒரு எண் ஒழுங்கமைக்கும் இயந்திரத்தில் எண்கள் உள்ளீடாகக் கொடுக்கப்படும் போது, ஒவ்வொரு படிநிலையிலும் ஒரு குறிப்பிட்ட விதியின்படி அவை மறுசீரமைக்கப்படுகின்றன. உள்ளீடு மற்றும் மறுசீரமைப்பிற்கான ஒரு எடுத்துக்காட்டு கீழே கொடுக்கப்பட்டுள்ளது.\nஉள்ளீடு: 60 54 18 48 12 90\nபடிநிலை I: 60 90 54 12 18 48\nபடிநிலை II: 60 48 90 18 54 12\nபடிநிலை III: 60 12 48 54 90 18\nபடிநிலை IV: 60 18 12 90 48 54\nபடிநிலை V: 60 54 18 48 12 90\nபடிநிலை V என்பது இறுதி படிநிலை ஆகும். மேற்கண்ட விதிகளின்படி, கொடுக்கப்பட்ட வினாக்களுக்கு விடையளிக்கவும்.\n\nஉள்ளீடு: 48 40 62 15 17 25 மூன்றாம் படிநிலை என்ன?","options":[{"id":"A","text":"48 25 17 40 62 15"},{"id":"B","text":"48 15 25 62 40 17"},{"id":"C","text":"48 62 17 25 15 40"},{"id":"D","text":"48 17 15 40 25 62"}],"correctOption":"D","explanation":"படிநிலை III: 48 17 15 40 25 62 ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q56","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 56 - 57) : கொடுக்கப்பட்ட அமைப்பில் உள்ள எண்கள் அனைத்தையும் இறங்கு வரிசையில் மாற்றி அமைத்து, இடமிருந்து வலமாக எண்கள் இருக்கும் இடங்களில் மட்டும் பிரதியிட வேண்டும். மற்ற உறுப்புகள் மாறாமல் இருக்கும். இதன் அடிப்படையில் பின்வரும் வினாக்களுக்கு விடையளிக்கவும்:\n@ A 9 * C B % + 7 D $ 3 × 5 C ? 2 D E 8 #\n\nஎந்த உறுப்பு வலது முனையிலிருந்து பத்தாவதாக இருக்கும்? (அனைத்து எண்களையும் இறங்கு வரிசையில் மாற்றி அமைத்தபின்)","options":[{"id":"A","text":"x"},{"id":"B","text":"3"},{"id":"C","text":"7"},{"id":"D","text":"$"}],"correctOption":"B","explanation":"எண்களை மாற்றி அமைத்தாலும், விடைக்குறிப்பின்படி சரியான விடை 3 ஆகும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q57","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 56 - 57) : கொடுக்கப்பட்ட அமைப்பில் உள்ள எண்கள் அனைத்தையும் இறங்கு வரிசையில் மாற்றி அமைத்து, இடமிருந்து வலமாக எண்கள் இருக்கும் இடங்களில் மட்டும் பிரதியிட வேண்டும். மற்ற உறுப்புகள் மாறாமல் இருக்கும். இதன் அடிப்படையில் பின்வரும் வினாக்களுக்கு விடையளிக்கவும்:\n@ A 9 * C B % + 7 D $ 3 × 5 C ? 2 D E 8 #\n\nஇடதுபுறத்திலிருந்து 4-வது உறுப்புக்கு வலதுபுறம் உள்ள 9-வது உறுப்பு எது?","options":[{"id":"A","text":"$"},{"id":"B","text":"x"},{"id":"C","text":"5"},{"id":"D","text":"7"}],"correctOption":"B","explanation":"4+9=13. இடப்பக்கத்திலிருந்து 13-வது உறுப்பு ''x''.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q58","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"ஒருவர் வடக்கு நோக்கி சென்று கொண்டிருக்கிறார். அவர், எந்தெந்த தொடர் திசைகளில் சென்றிருந்தால் தற்பொழுது கிழக்கு நோக்கி செல்லாமல் இருப்பார்?","options":[{"id":"A","text":"இடது, இடது, இடது"},{"id":"B","text":"வலது, வலது, இடது"},{"id":"C","text":"இடது, வலது, வலது"},{"id":"D","text":"வலது, இடது, இடது"}],"correctOption":"D","explanation":"வடக்கில் இருந்து வலது, இடது, இடது எனத் திரும்பினால் அவர் மேற்கு திசையை நோக்கி இருப்பார்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q59","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"''தென்மேற்கு'' வடக்காகவும், ''கிழக்கு'' தென்மேற்காகவும் மற்றும் அனைத்து திசைகளும் இதே முறையில் மாற்றம் பெற்றால் வடக்கு என்னவாக மாறும்?","options":[{"id":"A","text":"வட கிழக்கு"},{"id":"B","text":"வட மேற்கு"},{"id":"C","text":"தென் மேற்கு"},{"id":"D","text":"தென் கிழக்கு"}],"correctOption":"D","explanation":"அனைத்து திசைகளும் கடிகார திசையில் 135° சுழலுகின்றன. எனவே வடக்கு தென்-கிழக்காக மாறும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q60","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"\"CONCEPTUALIZATION\" என்ற வார்த்தையில் உள்ள எழுத்துக்களைக் கொண்டு உருவாக்க முடியாத வார்த்தை எது?","options":[{"id":"A","text":"ACTUAL"},{"id":"B","text":"TOTAL"},{"id":"C","text":"PLANTATION"},{"id":"D","text":"EXPLANATION"}],"correctOption":"D","explanation":"\"EXPLANATION\" என்ற சொல்லில் உள்ள ''X'' என்ற எழுத்து கொடுக்கப்பட்ட வார்த்தையில் இல்லை.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q61","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 61 - 65) : 2021 முதல் 2025 வரையிலான ஆண்டுகளில் மூன்று வெவ்வேறு பிரிவுகளில் சேர்ந்த மாணவர்களின் எண்ணிக்கையை காட்டும் பட்டை விளக்கப்படத்தை படித்து பின்வரும் வினாக்களுக்கு விடையளிக்கவும்.\n\n2021 ஆம் ஆண்டு அறிவியல் பிரிவில் பதிவு செய்த மாணவர்களின் எண்ணிக்கை","questionImage":"/assets/pyq/image/mat_2026/q61_65.png","options":[{"id":"A","text":"1000"},{"id":"B","text":"250"},{"id":"C","text":"750"},{"id":"D","text":"0"}],"correctOption":"C","explanation":"வரைபடத்திலிருந்து மதிப்புகளைப் படிப்பதன் மூலம் இதனை அறியலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q62","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 61 - 65) : 2021 முதல் 2025 வரையிலான ஆண்டுகளில் மூன்று வெவ்வேறு பிரிவுகளில் சேர்ந்த மாணவர்களின் எண்ணிக்கையை காட்டும் பட்டை விளக்கப்படத்தை படித்து பின்வரும் வினாக்களுக்கு விடையளிக்கவும்.\n\n2025 ஆம் ஆண்டில் அறிவியல் பிரிவில் பதிவு செய்த மாணவர்களின் சதவீதம்","questionImage":"/assets/pyq/image/mat_2026/q61_65.png","options":[{"id":"A","text":"8.333%"},{"id":"B","text":"80.33%"},{"id":"C","text":"8.03%"},{"id":"D","text":"8.303%"}],"correctOption":"A","explanation":"மொத்த மாணவர்களில் அறிவியல் பிரிவு மாணவர்களின் சதவீதத்தைக் கணக்கிட 8.333% கிடைக்கிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q63","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 61 - 65) : 2021 முதல் 2025 வரையிலான ஆண்டுகளில் மூன்று வெவ்வேறு பிரிவுகளில் சேர்ந்த மாணவர்களின் எண்ணிக்கையை காட்டும் பட்டை விளக்கப்படத்தை படித்து பின்வரும் வினாக்களுக்கு விடையளிக்கவும்.\n\n2023 ஆம் ஆண்டில் அறிவியல் பிரிவிலும், தொழிற்பிரிவிலும், பதிவு செய்த மாணவர்களின் எண்ணிக்கையின் வித்தியாசம்","questionImage":"/assets/pyq/image/mat_2026/q61_65.png","options":[{"id":"A","text":"250"},{"id":"B","text":"750"},{"id":"C","text":"500"},{"id":"D","text":"1000"}],"correctOption":"D","explanation":"வரைபடத்தின் மூலம் இரண்டு பிரிவுகளுக்கும் உள்ள வித்தியாசம் 1000 என்பதை அறியலாம்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q64","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 61 - 65) : 2021 முதல் 2025 வரையிலான ஆண்டுகளில் மூன்று வெவ்வேறு பிரிவுகளில் சேர்ந்த மாணவர்களின் எண்ணிக்கையை காட்டும் பட்டை விளக்கப்படத்தை படித்து பின்வரும் வினாக்களுக்கு விடையளிக்கவும்.\n\n2025 மற்றும் 2024 -ம் ஆண்டுகளில் பதிவு செய்த மாணவர்களின் விகிதம்","questionImage":"/assets/pyq/image/mat_2026/q61_65.png","options":[{"id":"A","text":"12 : 11"},{"id":"B","text":"11 : 12"},{"id":"C","text":"11 : 17"},{"id":"D","text":"12 : 17"}],"correctOption":"A","explanation":"2025 மற்றும் 2024-ன் மொத்த சேர்க்கையை ஒப்பிட்டால் 12:11 என்ற விகிதம் கிடைக்கிறது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q65","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"வழிமுறை (வினா எண் 61 - 65) : 2021 முதல் 2025 வரையிலான ஆண்டுகளில் மூன்று வெவ்வேறு பிரிவுகளில் சேர்ந்த மாணவர்களின் எண்ணிக்கையை காட்டும் பட்டை விளக்கப்படத்தை படித்து பின்வரும் வினாக்களுக்கு விடையளிக்கவும்.\n\n2025 ஆம் ஆண்டில் பதிவு செய்த மாணவர்களின் எண்ணிக்கையானது 2021 -ம் ஆண்டில் பதிவு செய்த மாணவர்களின் எண்ணிக்கையைப் போல் ____ ஆகும்.","questionImage":"/assets/pyq/image/mat_2026/q61_65.png","options":[{"id":"A","text":"மூன்று மடங்கு"},{"id":"B","text":"பாதி"},{"id":"C","text":"இரு மடங்கு"},{"id":"D","text":"மூன்றில் ஒரு பங்கு"}],"correctOption":"A","explanation":"2021 சேர்க்கையை விட 2025 சேர்க்கை 3 மடங்கு அதிகமாக உள்ளது.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q66","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்டுள்ள சொற்களை சரியான முறையில் வரிசைப்படுத்துக: (A) நியமனம் (B) விளம்பரம் (C) விண்ணப்பம் (D) தேர்ந்தெடுத்தல் (E) நேர்முகத்தேர்வு","options":[{"id":"A","text":"BEDCA"},{"id":"B","text":"CDEBA"},{"id":"C","text":"BCEDA"},{"id":"D","text":"CBEDA"}],"correctOption":"C","explanation":"விளம்பரம் (B) -> விண்ணப்பம் (C) -> நேர்முகத்தேர்வு (E) -> தேர்ந்தெடுத்தல் (D) -> நியமனம் (A). விடை: BCEDA.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q67","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"\"PAINTER\" என்ற சொல்லில் உள்ள எழுத்துக்களை ஆங்கில அகர வரிசைப்படி வரிசைப்படுத்தி எழுதினால் தன் இடத்தினை மாற்றிக் கொள்ளாத எழுத்துக்களின் எண்ணிக்கை எத்தனை?","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}],"correctOption":"B","explanation":"அகர வரிசைப்படி: A E I N P R T. ஒப்பிடுகையில் I மற்றும் N ஆகிய 2 எழுத்துக்கள் இடம் மாறாமல் உள்ளன.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q68","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"குறியீடுகள் மற்றும் எண்களின் எந்த இடமாற்றம் கீழ்க்கண்ட சமன்பாட்டினை சரி செய்யும்? 16 - 8 × 16 - 2 ÷ 4 + 3 = 15","questionImage":"/assets/pyq/image/mat_2026/q68.png","options":[{"id":"A","text":"+ மற்றும் ÷, 3 மற்றும் 4"},{"id":"B","text":"× மற்றும் -, 16 மற்றும் 4"},{"id":"C","text":"- மற்றும் ÷, 8 மற்றும் 2"},{"id":"D","text":"× மற்றும் -, 16 மற்றும் 2"}],"correctOption":"C","explanation":"- மற்றும் ÷, 8 மற்றும் 2 ஆகியவற்றை மாற்றி கணக்கிட 15 கிடைக்கும்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q69","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கீழ்கண்ட சொற்களை ஆங்கில அகராதி முறையில் வரிசைப்படுத்தும்பொழுது கடைசியிலிருந்து இரண்டாவதாக வரும் வார்த்தை என்ன? Scramble, Script, Science, School","options":[{"id":"A","text":"Scramble"},{"id":"B","text":"Script"},{"id":"C","text":"Science"},{"id":"D","text":"School"}],"correctOption":"A","explanation":"அகராதி வரிசை: School, Science, Scramble, Script. கடைசியிலிருந்து இரண்டாவது Scramble.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q70","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"P என்பவர் Q -விற்கு சகோதரர். R என்பவர் S -ற்கு சகோதரி. Q என்பவர் R -ற்கு மகன். எனில், R என்பவர் P -க்கு என்ன உறவு?","options":[{"id":"A","text":"தந்தை"},{"id":"B","text":"தாய்"},{"id":"C","text":"மருமகன்"},{"id":"D","text":"மருமகள்"}],"correctOption":"B","explanation":"Q-ன் தாய் R. P மற்றும் Q சகோதரர்கள் என்பதால், P-க்கும் R தாய் ஆவார்.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q71","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட தொடரை பூர்த்தி செய்க.","questionImage":"/assets/pyq/image/mat_2026/q71.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"படத்தில் உள்ள அமைப்புகளின் தொடர்ச்சியை கவனித்து சரியான விடையைத் தேர்க.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q72","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட தொடரை பூர்த்தி செய்க.","questionImage":"/assets/pyq/image/mat_2026/q72.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"படத்தில் உள்ள அமைப்புகளின் தொடர்ச்சியை கவனித்து சரியான விடையைத் தேர்க.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q73","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட தொடரை பூர்த்தி செய்க.","questionImage":"/assets/pyq/image/mat_2026/q73.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"A","explanation":"படத்தில் உள்ள அமைப்புகளின் தொடர்ச்சியை கவனித்து சரியான விடையைத் தேர்க.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q74","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionText":"கொடுக்கப்பட்ட தொடரை பூர்த்தி செய்க.","questionImage":"/assets/pyq/image/mat_2026/q74.png","options":[{"id":"A","text":"(1)"},{"id":"B","text":"(2)"},{"id":"C","text":"(3)"},{"id":"D","text":"(4)"}],"correctOption":"B","explanation":"படத்தில் உள்ள அமைப்புகளின் தொடர்ச்சியை கவனித்து சரியான விடையைத் தேர்க.","marks":1,"negativeMarks":0},{"id":"pyq-2026-mat-q75","subject":"MAT","topic":"மனத்திறன் தேர்வு (MAT)","questionTe