INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('MAT_1', 'MAT', 1, '[{"id":"unit-matquiz-1-q1","subject":"MAT","topic":"Unit 1","questionText":"கொடுக்கப்பட்டுள்ள எண் தொடரில் விடுபட்ட எண்ணை காண்க.\n4,5,7,10,11,13,16,17,?,22","options":[{"id":"A","text":"18"},{"id":"B","text":"19"},{"id":"C","text":"20"},{"id":"D","text":"21"}],"correctOption":"B","explanation":"+1, +2, +3 எனத் தொடர்ந்து கூட்டப்பட்டுள்ளது. (17 + 2 = 19)","marks":1,"negativeMarks":0},{"id":"unit-matquiz-1-q2","subject":"MAT","topic":"Unit 1","questionText":"கொடுக்கப்பட்டுள்ள எண் தொடரில் விடுபட்ட எண்ணை காண்க.\n625, 5,125, 25,?,125","options":[{"id":"A","text":"5"},{"id":"B","text":"25"},{"id":"C","text":"125"},{"id":"D","text":"625"}],"correctOption":"B","explanation":"இரண்டு தொடர்கள்: 625 ÷ 5 = 125, 125 ÷ 5 = 25. மற்றும் 5 × 5 = 25, 25 × 5 = 125. விடை 25.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-1-q3","subject":"MAT","topic":"Unit 1","questionText":"கொடுக்கப்பட்டுள்ள எண் தொடரில் விடுபட்ட எண்ணை காண்க.\n3,7,15,?,63,127","options":[{"id":"A","text":"30"},{"id":"B","text":"31"},{"id":"C","text":"47"},{"id":"D","text":"52"}],"correctOption":"B","explanation":"+4, +8, +16, +32, +64 என கூட்டப்பட்டுள்ளது. (15 + 16 = 31)","marks":1,"negativeMarks":0},{"id":"unit-matquiz-1-q4","subject":"MAT","topic":"Unit 1","questionText":"கொடுக்கப்பட்டுள்ள எண் தொடரில் விடுபட்ட எண்ணை காண்க.\n1,1,16,4,25,5,36,6,?,11","options":[{"id":"A","text":"121"},{"id":"B","text":"112"},{"id":"C","text":"211"},{"id":"D","text":"111"}],"correctOption":"A","explanation":"இரண்டு தொடர்கள்: வர்க்க எண்கள் (1², 4², 5², 6², 11² -> 121) மற்றும் இயல் எண்கள் (1, 4, 5, 6, 11).","marks":1,"negativeMarks":0},{"id":"unit-matquiz-1-q5","subject":"MAT","topic":"Unit 1","questionText":"கொடுக்கப்பட்டுள்ள எண் தொடரில் விடுபட்ட எண்ணை காண்க.\n53,59,61,67,?,73, 79,83","options":[{"id":"A","text":"74"},{"id":"B","text":"69"},{"id":"C","text":"71"},{"id":"D","text":"68"}],"correctOption":"C","explanation":"இது பக