INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('MAT_12', 'MAT', 12, '[{"id":"unit-matquiz-12-q1","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q1.png","options":[{"id":"A","text":"N"},{"id":"B","text":"H"},{"id":"C","text":"G"},{"id":"D","text":"J"}],"correctOption":"A","explanation":"E(5) + I(9) = N(14). J(10) + M(13) = W(23). எனவே விடுபட்ட எழுத்து N.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q2","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q2.png","options":[{"id":"A","text":"E"},{"id":"B","text":"G"},{"id":"C","text":"H"},{"id":"D","text":"P"}],"correctOption":"C","explanation":"B(2), D(4), F(6). C(3), F(6), I(9). D(4), H(8), L(12). எனவே விடுபட்ட எழுத்து H.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q3","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q3.png","options":[{"id":"A","text":"Q"},{"id":"B","text":"R"},{"id":"C","text":"J"},{"id":"D","text":"L"}],"correctOption":"A","explanation":"F(6) + 10 = 16. E(5) + X = 22 => X = 17 (Q). J(10), ?(Q).","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q4","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q4.png","options":[{"id":"A","text":"X"},{"id":"B","text":"W"},{"id":"C","text":"R"},{"id":"D","text":"V"}],"correctOption":"B","explanation":"Z (-2) X (-2) V (-2) T. Z (-3) W (-3) T (-3) Q. விடுபட்ட எழுத்து W.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q5","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q5.png","options":[{"id":"A","text":"G"},{"id":"B","text":"F"},{"id":"C","text":"J"},{"id":"D","text":"