egativeMarks":0},{"id":"unit-matquiz-12-q10","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q10.png","options":[{"id":"A","text":"E"},{"id":"B","text":"F"},{"id":"C","text":"D"},{"id":"D","text":"V"}],"correctOption":"A","explanation":"வலமிருந்து இடமாக (Z->A) எழுத்துக்களின் இடமதிப்பு: W(4), Q(10), K(16), E(22). எண்கள்: 4x2=8, 10x2=20, 16x2=32, 22x2=44. விடுபட்ட எழுத்து E.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q11","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q11.png","options":[{"id":"A","text":"O"},{"id":"B","text":"C"},{"id":"C","text":"D"},{"id":"D","text":"H"}],"correctOption":"C","explanation":"எதிர் எதிரே உள்ள எழுத்துக்களின் இடமதிப்பு கூடுதல் 18. M(13) + E(5) = 18. G(7) + K(11) = 18. N(14) + X(4) = 18. 4 வது எழுத்து D.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q12","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q12.png","options":[{"id":"A","text":"216 P"},{"id":"B","text":"42 P"},{"id":"C","text":"18 N"},{"id":"D","text":"216 N"}],"correctOption":"A","explanation":"5B(5¹), 125D(5³), 25F(5²). 4J(4¹), 64L(4³), 16N(4²). 6N(6¹), 216P(6³), 36R(6²). விடை 216 P.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q13","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q13.png","options":[{"id":"A","text":"M"},{"id":"B","text":"H"},{"id":"C","text":"J"},{"id":"D","text":"G"}],"correctOption":"B","explanation":"T = 20, P = 16, L = 12. 8 வது எழுத்து H.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q14","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q14.png","options":[{"id":"A","text":"T"},{"id":"B","text":"J"},{"id":"C","text":"K"},{"id":"D","text":"O"}],"correctOption":"B","explanation":"7+9 = 16 ÷ 2 = 8 (H). 17+19 = 36 ÷ 2 = 18 (R). 9+11 = 20 ÷ 2 = 10 (J).","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q15","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q15.png","options":[{"id":"A","text":"D5"},{"id":"B","text":"D3"},{"id":"C","text":"D4"},{"id":"D","text":"D6"}],"correctOption":"A","explanation":"A2, C4, E6. B3, D5, F7. C5, E7, G9. விடுபட்டது D5.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q16","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q16.png","options":[{"id":"A","text":"FG"},{"id":"B","text":"CD"},{"id":"C","text":"GH"},{"id":"D","text":"EF"}],"correctOption":"A","explanation":"B(2)+C(3)=5. F(6)+G(7)=13. H(8)+I(9)=17. I(9)+J(10)=19. விடுபட்டது FG.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q17","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q17.png","options":[{"id":"A","text":"5"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"8"}],"correctOption":"D","explanation":"M(13) - D(4) = 9. Q(17) - J(10) = 7. P(16) - H(8) = 8.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q18","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q18.png","options":[{"id":"A","text":"17"},{"id":"B","text":"27"},{"id":"C","text":"29"},{"id":"D","text":"21"}],"correctOption":"B","explanation":"Z(26)+A(1)=27. Y(25)+B(2)=27. X(24)+C(3)=27. W(23)+D(4)=27. V(22)+E(5)=27.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q19","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q19.png","options":[{"id":"A","text":"S"},{"id":"B","text":"T"},{"id":"C","text":"R"},{"id":"D","text":"P"}],"correctOption":"C","explanation":"C(3)+D(4)=7(G). H(8)+I(9)=17(Q). G(7)+K(11)=18(R).","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q20","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q20.png","options":[{"id":"A","text":"A"},{"id":"B","text":"B"},{"id":"C","text":"Y"},{"id":"D","text":"P"}],"correctOption":"A","explanation":"சுற்றியுள்ள எண்கள் மற்றும் மைய எழுத்தின் இடமதிப்பு ஆகியவற்றின் கூடுதல் 27. 5+7+13+2(B)=27. 5+1+8+13(M)=27. 8+4+7+8(H)=27. 13+4+9+X=27 => X=1 (A).","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q21","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q21.png","options":[{"id":"A","text":"Y"},{"id":"B","text":"W"},{"id":"C","text":"V"},{"id":"D","text":"X"}],"correctOption":"D","explanation":"C(+2) E(+3) H. H(+3) K(+4) O. O(+4) S(+5) X.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q22","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q22.png","options":[{"id":"A","text":"O,N,Z"},{"id":"B","text":"C,L,O"},{"id":"C","text":"X,Q,O"},{"id":"D","text":"O,Q,N"}],"correctOption":"C","explanation":"D(-2) B(-4) X. S(-2) Q(-4) M. O(-2) M(-4) I. விடுபட்டவை X, Q, O.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q23","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q23.png","options":[{"id":"A","text":"A"},{"id":"B","text":"S"},{"id":"C","text":"U"},{"id":"D","text":"V"}],"correctOption":"C","explanation":"வலமிருந்து இடமாக Z->A இடமதிப்பு: O(12), N(13) => √(12+13) = 5. T(7), R(9) => √(7+9) = 4. X(3), U(6) => √(3+6) = 3.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q24","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q24.png","options":[{"id":"A","text":"S"},{"id":"B","text":"H"},{"id":"C","text":"K"},{"id":"D","text":"Y"}],"correctOption":"A","explanation":"B(+5) G(+5) L. E(+5) J(+5) O. I(+5) N(+5) S.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-12-q25","subject":"MAT","topic":"Unit 12","questionText":"விடுபட்ட எழுத்தைக் காண்க.","questionImage":"/assets/matquiz/image/unit12/image/unit12/q25.png","options":[{"id":"A","text":"B"},{"id":"B","text":"C"},{"id":"C","text":"D"},{"id":"D","text":"E"}],"correctOption":"C","explanation":"P(16) - J(10) = F(6). T(20) - H(8) = L(12). V(22) - R(18) = 4(D).","marks":1,"negativeMarks":0}]', datetime('now'));
INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('MAT_13', 'MAT', 13, '[{"id":"unit-matquiz-13-q1","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. கிரிக்கெட் மட்டும் விளையாடுபவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"6"},{"id":"B","text":"12"},{"id":"C","text":"20"},{"id":"D","text":"24"}],"correctOption":"B","explanation":"முக்கோணத்தில் மட்டும் உள்ள எண் = 12.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q2","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. கிரிக்கெட் அல்லாமல் ஹாக்கி மற்றும் கால்பந்து விளையாடுபவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"6"},{"id":"B","text":"16"},{"id":"C","text":"22"},{"id":"D","text":"37"}],"correctOption":"A","explanation":"வட்டம் மற்றும் செவ்வகத்தில் மட்டும் வெட்டிக் கொள்ளும் இடத்தில் வரும் எண் = 1 + 5 = 6.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q3","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. மூன்று விளையாட்டுக்களும் விளையாடுபவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"5"},{"id":"B","text":"20"},{"id":"C","text":"4"},{"id":"D","text":"1"}],"correctOption":"C","explanation":"வட்டம், செவ்வகம் மற்றும் முக்கோணத்தில் பொதுவாக உள்ள எண் = 4.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q4","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. கால்பந்து மட்டும் விளையாடுபவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"22"},{"id":"B","text":"26"},{"id":"C","text":"9"},{"id":"D","text":"16"}],"correctOption":"D","explanation":"செவ்வகத்தில் மட்டும் உள்ள எண்கள் = 9 + 7 = 16.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q5","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. ஏதேனும் இரு விளையாட்டு மட்டும் விளையாடுபவர்கள்:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"8"},{"id":"B","text":"14"},{"id":"C","text":"6"},{"id":"D","text":"20"}],"correctOption":"B","explanation":"இரு விளையாட்டுகளில் மட்டும் பொதுவாக உள்ள எண்கள் = 8 + 6 = 14.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q6","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. ஹாக்கி விளையாட்டை தவிர மற்ற ஏதேனும் ஒரு விளையாட்டை விளையாடும் மாணவர்கள்:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"16"},{"id":"B","text":"12"},{"id":"C","text":"33"},{"id":"D","text":"28"}],"correctOption":"D","explanation":"வட்டத்தை தவிர்த்து மற்ற இரண்டு உருவங்களில் உள்ள எண்கள் = 12 + 7 + 9 = 28.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q7","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. ஹாக்கி விளையாட்டு மட்டும் விளையாடுபவர்கள்:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"6"},{"id":"B","text":"2"},{"id":"C","text":"5"},{"id":"D","text":"4"}],"correctOption":"A","explanation":"வட்டத்தில் மட்டும் உள்ள எண் = 6.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q8","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. ஏதேனும் ஒரு விளையாட்டு மட்டும் விளையாடுபவர்கள்:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"34"},{"id":"B","text":"28"},{"id":"C","text":"18"},{"id":"D","text":"5"}],"correctOption":"A","explanation":"ஒவ்வொரு வடிவத்திலும் தனியாக உள்ள எண்களின் கூடுதல் = (6 + 12 + 7 + 9) = 34.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q9","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. கிரிக்கெட், கால்பந்து, ஹாக்கி இம்முன்றையும் தவிர மற்ற விளையாட்டு விளையாடுபவர்கள்:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"20"},{"id":"B","text":"4"},{"id":"C","text":"5"},{"id":"D","text":"6"}],"correctOption":"C","explanation":"மூன்று விளையாட்டுகளையும் தவிர ஐங்கோணத்தில் மட்டும் உள்ள எண்கள் = 3 + 2 = 5.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q10","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் ஹாக்கி விளையாடுபவர்களையும், செவ்வகம் கால்பந்து விளையாடுபவர்களையும், முக்கோணம் கிரிக்கெட் விளையாடுபவர்களையும், ஐங்கோணம் வகுப்பில் உள்ள மாணவர்களையும் குறிக்கிறது. வகுப்பில் உள்ள மொத்த மாணவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q1-10.png","options":[{"id":"A","text":"52"},{"id":"B","text":"41"},{"id":"C","text":"40"},{"id":"D","text":"57"}],"correctOption":"D","explanation":"அனைத்து எண்களின் கூடுதல் = 57.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q11","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் சதுரம் ஓவியம் வரைவதில் விருப்பமுள்ளவர்களையும், செவ்வகம் விளையாட்டில் ஆர்வமுள்ளவர்களையும், முக்கோணம் நடனத்தில் நாட்டமுள்ளவர்களையும், வட்டம் நாடகம் நடிப்பதில் விருப்பமுள்ளவர்களையும் குறிக்கிறது. ஓவியம் மற்றும் விளையாட்டில் ஆர்வமில்லாத ஆனால் நடனம் மற்றும் நாடகத்தில் விருப்பமுள்ளவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q11-15.png","options":[{"id":"A","text":"1"},{"id":"B","text":"4"},{"id":"C","text":"5"},{"id":"D","text":"3"}],"correctOption":"B","explanation":"முக்கோணம் மற்றும் வட்டத்தில் மட்டும் வெட்டிக்கொள்ளும் இடத்தில் வரும் எண் = 4.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q12","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் சதுரம் ஓவியம் வரைவதில் விருப்பமுள்ளவர்களையும், செவ்வகம் விளையாட்டில் ஆர்வமுள்ளவர்களையும், முக்கோணம் நடனத்தில் நாட்டமுள்ளவர்களையும், வட்டம் நாடகம் நடிப்பதில் விருப்பமுள்ளவர்களையும் குறிக்கிறது. அனைத்திலும் விருப்பம் உடையவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q11-15.png","options":[{"id":"A","text":"3"},{"id":"B","text":"6"},{"id":"C","text":"2"},{"id":"D","text":"9"}],"correctOption":"A","explanation":"அனைத்து வடிவங்களுக்கும் பொதுவானது = 3.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q13","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் சதுரம் ஓவியம் வரைவதில் விருப்பமுள்ளவர்களையும், செவ்வகம் விளையாட்டில் ஆர்வமுள்ளவர்களையும், முக்கோணம் நடனத்தில் நாட்டமுள்ளவர்களையும், வட்டம் நாடகம் நடிப்பதில் விருப்பமுள்ளவர்களையும் குறிக்கிறது. ஏதேனும் ஒன்றில் மட்டும் விருப்பமுள்ளவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q11-15.png","options":[{"id":"A","text":"15"},{"id":"B","text":"20"},{"id":"C","text":"16"},{"id":"D","text":"21"}],"correctOption":"C","explanation":"தனித்து இருக்கும் எண்களின் கூடுதல் = (7 + 8 + 1) = 16.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q14","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் சதுரம் ஓவியம் வரைவதில் விருப்பமுள்ளவர்களையும், செவ்வகம் விளையாட்டில் ஆர்வமுள்ளவர்களையும், முக்கோணம் நடனத்தில் நாட்டமுள்ளவர்களையும், வட்டம் நாடகம் நடிப்பதில் விருப்பமுள்ளவர்களையும் குறிக்கிறது. ஓவியம் வரைவதில் விருப்பமில்லாத ஆனால் விளையாட்டில் ஆர்வமுள்ளவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q11-15.png","options":[{"id":"A","text":"22"},{"id":"B","text":"25"},{"id":"C","text":"26"},{"id":"D","text":"7"}],"correctOption":"A","explanation":"சதுரத்தை தவிர்த்து செவ்வகத்தில் மட்டும் உள்ள எண்கள் = (8 + 5 + 9) = 22.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q15","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் சதுரம் ஓவியம் வரைவதில் விருப்பமுள்ளவர்களையும், செவ்வகம் விளையாட்டில் ஆர்வமுள்ளவர்களையும், முக்கோணம் நடனத்தில் நாட்டமுள்ளவர்களையும், வட்டம் நாடகம் நடிப்பதில் விருப்பமுள்ளவர்களையும் குறிக்கிறது. குறைந்தபட்சம் மூன்று செயல்பாடுகளில் ஆர்வமுள்ளவர்களின் எண்ணிக்கை:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q11-15.png","options":[{"id":"A","text":"3"},{"id":"B","text":"6"},{"id":"C","text":"9"},{"id":"D","text":"18"}],"correctOption":"D","explanation":"மூன்று மற்றும் அதற்கு மேற்பட்ட வடிவங்களுக்கு பொதுவான எண்கள் = (6 + 3 + 9) = 18.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q16","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் இருசக்கர வாகனத்தைப் பயன்படுத்துபவர்களையும், சதுரம் பேருந்தை பயன்படுத்துபவர்களையும், முக்கோணம் மகிழுந்தை பயன்படுத்துபவர்களையும், செவ்வகம் மிதி வண்டியை பயன்படுத்துபவர்களையும் குறிக்கிறது. எப்பகுதி ஏதேனும் ஒன்றை மட்டும் பயன்படுத்தி அலுவலகத்திற்கு செல்பவர்களை குறிக்கிறது:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q16-20.png","options":[{"id":"A","text":"AEKX"},{"id":"B","text":"ABEK"},{"id":"C","text":"KXEY"},{"id":"D","text":"CBEY"}],"correctOption":"B","explanation":"ஒவ்வொரு வடிவத்தில் மட்டும் உள்ள எழுத்து = A, B, E, K.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q17","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் இருசக்கர வாகனத்தைப் பயன்படுத்துபவர்களையும், சதுரம் பேருந்தை பயன்படுத்துபவர்களையும், முக்கோணம் மகிழுந்தை பயன்படுத்துபவர்களையும், செவ்வகம் மிதி வண்டியை பயன்படுத்துபவர்களையும் குறிக்கிறது. இருசக்கர வாகனத்தை பயன்படுத்தாமல் பேருந்து மற்றும் மிதிவண்டியை பயன்படுத்துபவர்களை குறிப்பது:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q16-20.png","options":[{"id":"A","text":"K"},{"id":"B","text":"E"},{"id":"C","text":"A"},{"id":"D","text":"X"}],"correctOption":"D","explanation":"வட்டத்தை தவிர சதுரம் மற்றும் செவ்வகத்திற்கு பொதுவான எழுத்து = X.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q18","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் இருசக்கர வாகனத்தைப் பயன்படுத்துபவர்களையும், சதுரம் பேருந்தை பயன்படுத்துபவர்களையும், முக்கோணம் மகிழுந்தை பயன்படுத்துபவர்களையும், செவ்வகம் மிதி வண்டியை பயன்படுத்துபவர்களையும் குறிக்கிறது. ஏதேனும் மூன்றை மட்டும் பயன்படுத்தி அலுவலகத்திற்கு செல்பவர்களை குறிப்பது:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q16-20.png","options":[{"id":"A","text":"DZ"},{"id":"B","text":"HZ"},{"id":"C","text":"DL"},{"id":"D","text":"HL"}],"correctOption":"A","explanation":"மூன்று வடிவங்களுக்கு பொதுவான எழுத்துக்கள் = D, Z.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q19","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் இருசக்கர வாகனத்தைப் பயன்படுத்துபவர்களையும், சதுரம் பேருந்தை பயன்படுத்துபவர்களையும், முக்கோணம் மகிழுந்தை பயன்படுத்துபவர்களையும், செவ்வகம் மிதி வண்டியை பயன்படுத்துபவர்களையும் குறிக்கிறது. இருசக்கர வாகனத்தை பயன்படுத்தி பேருந்தை பயன்படுத்தாமல் அலுவலகத்திற்கு செல்பவர்களை குறிப்பது:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q16-20.png","options":[{"id":"A","text":"XK"},{"id":"B","text":"AB"},{"id":"C","text":"YL"},{"id":"D","text":"XY"}],"correctOption":"C","explanation":"சதுரத்தை தவிர மற்ற வடிவங்களில் உள்ள எழுத்துக்கள் = A, B.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q20","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் வட்டம் இருசக்கர வாகனத்தைப் பயன்படுத்துபவர்களையும், சதுரம் பேருந்தை பயன்படுத்துபவர்களையும், முக்கோணம் மகிழுந்தை பயன்படுத்துபவர்களையும், செவ்வகம் மிதி வண்டியை பயன்படுத்துபவர்களையும் குறிக்கிறது. அனைத்து வாகனங்களையும் பயன்படுத்துவர்களை குறிப்பது:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q16-20.png","options":[{"id":"A","text":"D"},{"id":"B","text":"L"},{"id":"C","text":"H"},{"id":"D","text":"C"}],"correctOption":"B","explanation":"அனைத்து வடிவங்களுக்கும் பொதுவான எழுத்து = L.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q21","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் செவ்வகம், சதுரம், வட்டம், முக்கோணம் ஆகியவை முறையே நிலக்கரி, இரும்பு, தங்கம் மற்றும் வெள்ளி உற்பத்தி செய்யப்படும் இடங்களைக் குறிக்கிறது. எப்பகுதியில் இரும்பு மற்றும் தங்கம் மட்டும் உற்பத்தி செய்யப்படுகிறது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q21-25.png","options":[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"4"},{"id":"D","text":"8"}],"correctOption":"C","explanation":"சதுரம் மற்றும் வட்டத்திற்கு மட்டும் பொதுவானது = 4.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q22","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் செவ்வகம், சதுரம், வட்டம், முக்கோணம் ஆகியவை முறையே நிலக்கரி, இரும்பு, தங்கம் மற்றும் வெள்ளி உற்பத்தி செய்யப்படும் இடங்களைக் குறிக்கிறது. எப்பகுதி தங்கம் மற்றும் வெள்ளி உற்பத்தியைக் குறிக்கிறது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q21-25.png","options":[{"id":"A","text":"10"},{"id":"B","text":"11"},{"id":"C","text":"8"},{"id":"D","text":"6"}],"correctOption":"A","explanation":"வட்டம் மற்றும் முக்கோணத்திற்கு பொதுவானது = 10.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q23","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் செவ்வகம், சதுரம், வட்டம், முக்கோணம் ஆகியவை முறையே நிலக்கரி, இரும்பு, தங்கம் மற்றும் வெள்ளி உற்பத்தி செய்யப்படும் இடங்களைக் குறிக்கிறது. எப்பகுதி நான்கு தாதுக்கள் உற்பத்தி செய்யப்படும் பகுதிகளைக் குறிக்கிறது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q21-25.png","options":[{"id":"A","text":"8"},{"id":"B","text":"9"},{"id":"C","text":"10"},{"id":"D","text":"11"}],"correctOption":"A","explanation":"அனைத்து வடிவங்களுக்கும் பொதுவானது = 8.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q24","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் செவ்வகம், சதுரம், வட்டம், முக்கோணம் ஆகியவை முறையே நிலக்கரி, இரும்பு, தங்கம் மற்றும் வெள்ளி உற்பத்தி செய்யப்படும் இடங்களைக் குறிக்கிறது. எப்பகுதியில் வெள்ளி அல்லாது நிலக்கரி, இரும்பு மற்றும் தங்கம் உற்பத்தி செய்யப்படுகிறது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q21-25.png","options":[{"id":"A","text":"9"},{"id":"B","text":"5"},{"id":"C","text":"4"},{"id":"D","text":"2"}],"correctOption":"D","explanation":"முக்கோணத்தை தவிர மற்ற மூன்று வடிவங்களுக்கும் பொதுவானது = 2.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q25","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்காணும் படத்தில் செவ்வகம், சதுரம், வட்டம், முக்கோணம் ஆகியவை முறையே நிலக்கரி, இரும்பு, தங்கம் மற்றும் வெள்ளி உற்பத்தி செய்யப்படும் இடங்களைக் குறிக்கிறது. எப்பகுதியில் இரும்பு அல்லாது நிலக்கரி, தங்கம் மற்றும் வெள்ளி உற்பத்தி செய்யப்படுகிறது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q21-25.png","options":[{"id":"A","text":"6"},{"id":"B","text":"9"},{"id":"C","text":"10"},{"id":"D","text":"11"}],"correctOption":"C","explanation":"சதுரத்தை தவிர மற்ற மூன்று வடிவங்களுக்கும் பொதுவானது = 10.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q26","subject":"MAT","topic":"Unit 13","questionText":"கீழே கொடுக்கப்பட்ட படத்தை உற்று நோக்கி விடையளி. வட்டங்கள் முறையே தலைவர்கள், இந்தியர்கள் மற்றும் பாடகர்களைக் குறிக்கின்றன. எந்த பகுதி பாடகர்கள் அல்லாத இந்திய தலைவர்களைக் குறிக்கின்றது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q26-30.png","options":[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"4"},{"id":"D","text":"5"}],"correctOption":"A","explanation":"பாடகர்கள் வட்டத்தை தவிர்த்து இந்தியர்கள் மற்றும் தலைவர்கள் வட்டங்களுக்கு பொதுவானது = 2.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q27","subject":"MAT","topic":"Unit 13","questionText":"கீழே கொடுக்கப்பட்ட படத்தை உற்று நோக்கி விடையளி. வட்டங்கள் முறையே தலைவர்கள், இந்தியர்கள் மற்றும் பாடகர்களைக் குறிக்கின்றன. எந்த பகுதி, பாடகர்களாக உள்ள இந்தியத் தலைவர்களைக் குறிக்கிறது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q26-30.png","options":[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"4"},{"id":"D","text":"5"}],"correctOption":"B","explanation":"மூன்று வட்டங்களுக்கும் பொதுவானது = 3.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q28","subject":"MAT","topic":"Unit 13","questionText":"கீழே கொடுக்கப்பட்ட படத்தை உற்று நோக்கி விடையளி. வட்டங்கள் முறையே தலைவர்கள், இந்தியர்கள் மற்றும் பாடகர்களைக் குறிக்கின்றன. எந்தப்பகுதி, பாடகர்களாகவும் இந்தியர்களாகவும் அல்லாத தலைவர்களைக் குறிக்கிறது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q26-30.png","options":[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"6"},{"id":"D","text":"7"}],"correctOption":"C","explanation":"தலைவர்கள் வட்டத்தில் மட்டும் தனியாக உள்ளது = 6.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q29","subject":"MAT","topic":"Unit 13","questionText":"கீழே கொடுக்கப்பட்ட படத்தை உற்று நோக்கி விடையளி. வட்டங்கள் முறையே தலைவர்கள், இந்தியர்கள் மற்றும் பாடகர்களைக் குறிக்கின்றன. எப்பகுதி தலைவர்களாக அல்லாத இந்தியர்களையும் பாடகர்களையும் குறிக்கிறது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q26-30.png","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}],"correctOption":"D","explanation":"தலைவர்கள் வட்டத்தை தவிர்த்து இந்தியர்கள் மற்றும் பாடகர்கள் வட்டங்களுக்கு பொதுவானது = 4.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q30","subject":"MAT","topic":"Unit 13","questionText":"கீழே கொடுக்கப்பட்ட படத்தை உற்று நோக்கி விடையளி. வட்டங்கள் முறையே தலைவர்கள், இந்தியர்கள் மற்றும் பாடகர்களைக் குறிக்கின்றன. எப்பகுதி இந்தியர்களாகவும் தலைவர்களாகவும் அல்லாத பாடகர்களைக் குறிக்கின்றது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q26-30.png","options":[{"id":"A","text":"2"},{"id":"B","text":"4"},{"id":"C","text":"6"},{"id":"D","text":"7"}],"correctOption":"D","explanation":"பாடகர்கள் வட்டத்தில் மட்டும் தனியாக உள்ளது = 7.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q31","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்கண்ட வரைபடத்தில் முக்கோணம் மருத்துவர்களையும், வட்டம் விளையாடுபவர்களையும், செவ்வகம் ஓவியர்களையும் குறிக்கிறது. விளையாடுபவர்களாகவும், ஓவியர்களாகவும் உள்ள மருத்துவர்களின் எண்ணிக்கையை குறிப்பது?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q31-35.png","options":[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"4"},{"id":"D","text":"5"}],"correctOption":"D","explanation":"மூன்று வடிவங்களுக்கும் பொதுவான எண் = 5.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q32","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்கண்ட வரைபடத்தில் முக்கோணம் மருத்துவர்களையும், வட்டம் விளையாடுபவர்களையும், செவ்வகம் ஓவியர்களையும் குறிக்கிறது. ஓவியர்களாக உள்ள விளையாடுபவர்களின் எண்ணிக்கையைக் குறிக்கும் எண்:","questionImage":"/assets/matquiz/image/unit13/image/unit13/q31-35.png","options":[{"id":"A","text":"6"},{"id":"B","text":"7"},{"id":"C","text":"8"},{"id":"D","text":"4"}],"correctOption":"A","explanation":"செவ்வகம் மற்றும் வட்டத்திற்கு பொதுவான எண் = 6.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q33","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்கண்ட வரைபடத்தில் முக்கோணம் மருத்துவர்களையும், வட்டம் விளையாடுபவர்களையும், செவ்வகம் ஓவியர்களையும் குறிக்கிறது. விளையாடுபவர்களாகவோ, மருத்துவர்களாகவோ அல்லாத ஓவியர்களின் எண்ணிக்கையைக் குறிக்கும் எண்?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q31-35.png","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}],"correctOption":"A","explanation":"வட்டம் மற்றும் முக்கோணத்தை தவிர செவ்வகத்தில் மட்டும் உள்ள எண் = 1.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q34","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்கண்ட வரைபடத்தில் முக்கோணம் மருத்துவர்களையும், வட்டம் விளையாடுபவர்களையும், செவ்வகம் ஓவியர்களையும் குறிக்கிறது. எந்த எண் விளையாடுபவர்களாகவோ அல்லது ஓவியர்களாகவோ அல்லாத மருத்துவர்களாக உள்ளவர்களின் எண்ணிக்கை?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q31-35.png","options":[{"id":"A","text":"21"},{"id":"B","text":"4"},{"id":"C","text":"3"},{"id":"D","text":"5"}],"correctOption":"C","explanation":"வட்டம் மற்றும் செவ்வகத்தை தவிர முக்கோணத்தில் மட்டும் உள்ள எண் = 3.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-13-q35","subject":"MAT","topic":"Unit 13","questionText":"கீழ்க்கண்ட வரைபடத்தில் முக்கோணம் மருத்துவர்களையும், வட்டம் விளையாடுபவர்களையும், செவ்வகம் ஓவியர்களையும் குறிக்கிறது. எந்த எண் ஓவியர்களாகவோ அல்லது மருத்துவர்களாகவோ அல்லாத விளையாடுபவர்களாக உள்ளவர்களின் எண்ணிக்கை?","questionImage":"/assets/matquiz/image/unit13/image/unit13/q31-35.png","options":[{"id":"A","text":"1, 2"},{"id":"B","text":"3, 4"},{"id":"C","text":"6, 7"},{"id":"D","text":"7, 8"}],"correctOption":"D","explanation":"செவ்வகம் மற்றும் முக்கோணத்தை தவிர வட்டத்தில் மட்டும் உள்ள எண்கள் = 7, 8.","marks":1,"negativeMarks":0}]', datetime('now'));
INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('MAT_14', 'MAT', 14, '[{"id":"unit-matquiz-14-q1","subject":"MAT","topic":"Unit 14","questionText":"கொடுக்கப்பட்ட வார்த்தையில் உள்ள எழுத்துக்களிலிருந்து உருவாக்கப்படக் கூடிய வார்த்தையினைத் தேர்ந்தெடுக்கவும்: CHEMICAL","options":[{"id":"A","text":"CLICHE"},{"id":"B","text":"CLINCHE"},{"id":"C","text":"CHEMIST"},{"id":"D","text":"MENACE"}],"correctOption":"A","explanation":"CHEMICAL என்ற வார்த்தையில் உள்ள எழுத்துக்களில் இருந்து CLICHE என்ற வார்த்தை உருவாக்கப்பட்டுள்ளது.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-14-q2","subject":"MAT","topic":"Unit 14","questionText":"கொடுக்கப்பட்ட வார்த்தையில் உள்ள எழுத்துக்களிலிருந்து உருவாக்கப்படக் கூடிய வார்த்தையினைத் தேர்ந்தெடுக்கவும்: UNION","options":[{"id":"A","text":"ONION"},{"id":"B","text":"NOUN"},{"id":"C","text":"NEON"},{"id":"D","text":"NOON"}],"correctOption":"B","explanation":"UNION என்ற வார்த்தையில் உள்ள எழுத்துக்களில் இருந்து NOUN என்ற வார்த்தை உருவாக்கப்பட்டுள்ளது.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-14-q3","subject":"MAT","topic":"Unit 14","questionText":"கொடுக்கப்பட்ட வார்த்தையில் உள்ள எழுத்துக்களிலிருந்து உருவாக்கப்படக் கூடிய வார்த்தையினைத் தேர்ந்தெடுக்கவும்: PRINCIPAL","options":[{"id":"A","text":"LEAP"},{"id":"B","text":"PEAR"},{"id":"C","text":"PAIR"},{"id":"D","text":"PRINCE"}],"correctOption":"C","explanation":"PRINCIPAL என்ற வார்த்தையில் உள்ள எழுத்துக்களில் இருந்து PAIR என்ற வார்த்தை உருவாக்கப்பட்டுள்ளது.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-14-q4","subject":"MAT","topic":"Unit 14","questionText":"கொடுக்கப்பட்ட வார்த்தையில் உள்ள எழுத்துக்களிலிருந்து உருவாக்கப்படக் கூடிய வார்த்தையினைத் தேர்ந்தெடுக்கவும்: TEASER","options":[{"id":"A","text":"REAL"},{"id":"B","text":"EASY"},{"id":"C","text":"ERASER"},{"id":"D","text":"EASE"}],"correctOption":"D","explanation":"TEASER என்ற வார்த்தையில் உள்ள எழுத்துக்களில் இருந்து EASE என்ற வார்த்தை உருவாக்கப்பட்டுள்ளது.","marks":1,"negativeMarks":0},{"id