INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('MAT_15', 'MAT', 15, '[{"id":"unit-matquiz-15-q1","subject":"MAT","topic":"Unit 15","questionText":"கீழே கொடுக்கப்பட்டுள்ள வார்த்தையில் உள்ள எழுத்துக்களிலிருந்து உருவாக்கப்பட முடியாத வார்த்தையினைத் தேர்ந்தெடுக்கவும்: POSTFORMING","options":[{"id":"A","text":"STRONG"},{"id":"B","text":"STRING"},{"id":"C","text":"PERFORM"},{"id":"D","text":"POST"}],"correctOption":"C","explanation":"POSTFORMING என்ற வார்த்தையில் உள்ள எழுத்துக்களில் இருந்து PERFORM என்ற வார்த்தை உருவாக்கப்படவில்லை.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-15-q2","subject":"MAT","topic":"Unit 15","questionText":"கீழே கொடுக்கப்பட்டுள்ள வார்த்தையில் உள்ள எழுத்துக்களிலிருந்து உருவாக்கப்பட முடியாத வார்த்தையினைத் தேர்ந்தெடுக்கவும்: MERMAID","options":[{"id":"A","text":"MAID"},{"id":"B","text":"DEER"},{"id":"C","text":"RAID"},{"id":"D","text":"DAM"}],"correctOption":"B","explanation":"MERMAID என்ற வார்த்தையில் உள்ள எழுத்துக்களில் இருந்து DEER என்ற வார்த்தை உருவாக்கப்படவில்லை (E என்ற எழுத்து ஒரு முறை மட்டுமே உள்ளது).","marks":1,"negativeMarks":0},{"id":"unit-matquiz-15-q3","subject":"MAT","topic":"Unit 15","questionText":"கீழே கொடுக்கப்பட்டுள்ள வார்த்தையில் உள்ள எழுத்துக்களிலிருந்து உருவாக்கப்பட முடியாத வார்த்தையினைத் தேர்ந்தெடுக்கவும்: SNOWY","options":[{"id":"A","text":"SNOW"},{"id":"B","text":"WON"},{"id":"C","text":"SON"},{"id":"D","text":"WHY"}],"correctOption":"D","explanation":"SNOWY என்ற வார்த்தையில் உள்ள எழுத்துக்களில் இருந்து WHY என்ற வார்த்தை உருவாக்கப்படவில்லை (H இல்லை).","marks":1,"negativeMarks":0},{"id":"unit-matquiz-15-q4","subject":"MAT","topic":"Unit 15","questionText":"கீழே கொடுக்கப்பட்டுள்ள வார்த்தையில் உள்ள எழுத்துக்களிலிருந்து உருவாக்கப்பட முடியாத வார்த்தையினைத் தேர்ந்தெடுக்கவும்: WATERMELON","options":[{"id":"A","text":"LEMON"},{"id":"B","text":"LION"},{"id":"C","text":"METER"},{"id":"D","text":"TERM"}],"correctOption":"B","explanation":"WATERMELON என்ற வார்த்தையில் உள்ள எழுத்துக்களில் இர