INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('MAT_16', 'MAT', 16, '[{"id":"unit-matquiz-16-q1","subject":"MAT","topic":"Unit 16","questionText":"கொடுக்கப்பட்ட வார்த்தைகளை ஆங்கில அகராதியின் அடிப்படையில் அகர வரிசையில் எழுதி முதலில் வரும் வார்த்தையைத் தேர்ந்தெடு: \n1) Office 2) Late 3) Zone 4) Yellow","options":[{"id":"A","text":"Office"},{"id":"B","text":"Late"},{"id":"C","text":"Zone"},{"id":"D","text":"Yellow"}],"correctOption":"B","explanation":"Office, Late, Zone, Yellow இவற்றில் அகராதி வரிசைப்படி L முதலில் வரும். எனவே Late என்ற வார்த்தை முதலில் அமையும்.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-16-q2","subject":"MAT","topic":"Unit 16","questionText":"கொடுக்கப்பட்ட வார்த்தைகளை ஆங்கில அகராதியின் அடிப்படையில் அகர வரிசையில் எழுதி முதலில் வரும் வார்த்தையைத் தேர்ந்தெடு: \n1) Short 2) Shore 3) Shirt 4) Shout","options":[{"id":"A","text":"Short"},{"id":"B","text":"Shore"},{"id":"C","text":"Shirt"},{"id":"D","text":"Shout"}],"correctOption":"C","explanation":"Short, Shore, Shirt, Shout - இவற்றில் முதல் இரண்டு எழுத்துக்கள் (sh) அனைத்து வார்த்தைகளிலும் உள்ளது. எனவே, மூன்றாவது எழுத்துக்களான o, o, i, o ஆகியவற்றை பார்க்கவும். இதில் i என்ற எழுத்தே முதலில் அமையும். எனவே, Shirt என்ற வார்த்தை முதலில் அமையும்.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-16-q3","subject":"MAT","topic":"Unit 16","questionText":"கொடுக்கப்பட்ட வார்த்தைகளை ஆங்கில அகராதியின் அடிப்படையில் அகர வரிசையில் எழுதி முதலில் வரும் வார்த்தையைத் தேர்ந்தெடு: \n1) Race 2) Accident 3) Injury 4) Disability","options":[{"id":"A","text":"Race"},{"id":"B","text":"Accident"},{"id":"C","text":"Injury"},{"id":"D","text":"Disability"}],"correctOption":"B","explanation":"Race, Accident, Injury, Disability இவற்றில் அகராதி வரிசைப்படி A முதலில் அமையும். எனவே Accident என்ற வார்த்தை முதலில் அமையும்.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-16-q4","subject":"MAT","topic":"Unit 16","questionText":"கொடுக்கப்பட்ட வார்த்தைகளை ஆங்கில அகராதியின் அடிப்படையில் அகர வரிசையில் எழுதி முதலில் வரும் வார்த்தையைத் தேர்ந்தெடு: \n1) Era 2) Ice 3) Car 4) Hill","options":[{"id":"A","text":"Era"},{"id":"B","text":"Ice"},{"id":"C","text":"Car"},{"id":"D","text":"Hill"}],"correctOption":"C","explanation":"Era, Ice, Car, Hill - இவற்றில் அகராதி வரிசைப்படி C முதலில் அமையும். எனவே Car என்ற வார்த்தை முதலில் அமையும்.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-16-q5","subject":"MAT","topic":"Unit 16","questionText":"கொடுக்கப்பட்ட வார்த்தைகளை ஆங்கில அகராதியின் அடிப்படையில் அகர வரிசையில் எழுதி முதலில் வரும் வார்த்தையைத் தேர்ந்தெடு: \n1) Woman 2) Wood 3) World 4) Wound","options":[{"id":"A","text":"Woman"},{"id":"B","text":"Wood"},{"id":"C","text":"World"},{"id":"D","text":"Wound"}],"correctOption":"A","explanation":"Woman, Wood, World, Wound - இவற்றில் W மற்றும் O ஆகிய முதல் இரு எழுத்துக்கள் அனைத்து வார்த்தைகளிலும் பொதுவாக உள்ளது. எனவே, மூன்றாவது எழுத்துக்களான m, o, r, u ஆகியவற்றை பார்க்கும்பொழுது m என்ற வார்த்தை முதலில் அமையும். எனவே, Woman என்ற வார்த்தை முதலில் அமையும்.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-16-q6","subject":"MAT","topic":"Unit 16","questionText":"கொடுக்கப்பட்ட வார்த்தைகளை ஆங்கில அகராதியின் அடிப்படையில் அகர வரிசையில் எழுதி முதலில் வரும் வார்த்தையைத் தேர்ந்தெடு: \n1) Yellow 2) Table 3) Apple 4) Plate","options":[{"id":"A","text":"Yellow"},{"id":"B","text":"Table"},{"id":"C","text":"Apple"},{"id":"D","text":"Plate"}],"correctOption":"C","explanation":"Yellow, Table, Apple, Plate - இவற்றில் அகராதி வரிசைப்படி A முதலில் அமையும். எனவே Apple என்ற வார்த்தை முதலில் அமையும்.","marks":1,"negativeMarks":0},{"id":"unit-matquiz-16-q7","subject":"MAT","topic":"Unit 16","questionText":"கொடுக்கப்பட்ட வார்த்தைகளை ஆங்கில அகராதியின் அடிப்படையில் அகர வரிசையில் எழுதி முதலில் வரும் வார்த்தையைத் தேர்ந்தெடு: \n1) Examination 2) Association 3) Legistation 4) Foundation","options":[{"id":"A","text":"Examination"},{"id":"B","text":"Association"},{"id":"C","text":"Legistation"},{"id":"D","text":"Foundation"}],"correctOption":"B","explanation":"Exami