INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('SAT_MATHS_5', 'SAT_MATHS', 5, '[{"id":"unit-satmaths-5-q1","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சதுரத்தின் பக்க அளவு 16 மீ. எனில், அதன் சுற்றளவு என்ன?","options":[{"id":"A","text":"4 மீ"},{"id":"B","text":"256 மீ"},{"id":"C","text":"32 மீ"},{"id":"D","text":"64 மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 64 மீ. சதுரத்தின் சுற்றளவு காணும் சூத்திரம் = 4 × பக்கம். எனவே, 4 × 16 = 64 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q2","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சதுரத்தின் பக்க அளவு 9 மீ. எனில், அதன் பரப்பளவு என்ன?","options":[{"id":"A","text":"81 ச.மீ"},{"id":"B","text":"17 ச.மீ"},{"id":"C","text":"13 ச.மீ"},{"id":"D","text":"20 ச.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 81 ச.மீ. சதுரத்தின் பரப்பளவு = பக்கம் × பக்கம் = 9 × 9 = 81 ச.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q3","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சதுரத்தின் பரப்பளவு 169 செ.மீ² எனில் அதன் பக்கம்","options":[{"id":"A","text":"12 செ.மீ"},{"id":"B","text":"8 செ.மீ"},{"id":"C","text":"13 செ.மீ"},{"id":"D","text":"16 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 13 செ.மீ. பரப்பளவு = பக்கம்² = 169. எனவே, பக்கம் = √169 = 13 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q4","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சதுர வடிவப் பூங்காவின் சுற்றளவு 40 மீ எனில், பூங்காவின் ஒரு பக்க அளவு","options":[{"id":"A","text":"10 மீ"},{"id":"B","text":"8 மீ"},{"id":"C","text":"160 மீ"},{"id":"D","text":"16 மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 10 மீ. சுற்றளவு 4 × பக்கம் = 40. எனவே, பக்கம் = 40 / 4 = 10 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q5","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சதுர வடிவ தோட்டத்தை ஒருவர் எல்லையில் சுற்றி வர 64 மீ. நடக்க வேண்டியுள்ளது. எனில் அத்தோட்டத்தின் பரப்பு","options":[{"id":"A","text":"32 ச.மீ"},{"id":"B","text":"81 ச.மீ"},{"id":"C","text":"256 ச.மீ"},{"id":"D","text":"18 ச.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 256 ச.மீ. எல்லையைச் சுற்றி வருவது சுற்றளவைக் குறிக்கும் (4a = 64 மீ), இதிலிருந்து a = 16 மீ. பரப்பளவு = 16 × 16 = 256 ச.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q6","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சதுர வடிவப் பூங்காவின் பரப்பளவு 36 மீ² எனில், பூங்காவின் சுற்றளவு","options":[{"id":"A","text":"24 மீ"},{"id":"B","text":"81 மீ"},{"id":"C","text":"9 மீ"},{"id":"D","text":"18 மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 24 மீ. பரப்பளவு a² = 36 எனில் a = 6 மீ. சுற்றளவு 4a = 4 × 6 = 24 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q7","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் பரப்பளவு ____ ச.அலகுகள்.","options":[{"id":"A","text":"\\( l \\times b \\)"},{"id":"B","text":"\\( b \\times h \\)"},{"id":"C","text":"\\( \\frac{1}{2} \\times h \\times (a+b) \\)"},{"id":"D","text":"\\( \\frac{1}{2} \\times d \\times (h_1+h_2) \\)"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): \\( l \\times b \\). செவ்வகத்தின் பரப்பளவு நீளம் (l) மற்றும் அகலத்தின் (b) பெருக்கற்பலனுக்குச் சமம்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q8","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் நீளம் 70 மி.மீ மற்றும் அகலம் 60 மி.மீ எனில் அதன் பரப்பளவு","options":[{"id":"A","text":"4200 ச.மி.மீ"},{"id":"B","text":"26 ச.மி.மீ"},{"id":"C","text":"130 ச.மி.மீ"},{"id":"D","text":"42 ச.செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 42 ச.செ.மீ. பரப்பளவு = 70 × 60 = 4200 ச.மி.மீ. 100 ச.மி.மீ = 1 ச.செ.மீ என்பதால், 4200 ச.மி.மீ = 42 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q9","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் நீளம் 6.3 மீ மற்றும் அகலம் 3.2 மீ எனில் அதன் சுற்றளவு","options":[{"id":"A","text":"9.5 மீ"},{"id":"B","text":"20.16 மீ"},{"id":"C","text":"19 மீ"},{"id":"D","text":"25.2 மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 19 மீ. செவ்வகத்தின் சுற்றளவு = 2(l + b) = 2(6.3 + 3.2) = 2(9.5) = 19 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q10","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் பரப்பளவு 84 மீ² மற்றும் நீளம் 14 மீ எனில் அகலம்","options":[{"id":"A","text":"6 மீ"},{"id":"B","text":"98 மீ"},{"id":"C","text":"1176 மீ"},{"id":"D","text":"8 மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 6 மீ. அகலம் = பரப்பளவு / நீளம் = 84 / 14 = 6 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q11","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வக வடிவிலான புகைப்படம் ஒன்றின் பரப்பளவு 820 ச.செ.மீ. மற்றும் அகலம் 20 செ.மீ. எனில் அதன் நீளம்","options":[{"id":"A","text":"40 செ.மீ."},{"id":"B","text":"41 செ.மீ."},{"id":"C","text":"45 செ.மீ."},{"id":"D","text":"48 செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 41 செ.மீ. நீளம் = பரப்பளவு / அகலம் = 820 / 20 = 41 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q12","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் சுற்றளவு 36 மி.மீ. மற்றும் அதன் நீளம் 12 மி.மீ. எனில் அதன் அகலம்?","options":[{"id":"A","text":"32 மி.மீ."},{"id":"B","text":"6 மி.மீ."},{"id":"C","text":"3 மி.மீ."},{"id":"D","text":"24 மி.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 6 மி.மீ. சுற்றளவு 2(l + b) = 36. எனவே l + b = 18. 12 + b = 18 என்றால் b = 6 மி.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q13","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் சுற்றளவு 200 மி.மீ. மற்றும் அதன் அகலம் 30 மி.மீ. எனில் அதன் பரப்பளவு எவ்வளவு?","options":[{"id":"A","text":"460 ச.மி.மீ"},{"id":"B","text":"6000 ச.மி.மீ"},{"id":"C","text":"3000 ச.மி.மீ"},{"id":"D","text":"2100 ச.மி.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 2100 ச.மி.மீ. சுற்றளவு 2(l + 30) = 200 => l + 30 = 100 => l = 70. பரப்பளவு = l × b = 70 × 30 = 2100 ச.மி.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q14","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் பரப்பளவு 90 ச.மீ. மற்றும் அதன் நீளம் 15 மீ. எனில் அதன் சுற்றளவு என்ன?","options":[{"id":"A","text":"6 மீ"},{"id":"B","text":"21 மீ"},{"id":"C","text":"42 மீ"},{"id":"D","text":"1350 மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 42 மீ. அகலம் = 90 / 15 = 6 மீ. சுற்றளவு = 2(15 + 6) = 42 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q15","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு முக்கோணத்தின் அடிப்பக்கம் 9 செ.மீ மற்றும் உயரம் 12 செ.மீ எனில் அதன் பரப்பளவு","options":[{"id":"A","text":"108 ச.செ.மீ"},{"id":"B","text":"21 ச.செ.மீ"},{"id":"C","text":"42 ச.செ.மீ"},{"id":"D","text":"54 ச.செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 54 ச.செ.மீ. முக்கோணத்தின் பரப்பளவு = (1/2) × b × h = (1/2) × 9 × 12 = 54 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q16","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு முக்கோணத்தின் பரப்பளவு 240 ச.செ.மீ. மற்றும் உயரம் 12 செ.மீ எனில் அதன் அடிப்பக்கம் என்ன?","options":[{"id":"A","text":"20 செ.மீ."},{"id":"B","text":"40 செ.மீ."},{"id":"C","text":"80 செ.மீ."},{"id":"D","text":"24 செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 40 செ.மீ. (1/2) × b × 12 = 240 => 6b = 240 => b = 40 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q17","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு விளையாட்டுத்திடல் செங்கோண முக்கோண வடிவில் உள்ளது. செங்கோணம் தாங்கிய பக்கங்கள் 50 மீ, 80 மீ திடலில் சிமெண்ட் பூச சதுர மீட்டருக்கு ₹5 வீதம் ஆகும் செலவு","options":[{"id":"A","text":"₹20000"},{"id":"B","text":"₹15000"},{"id":"C","text":"₹10000"},{"id":"D","text":"₹12500"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): ₹10000. பரப்பளவு = (1/2) × 50 × 80 = 2000 ச.மீ. ஆகும் செலவு = 2000 × 5 = ₹10000.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q18","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு தோட்டம் 5 மீ பக்க அளவுடைய சதுர வடிவில் உள்ளது. ஒவ்வொரு பக்கமும் 2 சுற்றுகள் கம்பியால் வேலி அமைக்க வேண்டும். மீட்டருக்கு ₹10 வீதம் தோட்டத்திற்கு வேலி அமைக்கத் தேவைப்படும் தொகையினைக் காண்க.","options":[{"id":"A","text":"₹500"},{"id":"B","text":"₹600"},{"id":"C","text":"₹400"},{"id":"D","text":"₹300"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): ₹400. தோட்டத்தின் சுற்றளவு = 4 × 5 = 20 மீ. 2 சுற்றுகளுக்குத் தேவையான கம்பி = 2 × 20 = 40 மீ. மொத்தச் செலவு = 40 × 10 = ₹400.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q19","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சதுரத்தின் பக்கம் 10 செ.மீ. அதனுடைய பக்கம் மூன்று மடங்காகும் போது சுற்றளவு எத்தனை மடங்காக அதிகரிக்கும்?","options":[{"id":"A","text":"2 மடங்கு"},{"id":"B","text":"3 மடங்கு"},{"id":"C","text":"4 மடங்கு"},{"id":"D","text":"5 மடங்கு"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 3 மடங்கு. சதுரத்தின் சுற்றளவு அதன் பக்க அளவோடு நேர்விகிதத்தில் இருக்கும் (P = 4a). எனவே, பக்க அளவு மூன்று மடங்கானால் சுற்றளவும் 3 மடங்காகவே அதிகரிக்கும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q20","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சதுரத்தின் பக்கத்தை நான்கில் ஒரு பங்காக குறைத்தால் உருவாகும் புதிய சதுரத்தின் பரப்பளவில் என்ன மாற்றம் ஏற்படும்?","options":[{"id":"A","text":"1/15 பகுதி குறையும்"},{"id":"B","text":"1/16 பகுதி அதிகரிக்கும்"},{"id":"C","text":"1/16 பகுதி குறையும்"},{"id":"D","text":"1/15 பகுதி அதிகரிக்கும்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 1/16 பகுதி குறையும். பரப்பளவு என்பது பக்கத்தின் வர்க்கமாகும் (Area = a²). பக்கத்தை (1/4) ஆகக் குறைத்தால், பரப்பளவு (1/4)² = 1/16 ஆகக் குறையும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q21","subject":"SAT_MATHS","topic":"Unit 5","questionText":"85 மீ நீளமும், 45 மீ அகலமும் கொண்ட சுவற்றில் வண்ணம் தீட்ட 1 ச.மீ. க்கு ₹8.80 வீதம் ஆகும் மொத்த செலவு","options":[{"id":"A","text":"₹33,660"},{"id":"B","text":"₹33,600"},{"id":"C","text":"₹43,660"},{"id":"D","text":"₹27,660"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): ₹33,660. சுவற்றின் பரப்பளவு = 85 × 45 = 3825 ச.மீ. மொத்த செலவு = 3825 × 8.80 = ₹33,660.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q22","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ABCD என்ற சதுரத்தில் AC ஒரு மூலைவிட்டம் எனில் ∠BAC இன் மதிப்பு","options":[{"id":"A","text":"90°"},{"id":"B","text":"45°"},{"id":"C","text":"180°"},{"id":"D","text":"30°"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 45°. சதுரத்தின் ஒவ்வொரு கோணமும் 90° ஆகும். மூலைவிட்டம் அந்தக் கோணத்தை இருசமக் கூறிடும். எனவே, 90° / 2 = 45°.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q23","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் ஒவ்வொரு பக்கமும் இரு மடங்காகும் போது அதனுடைய பரப்பளவு","options":[{"id":"A","text":"2 மடங்கு அதிகரிக்கும்"},{"id":"B","text":"4 மடங்கு குறையும்"},{"id":"C","text":"2 மடங்கு குறையும்"},{"id":"D","text":"4 மடங்கு அதிகரிக்கும்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 4 மடங்கு அதிகரிக்கும். செவ்வகத்தின் பரப்பளவு = l × b. இரு மடங்கானால் புதிய பரப்பளவு = (2l) × (2b) = 4(l × b) = 4 மடங்கு.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q24","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வக வடிவ பூங்காவின் நீளம் அகலத்தை விட 14 மீ அதிகமாக உள்ளது. அப்பூங்காவின் சுற்றளவு 200 மீ எனில் அதன் நீளம்","options":[{"id":"A","text":"58 மீ"},{"id":"B","text":"57 மீ"},{"id":"C","text":"43 மீ"},{"id":"D","text":"63 மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 57 மீ. அகலத்தை b என்க. நீளம் l = b + 14. சுற்றளவு 2(l + b) = 200. l + b = 100 => b + 14 + b = 100 => 2b = 86 => b = 43. நீளம் = 43 + 14 = 57 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q25","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வக வடிவ தாளின் சுற்றளவு 56 cm ஆகும். அதன் நீளமானது அகலத்தைப் போல மூன்று மடங்காகும் எனில், அகலம் என்ன?","options":[{"id":"A","text":"8 cm"},{"id":"B","text":"56 cm"},{"id":"C","text":"7 cm"},{"id":"D","text":"21 cm"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 7 cm. நீளம் l = 3b. சுற்றளவு 2(l + b) = 56. l + b = 28 => 3b + b = 28 => 4b = 28 => b = 7 cm.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q26","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் நீளம் 40 செ.மீ. மற்றும் அகலம் 20 செ.மீ. எனில், அச்செவ்வகத்திலிருந்து எத்தனை 10 செ.மீ. பக்க அளவுள்ள சதுரங்களை உருவாக்க முடியும்?","options":[{"id":"A","text":"10"},{"id":"B","text":"9"},{"id":"C","text":"8"},{"id":"D","text":"7"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 8. செவ்வகத்தின் பரப்பளவு = 40 × 20 = 800 ச.செ.மீ. சதுரத்தின் பரப்பளவு = 10 × 10 = 100 ச.செ.மீ. உருவாக்கக் கூடிய சதுரங்களின் எண்ணிக்கை = 800 / 100 = 8.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q27","subject":"SAT_MATHS","topic":"Unit 5","questionText":"L வடிவப் படத்தின் சுற்றளவு காண்க (வெளிப்புற பக்கங்கள் 28 செ.மீ மற்றும் 28 செ.மீ, மேற்புறம் மற்றும் வலதுபுறம் 7 செ.மீ).","options":[{"id":"A","text":"70 செ.மீ"},{"id":"B","text":"63 செ.மீ"},{"id":"C","text":"108 செ.மீ"},{"id":"D","text":"112 செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 112 செ.மீ. L வடிவத்தின் சுற்றளவு = 28 (வெளிப்புற செங்குத்து) + 28 (வெளிப்புற கிடைமட்டம்) + 7 (மேற்புறம்) + 21 (உட்புற செங்குத்து: 28-7) + 21 (உட்புற கிடைமட்டம்: 28-7) + 7 (வலதுபுறம்) = 112 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q28","subject":"SAT_MATHS","topic":"Unit 5","questionText":"L வடிவப் படத்தின் பரப்பளவு காண்க (வெளிப்புற பக்கங்கள் 28 செ.மீ மற்றும் 28 செ.மீ, மேற்புறம் மற்றும் வலதுபுறம் 7 செ.மீ).","options":[{"id":"A","text":"392 ச.செ.மீ"},{"id":"B","text":"196 ச.செ.மீ"},{"id":"C","text":"343 ச.செ.மீ"},{"id":"D","text":"112 ச.செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 343 ச.செ.மீ. இந்தப் படத்தை இரண்டு செவ்வகங்களாகப் பிரிக்கலாம்: (28×7) மற்றும் (21×7). பரப்பளவு = 196 + 147 = 343 ச.செ.மீ. (அல்லது பெரிய 28×28 சதுரத்திலிருந்து 21×21 சதுரத்தைக் கழித்தால், 784 - 441 = 343 ச.செ.மீ கிடைக்கும்).","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q29","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு இணைகரத்தின் பரப்பளவு ____ ச.அலகுகள்.","options":[{"id":"A","text":"\\( l \\times b \\)"},{"id":"B","text":"\\( b \\times h \\)"},{"id":"C","text":"\\( \\frac{1}{2} \\times h \\times (a+b) \\)"},{"id":"D","text":"\\( \\frac{1}{2} \\times d \\times (h_1+h_2) \\)"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( b \\times h \\). இணைகரத்தின் பரப்பளவு அடிப்பக்கம் (b) மற்றும் அதன் உயரத்தின் (h) பெருக்கற்பலனுக்குச் சமம்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q30","subject":"SAT_MATHS","topic":"Unit 5","questionText":"10 மீ அடிப்பக்கத்தையும், 7 மீ உயரத்தையும் கொண்ட இணைகரம் ஒன்றின் பரப்பு","options":[{"id":"A","text":"70 ச.மீ"},{"id":"B","text":"35 ச.மீ"},{"id":"C","text":"7 ச.மீ"},{"id":"D","text":"10 ச.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 70 ச.மீ. இணைகரத்தின் பரப்பளவு = b × h = 10 × 7 = 70 ச.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q31","subject":"SAT_MATHS","topic":"Unit 5","questionText":"அடிப்பக்கம் 16 செ.மீ. மற்றும் உயரம் 6 செ.மீ. அளவுகள் கொண்ட இணைகரத்தின் பரப்பளவு","options":[{"id":"A","text":"90 ச.செ.மீ"},{"id":"B","text":"96 ச.செ.மீ"},{"id":"C","text":"86 ச.செ.மீ"},{"id":"D","text":"92 ச.செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 96 ச.செ.மீ. பரப்பளவு = b × h = 16 × 6 = 96 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q32","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தின் அடிப்பக்கம் மற்றும் உயரம் முறையே 12 செ.மீ. மற்றும் 9 செ.மீ. எனில் அதன் பரப்பளவு","options":[{"id":"A","text":"102 ச.செ.மீ"},{"id":"B","text":"56 ச.செ.மீ"},{"id":"C","text":"108 ச.செ.மீ"},{"id":"D","text":"40 ச.செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 108 ச.செ.மீ. பரப்பளவு = b × h = 12 × 9 = 108 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q33","subject":"SAT_MATHS","topic":"Unit 5","questionText":"அடிப்பக்கம் 15 செ.மீ மற்றும் உயரம் 4 செ.மீ கொண்ட இணைகரத்தின் பரப்பளவு","options":[{"id":"A","text":"60 ச.செ.மீ"},{"id":"B","text":"60 செ.மீ"},{"id":"C","text":"40 ச.செ.மீ"},{"id":"D","text":"40 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (2) (ஆவணத்தின்படி). இருப்பினும், அலகு சதுர சென்டிமீட்டராக இருக்க வேண்டும். பரப்பளவு = 15 × 4 = 60 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q34","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தின் ஒரு கோணம் செங்கோணம் எனில் அது","options":[{"id":"A","text":"சரிவகம்"},{"id":"B","text":"செவ்வகம்"},{"id":"C","text":"சாய்சதுரம்"},{"id":"D","text":"சதுரம்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): செவ்வகம். இணைகரத்தின் ஒரு கோணம் 90° ஆக அமைந்தால், அதன் அனைத்துக் கோணங்களும் 90° ஆகி, அது செவ்வகமாக மாறும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q35","subject":"SAT_MATHS","topic":"Unit 5","questionText":"அடுத்துள்ள பக்கங்கள் முறையே 6 செ.மீ. மற்றும் 5 செ.மீ. கொண்ட இணைகரத்தின் சுற்றளவு","options":[{"id":"A","text":"12 செ.மீ"},{"id":"B","text":"10 செ.மீ"},{"id":"C","text":"24 செ.மீ"},{"id":"D","text":"22 செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 22 செ.மீ. இணைகரத்தின் சுற்றளவு = 2 × (a + b) = 2 × (6 + 5) = 2 × 11 = 22 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q36","subject":"SAT_MATHS","topic":"Unit 5","questionText":"52 ச.செ.மீ. பரப்பளவும், 4 செ.மீ. உயரமும் கொண்ட இணைகரத்தின் அடிப்பக்க அளவு","options":[{"id":"A","text":"48 செ.மீ"},{"id":"B","text":"104 செ.மீ"},{"id":"C","text":"13 செ.மீ"},{"id":"D","text":"26 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 13 செ.மீ. அடிப்பக்கம் = பரப்பளவு / உயரம் = 52 / 4 = 13 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q37","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தின் அடிப்பக்கத்தை இரண்டு மடங்காகவும், உயரத்தை பாதியாகவும் மாற்றும் போது இணைகரத்தின் பரப்பளவு எவ்வாறு மாறும்?","options":[{"id":"A","text":"பாதியாக மாறும்"},{"id":"B","text":"மாறாது"},{"id":"C","text":"இரண்டு மடங்காகும்"},{"id":"D","text":"ஏதுமில்லை"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): மாறாது. புதிய பரப்பளவு = (2b) × (h/2) = b × h = பழைய பரப்பளவு.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q38","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தின் உயரம் 8 செ.மீ. மற்றும் அதன் அடிப்பக்கம் உயரத்தைப் போல் மூன்று மடங்கு எனில், அதன் பரப்பளவு","options":[{"id":"A","text":"64 ச.செ.மீ"},{"id":"B","text":"192 ச.செ.மீ"},{"id":"C","text":"32 ச.செ.மீ"},{"id":"D","text":"72 ச.செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 192 ச.செ.மீ. உயரம் (h) = 8 செ.மீ. அடிப்பக்கம் (b) = 3 × 8 = 24 செ.மீ. பரப்பளவு = 24 × 8 = 192 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q39","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தின் அடிப்பக்கமானது அதன் உயரத்தைப் போல 4 மடங்காகவும் அதன் பரப்பளவு 100 ச.செ.மீ. ஆகவும் இருப்பின் உயரம் என்ன?","options":[{"id":"A","text":"5 செ.மீ"},{"id":"B","text":"4 செ.மீ"},{"id":"C","text":"10 செ.மீ"},{"id":"D","text":"25 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 5 செ.மீ. b = 4h. பரப்பளவு = b × h = 4h × h = 4h² = 100. இதிலிருந்து h² = 25 மற்றும் h = 5 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q40","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தின் அடிப்பக்கம் 16 செ.மீ., அதன் உயரம் அடிப்பக்கத்தை விட 7 செ.மீ. குறைவு எனில் அதன் பரப்பளவு","options":[{"id":"A","text":"112 ச.செ.மீ"},{"id":"B","text":"144 ச.செ.மீ"},{"id":"C","text":"142 ச.செ.மீ"},{"id":"D","text":"182 ச.செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 144 ச.செ.மீ. அடிப்பக்கம் b = 16 செ.மீ. உயரம் h = 16 - 7 = 9 செ.மீ. பரப்பளவு = 16 × 9 = 144 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q41","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகர வடிவிலான மைதானத்தின் உயரம் 14 மீ. மேலும் அதன் அடிப்பக்கம், உயரத்தை விட 8 மீ கூடுதல் எனில், மைதானத்தைச் சமப்படுத்த ஒரு ச.மீ. க்கு ₹15 வீதம் எவ்வளவு செலவு ஆகும்?","options":[{"id":"A","text":"₹4600"},{"id":"B","text":"₹4620"},{"id":"C","text":"₹1680"},{"id":"D","text":"₹330"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): ₹4620. உயரம் h = 14 மீ. அடிப்பக்கம் b = 14 + 8 = 22 மீ. பரப்பளவு = 22 × 14 = 308 ச.மீ. ஆகும் செலவு = 308 × 15 = ₹4620.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q42","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு இணைகரத்தில் அடிப்பக்கமும் உயரமும் 5 : 4 என்ற விகிதத்தில் உள்ளன. அடிப்பக்கம் 35 செ.மீ. எனில் பரப்பளவு என்ன?","options":[{"id":"A","text":"670 ச.செ.மீ"},{"id":"B","text":"880 ச.செ.மீ"},{"id":"C","text":"980 ச.செ.மீ"},{"id":"D","text":"5795 ச.செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 980 ச.செ.மீ. விகிதம் 5:4. 5x = 35 => x = 7. உயரம் 4x = 4 × 7 = 28 செ.மீ. பரப்பளவு = 35 × 28 = 980 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q43","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தின் அடிப்பக்கமும் உயரமும் 7 : 3 என்ற விகிதத்தில் உள்ளன. அதன் உயரம் 45 செ.மீ. எனில், அதன் பரப்பளவு","options":[{"id":"A","text":"4725 ச.செ.மீ"},{"id":"B","text":"1470 ச.செ.மீ"},{"id":"C","text":"676 ச.செ.மீ"},{"id":"D","text":"916 ச.செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 4725 ச.செ.மீ. விகிதம் 7:3. 3x = 45 => x = 15. அடிப்பக்கம் 7x = 7 × 15 = 105 செ.மீ. பரப்பளவு = 105 × 45 = 4725 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q44","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தின் மூலைவிட்டங்கள் சமம் எனில் அது","options":[{"id":"A","text":"சதுரம்"},{"id":"B","text":"செவ்வகம்"},{"id":"C","text":"சாய்சதுரம்"},{"id":"D","text":"சரிவகம்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): செவ்வகம். இணைகரத்தின் மூலைவிட்டங்கள் சமமாக இருந்தால், அது செவ்வகமாக இருக்கும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q45","subject":"SAT_MATHS","topic":"Unit 5","questionText":"தவறான கூற்றைக் கண்டறியவும்.","options":[{"id":"A","text":"ஒரு சதுரத்தின் நான்கு கோணங்களும் சமம்"},{"id":"B","text":"ஒரு சதுரம் சாய்சதுரம் ஆகும்."},{"id":"C","text":"ஒரு இணைகரத்தில் எதிரெதிர்க் கோணங்கள் சமம்"},{"id":"D","text":"ஒரு செவ்வகத்தின் மூலைவிட்டங்கள் சமமல்ல."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): ஒரு செவ்வகத்தின் மூலைவிட்டங்கள் சமமல்ல. செவ்வகத்தின் மூலைவிட்டங்கள் சமம் என்பதே உண்மை. எனவே இந்தக் கூற்று தவறானது.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q46","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சாய்சதுரத்தின் பரப்பளவு காணும் வாய்ப்பாடு எது?\n(a) ½ × b × h ச.அ.\n(b) ½ × d₁ × d₂ ச.அ.\n(c) ½ × h × (a+b) ச.அ.\n(d) b × h ச.அ.","options":[{"id":"A","text":"(b) மட்டும்"},{"id":"B","text":"(b) மற்றும் (d)"},{"id":"C","text":"(c) மற்றும் (d)"},{"id":"D","text":"(a) மற்றும் (b)"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): (b) மற்றும் (d). சாய்சதுரம் ஓர் இணைகரம் என்பதால் பரப்பளவு b × h ஆகவும் இருக்கலாம். மூலைவிட்டங்களைக் கொண்டு ½ × d₁ × d₂ ஆகவும் கணக்கிடலாம்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q47","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பக்கம் 4 செ.மீ. உயரம் 3 செ.மீ. அளவுகள் கொண்ட சாய்சதுரத்தின் பரப்பளவு","options":[{"id":"A","text":"7 ச.செ.மீ"},{"id":"B","text":"24 ச.செ.மீ"},{"id":"C","text":"12 ச.செ.மீ"},{"id":"D","text":"10 ச.செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 12 ச.செ.மீ. சாய்சதுரத்தின் பரப்பளவு = பக்கம் × உயரம் = 4 × 3 = 12 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q48","subject":"SAT_MATHS","topic":"Unit 5","questionText":"சாய்சதுரத்தின் மூலைவிட்டங்களுக்கு இடையே உள்ள கோணம்","options":[{"id":"A","text":"120°"},{"id":"B","text":"180°"},{"id":"C","text":"90°"},{"id":"D","text":"100°"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 90°. சாய்சதுரத்தின் மூலைவிட்டங்கள் ஒன்றையொன்று செங்கோணத்தில் (90°) இருசமக் கூறிடும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q49","subject":"SAT_MATHS","topic":"Unit 5","questionText":"இரண்டு மூலைவிட்டங்களும் 8 செ.மீ. அளவு கொண்ட சாய்சதுரத்தின் பரப்பளவு","options":[{"id":"A","text":"64 ச.செ.மீ"},{"id":"B","text":"32 ச.செ.மீ"},{"id":"C","text":"30 ச.செ.மீ"},{"id":"D","text":"16 ச.செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 32 ச.செ.மீ. பரப்பளவு = ½ × d₁ × d₂ = ½ × 8 × 8 = 32 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q50","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பக்க அளவு 17 செ.மீ. மற்றும் உயரம் 8 செ.மீ. கொண்ட சாய்சதுரத்தின் பரப்பளவு","options":[{"id":"A","text":"136 ச.செ.மீ"},{"id":"B","text":"200 ச.செ.மீ"},{"id":"C","text":"136 ச.செ.மீ"},{"id":"D","text":"200 ச.செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 136 ச.செ.மீ. பரப்பளவு = அடிப்பக்கம் × உயரம் = 17 × 8 = 136 ச.செ.மீ. (விருப்பங்கள் மீண்டும் கொடுக்கப்பட்டுள்ளன, விடைக்குறிப்பு படி (3) சரியான விடை).","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q51","subject":"SAT_MATHS","topic":"Unit 5","questionText":"சாய்சதுரத்தின் பரப்பளவு காண்க.","questionImage":"/assets/satmaths/image/unit5/image/unit5/q51.png","options":[{"id":"A","text":"71.5 ச.செ.மீ"},{"id":"B","text":"12 ச.செ.மீ"},{"id":"C","text":"143 ச.செ.மீ"},{"id":"D","text":"136 ச.செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 71.5 ச.செ.மீ. படத்தில் மூலைவிட்டங்கள் 13 செ.மீ மற்றும் 11 செ.மீ எனக் கொடுக்கப்பட்டுள்ளன. பரப்பளவு = ½ × d₁ × d₂ = ½ × 13 × 11 = ½ × 143 = 71.5 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q52","subject":"SAT_MATHS","topic":"Unit 5","questionText":"இரு மூலைவிட்டங்களின் பெருக்கற்பலன் 48 ச.செ.மீ. எனில் சாய்சதுரத்தின் பரப்பளவு","options":[{"id":"A","text":"48 ச.செ.மீ"},{"id":"B","text":"248 ச.செ.மீ"},{"id":"C","text":"24 ச.செ.மீ"},{"id":"D","text":"12 ச.செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 24 ச.செ.மீ. சாய்சதுரத்தின் பரப்பளவு = ½ × (d₁ × d₂). மூலைவிட்டங்களின் பெருக்கற்பலன் 48. எனவே, பரப்பளவு = ½ × 48 = 24 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q53","subject":"SAT_MATHS","topic":"Unit 5","questionText":"8.5 செ.மீ. அடிப்பக்கமும் 5.2 செ.மீ உயரமும் உடைய சாய்சதுரத்தின் பரப்பளவு என்ன?","options":[{"id":"A","text":"44.12 ச.செ.மீ"},{"id":"B","text":"45.2 ச.செ.மீ"},{"id":"C","text":"40 ச.செ.மீ"},{"id":"D","text":"44.2 ச.செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 44.2 ச.செ.மீ. பரப்பளவு = அடிப்பக்கம் × உயரம் = 8.5 × 5.2 = 44.2 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q54","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு பூந்தோட்டம் சாய்சதுர வடிவில் உள்ளது. அதன் மூலைவிட்டங்கள் 18 மீ, 25 மீ எனில் பூந்தோட்டத்தின் பரப்பளவு","options":[{"id":"A","text":"450 ச.மீ"},{"id":"B","text":"225 ச.மீ"},{"id":"C","text":"324 ச.மீ"},{"id":"D","text":"180 ச.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 225 ச.மீ. பரப்பளவு = ½ × d₁ × d₂ = ½ × 18 × 25 = 9 × 25 = 225 ச.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q55","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சாய்சதுரத்தின் மூலைவிட்டங்களின் நீளங்கள் முறையே 1.3 செ.மீ. மற்றும் 1.6 செ.மீ. எனில் அதன் பரப்பளவு","options":[{"id":"A","text":"1.04 ச.செ.மீ"},{"id":"B","text":"10.4 ச.செ.மீ"},{"id":"C","text":"2.08 ச.செ.மீ"},{"id":"D","text":"1.40 ச.செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 1.04 ச.செ.மீ. பரப்பளவு = ½ × 1.3 × 1.6 = ½ × 2.08 = 1.04 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q56","subject":"SAT_MATHS","topic":"Unit 5","questionText":"சாய்சதுரத்தின் அடிப்பக்கம் மற்றும் உயரம் முறையே 3:1 என்ற விகிதத்தில் உள்ளன. அதன் உயரம் 4 செ.மீ. எனில் அதன் பரப்பளவு","options":[{"id":"A","text":"48 ச.செ.மீ"},{"id":"B","text":"50 ச.செ.மீ"},{"id":"C","text":"60 ச.செ.மீ"},{"id":"D","text":"40 ச.செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 48 ச.செ.மீ. உயரம் = 4 செ.மீ. அடிப்பக்கம், உயரத்தின் 3 மடங்கு, எனவே 3 × 4 = 12 செ.மீ. பரப்பளவு = அடிப்பக்கம் × உயரம் = 12 × 4 = 48 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q57","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சாய்சதுரத்தின் சிறிய மூலைவிட்டம் 60 மீ ஆகும். அதன் மூலைவிட்டங்கள் 3:4 என்ற விகிதத்தில் உள்ளன. எனில் அதன் பரப்பளவு காண்க.","options":[{"id":"A","text":"3600 ச.மீ"},{"id":"B","text":"1200 ச.மீ"},{"id":"C","text":"2400 ச.மீ"},{"id":"D","text":"4800 ச.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 2400 ச.மீ. விகிதம் 3:4. சிறிய மூலைவிட்டம் 3x = 60 மீ => x = 20 மீ. பெரிய மூலைவிட்டம் 4x = 4 × 20 = 80 மீ. பரப்பளவு = ½ × 60 × 80 = 2400 ச.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q58","subject":"SAT_MATHS","topic":"Unit 5","questionText":"கீழுள்ள கூற்றுகளில் சாய்சதுரத்திற்குப் பொருந்தாத கூற்று எது?","options":[{"id":"A","text":"எல்லா பக்கங்களும் சமம்"},{"id":"B","text":"எதிர்ப்பக்கங்கள் இணை"},{"id":"C","text":"மூலைவிட்டங்கள் சமம்"},{"id":"D","text":"மூலைவிட்டங்கள் இருசமக்கூறிடும்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): மூலைவிட்டங்கள் சமம். ஒரு சாய்சதுரத்தில் மூலைவிட்டங்கள் ஒன்றையொன்று செங்குத்தாக இருசமக் கூறிடும், ஆனால் அவை அளவில் சமமாக இருக்க வேண்டிய அவசியமில்லை. சதுரத்திற்கு மட்டுமே மூலைவிட்டங்கள் சமமாக இருக்கும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q59","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சாய்சதுரத்தின் பரப்பளவு மற்றும் உயரம் முறையே 180 ச.மீ. மற்றும் 12 மீ எனில் அதன் அடிப்பக்கம்","options":[{"id":"A","text":"9 மீ"},{"id":"B","text":"10 மீ"},{"id":"C","text":"15 மீ"},{"id":"D","text":"12 மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 15 மீ. பரப்பளவு = அடிப்பக்கம் × உயரம். 180 = அடிப்பக்கம் × 12. எனவே, அடிப்பக்கம் = 180 / 12 = 15 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q60","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சாய்சதுரத்தின் பரப்பளவு 60 ச.செ.மீ. மற்றும் அதன் ஒரு மூலைவிட்டம் 8 செ.மீ எனில் மற்றொரு மூலைவிட்டம்","options":[{"id":"A","text":"8 செ.மீ"},{"id":"B","text":"15 செ.மீ"},{"id":"C","text":"12 செ.மீ"},{"id":"D","text":"24 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 15 செ.மீ. பரப்பளவு = ½ × d₁ × d₂. 60 = ½ × 8 × d₂. 60 = 4 × d₂. d₂ = 60 / 4 = 15 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q61","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பரப்பளவு 96 ச.மீ. மற்றும் பக்க அளவு 24 மீ கொண்ட சாய்சதுரத்தின் உயரம்","options":[{"id":"A","text":"8 மீ"},{"id":"B","text":"10 மீ"},{"id":"C","text":"2 மீ"},{"id":"D","text":"4 மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 4 மீ. பரப்பளவு = அடிப்பக்கம் × உயரம். 96 = 24 × உயரம். உயரம் = 96 / 24 = 4 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q62","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பரப்பளவு 128 ச.செ.மீ. மற்றும் ஒரு மூலைவிட்ட அளவு 32 செ.மீ. கொண்ட சாய்சதுரத்தின் மற்றொரு மூலைவிட்ட அளவு","options":[{"id":"A","text":"12 செ.மீ"},{"id":"B","text":"8 செ.மீ"},{"id":"C","text":"4 செ.மீ"},{"id":"D","text":"20 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 8 செ.மீ. 128 = ½ × 32 × d₂. 128 = 16 × d₂. d₂ = 128 / 16 = 8 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q63","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சாய்சதுரத்தின் பரப்பளவு 50 ச.செ.மீ. அதன் ஒரு மூலைவிட்டம் மற்றொரு மூலைவிட்டத்தைப் போல் 4 மடங்கு எனில், பெரிய மூலைவிட்டத்தின் அளவு","options":[{"id":"A","text":"20 செ.மீ"},{"id":"B","text":"4 செ.மீ"},{"id":"C","text":"5 செ.மீ"},{"id":"D","text":"25 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 20 செ.மீ. சிறிய மூலைவிட்டம் x என்க. பெரிய மூலைவிட்டம் 4x. பரப்பளவு = ½ × x × 4x = 2x² = 50. x² = 25 => x = 5. பெரிய மூலைவிட்டம் = 4 × 5 = 20 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q64","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செவ்வகத்தின் நீளம், அகலம் முறையே 40 செ.மீ. மற்றும் 26 செ.மீ. இச்செவ்வகத்தின் பக்கங்களின் மையப்புள்ளிகளை முறையே இணைப்பதால் ஏற்படும் சாய்சதுரத்தின் பரப்பளவு","options":[{"id":"A","text":"1040 ச.செ.மீ"},{"id":"B","text":"2080 ச.செ.மீ"},{"id":"C","text":"260 ச.செ.மீ"},{"id":"D","text":"520 ச.செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 520 ச.செ.மீ. செவ்வகத்தின் பக்கங்களின் மையப்புள்ளிகளை இணைக்கும்போது உருவாகும் சாய்சதுரத்தின் மூலைவிட்டங்கள் செவ்வகத்தின் நீளம் மற்றும் அகலத்திற்குச் சமமாக இருக்கும். எனவே, d₁ = 40, d₂ = 26. பரப்பளவு = ½ × 40 × 26 = 20 × 26 = 520 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q65","subject":"SAT_MATHS","topic":"Unit 5","questionText":"சாய்சதுரத்தின் பரப்பளவு 98 ச.செ.மீ. அதன் சுற்றளவு 28 செ.மீ. எனில் சாய்சதுரத்தின் உயரம்","options":[{"id":"A","text":"3.5 செ.மீ"},{"id":"B","text":"14 செ.மீ"},{"id":"C","text":"7 செ.மீ"},{"id":"D","text":"10 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 14 செ.மீ. சுற்றளவு = 4a = 28 செ.மீ => a = 7 செ.மீ. பரப்பளவு = அடிப்பக்கம் × உயரம் = 7 × உயரம் = 98. உயரம் = 98 / 7 = 14 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q66","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பின்வருவனவற்றுள் எது தவறான கூற்று அல்ல?","options":[{"id":"A","text":"ஒரு சாய்சதுரத்தின் மூலைவிட்டங்கள் ஒரே அளவாக இருக்கும்"},{"id":"B","text":"ஒரு சதுரம் சாய்சதுரம் ஆகும்"},{"id":"C","text":"ஓர் இணைகரத்தில் எல்லாப் பக்கங்களும் சமமாக இருந்தால் அது சதுரம்"},{"id":"D","text":"ஓர் இணைகரத்தில் ஒரு சோடி இணையில்லாத பக்கங்கள் இருப்பின் அது ஒரு சாய்சதுரம் எனப்படும்."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): ஒரு சதுரம் சாய்சதுரம் ஆகும். தவறான கூற்று அல்ல என்றால், சரியான கூற்று என்று பொருள். சதுரம் என்பது சாய்சதுரத்தின் அனைத்துப் பண்புகளையும் (நான்கு பக்கங்கள் சமம்) பூர்த்தி செய்வதால், ஒவ்வொரு சதுரமும் ஒரு சாய்சதுரமே ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q67","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தில் ஒரு சோடி எதிர்ப்பக்கங்கள் மட்டும் இணையாக இருந்தால் அது","options":[{"id":"A","text":"சாய்சதுரம்"},{"id":"B","text":"சரிவகம்"},{"id":"C","text":"இருசமபக்க சரிவகம்"},{"id":"D","text":"இணைகரம்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): சரிவகம். ஓர் இணைகரத்தில் ஒரு சோடி எதிர்ப்பக்கங்கள் மட்டும் இணையாக இருந்தால் (மற்றுமொரு சோடி இணையாக இல்லை எனில்), அது சரிவகம் (Trapezium) எனப்படும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q68","subject":"SAT_MATHS","topic":"Unit 5","questionText":"எதிர்ப் பக்கங்கள் இணையாகவும், சமமாகவும் உள்ள நான்கு பக்கங்கள் கொண்ட ஒரு மூடிய உருவம்","options":[{"id":"A","text":"சாய்சதுரம்"},{"id":"B","text":"சரிவகம்"},{"id":"C","text":"இருசமபக்க சரிவகம்"},{"id":"D","text":"இணைகரம்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): இணைகரம். எதிர்ப்பக்கங்கள் இணையாகவும் சமமாகவும் உள்ள நான்கு பக்கங்கள் கொண்ட வடிவம் இணைகரம் (Parallelogram) ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q69","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சரிவகத்தில் இணையற்ற பக்கங்கள் சமம் எனில் அது ஒரு","options":[{"id":"A","text":"சதுரம்"},{"id":"B","text":"செவ்வகம்"},{"id":"C","text":"இருசமபக்கச் சரிவகம்"},{"id":"D","text":"இணைகரம்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): இருசமபக்கச் சரிவகம். ஒரு சரிவகத்தில் இணையாக இல்லாத இரண்டு பக்கங்களும் சம நீளமுடையவை என்றால், அது இருசமபக்கச் சரிவகம் (Isosceles Trapezium) எனப்படும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q70","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தில் அனைத்துப் பக்கங்களும் சமமாக இருப்பின் அது ஒரு","options":[{"id":"A","text":"சாய்சதுரம்"},{"id":"B","text":"சரிவகம்"},{"id":"C","text":"இருசமபக்க சரிவகம்"},{"id":"D","text":"இணைகரம்"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): சாய்சதுரம். ஓர் இணைகரத்தின் அனைத்து (நான்கு) பக்கங்களும் சம நீளமுடையவை என்றால், அது சாய்சதுரம் (Rhombus) ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q71","subject":"SAT_MATHS","topic":"Unit 5","questionText":"நீர்ப் பாசனக் கால்வாய்களில் பெரும்பாலான இடங்களில் பயன்படுத்தப்படும் வடிவ அமைப்பு","options":[{"id":"A","text":"இணைகரம்"},{"id":"B","text":"சாய்சதுரம்"},{"id":"C","text":"சதுரம்"},{"id":"D","text":"சரிவகம்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): சரிவகம். நீர்ப்பாசனக் கால்வாய்கள் பெரும்பாலும் சரிவக (Trapezium) வடிவிலேயே அமைக்கப்படுகின்றன.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q72","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சரிவகத்தின் பரப்பளவு காணும் வாய்ப்பாடு எது?","options":[{"id":"A","text":"½ × b × h ச.அ"},{"id":"B","text":"½ × d₁ × d₂ ச.அ"},{"id":"C","text":"½ × h × (a+b) ச.அ"},{"id":"D","text":"½ × d × (h₁+h₂) ச.அ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): ½ × h × (a+b) ச.அ. சரிவகத்தின் பரப்பளவு = ½ × உயரம் × (இணைப்பக்கங்களின் கூடுதல்).","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q73","subject":"SAT_MATHS","topic":"Unit 5","questionText":"உயரம் 5 செ.மீ., இணைப்பக்கங்களின் அளவுகள் முறையே 8 செ.மீ., 10 செ.மீ. கொண்ட சரிவகத்தின் பரப்பளவு","options":[{"id":"A","text":"45 ச.செ.மீ"},{"id":"B","text":"40 ச.செ.மீ"},{"id":"C","text":"18 ச.செ.மீ"},{"id":"D","text":"50 ச.செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 45 ச.செ.மீ. பரப்பளவு = ½ × h × (a+b) = ½ × 5 × (8+10) = ½ × 5 × 18 = 45 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q74","subject":"SAT_MATHS","topic":"Unit 5","questionText":"சரிவகத்தின் இணைப்பக்கங்கள் முறையே 23 செ.மீ., 12 செ.மீ. இணைப்பக்கங்களுக்கு இடையே உள்ள தூரம் 9 செ.மீ. எனில் சரிவகத்தின் பரப்பளவு","options":[{"id":"A","text":"189 ச.செ.மீ"},{"id":"B","text":"157.5 ச.செ.மீ"},{"id":"C","text":"352 ச.செ.மீ"},{"id":"D","text":"828 ச.செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 157.5 ச.செ.மீ. பரப்பளவு = ½ × h × (a+b) = ½ × 9 × (23+12) = ½ × 9 × 35 = 157.5 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q75","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சரிவகத்தில் இணைப்பக்கங்களின் கூடுதல் 18 செ.மீ. குத்துயரம் 15 செ.மீ. எனில் அதன் பரப்பளவு","options":[{"id":"A","text":"105 ச.செ.மீ"},{"id":"B","text":"115 ச.செ.மீ"},{"id":"C","text":"125 ச.செ.மீ"},{"id":"D","text":"135 ச.செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 135 ச.செ.மீ. பரப்பளவு = ½ × h × (இணைப்பக்கங்களின் கூடுதல்) = ½ × 15 × 18 = 15 × 9 = 135 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q76","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சரிவக வடிவ கண்ணாடியின் பரப்பளவு 840 ச.செ.மீ அதன் மேல் மற்றும் அடி நீளம் 12 செ.மீ, 8 செ.மீ எனில் கண்ணாடியின் உயரம்","options":[{"id":"A","text":"84 செ.மீ"},{"id":"B","text":"78 செ.மீ"},{"id":"C","text":"63 செ.மீ"},{"id":"D","text":"42 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 84 செ.மீ. 840 = ½ × h × (12+8) = ½ × h × 20 = 10h. உயரம் h = 840 / 10 = 84 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q77","subject":"SAT_MATHS","topic":"Unit 5","questionText":"இணைப்பக்கங்களின் கூடுதல் 20 சென்டிமீட்டராகவும், பரப்பளவு 80 சதுர சென்டிமீட்டர் கொண்ட சரிவகத்தின் குத்துயரம் என்ன?","options":[{"id":"A","text":"8 செ.மீ"},{"id":"B","text":"80 செ.மீ"},{"id":"C","text":"8 செ.மீ"},{"id":"D","text":"40 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 8 செ.மீ. 80 = ½ × h × 20 = 10h. h = 80 / 10 = 8 செ.மீ. (விருப்பங்களில் 8 இருமுறை இருந்தாலும், முதல் விருப்பமே சரியான விடையாகக் கொள்ளப்படும்).","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q78","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பரப்பளவு 828 ச.செ.மீ., இணைப்பக்க அளவுகள் 19.6 செ.மீ., 16.4 செ.மீ. கொண்ட சரிவகத்தின் உயரம்","options":[{"id":"A","text":"19 செ.மீ"},{"id":"B","text":"46 செ.மீ"},{"id":"C","text":"14 செ.மீ"},{"id":"D","text":"18 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 46 செ.மீ. இணைப்பக்கங்களின் கூடுதல் = 19.6 + 16.4 = 36. 828 = ½ × h × 36 = 18h. h = 828 / 18 = 46 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q79","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பரப்பளவு 140 ச.மீ., இணைப்பக்க அளவுகளின் கூடுதல் 10 மீ. கொண்ட சரிவகத்தின் உயரம்","options":[{"id":"A","text":"7 மீ"},{"id":"B","text":"40 மீ"},{"id":"C","text":"14 மீ"},{"id":"D","text":"28 மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 28 மீ. 140 = ½ × h × 10 = 5h. h = 140 / 5 = 28 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q80","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பரப்பளவு 189 ச.மீ., உயரம் 14 செ.மீ. கொண்ட சரிவகத்தின் இணைப்பக்க அளவுகளின் கூடுதல்","options":[{"id":"A","text":"27 செ.மீ"},{"id":"B","text":"54 செ.மீ"},{"id":"C","text":"13.5 செ.மீ"},{"id":"D","text":"28 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 27 செ.மீ. (இங்கு அலகுகள் செ.மீ என எடுத்துக்கொள்ளப்பட்டுள்ளன). 189 = ½ × 14 × (கூடுதல்) = 7 × (கூடுதல்). கூடுதல் = 189 / 7 = 27 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q81","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சரிவகத்தின் பரப்பளவு 162 செ.மீ² அதன் இணைப் பக்க அளவுகள் 9 செ.மீ., 18 செ.மீ. எனில் இணைப் பக்கங்களுக்கு இடைப்பட்ட தொலைவு என்ன?","options":[{"id":"A","text":"24 செ.மீ"},{"id":"B","text":"12 செ.மீ"},{"id":"C","text":"13 செ.மீ"},{"id":"D","text":"15 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 12 செ.மீ. இடைப்பட்ட தொலைவு என்பது உயரம்(h) ஆகும். 162 = ½ × h × (9+18) = ½ × h × 27. 13.5h = 162. h = 162 / 13.5 = 12 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q82","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சரிவகத்தின் பரப்பு 33.32 செ.மீ². மற்றும் அதன் ஒரு பக்க அளவு 8 செ.மீ. உயரம் 5.6 செ.மீ. எனில் மற்றொரு பக்க அளவு","options":[{"id":"A","text":"11.9 செ.மீ"},{"id":"B","text":"3.9 செ.மீ"},{"id":"C","text":"8.9 செ.மீ"},{"id":"D","text":"5.9 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 3.9 செ.மீ. 33.32 = ½ × 5.6 × (8+x) = 2.8 × (8+x). 8+x = 33.32 / 2.8 = 11.9. x = 11.9 - 8 = 3.9 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q83","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பொருத்துக.\n(a) இணைகரத்தின் பரப்பளவு -> (iii) bh ச.அ.\n(b) சாய்சதுரத்தின் பரப்பளவு -> (i) ½ d₁ d₂ ச.அ.\n(c) நீர் பாசனக் கால்வாய் -> (iv) சரிவகம்\n(d) சரிவகத்தின் பரப்பளவு -> (ii) ½ h(a+b) ச.அ.\n(e) டைமண்ட் கிராசிங் -> (v) சாய்சதுரம்","options":[{"id":"A","text":"a-v, b-i, c-iv, d-ii, e-iii"},{"id":"B","text":"a-iv, b-i, c-v, d-ii, e-iii"},{"id":"C","text":"a-iii, b-iv, c-i, d-ii, e-v"},{"id":"D","text":"a-ii, b-i, c-iv, d-ii, e-v"}],"correctOption":"D","explanation":"ஆவணத்தின் விடைக்குறிப்புப் படி சரியான விடை (4) எனக் கொடுக்கப்பட்டுள்ளது.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q84","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சரிவகத்தின் இரு இணைப்பக்கங்களின் வேறுபாடு 4 செ.மீ. மற்றும் அவற்றிற்கு இடைப்பட்ட குத்துயரம் 19 செ.மீ., பரப்பு 475 செ.மீ². எனில் இணைப்பக்கங்களின் நீளங்கள்","options":[{"id":"A","text":"27 செ.மீ., 23 செ.மீ."},{"id":"B","text":"26 செ.மீ., 23 செ.மீ."},{"id":"C","text":"27 செ.மீ., 22 செ.மீ."},{"id":"D","text":"27 செ.மீ., 25 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 27 செ.மீ., 23 செ.மீ. 475 = ½ × 19 × (a+b) => a+b = (475 × 2)/19 = 50. a-b = 4 எனக் கொடுக்கப்பட்டுள்ளது. a+b=50 மற்றும் a-b=4 என்பதைத் தீர்க்க, a=27, b=23.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q85","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஓர் இணைகரத்தின் உயரத்தை 3 மடங்காகவும், அடிப்பக்கத்தை 2/3 மடங்காகவும் மாற்றும் போது கிடைக்கும் புதிய இணைகரத்தின் பரப்பளவு எவ்வாறு மாறும்?","options":[{"id":"A","text":"பாதியாக"},{"id":"B","text":"மாறாது"},{"id":"C","text":"2 மடங்காக"},{"id":"D","text":"3 மடங்காக"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 2 மடங்காக. புதிய பரப்பளவு = (2/3 b) × (3 h) = 2 bh. எனவே பழைய பரப்பளவை விட இரு மடங்காகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q86","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ABCD என்ற இணைகரத்தில் ∠A இன் மதிப்பிலிருந்து ∠C இன் மதிப்பைக் கழித்தால்","options":[{"id":"A","text":"90°"},{"id":"B","text":"0°"},{"id":"C","text":"180°"},{"id":"D","text":"45°"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 0°. இணைகரத்தின் எதிரெதிர் கோணங்கள் சமம் (∠A = ∠C). எனவே ∠A - ∠C = 0°.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q87","subject":"SAT_MATHS","topic":"Unit 5","questionText":"படத்தில், ABCD என்ற இணைகரத்தின் பரப்பிற்கும் ABC என்ற முக்கோணத்தின் பரப்பிற்கும் இடையே உள்ள விகிதம்","questionImage":"/assets/satmaths/image/unit5/image/unit5/q87.png","options":[{"id":"A","text":"1:2"},{"id":"B","text":"2:1"},{"id":"C","text":"3:2"},{"id":"D","text":"2:3"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 2:1. இணைகரத்தின் மூலைவிட்டம் (AC) இணைகரத்தை இரு சம முக்கோணங்களாகப் பிரிக்கிறது. எனவே இணைகரத்தின் பரப்பளவு முக்கோணத்தின் பரப்பளவைப் போல் 2 மடங்காகும். விகிதம் 2:1.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q88","subject":"SAT_MATHS","topic":"Unit 5","questionText":"கொடுக்கப்பட்ட இணைகரத்தில், AC=34 cm ஆகும். மூலைவிட்டம் AC க்கும் B மற்றும் D ஆகியவற்றிற்கும் இடையே உள்ள செங்குத்துத் தூரம் 12 cm ஆகும். எனில் இந்த இணைகரத்தின் பரப்பு என்ன?","questionImage":"/assets/satmaths/image/unit5/image/unit5/q88.png","options":[{"id":"A","text":"204 ச.செ.மீ"},{"id":"B","text":"408 ச.செ.மீ"},{"id":"C","text":"816 ச.செ.மீ"},{"id":"D","text":"806 ச.செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 408 ச.செ.மீ. இணைகரம் இரண்டு ஒத்த முக்கோணங்களாகப் பிரிக்கப்படுகிறது. ஒரு முக்கோணத்தின் பரப்பு = ½ × 34 × 12 = 204. மொத்தப் பரப்பு = 2 × 204 = 408 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q89","subject":"SAT_MATHS","topic":"Unit 5","questionText":"கொடுக்கப்பட்ட இணைகரத்தில், AB=15 cm, AD=12 cm மற்றும் MC=10 cm ஆகும். AD ⊥ MC மற்றும் AB ⊥ CL எனில், CL இன் நீளம் என்ன?","questionImage":"/assets/satmaths/image/unit5/image/unit5/q89.png","options":[{"id":"A","text":"12 செ.மீ"},{"id":"B","text":"4 செ.மீ"},{"id":"C","text":"8 செ.மீ"},{"id":"D","text":"6 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 8 செ.மீ. இணைகரத்தின் பரப்பளவு = அடிப்பக்கம் × உயரம். பரப்பளவு = AD × MC = 12 × 10 = 120. பரப்பளவு = AB × CL = 15 × CL. 15 × CL = 120 => CL = 120 / 15 = 8 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q90","subject":"SAT_MATHS","topic":"Unit 5","questionText":"சதுரம் மற்றும் சாய்சதுரம் இரண்டும் ஒரே அடிப்பக்கத்தைக் கொண்டிருந்தால் சதுரம் மற்றும் சாய்சதுரத்தின் பரப்பளவின் விகிதமானது","options":[{"id":"A","text":"1 ஐ விட அதிகமாகும்"},{"id":"B","text":"1 க்கு சமமாகும்"},{"id":"C","text":"1/2 க்கு சமமாகும்"},{"id":"D","text":"2 ஐ விட அதிகமாகும்"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 1 ஐ விட அதிகமாகும். சதுரத்தின் பரப்பு = அடிப்பக்கம் × அடிப்பக்கம். சாய்சதுரத்தின் பரப்பு = அடிப்பக்கம் × உயரம். சாய்சதுரத்தில் உயரம் அதன் பக்க அளவை (அடிப்பக்கத்தை) விட எப்போதும் குறைவாகவே இருக்கும் (அது சதுரமாக இல்லாத பட்சத்தில்). எனவே சதுரத்தின் பரப்பே அதிகம். விகிதம் > 1.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q91","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சதுரத்தின் பரப்பும், ஒரு செவ்வகத்தின் பரப்பும் சமம். அவற்றின் சுற்றளவுகள் முறையே P₁ மற்றும் P₂ எனில்","options":[{"id":"A","text":"P₁ < P₂"},{"id":"B","text":"P₁ = P₂"},{"id":"C","text":"P₁ > P₂"},{"id":"D","text":"P₁ ≥ P₂"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): P₁ < P₂. சம பரப்பளவு கொண்ட சதுரம் மற்றும் செவ்வகங்களில், சதுரத்தின் சுற்றளவு எப்போதுமே செவ்வகத்தின் சுற்றளவை விடக் குறைவாகவே இருக்கும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q92","subject":"SAT_MATHS","topic":"Unit 5","questionText":"48 மீ பக்க அளவு கொண்ட ஒரு சதுரமும், 18 மீ உயரம் கொண்ட ஒரு இணைகரமும் சமப் பரப்பளவை கொண்டவை எனில் இணைகரத்தின் அடிப்பக்க அளவு","options":[{"id":"A","text":"100 மீ"},{"id":"B","text":"112 மீ"},{"id":"C","text":"128 மீ"},{"id":"D","text":"142 மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 128 மீ. சதுரத்தின் பரப்பளவு = 48 × 48 = 2304 ச.மீ. இணைகரத்தின் பரப்பு = b × 18 = 2304. b = 2304 / 18 = 128 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q93","subject":"SAT_MATHS","topic":"Unit 5","questionText":"676 ச.செ.மீ. பரப்பளவு கொண்ட ஓர் இணைகரத்தின் உயரம் அதன் அடிப்பக்கத்தில் நான்கில் ஒரு பங்கு எனில் அதன் அடிப்பக்கம், உயரம் முறையே","options":[{"id":"A","text":"13, 52"},{"id":"B","text":"52, 13"},{"id":"C","text":"48, 24"},{"id":"D","text":"30, 42"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 52, 13. உயரம் h = b/4. பரப்பளவு = b × (b/4) = b²/4 = 676. b² = 676 × 4 = 2704 => b = 52 செ.மீ. h = 52/4 = 13 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q94","subject":"SAT_MATHS","topic":"Unit 5","questionText":"பரப்பளவு 576 ச.செ.மீ., உயரத்தைப் போல் நான்கு மடங்கு கொண்ட அடிப்பக்கத்தையும் உடைய இணைகரத்தின் உயரம்","options":[{"id":"A","text":"12 செ.மீ"},{"id":"B","text":"11 செ.மீ"},{"id":"C","text":"13 செ.மீ"},{"id":"D","text":"15 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 12 செ.மீ. b = 4h. பரப்பளவு = b × h = 4h × h = 4h² = 576. h² = 576/4 = 144 => h = 12 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q95","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு இணைகரத்தின் இரண்டு அடுத்தடுத்த கோணங்கள் (5x-5)° மற்றும் (10x+35)° எனில், அந்தக் கோணங்களின் விகிதம்","options":[{"id":"A","text":"2:3"},{"id":"B","text":"3:4"},{"id":"C","text":"1:3"},{"id":"D","text":"1:2"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 1:3. இணைகரத்தின் அடுத்தடுத்த கோணங்களின் கூடுதல் 180°. (5x-5) + (10x+35) = 180 => 15x + 30 = 180 => 15x = 150 => x = 10. கோணங்கள்: (50-5)=45° மற்றும் (100+35)=135°. விகிதம் 45:135 = 1:3.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q96","subject":"SAT_MATHS","topic":"Unit 5","questionText":"507 ச.செ.மீ பரப்பளவு கொண்ட ஓர் இணைகரத்தின் உயரம் அதன் அடிப்பக்கத்தின் 3-ல் ஒரு பங்கு எனில் அதன் உயரம் காண்க.","options":[{"id":"A","text":"11 செ.மீ"},{"id":"B","text":"12 செ.மீ"},{"id":"C","text":"13 செ.மீ"},{"id":"D","text":"14 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 13 செ.மீ. உயரம் h = b/3 => b = 3h. பரப்பளவு = 3h × h = 3h² = 507. h² = 169 => h = 13 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q97","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ABCD என்ற இணைகரத்தில் ∠A=75°, ∠B + ∠C-ன் மதிப்பு","options":[{"id":"A","text":"75°"},{"id":"B","text":"120°"},{"id":"C","text":"180°"},{"id":"D","text":"105°"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 180°. இணைகரத்தில் அடுத்தடுத்த கோணங்களின் கூடுதல் 180°. ∠B மற்றும் ∠C அடுத்தடுத்த கோணங்களாகும். எனவே ∠B + ∠C = 180°.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q98","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சாய்சதுரத்தின் பரப்பளவு 576 ச.செ.மீ. ஒரு மூலைவிட்டமானது, மற்றொரு மூலைவிட்டத்தில் பாதி எனில், மூலைவிட்டங்களின் அளவுகள் முறையே","options":[{"id":"A","text":"48, 24"},{"id":"B","text":"45, 28"},{"id":"C","text":"13, 52"},{"id":"D","text":"17, 14"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 48, 24. d₂ = d₁/2. பரப்பளவு = ½ × d₁ × (d₁/2) = d₁²/4 = 576. d₁² = 576 × 4 = 2304 => d₁ = 48. d₂ = 48/2 = 24. எனவே மூலைவிட்டங்கள் 48 மற்றும் 24.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q99","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சாய்சதுரத்தின் மூலைவிட்ட அளவுகளின் கூடுதல் 24 மீ. பெரிய மூலைவிட்டத்தின் அளவு, சிறிய மூலைவிட்டத்தின் அளவைப் போல மூன்று மடங்கு எனில் அதன் பரப்பளவு","options":[{"id":"A","text":"54 ச.மீ"},{"id":"B","text":"45 ச.மீ"},{"id":"C","text":"169 ச.மீ"},{"id":"D","text":"38 ச.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 54 ச.மீ. d₁ + d₂ = 24. d₁ = 3d₂. 3d₂ + d₂ = 4d₂ = 24 => d₂ = 6. d₁ = 3×6 = 18. பரப்பளவு = ½ × 18 × 6 = 54 ச.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q100","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு சாய்சதுரத்தின் பரப்பளவு 64 செ.மீ² அதன் ஒரு மூலைவிட்டமானது மற்றொரு மூலைவிட்டத்தில் பாதி எனில், மூலைவிட்டங்களின் கூடுதல் என்ன?","options":[{"id":"A","text":"24 செ.மீ"},{"id":"B","text":"14 செ.மீ"},{"id":"C","text":"18 செ.மீ"},{"id":"D","text":"16 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 24 செ.மீ. பரப்பளவு = ½ × d₁ × (d₁/2) = d₁²/4 = 64. d₁² = 256 => d₁ = 16. d₂ = 16/2 = 8. கூடுதல் = 16 + 8 = 24 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q101","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு செங்கோண முக்கோணத்தின் பரப்பளவு","options":[{"id":"A","text":"b × h ச.அ."},{"id":"B","text":"½ × b × h ச.அ."},{"id":"C","text":"l × b ச.அ."},{"id":"D","text":"½ × h × (a+b) ச.அ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): ½ × b × h ச.அ. செங்கோண முக்கோணத்தின் பரப்பளவைக் காண அடிப்பக்கத்தையும் குத்துயரத்தையும் பெருக்கி இரண்டால் வகுக்க வேண்டும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q102","subject":"SAT_MATHS","topic":"Unit 5","questionText":"கீழ்க்காணும் படத்தின் பரப்பளவு","questionImage":"/assets/satmaths/image/unit5/image/unit5/q102.png","options":[{"id":"A","text":"52 ச.செ.மீ"},{"id":"B","text":"17 ச.செ.மீ"},{"id":"C","text":"42 ச.செ.மீ"},{"id":"D","text":"26 ச.செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 26 ச.செ.மீ. முக்கோணத்தின் அடிப்பக்கம் 13 செ.மீ, உயரம் 4 செ.மீ எனக் கொடுக்கப்பட்டுள்ளது. பரப்பளவு = ½ × 13 × 4 = 26 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q103","subject":"SAT_MATHS","topic":"Unit 5","questionText":"இணைகரத்தின் பரப்பளவு 400 செ.மீ² அதன் அடிப்பக்கம் 8 செ.மீ. எனில், அதன் உயரம்","options":[{"id":"A","text":"100 செ.மீ"},{"id":"B","text":"150 செ.மீ"},{"id":"C","text":"100 செ.மீ"},{"id":"D","text":"50 செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 50 செ.மீ. இணைகரத்தின் பரப்பளவு = அடிப்பக்கம் × உயரம். 400 = 8 × உயரம் => உயரம் = 400 / 8 = 50 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q104","subject":"SAT_MATHS","topic":"Unit 5","questionText":"சாய்சதுரத்தின் பரப்பளவு 50 மீ² எனில், அதன் மூலைவிட்டங்களின் பெருக்கற்பலன்","options":[{"id":"A","text":"25"},{"id":"B","text":"50"},{"id":"C","text":"100"},{"id":"D","text":"200"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 100. பரப்பளவு = ½ × (மூலைவிட்டங்களின் பெருக்கற்பலன்). 50 = ½ × (d₁ × d₂). எனவே, (d₁ × d₂) = 50 × 2 = 100.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q105","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு அலுவலகத்தின் ஜன்னல் சாய்சதுர வடிவில் உள்ளது. அதன் பரப்பளவு 500 ச.செ.மீ. ஆகும். அந்த ஜன்னலானது சிறுசிறு சாய்சதுர வடிவிலான கண்ணாடித் துண்டுகளால் அலங்கரிக்கப்பட்டது. அச்சிறு கண்ணாடியின் மூலைவிட்ட அளவுகள் 10 செ.மீ. மற்றும் 5 செ.மீ. எனில் தேவைப்படும் சிறு சாய்சதுர வடிவ கண்ணாடித் துண்டுகளின் எண்ணிக்கை","options":[{"id":"A","text":"25"},{"id":"B","text":"20"},{"id":"C","text":"10"},{"id":"D","text":"50"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 20. ஒரு சிறிய கண்ணாடித் துண்டின் பரப்பளவு = ½ × 10 × 5 = 25 ச.செ.மீ. தேவையான எண்ணிக்கை = மொத்தப் பரப்பளவு / ஒரு துண்டின் பரப்பளவு = 500 / 25 = 20.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q106","subject":"SAT_MATHS","topic":"Unit 5","questionText":"------- என்பது மூடிய வடிவத்தின் அடைபட்ட சமதளப் பகுதியாகும்.","options":[{"id":"A","text":"பரப்பளவு"},{"id":"B","text":"சுற்றளவு"},{"id":"C","text":"அகலம்"},{"id":"D","text":"நீளம்"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): பரப்பளவு. ஒரு மூடிய வடிவத்தால் அடைபடும் சமதளப் பகுதி அதன் பரப்பளவு (Area) என்று அழைக்கப்படுகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q107","subject":"SAT_MATHS","topic":"Unit 5","questionText":"அடுத்துள்ள பக்கங்கள் முறையே 4.2 செ.மீ., மற்றும் 3.8 செ.மீ. கொண்ட இணைகரத்தின் சுற்றளவு","options":[{"id":"A","text":"12 செ.மீ"},{"id":"B","text":"16 செ.மீ"},{"id":"C","text":"24 செ.மீ"},{"id":"D","text":"22 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 16 செ.மீ. இணைகரத்தின் சுற்றளவு = 2 × (a + b) = 2 × (4.2 + 3.8) = 2 × 8 = 16 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q108","subject":"SAT_MATHS","topic":"Unit 5","questionText":"''டயமண்ட் கிராசிங்'' என்பது -------- வடிவத்தைக் குறிக்கும்.","options":[{"id":"A","text":"சதுரம்"},{"id":"B","text":"இணைகரம்"},{"id":"C","text":"சாய்சதுரம்"},{"id":"D","text":"செவ்வகம்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): சாய்சதுரம். இரண்டு இரயில் பாதைகள் கடக்கும் இடத்தில் உருவாகும் அமைப்பு ''டயமண்ட் கிராசிங்'' எனப்படுகிறது, இது சாய்சதுர (Rhombus) வடிவத்தில் அமையும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-5-q109","subject":"SAT_MATHS","topic":"Unit 5","questionText":"ஒரு இணைகரத்தின் அடிப்பக்கமானது அதன் உயரத்தைப் போல 4 மடங்கு மற்றும் அதன் பரப்பு 256 செ.மீ² எனில் அதன் உயரம்","options":[{"id":"A","text":"4 செ.மீ"},{"id":"B","text":"6 செ.மீ"},{"id":"C","text":"8 செ.மீ"},{"id":"D","text":"16 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 8 செ.மீ. b = 4h. பரப்பளவு = b × h = 4h × h = 4h² = 256. h² = 256/4 = 64 => h = 8 செ.மீ.","marks":1,"negativeMarks":0}]', datetime('now'));
INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('SAT_MATHS_6', 'SAT_MATHS', 6, '[{"id":"unit-satmaths-6-q1","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் சுற்றளவைக் காண உதவும் சூத்திரம்","options":[{"id":"A","text":"\\( 2\\pi r \\) அலகுகள்"},{"id":"B","text":"\\( \\pi r^2 + 2r \\) அலகுகள்"},{"id":"C","text":"\\( \\pi r^2 \\) ச.அலகுகள்"},{"id":"D","text":"\\( \\pi r^3 \\) கன அலகுகள்"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): \\( 2\\pi r \\) அலகுகள்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q2","subject":"SAT_MATHS","topic":"Unit 6","questionText":"c = 2πr என்னும் சூத்திரத்தில் r என்பது","options":[{"id":"A","text":"சுற்றளவு"},{"id":"B","text":"பரப்பளவு"},{"id":"C","text":"சுழற்சி"},{"id":"D","text":"ஆரம்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): ஆரம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q3","subject":"SAT_MATHS","topic":"Unit 6","questionText":"வட்டத்தின் சுற்றளவு என்பது எப்போதும்","options":[{"id":"A","text":"அதன் விட்டத்தைப் போல் மூன்று மடங்கு"},{"id":"B","text":"அதன் விட்டத்தின் மூன்று மடங்கை விட அதிகம்"},{"id":"C","text":"அதன் விட்டத்தின் மூன்று மடங்கை விடக் குறைவு"},{"id":"D","text":"அதன் ஆரத்தைப் போல் மூன்று மடங்கு"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): அதன் விட்டத்தின் மூன்று மடங்கை விட அதிகம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q4","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஆரம் 14 செ.மீ உடைய வட்டத் தகட்டின் சுற்றளவு","options":[{"id":"A","text":"88 செ.மீ"},{"id":"B","text":"88 ச.செ.மீ"},{"id":"C","text":"42 செ.மீ"},{"id":"D","text":"42 ச.செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 88 செ.மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q5","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஆரம் 10 செ.மீ உடைய வட்டத்தின் சுற்றளவு (π = 3.14)","options":[{"id":"A","text":"31.4 செ.மீ"},{"id":"B","text":"220/7 செ.மீ"},{"id":"C","text":"62.8 செ.மீ"},{"id":"D","text":"100 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 62.8 செ.மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q6","subject":"SAT_MATHS","topic":"Unit 6","questionText":"கொடுக்கப்பட்ட வளையலின் சுற்றளவு காண்க (விட்டம் d = 6 cm, π = 3.14)","questionImage":"/assets/satmaths/image/unit6/image/unit6/q6.png","options":[{"id":"A","text":"18.84 செ.மீ"},{"id":"B","text":"18.34 செ.மீ"},{"id":"C","text":"84.18 செ.மீ"},{"id":"D","text":"841.8 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 18.84 செ.மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q7","subject":"SAT_MATHS","topic":"Unit 6","questionText":"d = 70 செ.மீ. கொண்ட வட்டத்தின் சுற்றளவு","options":[{"id":"A","text":"110 செ.மீ"},{"id":"B","text":"220 செ.மீ"},{"id":"C","text":"330 செ.மீ"},{"id":"D","text":"140 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 220 செ.மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q8","subject":"SAT_MATHS","topic":"Unit 6","questionText":"விட்டம் 15 செ.மீ உடைய வட்டத்தின் சுற்றளவு","options":[{"id":"A","text":"46.1 செ.மீ"},{"id":"B","text":"48.1 செ.மீ"},{"id":"C","text":"30 செ.மீ"},{"id":"D","text":"47.1 செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 47.1 செ.மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q9","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டக் கிணற்றின் விட்டம் 4.2 மீ எனில் அதன் சுற்றளவு","options":[{"id":"A","text":"13.2 மீ"},{"id":"B","text":"13.8 மீ"},{"id":"C","text":"18.4 மீ"},{"id":"D","text":"4.96 மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 13.2 மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q10","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் சுற்றளவு 82π செ.மீ எனில் அதன் ''r'' இன் மதிப்பு","options":[{"id":"A","text":"41 செ.மீ"},{"id":"B","text":"82 செ.மீ"},{"id":"C","text":"21 செ.மீ"},{"id":"D","text":"20 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 41 செ.மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q11","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் சுற்றளவு 132 மீ எனில் அதன் விட்டம்","options":[{"id":"A","text":"21 மீ"},{"id":"B","text":"42 மீ"},{"id":"C","text":"66 மீ"},{"id":"D","text":"84 மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (3): 42 மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q12","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு மாட்டுவண்டிச் சக்கரத்தின் விட்டம் 1.4 மீ. அது 15 முறை சுழலும் போது கடக்கும் தொலைவு","options":[{"id":"A","text":"84 மீ"},{"id":"B","text":"48.4 மீ"},{"id":"C","text":"66 மீ"},{"id":"D","text":"76 மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 66 மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q13","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு விளையாட்டுத் திடல் 350 மீ விட்டத்துடன் கூடிய வட்ட வடிவில் உள்ளது. ஒர் ஓட்டப்பந்தய வீரர், அத்திடலை நான்கு முறை சுற்றி வருகிறார் எனில், அவர் கடந்த தொலைவைக் காண்க.","options":[{"id":"A","text":"2200 மீ"},{"id":"B","text":"4400 மீ"},{"id":"C","text":"4300 மீ"},{"id":"D","text":"4200 மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 4400 மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q14","subject":"SAT_MATHS","topic":"Unit 6","questionText":"1320 செ.மீ. நீளமுள்ள ஒரு கம்பி 7 செ.மீ. ஆரமுள்ள வட்டங்களாக மாற்றப்படுகிறது எனில் எத்தனை வட்டக் கம்பிகளை உருவாக்க முடியும்?","options":[{"id":"A","text":"40"},{"id":"B","text":"50"},{"id":"C","text":"20"},{"id":"D","text":"30"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 30","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q15","subject":"SAT_MATHS","topic":"Unit 6","questionText":"கடிகாரத்தில், 56 மி.மீ நீளமுள்ள வினாடி முள்ளின் முனை ஒரு நிமிடத்தில் கடக்கும் தொலைவு","options":[{"id":"A","text":"42 மி.மீ"},{"id":"B","text":"352 மி.மீ"},{"id":"C","text":"840 மி.மீ"},{"id":"D","text":"484 மி.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 352 மி.மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q16","subject":"SAT_MATHS","topic":"Unit 6","questionText":"கீழ்க்கண்டவற்றில் எது சரியான கூற்று?","options":[{"id":"A","text":"வட்டத்தின் சுற்றளவு அதன் ஆரத்தின் 6 மடங்கை விட அதிகமாக இருக்கும்."},{"id":"B","text":"சமப் பரப்பளவுகளைக் கொண்ட சதுரம் மற்றும் வட்டம் ஆகியவற்றில் சதுரம் அதிக சுற்றளவைப் பெற்றிருக்கும்."},{"id":"C","text":"வட்டத்தின் பரிதிக்கும் விட்டத்திற்கும் இடையேயான விகிதம் எப்போதும் ஒரு மாறிலி ஆகும்."},{"id":"D","text":"மேற்கண்ட அனைத்தும்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): மேற்கண்ட அனைத்தும்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q17","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு டிராக்டர் வண்டிச் சக்கரத்தின் ஆரம் 77 செ.மீ எனில் அது 35 முறை சுற்றும் போது கடக்கும் தொலைவு","options":[{"id":"A","text":"484 செ.மீ"},{"id":"B","text":"1884 செ.மீ"},{"id":"C","text":"16940 செ.மீ"},{"id":"D","text":"1760 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 16940 செ.மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q18","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு மகிழுந்தின் சக்கரம் 20 சுற்றுகளில் 3520 செ.மீ. தொலைவை கடக்கிறது எனில் அதன் ஆரம்","options":[{"id":"A","text":"84 செ.மீ"},{"id":"B","text":"25 செ.மீ"},{"id":"C","text":"28 செ.மீ"},{"id":"D","text":"49 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 28 செ.மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q19","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்ட வடிவப் புல்வெளியைச் சுற்றி அலங்கரிக்க, ஒரு மீட்டருக்கு ₹55 வீதம் ₹16940 செலவாகிறது எனில், அதன் ஆரம்","options":[{"id":"A","text":"49 மீ"},{"id":"B","text":"84 மீ"},{"id":"C","text":"28 மீ"},{"id":"D","text":"42 மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 49 மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q20","subject":"SAT_MATHS","topic":"Unit 6","questionText":"வட்டத்தின் பரப்பளவு காண உதவும் சூத்திரம்","options":[{"id":"A","text":"\\( 4\\pi r^2 \\) ச.அலகுகள்"},{"id":"B","text":"\\( \\pi r^2 \\) ச.அலகுகள்"},{"id":"C","text":"\\( 2\\pi r^2 \\) ச.அலகுகள்"},{"id":"D","text":"\\( \\pi r^2 + 2r \\) ச.அலகுகள்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( \\pi r^2 \\) ச.அலகுகள்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q21","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் பரப்பளவிற்கும் அதன் அரை வட்டத்தின் பரப்பளவிற்கும் இடையேயான விகிதம்","options":[{"id":"A","text":"2:1"},{"id":"B","text":"1:2"},{"id":"C","text":"4:1"},{"id":"D","text":"1:4"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 2:1 [cite: 209, 211, 212, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q22","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஆரம் ''n'' அலகுகள் உடைய வட்டத்தின் பரப்பளவு","options":[{"id":"A","text":"\\( 2\\pi r^2 \\) ச.அலகுகள்"},{"id":"B","text":"\\( \\pi m^2 \\) ச.அ."},{"id":"C","text":"\\( \\pi r^2 \\) ச.அலகுகள்"},{"id":"D","text":"\\( \\pi n^2 \\) ச.அலகுகள்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): \\( \\pi n^2 \\) ச.அலகுகள் [cite: 216, 217, 221, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q23","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஆரம் 21 செ.மீ. அளவுள்ள வட்டத்தின் பரப்பளவு","options":[{"id":"A","text":"1386 ச.செ.மீ."},{"id":"B","text":"1384 ச.செ.மீ."},{"id":"C","text":"2464 ச.செ.மீ."},{"id":"D","text":"616 ச.செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 1386 ச.செ.மீ. [cite: 225, 226, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q24","subject":"SAT_MATHS","topic":"Unit 6","questionText":"28 செ.மீ. விட்டமுள்ள சாகச வளையத்தின் பரப்பளவு","options":[{"id":"A","text":"2464 ச.செ.மீ."},{"id":"B","text":"1384 ச.செ.மீ."},{"id":"C","text":"616 ச.செ.மீ."},{"id":"D","text":"636 ச.செ.மீ."}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 616 ச.செ.மீ. [cite: 231, 233, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q25","subject":"SAT_MATHS","topic":"Unit 6","questionText":"4.9 மீ நீளமுள்ள ஒரு கயிற்றால் ஓர் ஆடு கட்டப்பட்டுள்ளது எனில் ஆடு மேயக் கூடிய அதிகபட்ச பகுதியின் பரப்பளவு","options":[{"id":"A","text":"75.46 மீ²"},{"id":"B","text":"4.96 மீ²"},{"id":"C","text":"56 மீ²"},{"id":"D","text":"57.2 மீ²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 75.46 மீ² [cite: 235, 236, 237, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q26","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் பரப்பளவு 2464 ச.செ.மீ. அதன் விட்டம் என்ன?","options":[{"id":"A","text":"28 செ.மீ."},{"id":"B","text":"56 செ.மீ."},{"id":"C","text":"14 செ.மீ."},{"id":"D","text":"70 செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 56 செ.மீ. [cite: 239, 241, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q27","subject":"SAT_MATHS","topic":"Unit 6","questionText":"பொருத்துக: (i) விட்டம் (ii) 2πr (iii) (π+2)r (iv) விட்டம்/2 (v) πr²","options":[{"id":"A","text":"a-v, b-iv, c-ii, d-i"},{"id":"B","text":"a-iv, b-ii, c-iii, d-i"},{"id":"C","text":"a-iv, b-ii, c-ii, d-i"},{"id":"D","text":"a-v, b-iii, c-v, d-i"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): a-v, c-ii, d-i (மற்றும் b-iv) [cite: 247, 248, 251, 253, 256, 258, 259, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q28","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டப் பூங்காவின் சுற்றளவு 44 மீ எனில், அந்தப் பூங்காவின் பரப்பளவு","options":[{"id":"A","text":"154 மீ²"},{"id":"B","text":"174 மீ²"},{"id":"C","text":"44 மீ²"},{"id":"D","text":"176 மீ²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 154 மீ² [cite: 267, 274, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q29","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் சுற்றளவு 352 செ.மீ எனில், அந்த வட்டத்தின் பரப்பளவு","options":[{"id":"A","text":"8662 ச.செ.மீ."},{"id":"B","text":"12474 ச.செ.மீ."},{"id":"C","text":"2772 ச.செ.மீ."},{"id":"D","text":"9856 ச.செ.மீ."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 9856 ச.செ.மீ. [cite: 271, 275, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q30","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் பரப்பளவு 196π ச.செ.மீ எனில், அந்த வட்டத்தின் சுற்றளவு","options":[{"id":"A","text":"14 செ.மீ."},{"id":"B","text":"88 செ.மீ."},{"id":"C","text":"\\( \\pi(44)^2 \\) செ.மீ."},{"id":"D","text":"986 செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 88 செ.மீ. [cite: 275, 277, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q31","subject":"SAT_MATHS","topic":"Unit 6","questionText":"7 மீ ஆரமுள்ள வட்ட வடிவ நீச்சல் குளத்தின் தளத்திற்குச் சிமெண்ட் பூச சதுர மீட்டருக்கு ₹18 வீதம் ஆகும் செலவு","options":[{"id":"A","text":"₹247"},{"id":"B","text":"₹2829"},{"id":"C","text":"₹2772"},{"id":"D","text":"₹9590"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): ₹2772 [cite: 278, 279, 283, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q32","subject":"SAT_MATHS","topic":"Unit 6","questionText":"வட்டப் பாதையின் அகலம் காணும் சூத்திரம்","options":[{"id":"A","text":"(L-l) அலகுகள்"},{"id":"B","text":"(B-b) அலகுகள்"},{"id":"C","text":"(R-r) அலகுகள்"},{"id":"D","text":"(r-R) அலகுகள்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): (R-r) அலகுகள் [cite: 281, 286, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q33","subject":"SAT_MATHS","topic":"Unit 6","questionText":"வட்ட நடைபாதையின் பரப்பளவு காணும் சூத்திரம்","options":[{"id":"A","text":"\\( \\pi(R^2-r^2) \\) ச.அலகுகள்"},{"id":"B","text":"\\( \\pi r^2 \\) ச.அலகுகள்"},{"id":"C","text":"\\( 2\\pi r^2 \\) ச.அலகுகள்"},{"id":"D","text":"\\( \\pi r^2+2r \\) ச.அலகுகள்"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): \\( \\pi(R^2-r^2) \\) ச.அலகுகள் [cite: 282, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q34","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டப்பாதையின் வெளி மற்றும் உள் ஆரங்கள் 9 செ.மீ. மற்றும் 6 செ.மீ. எனில் அதன் அகலம்","options":[{"id":"A","text":"3 செ.மீ."},{"id":"B","text":"6 செ.மீ."},{"id":"C","text":"1.5 செ.மீ."},{"id":"D","text":"9 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 3 செ.மீ. [cite: 293, 294, 295, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q35","subject":"SAT_MATHS","topic":"Unit 6","questionText":"52 மீ ஆரமுள்ள ஒரு வட்டவடிவமுள்ள புல்வெளியின் மையத்தில் 45 மீ நீளமுள்ள ஒரு கயிற்றால் ஒரு ஆடு கட்டப்பட்டுள்ளது. அந்த ஆட்டால் மேய முடியாத புல்வெளியின் பரப்பளவு","options":[{"id":"A","text":"668 மீ²"},{"id":"B","text":"2000 மீ²"},{"id":"C","text":"2134 மீ²"},{"id":"D","text":"770 மீ²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 2134 மீ² [cite: 299, 300, 301, 309, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q36","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்ட வடிவப் பூந்தோட்டத்தின் ஆரம் 21 மீ. அந்தத் தோட்டத்தைச் சுற்றி 14 மீ அகலம் உள்ள வட்ட நடைபாதை உள்ளது எனில் அந்த வட்டப் பாதையின் பரப்பளவு","options":[{"id":"A","text":"286 மீ²"},{"id":"B","text":"2644 மீ²"},{"id":"C","text":"2464 மீ²"},{"id":"D","text":"3522 மீ²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 2464 மீ² [cite: 305, 306, 310, 311, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q37","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்ட வடிவ கிரிக்கெட் அரங்கத்தின் விட்டம் 224 மீ. அதன் உட்புறமாகச் சுற்றிலும் பார்வையாளர்கள் அமர்ந்து பார்ப்பதற்காக பார்வையாளர்கள் மாடம் 14 மீ அகலத்தில் கட்டப்பட்டுள்ளது. எனில், விளையாடப் பயன்படும் இடத்தின் பரப்பளவு?","options":[{"id":"A","text":"10472 மீ²"},{"id":"B","text":"9856 மீ²"},{"id":"C","text":"11272 மீ²"},{"id":"D","text":"8756 மீ²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 10472 மீ² [cite: 313, 314, 320, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q38","subject":"SAT_MATHS","topic":"Unit 6","questionText":"படத்தில் உள்ள இரு வட்டங்களின் சுற்றளவுகளின் வித்தியாசம் என்ன? (R = 14 cm, அகலம் = 3.5 cm)","questionImage":"/assets/satmaths/image/unit6/image/unit6/q38.png","options":[{"id":"A","text":"22 செ.மீ."},{"id":"B","text":"20 செ.மீ."},{"id":"C","text":"24 செ.மீ."},{"id":"D","text":"66 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 22 செ.மீ. [cite: 321, 322, 324, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q39","subject":"SAT_MATHS","topic":"Unit 6","questionText":"செவ்வக பாதையின் பரப்பளவு காணும் சூத்திரம்","options":[{"id":"A","text":"\\( \\pi(R^2-r^2) \\)"},{"id":"B","text":"\\( (L \\times B) - (l \\times b) \\) ச.அலகுகள்"},{"id":"C","text":"LB ச.அலகுகள்"},{"id":"D","text":"lb ச.அலகுகள்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( (L \\times B) - (l \\times b) \\) ச.அலகுகள் [cite: 329, 334, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q40","subject":"SAT_MATHS","topic":"Unit 6","questionText":"உட்புறச் செவ்வகத்தின் பரப்பளவு 15 ச.செ.மீ. மற்றும் வெளிப்புறச் செவ்வகத்தின் பரப்பளவு 48 ச.செ.மீ. எனில் செவ்வக நடைபாதையின் பரப்பளவு","options":[{"id":"A","text":"12 ச.செ.மீ."},{"id":"B","text":"23 ச.செ.மீ."},{"id":"C","text":"30 ச.செ.மீ."},{"id":"D","text":"33 ச.செ.மீ."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 33 ச.செ.மீ. [cite: 336, 337, 341, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q41","subject":"SAT_MATHS","topic":"Unit 6","questionText":"23 செ.மீ. நீளமும் 11 செ.மீ அகலமும் உள்ள ஓர் அட்டையில், அனைத்துப் பக்கங்களிலும் 3 செ.மீ. விளிம்பு இருக்கும் வகையில் ஓர் ஓவியம் வரையப்பட்டுள்ளது. அந்த விளிம்புப் பகுதியின் பரப்பளவு","options":[{"id":"A","text":"253 ச.செ.மீ."},{"id":"B","text":"85 ச.செ.மீ."},{"id":"C","text":"154 ச.செ.மீ."},{"id":"D","text":"168 ச.செ.மீ."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 168 ச.செ.மீ. [cite: 342, 343, 344, 348, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q42","subject":"SAT_MATHS","topic":"Unit 6","questionText":"படம் ஒரு நடைபாதையின் வான்வழிக்காட்சி (L=80m, B=50m, l=70m, b=40m) எனில் அந்தப் பாதையின் பரப்பளவு காண்க.","questionImage":"/assets/satmaths/image/unit6/image/unit6/q42.png","options":[{"id":"A","text":"1400 மீ²"},{"id":"B","text":"1200 மீ²"},{"id":"C","text":"3600 மீ²"},{"id":"D","text":"2200 மீ²"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 1200 மீ² [cite: 349, 355, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q43","subject":"SAT_MATHS","topic":"Unit 6","questionText":"9 மீ நீளமும், 7 மீ அகலமும் உள்ள ஒரு அறைக்கு வெளியே, 3 மீ சீரான அகலமுள்ள ஒரு தாழ்வாரம் உள்ளது. தாழ்வாரத்தின் பரப்பளவு","options":[{"id":"A","text":"132 மீ²"},{"id":"B","text":"118 மீ²"},{"id":"C","text":"154 மீ²"},{"id":"D","text":"91 மீ²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 132 மீ² [cite: 358, 359, 360, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q44","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு தளம் 10 மீ நீளமும் 8 மீ அகலமும் உள்ளது. அதன் மீது 7 மீ நீளமும் 5 மீ அகலமும் உள்ள விரிப்பு விரிக்கப்பட்டுள்ளது. அந்த விரிப்பால் மூடப்படாத பகுதியின் பரப்பளவு","options":[{"id":"A","text":"35 மீ²"},{"id":"B","text":"80 மீ²"},{"id":"C","text":"45 மீ²"},{"id":"D","text":"25 மீ²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 45 மீ² [cite: 364, 365, 368, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q45","subject":"SAT_MATHS","topic":"Unit 6","questionText":"76 மீ நீளமும் 70 மீ அகலமும் உள்ள ஒரு செவ்வக வடிவப் புல்வெளியின் மையத்தில், ஒரு மாடு 35 மீ நீளமுள்ள கயிற்றால் கட்டப்பட்டுள்ளது. அந்த மாடு மேய முடியாத நிலப்பரப்பளவை அளவிடுக.","options":[{"id":"A","text":"1470 மீ²"},{"id":"B","text":"3850 மீ²"},{"id":"C","text":"710 மீ²"},{"id":"D","text":"5320 மீ²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 1470 மீ² [cite: 369, 370, 371, 372, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q46","subject":"SAT_MATHS","topic":"Unit 6","questionText":"நீளம் 120 மீ அகலம் 90 மீ உள்ள ஒரு செவ்வக வடிவத் தோட்டத்தைச் சுற்றிப் பாதை அமைக்கப்படுகிறது. ஆனால் பாதை படத்தில் காட்டியுள்ளவாறு எதிரெதிர்ப் பக்கங்களில் மட்டும் சீராக 2 மீ, 1 மீ என்ற அகலங்களில் செல்கிறது. எனில் அந்தப் பாதையின் பரப்பளவு","questionImage":"/assets/satmaths/image/unit6/image/unit6/q46.png","options":[{"id":"A","text":"608 மீ²"},{"id":"B","text":"668 மீ²"},{"id":"C","text":"616 மீ²"},{"id":"D","text":"686 மீ²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 608 மீ² [cite: 376, 377, 378, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q47","subject":"SAT_MATHS","topic":"Unit 6","questionText":"படத்தில் உள்ள இரு வட்டங்களின் ஆரங்கள் 10 செ.மீ. மற்றும் 17 செ.மீ. ஆகியன ஆகும். இவ்விரண்டு வட்டங்களும் பொதுமைய வட்டங்கள் அல்ல. எனில், நிழலிடப்பட்ட பகுதியின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit6/image/unit6/q47.png","options":[{"id":"A","text":"533.8 ச.செ.மீ."},{"id":"B","text":"170 ச.செ.மீ."},{"id":"C","text":"694 ச.செ.மீ."},{"id":"D","text":"594 ச.செ.மீ."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 594 ச.செ.மீ. [cite: 386, 387, 390, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q48","subject":"SAT_MATHS","topic":"Unit 6","questionText":"நான்கு வீட்டு மனைகள் அடங்கிய ஒரு நிலத்தில் 10 அடி அகல தார்ச்சாலை அமைக்கப்பட்டுள்ளது. இந்நிலத்தின் நீள அகலங்கள் முறையே 100 அடி மற்றும் 80 அடி. எனில் தார்ச்சாலையின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit6/image/unit6/q48.png","options":[{"id":"A","text":"6300 ச.அடி"},{"id":"B","text":"1700 ச.அடி"},{"id":"C","text":"1800 ச.அடி"},{"id":"D","text":"6200 ச.அடி"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 1700 ச.அடி [cite: 391, 393, 394, 397, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q49","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வயலின் நீளம் 40 மீ. அகலம் 20 மீ. அவ்வயலில் 2 மீ. அகலமுள்ள வாய்க்கால் செல்கிறது. எனவே வயலில் பயிர் விளையும் இடத்தின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit6/image/unit6/q49.png","options":[{"id":"A","text":"916 மீ²"},{"id":"B","text":"680 மீ²"},{"id":"C","text":"684 மீ²"},{"id":"D","text":"664 மீ²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 684 மீ² [cite: 399, 400, 401, 405, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q50","subject":"SAT_MATHS","topic":"Unit 6","questionText":"வயலில் அடிக்கப்பட்டுள்ள கட்டையில் 3.5 மீ நீளம் கொண்ட தும்பு கயிறு கொண்டு ஆடு கட்டப்பட்டுள்ளது. ஆடு மேயக்கூடிய அதிகபட்ச பகுதியின் பரப்பளவு","options":[{"id":"A","text":"40.5 மீ²"},{"id":"B","text":"38.5 மீ²"},{"id":"C","text":"17.2 மீ²"},{"id":"D","text":"30.5 மீ²"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 38.5 மீ² [cite: 407, 409, 414, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q51","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் பெரிய நாணின் நீளம் 14 செ.மீ. எனில் அதன் சுற்றளவு மற்றும் பரப்பளவுகளின் எண்ணளவுகளின் விகிதம்","options":[{"id":"A","text":"7:2"},{"id":"B","text":"1:2"},{"id":"C","text":"2:7"},{"id":"D","text":"2:1"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 2:7 [cite: 412, 415, 418, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q52","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்ட வடிவ சக்கரத்தின் ஆரம் 1.75 மீ. அது 11 கி.மீ. தொலைவைக் கடந்திட எத்தனை சுற்றுகள் சுற்ற வேண்டும்.","options":[{"id":"A","text":"10"},{"id":"B","text":"100"},{"id":"C","text":"1000"},{"id":"D","text":"10000"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 1000 [cite: 419, 422, 425, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q53","subject":"SAT_MATHS","topic":"Unit 6","questionText":"இரண்டு வட்டங்களின் பரப்பளவின் விகிதம் 25:36 எனில் அந்த இரண்டு வட்டங்களுடைய சுற்றளவுகளின் விகிதம்","options":[{"id":"A","text":"6:5"},{"id":"B","text":"3:4"},{"id":"C","text":"4:3"},{"id":"D","text":"5:6"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 5:6 [cite: 427, 429, 433, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q54","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் விட்டம் D எனில் அதன் சுற்றளவு","options":[{"id":"A","text":"\\( 2\\pi D \\) அலகுகள்"},{"id":"B","text":"\\( \\pi D \\) அலகுகள்"},{"id":"C","text":"\\( 2\\pi r \\) அலகுகள்"},{"id":"D","text":"\\( \\pi r \\) அலகுகள்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( \\pi D \\) அலகுகள் [cite: 441, 447, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q55","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் சுற்றளவு மற்றும் பரப்பளவு எண்ணளவில் சமமாக இருந்தால் விட்டம் எதற்குச் சமமாக இருக்கும்?","options":[{"id":"A","text":"\\( \\pi / 2 \\)"},{"id":"B","text":"\\( 2\\pi \\)"},{"id":"C","text":"2"},{"id":"D","text":"4"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 4 [cite: 442, 443, 453, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q56","subject":"SAT_MATHS","topic":"Unit 6","questionText":"விட்டத்திற்கும் ஆரத்திற்குமுள்ள தொடர்பு","options":[{"id":"A","text":"ஆரம் = 2 × விட்டம்"},{"id":"B","text":"ஆரம் = விட்டம் + 2"},{"id":"C","text":"விட்டம் = ஆரம் + 2"},{"id":"D","text":"விட்டம் = 2 × ஆரம்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): விட்டம் = 2 × ஆரம் [cite: 447, 448, 454, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q57","subject":"SAT_MATHS","topic":"Unit 6","questionText":"வட்டத்தில் உள்ள கால்பகுதிகள் எத்தனை?","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 4 [cite: 450, 460, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q58","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் மிகப்பெரிய நாண், அதன் ______ எனப்படும்","options":[{"id":"A","text":"ஆரம்"},{"id":"B","text":"சுற்றளவு"},{"id":"C","text":"விட்டம்"},{"id":"D","text":"தொடுகோடு"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): விட்டம் [cite: 461, 462, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q59","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் ஆரம் இரு மடங்காக அதிகரித்தால் கிடைக்கும் புதிய வட்டத்தின் பரப்பளவு ______ ஆக அதிகரிக்கும்.","options":[{"id":"A","text":"அதே அளவு"},{"id":"B","text":"இரு மடங்கு"},{"id":"C","text":"மூன்று மடங்கு"},{"id":"D","text":"நான்கு மடங்கு"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): நான்கு மடங்கு [cite: 463, 464, 472, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q60","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஆரம் ''r'' உடைய வட்டத்தின் பரப்பளவு \\( \\pi r^2 \\). இங்கு \\( \\pi \\) என்பது","options":[{"id":"A","text":"ஒரு விகிதமுறு எண்"},{"id":"B","text":"ஒரு விகிதமுறா எண்"},{"id":"C","text":"ஒரு முழு எண்"},{"id":"D","text":"ஒரு எண் அல்ல"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): ஒரு விகிதமுறா எண் [cite: 475, 480, 574]","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q61","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு செவ்வக வடிவத் தோட்டத்தின் பரிமாணங்கள் 15 மீ × 8 மீ. அதன் பக்கங்களை அடுத்து 4 மீ அகலமுள்ள பாதை அமைக்கப்படுகிறது அந்தப் பாதையின் பரப்பளவு","options":[{"id":"A","text":"248 மீ²"},{"id":"B","text":"180 மீ²"},{"id":"C","text":"108 மீ²"},{"id":"D","text":"150 மீ²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 248 மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q62","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்ட வடிவப் பூங்காவின் சுற்றளவு \\( 15\\frac{2}{3} \\) மீ ஆகும். இதை மூன்று முறை கயிற்றினாலும் மற்றும் \\( \\frac{2}{3} \\) பகுதியை மின்சார கம்பியினாலும் வேலியிட்டால், அப்பூங்காவிற்கு எத்தனை மீட்டர் வேலி (கயிறு மற்றும் மின்சாரம் கம்பி) தேவைப்படும்.","options":[{"id":"A","text":"\\( 10\\frac{4}{9} \\) மீ"},{"id":"B","text":"\\( 57\\frac{4}{9} \\) மீ"},{"id":"C","text":"\\( 172\\frac{1}{3} \\) மீ"},{"id":"D","text":"\\( 31\\frac{1}{3} \\) மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( 57\\frac{4}{9} \\) மீ","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q63","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டப்புல்வெளியைச் சுற்றி ஒரு வட்டப்பாதை அமைக்கப்படவுள்ளது அந்தப் பாதையின் வெளிப்புற, உட்புறச் சுற்றளவுகள் முறையே 88 செ.மீ., 44 செ.மீ. எனில் அந்த நடைபாதையின் அகலம் என்ன?","options":[{"id":"A","text":"7 செ.மீ."},{"id":"B","text":"44 செ.மீ."},{"id":"C","text":"14 செ.மீ."},{"id":"D","text":"22 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 7 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q64","subject":"SAT_MATHS","topic":"Unit 6","questionText":"வட்டத் தகட்டின் ஆரம் 7 செ.மீ. எனில் சுற்றளவு என்ன?","options":[{"id":"A","text":"14 செ.மீ."},{"id":"B","text":"22 செ.மீ."},{"id":"C","text":"44 செ.மீ."},{"id":"D","text":"88 செ.மீ."}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 44 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q65","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தில் தவறான கூற்றினை எழுதுக.","options":[{"id":"A","text":"ஒரு வட்டத்தின் அனைத்து ஆரங்களும் ஒரே நீளமுடையன."},{"id":"B","text":"வட்டத்தின் ஒவ்வொரு விட்டமும் ஒரு நாணாகும்"},{"id":"C","text":"இரு விட்டங்கள் ஒரே முனைப்புள்ளிகளை பெற்றிருக்க முடியாது"},{"id":"D","text":"வட்டத்தின் ஒவ்வொரு நாணும் ஒரு விட்டமாகும்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): வட்டத்தின் ஒவ்வொரு நாணும் ஒரு விட்டமாகும்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q66","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்ட வடிவப் பூங்தோட்டத்தின் ஆரம் 14 மீ அந்தத் தோட்டத்தைச் சுற்றி 7 மீ அகலம் உள்ள வட்ட நடைபாதை உள்ளது எனில் அந்த வட்டப்பாதையின் பரப்பளவு காண்க.","options":[{"id":"A","text":"1225 மீ²"},{"id":"B","text":"22 மீ²"},{"id":"C","text":"484 மீ²"},{"id":"D","text":"770 மீ²"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 770 மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q67","subject":"SAT_MATHS","topic":"Unit 6","questionText":"வட்ட வடிவிலான ஒரு தாமிரக் கம்பியின் ஆரம் 35 செ.மீ. இது ஒரு சதுர வடிவில் வளைக்கப்படுகிறது எனில் அச்சதுரத்தின் பக்கத்தைக் காண்க.","options":[{"id":"A","text":"35 செ.மீ."},{"id":"B","text":"45 செ.மீ."},{"id":"C","text":"55 செ.மீ."},{"id":"D","text":"65 செ.மீ."}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 55 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q68","subject":"SAT_MATHS","topic":"Unit 6","questionText":"மாட்டு வண்டிச் சக்கரத்தின் ஆரம் 35 செ.மீ. அது 154 மீ தொலைவு கடந்தால், அச்சக்கரம் எத்தனை முழுச் சுற்றுகள் சுற்றியிருக்கும்?","options":[{"id":"A","text":"70"},{"id":"B","text":"189"},{"id":"C","text":"119"},{"id":"D","text":"86"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 70","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q69","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டமான தோட்டத்தைச் சுற்றி ஒரே நேரத்தில் துவங்கி A, B, C, D என்பவர்கள் ஒரே திசையில் ஓடுகிறனர். ஒரு முறை சுற்றி வர A,B,C,D என்பவர்கள் எடுத்துக்கொள்ளும் கால அளவு முறையை 30 நிமிடங்கள் 60 நிமிடங்கள், 90 நிமிடங்கள் மற்றும் 105 நிமிடங்கள் ஆகும். துவக்கப் புள்ளியில் எத்தனை மணிக்கு பிறகு இவர்கள் மீண்டும் சந்திப்பார்கள்?","options":[{"id":"A","text":"15 மணி நேரம்"},{"id":"B","text":"10 மணி நேரம்"},{"id":"C","text":"21 மணி நேரம்"},{"id":"D","text":"20 மணி நேரம்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 21 மணி நேரம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q70","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு செவ்வக வடிவ நிலம் 20 மீ நீளம் மற்றும் 14 மீ அகலம் கொண்டது அதைச் சுற்றி வெளிப்புறத்தில் அமைந்துள்ள சீரான அகலமுள்ள பாதையின் பரப்பு 111 ச.மீ. எனில் பாதையின் அகலம் என்ன?","options":[{"id":"A","text":"8/2 மீ"},{"id":"B","text":"3/2 மீ"},{"id":"C","text":"5/3 மீ"},{"id":"D","text":"1 மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 3/2 மீ (அல்லது 1.5 மீ)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q71","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் சுற்றளவுக்கும் ஆரத்துக்கும் உள்ள வேறுபாடு 37 செ.மீ. ஆகும். எனில் அவ்வட்டத்தின் ஆரம் என்ன?","options":[{"id":"A","text":"7 செ.மீ."},{"id":"B","text":"44 செ.மீ."},{"id":"C","text":"154 செ.மீ."},{"id":"D","text":"88 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 7 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q72","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் சுற்றளவு c எனவும் பரப்பளவு A எனவும் ஆரம் r எனவும் கருதினால், கீழ்க்கண்டவற்றுள் எது சரி?","options":[{"id":"A","text":"\\( r \\times C = 2 \\times A \\)"},{"id":"B","text":"\\( \\frac{c}{A} = \\frac{r}{2} \\)"},{"id":"C","text":"\\( A \\times C = \\frac{r^2}{4} \\)"},{"id":"D","text":"\\( \\frac{A}{r} = C \\)"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): \\( r \\times C = 2 \\times A \\)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q73","subject":"SAT_MATHS","topic":"Unit 6","questionText":"ஒரு வட்டத்தின் ஆரம் 1 அலகு அதிகரிக்கும் போது உருவாகும் வட்டத்தின் சுற்றளவுக்கும் விட்டத்திற்கும் உள்ள விகிதம் என்ன?","options":[{"id":"A","text":"\\( 1 : \\pi \\)"},{"id":"B","text":"\\( \\pi : 1 \\)"},{"id":"C","text":"\\( \\pi : 3 \\)"},{"id":"D","text":"\\( 3 : \\pi \\)"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( \\pi : 1 \\)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-6-q74","subject":"SAT_MATHS","topic":"Unit 6","questionText":"மோகன் என்பவர் 14 செ.மீ. ஆரமுள்ள ஒரு வட்டத் தகட்டை நான்கு சமபாகங்களாகப் பிரிக்கிறார். அதன் ஒரு கால் வட்டத் தகட்டின் சுற்றளவு","options":[{"id":"A","text":"50 செ.மீ."},{"id":"B","text":"22 செ.மீ."},{"id":"C","text":"28 செ.மீ."},{"id":"D","text":"36 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 50 செ.மீ.","marks":1,"negativeMarks":0}]', datetime('now'));
INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('SAT_MATHS_7', 'SAT_MATHS', 7, '[{"id":"unit-satmaths-7-q1","subject":"SAT_MATHS","topic":"Unit 7","questionText":"வட்டத்தின் பரிதிக்கும் அதன் விட்டத்திற்கும் இடையேயான விகிதம்","options":[{"id":"A","text":"\\( 2\\pi \\)"},{"id":"B","text":"\\( \\pi \\)"},{"id":"C","text":"\\( \\pi r^2 \\)"},{"id":"D","text":"r"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( \\pi \\)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q2","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் மீதுள்ள ஏதேனும் இரண்டு புள்ளிகளை இணைக்கும் கோடு","options":[{"id":"A","text":"பரிதி"},{"id":"B","text":"ஆரம்"},{"id":"C","text":"நாண்"},{"id":"D","text":"வட்டவில்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): நாண்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q3","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் மிகப் பெரிய நாண்","options":[{"id":"A","text":"ஆரம்"},{"id":"B","text":"மையம்"},{"id":"C","text":"வட்டவில்"},{"id":"D","text":"விட்டம்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): விட்டம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q4","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் மையக்கோண அளவு","options":[{"id":"A","text":"90°"},{"id":"B","text":"180°"},{"id":"C","text":"270°"},{"id":"D","text":"360°"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 360°","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q5","subject":"SAT_MATHS","topic":"Unit 7","questionText":"24 செ.மீ. விட்ட அளவுள்ள ஒரு வட்டத்தின் ஆரம்","options":[{"id":"A","text":"8 செ.மீ."},{"id":"B","text":"16 செ.மீ."},{"id":"C","text":"12 செ.மீ."},{"id":"D","text":"18 செ.மீ."}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 12 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q6","subject":"SAT_MATHS","topic":"Unit 7","questionText":"வட்டப்பரிதியின் ஒரு பகுதியே ______ ஆகும்.","options":[{"id":"A","text":"வட்டவில்"},{"id":"B","text":"மையக்கோணம்"},{"id":"C","text":"வட்டகோணப்பகுதி"},{"id":"D","text":"விட்டம்"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): வட்டவில்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q7","subject":"SAT_MATHS","topic":"Unit 7","questionText":"அரைவட்டத்தின் மையத்தில் அமையும் கோணம்","options":[{"id":"A","text":"நேர்கோணம்"},{"id":"B","text":"விரிகோணம்"},{"id":"C","text":"செங்கோணம்"},{"id":"D","text":"பூஜ்ஜியக் கோணம்"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): நேர்கோணம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q8","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் மிகப்பெரிய நாணின் பாதி அதன் ______ எனப்படும்.","options":[{"id":"A","text":"விட்டம்"},{"id":"B","text":"மையம்"},{"id":"C","text":"ஆரம்"},{"id":"D","text":"வட்டவில்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): ஆரம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q9","subject":"SAT_MATHS","topic":"Unit 7","questionText":"π தினம் எப்போது கொண்டாடப்படுகிறது?","options":[{"id":"A","text":"மார்ச் 14"},{"id":"B","text":"மே 5"},{"id":"C","text":"ஆகஸ்ட் 22"},{"id":"D","text":"ஆகஸ்ட் 5"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): மார்ச் 14","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q10","subject":"SAT_MATHS","topic":"Unit 7","questionText":"7 செ.மீ. ஆரமுள்ள வட்டத்தின் துல்லியமான சுற்றளவு என்ன?","options":[{"id":"A","text":"\\( 14\\pi \\) செ.மீ."},{"id":"B","text":"44 செ.மீ."},{"id":"C","text":"43.96 செ.மீ."},{"id":"D","text":"154 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): \\( 14\\pi \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q11","subject":"SAT_MATHS","topic":"Unit 7","questionText":"வட்டத்தின் பரப்பளவு 3465 ச.மீ எனில் அதன் சுற்றளவு","options":[{"id":"A","text":"70 மீ"},{"id":"B","text":"140 மீ"},{"id":"C","text":"210 மீ"},{"id":"D","text":"280 மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 210 மீ. பரப்பளவு \\( \\pi r^2 = 3465 \\Rightarrow \n\\frac{22}{7} r^2 = 3465 \\Rightarrow r^2 = 1102.5 \\Rightarrow r \\approx 33.2 \\) மீ. சுற்றளவு = \\( 2 \\pi r = 2 \\times \\frac{22}{7} \\times 33.2 \\approx 210 \\) மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q12","subject":"SAT_MATHS","topic":"Unit 7","questionText":"வட்ட வடிவ பூங்காவின் சுற்றளவு 880 செ.மீ. எனில், பூங்காவின் ஆரம்","options":[{"id":"A","text":"70 செ.மீ"},{"id":"B","text":"140 செ.மீ"},{"id":"C","text":"210 செ.மீ"},{"id":"D","text":"280 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 140 செ.மீ. சுற்றளவு = \\( 2 \\pi r = 880 \\Rightarrow 2 \\times \\frac{22}{7} \\times r = 880 \\Rightarrow r = \\frac{880 \\times 7}{44} = 140 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q13","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் மிகப்பெரிய நாணின் நீளம் 14 செ.மீ. எனில், அதன் சுற்றளவு மற்றும் பரப்பளவுகளின் எண்ணளவுகளின் விகிதம்","options":[{"id":"A","text":"7:2"},{"id":"B","text":"1:2"},{"id":"C","text":"2:7"},{"id":"D","text":"2:1"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 2:7. மிகப்பெரிய நாண் என்பது விட்டம் (d=14), எனவே ஆரம் r=7. சுற்றளவு = \\( 2\\pi r = 14\\pi \\). பரப்பளவு = \\( \\pi r^2 = 49\\pi \\). விகிதம் = \\( 14\\pi : 49\\pi = 2:7 \\).","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q14","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் ஆரம் இரு மடங்கு அதிகரித்தால் கிடைக்கும் புதிய வட்டத்தின் பரப்பளவு எவ்வளவு அதிகரிக்கும்?","options":[{"id":"A","text":"இரு மடங்கு"},{"id":"B","text":"நான்கு மடங்கு"},{"id":"C","text":"மூன்று மடங்கு"},{"id":"D","text":"எதுவும் மாற்றமில்லை"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): நான்கு மடங்கு. பழைய பரப்பளவு = \\( \\pi r^2 \\). புதிய ஆரம் = 2r. புதிய பரப்பளவு = \\( \\pi (2r)^2 = 4\\pi r^2 \\). எனவே 4 மடங்கு அதிகரிக்கும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q15","subject":"SAT_MATHS","topic":"Unit 7","questionText":"வட்டக்கோணப்பகுதியின் மையக்கோணம்","options":[{"id":"A","text":"\\( 360^{\\circ} \\)"},{"id":"B","text":"\\( 360^{\\circ} n \\)"},{"id":"C","text":"\\( \\frac{360^{\\circ}}{n} \\)"},{"id":"D","text":"\\( 180^{\\circ} \\)"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): \\( \\frac{360^{\\circ}}{n} \\). ஒரு வட்டத்தை ''n'' சமப் பகுதிகளாகப் பிரிக்கும்போது, ஒவ்வொரு வட்டக்கோணப்பகுதியின் மையக்கோணம் \\( \\theta = \\frac{360^{\\circ}}{n} \\) ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q16","subject":"SAT_MATHS","topic":"Unit 7","questionText":"நிழலிடப்பட்டுள்ள வட்டக்கோணப் பகுதியின் மையக்கோணம் என்ன? (வட்டம் 5 சமப் பகுதிகளாகப் பிரிக்கப்பட்டுள்ளதாகக் கொள்க)","options":[{"id":"A","text":"\\( 180^{\\circ} \\)"},{"id":"B","text":"\\( 72^{\\circ} \\)"},{"id":"C","text":"\\( 45^{\\circ} \\)"},{"id":"D","text":"\\( 36^{\\circ} \\)"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( 72^{\\circ} \\). வட்டம் 5 சமப் பகுதிகளாகப் பிரிக்கப்பட்டால் (n=5), மையக்கோணம் = \\( \\frac{360^{\\circ}}{5} = 72^{\\circ} \\).","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q17","subject":"SAT_MATHS","topic":"Unit 7","questionText":"பொருத்துக.\n(i) அரைவட்டத்தின் பரப்பளவு -> (a) \\( \\frac{1}{4}\\pi r^2 \\)\n(ii) வட்டக்கோணப் பகுதியின் வில்லின் நீளம் -> (b) \\( l+2r \\)\n(iii) வட்டக்கோணப் பகுதியின் பரப்பளவு -> (c) \\( \\frac{\\pi r^2}{2} \\)\n(iv) வட்டக்கோணப் பகுதியின் சுற்றளவு -> (d) \\( \\frac{\\theta}{360^{\\circ}} \\times 2\\pi r \\)\n(v) கால்வட்டத்தின் பரப்பளவு -> (e) \\( \\frac{\\theta}{360^{\\circ}} \\times \\pi r^2 \\)","options":[{"id":"A","text":"i-a, ii-b, iii-c, iv-d, v-e"},{"id":"B","text":"i-c, ii-d, iii-e, iv-b, v-a"},{"id":"C","text":"i-d, ii-c, iii-e, iv-a, v-b"},{"id":"D","text":"i-b, ii-e, iii-c, iv-d, v-a"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): i-c, ii-d, iii-e, iv-b, v-a.\n(i) அரைவட்டத்தின் பரப்பளவு = \\( \\frac{\\pi r^2}{2} \\) (c)\n(ii) வில்லின் நீளம் = \\( \\frac{\\theta}{360^{\\circ}} \\times 2\\pi r \\) (d)\n(iii) வட்டக்கோணப் பகுதியின் பரப்பளவு = \\( \\frac{\\theta}{360^{\\circ}} \\times \\pi r^2 \\) (e)\n(iv) வட்டக்கோணப் பகுதியின் சுற்றளவு = \\( l+2r \\) (b)\n(v) கால்வட்டத்தின் பரப்பளவு = \\( \\frac{1}{4}\\pi r^2 \\) (a).","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q18","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஆரம் 28 செ.மீ. உடைய அரைவட்டத்தின் பரப்பளவு காண்க. (\\( \\pi=\\frac{22}{7} \\))","options":[{"id":"A","text":"618 ச.செ.மீ"},{"id":"B","text":"144 ச.செ.மீ"},{"id":"C","text":"1232 ச.செ.மீ"},{"id":"D","text":"784 ச.செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 1232 ச.செ.மீ. அரைவட்டத்தின் பரப்பளவு = \\( \\frac{1}{2} \\pi r^2 = \\frac{1}{2} \\times \\frac{22}{7} \\times 28 \\times 28 = 11 \\times 4 \\times 28 = 1232 \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q19","subject":"SAT_MATHS","topic":"Unit 7","questionText":"விட்டம் 0.14 செ.மீ. கொண்ட அரைவட்டத்தின் பரப்பளவு (\\( \\pi=\\frac{22}{7} \\) எனக் கொள்க)","options":[{"id":"A","text":"0.0077 ச.செ.மீ"},{"id":"B","text":"0.77 ச.செ.மீ"},{"id":"C","text":"0.077 ச.செ.மீ"},{"id":"D","text":"0.7 ச.செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 0.0077 ச.செ.மீ. விட்டம் d = 0.14 செ.மீ, எனவே ஆரம் r = 0.07 செ.மீ. பரப்பளவு = \\( \\frac{1}{2} \\times \\frac{22}{7} \\times 0.07 \\times 0.07 = 11 \\times 0.01 \\times 0.07 = 0.0077 \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q20","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஆரம் 28 செ.மீ. உடைய அரைவட்டத்தின் சுற்றளவு காண்க.","options":[{"id":"A","text":"128 செ.மீ"},{"id":"B","text":"66 செ.மீ"},{"id":"C","text":"144 செ.மீ"},{"id":"D","text":"56 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 144 செ.மீ. அரைவட்டத்தின் சுற்றளவு = \\( r(\\pi + 2) = 28 \\left(\\frac{22}{7} + 2\\right) = 28 \\left(\\frac{36}{7}\\right) = 4 \\times 36 = 144 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q21","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஓர் அரைவட்ட பாகைமானியின் விட்ட அளவு 7 செ.மீ. ஆகும். அதன் புற எல்லை என்ன?","options":[{"id":"A","text":"11 செ.மீ"},{"id":"B","text":"18 செ.மீ"},{"id":"C","text":"21 செ.மீ"},{"id":"D","text":"24 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 18 செ.மீ. புற எல்லை (சுற்றளவு) = \\( r(\\pi + 2) \\). ஆரம் r = 3.5 செ.மீ. சுற்றளவு = \\( 3.5 \\times \\frac{36}{7} = 18 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q22","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஆரம் 6 செ.மீ., வில்லின் நீளம் 20 செ.மீ. கொண்டுள்ள வட்டக்கோணப்பகுதியின் பரப்பளவைக் காண்க.","options":[{"id":"A","text":"90 ச.செ.மீ"},{"id":"B","text":"60 ச.செ.மீ"},{"id":"C","text":"80 ச.செ.மீ"},{"id":"D","text":"120 ச.செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 60 ச.செ.மீ. வட்டக்கோணப்பகுதியின் பரப்பளவு = \\( \\frac{lr}{2} = \\frac{20 \\times 6}{2} = 60 \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q23","subject":"SAT_MATHS","topic":"Unit 7","questionText":"வட்ட வில்லின் நீளம் 48 மீ, ஆரம் 10 மீ எனில், வட்டக் கோணப்பகுதியின் பரப்பளவு என்ன?","options":[{"id":"A","text":"480 ச.மீ"},{"id":"B","text":"450 ச.மீ"},{"id":"C","text":"240 ச.மீ"},{"id":"D","text":"225 ச.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 240 ச.மீ. பரப்பளவு = \\( \\frac{lr}{2} = \\frac{48 \\times 10}{2} = 240 \\) ச.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q24","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டக் கோணப்பகுதியின் வில்லின் நீளம் 15 செ.மீ. மற்றும் ஆரம் 10 செ.மீ. எனில் அதன் சுற்றளவைக் காண்க.","options":[{"id":"A","text":"15 செ.மீ"},{"id":"B","text":"35 செ.மீ"},{"id":"C","text":"25 செ.மீ"},{"id":"D","text":"30 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 35 செ.மீ. சுற்றளவு P = \\( l + 2r = 15 + 2(10) = 15 + 20 = 35 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q25","subject":"SAT_MATHS","topic":"Unit 7","questionText":"வட்டக்கோணப்பகுதியின் ஆரத்தின் இருமடங்கு 30 மீ, சுற்றளவு 44 மீ எனில், அதன் வில்லின் நீளம்","options":[{"id":"A","text":"44 மீ"},{"id":"B","text":"42 மீ"},{"id":"C","text":"16 மீ"},{"id":"D","text":"14 மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 14 மீ. ஆரத்தின் இருமடங்கு 2r = 30. சுற்றளவு = \\( l + 2r = 44 \\Rightarrow l + 30 = 44 \\Rightarrow l = 14 \\) மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q26","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டக்கோணப்பகுதியின் ஆரம் 21 செ.மீ. மற்றும் அதன் மையக்கோணம் 120° எனில், அதன் வில்லின் நீளம்","options":[{"id":"A","text":"44 செ.மீ"},{"id":"B","text":"42 செ.மீ"},{"id":"C","text":"100.48 செ.மீ"},{"id":"D","text":"41.54 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 44 செ.மீ. வில்லின் நீளம் \\( l = \\frac{120^{\\circ}}{360^{\\circ}} \\times 2 \\times \\frac{22}{7} \\times 21 = \\frac{1}{3} \\times 44 \\times 3 = 44 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q27","subject":"SAT_MATHS","topic":"Unit 7","questionText":"மையக்கோணம் 45°, ஆரம் 16 செ.மீ. எனில், வட்டக் கோணப்பகுதியின் பரப்பளவு (\\( \\pi=3.14 \\))","options":[{"id":"A","text":"13.19 ச.செ.மீ"},{"id":"B","text":"12.56 ச.செ.மீ"},{"id":"C","text":"100.48 ச.செ.மீ"},{"id":"D","text":"41.54 ச.செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 100.48 ச.செ.மீ. பரப்பளவு = \\( \\frac{45^{\\circ}}{360^{\\circ}} \\times 3.14 \\times 16^2 = \\frac{1}{8} \\times 3.14 \\times 256 = 3.14 \\times 32 = 100.48 \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q28","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஆரம் 14 செ.மீ., மையக்கோணம் 45°, வில்லின் நீளம் 11 செ.மீ. உள்ள வட்டக்கோணப் பகுதியின் பரப்பளவு என்ன?","options":[{"id":"A","text":"154 ச.செ.மீ"},{"id":"B","text":"308 ச.செ.மீ"},{"id":"C","text":"77 ச.செ.மீ"},{"id":"D","text":"38.5 ச.செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 77 ச.செ.மீ. பரப்பளவு = \\( \\frac{lr}{2} = \\frac{11 \\times 14}{2} = 77 \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q29","subject":"SAT_MATHS","topic":"Unit 7","questionText":"வட்ட மையத்தில் தாங்கும் கோணம் 90°, அதன் ஆரம் 7 செ.மீ. எனில், வட்ட வில்லின் நீளம்","options":[{"id":"A","text":"22 செ.மீ"},{"id":"B","text":"44 செ.மீ"},{"id":"C","text":"11 செ.மீ"},{"id":"D","text":"33 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 11 செ.மீ. வில்லின் நீளம் = \\( \\frac{90^{\\circ}}{360^{\\circ}} \\times 2 \\times \\frac{22}{7} \\times 7 = \\frac{1}{4} \\times 44 = 11 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q30","subject":"SAT_MATHS","topic":"Unit 7","questionText":"35 செ.மீ. ஆரமுள்ள வட்ட வடிவிலான ஜிம்னாஸ்டிக் வளையமானது 5 சம அளவுள்ள விற்களாகப் பிரிக்கப்பட்டு வெவ்வேறு நிறங்களில் வண்ணமிடப்பட்டுள்ளது எனில், ஒவ்வொரு வட்டவில்லின் நீளம் என்ன?","options":[{"id":"A","text":"44 செ.மீ"},{"id":"B","text":"24 செ.மீ"},{"id":"C","text":"70 செ.மீ"},{"id":"D","text":"35 செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 44 செ.மீ. முழு வட்டத்தின் சுற்றளவு = \\( 2 \\times \\frac{22}{7} \\times 35 = 220 \\) செ.மீ. 5 சம விற்களாகப் பிரிக்கப்பட்டுள்ளதால், ஒரு வில்லின் நீளம் = \\( \\frac{220}{5} = 44 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q31","subject":"SAT_MATHS","topic":"Unit 7","questionText":"70 செ.மீ. ஆரமுள்ள வட்டமானது 5 சம அளவுள்ள வட்டக் கோணப் பகுதிகளாகப் பிரிக்கப்படுகிறது. அவை ஒவ்வொன்றின் பரப்பளவு","options":[{"id":"A","text":"3080 ச.செ.மீ"},{"id":"B","text":"706 ச.செ.மீ"},{"id":"C","text":"1232 ச.செ.மீ"},{"id":"D","text":"445 ச.செ.மீ"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 3080 ச.செ.மீ. முழு வட்டத்தின் பரப்பளவு = \\( \\frac{22}{7} \\times 70 \\times 70 = 15400 \\) ச.செ.மீ. 5 சமப் பகுதிகளாகப் பிரிக்கப்படுவதால், ஒரு பகுதியின் பரப்பளவு = \\( \\frac{15400}{5} = 3080 \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q32","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் விட்டம் 12.6 செ.மீ., அதில் 120° மையக்கோணமுள்ள வட்ட கோணப்பகுதியின் சுற்றளவு என்ன? (\\( \\pi=3.14 \\))","options":[{"id":"A","text":"13.19 செ.மீ"},{"id":"B","text":"41.54 செ.மீ"},{"id":"C","text":"44.56 செ.மீ"},{"id":"D","text":"25.79 செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 25.79 செ.மீ. ஆரம் r = 6.3 செ.மீ. வில்லின் நீளம் l = \\( \\frac{120^{\\circ}}{360^{\\circ}} \\times 3.14 \\times 12.6 = 13.188 \\). சுற்றளவு = \\( l + 2r = 13.188 + 12.6 = 25.788 \\approx 25.79 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q33","subject":"SAT_MATHS","topic":"Unit 7","questionText":"35 செ.மீ. ஆரமுள்ள வட்டமானது 5 சம அளவுள்ள வட்டக் கோணப் பகுதிகளாகப் பிரிக்கப்படுகிறது எனில், அவற்றுள் ஒரு வட்டக் கோணப் பகுதியின் சுற்றளவு ஆனது","options":[{"id":"A","text":"105 செ.மீ"},{"id":"B","text":"104 செ.மீ"},{"id":"C","text":"114 செ.மீ"},{"id":"D","text":"115 செ.மீ"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 114 செ.மீ. ஒரு வில்லின் நீளம் = \\( \\frac{1}{5} \\times 2 \\times \\frac{22}{7} \\times 35 = 44 \\). சுற்றளவு = \\( l + 2r = 44 + 70 = 114 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q34","subject":"SAT_MATHS","topic":"Unit 7","questionText":"56 செ.மீ. ஆரமுள்ள வட்ட வடிவிலான ஜிம்னாஸ்டிக் வளையமானது 8 சம அளவுள்ள விற்களாகப் பிரிக்கப்பட்டு வெவ்வேறு நிறங்களில் வண்ணமிடப்பட்டுள்ளது எனில், ஒவ்வொரு வட்ட வில்லின் நீளம் என்ன?","options":[{"id":"A","text":"41 செ.மீ"},{"id":"B","text":"42 செ.மீ"},{"id":"C","text":"43 செ.மீ"},{"id":"D","text":"44 செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 44 செ.மீ. ஒரு வில்லின் நீளம் = \\( \\frac{1}{8} \\times 2 \\times \\frac{22}{7} \\times 56 = \\frac{1}{8} \\times 44 \\times 8 = 44 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q35","subject":"SAT_MATHS","topic":"Unit 7","questionText":"10 செ.மீ. ஆரமுள்ள ஒரு வட்டத்தில் அதன் மையத்தில் 90° கோணத்தை ஒரு வட்டவில் உருவாக்குகிறது எனில், மிகப்பெரிய வட்டக் கோணப்பகுதியின் பரப்பைக் காண்க.","options":[{"id":"A","text":"\\( \\frac{1650}{3} \\) ச.செ.மீ"},{"id":"B","text":"\\( \\frac{1650}{9} \\) ச.செ.மீ"},{"id":"C","text":"\\( \\frac{1650}{11} \\) ச.செ.மீ"},{"id":"D","text":"\\( \\frac{1650}{7} \\) ச.செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): \\( \\frac{1650}{7} \\) ச.செ.மீ. பெரிய வட்டக் கோணப்பகுதியின் மையக்கோணம் = 360° - 90° = 270°. பரப்பளவு = \\( \\frac{270^{\\circ}}{360^{\\circ}} \\times \\frac{22}{7} \\times 10^2 = \\frac{3}{4} \\times \\frac{22}{7} \\times 100 = \\frac{1650}{7} \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q36","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டக்கோணப்பகுதியின் பரப்பு 60 செ.மீ². அதன் வில்லின் நீளம் 20 செ.மீ. எனில், அவற்றின் ஆரம் காண்க.","options":[{"id":"A","text":"3 செ.மீ"},{"id":"B","text":"6 செ.மீ"},{"id":"C","text":"4 செ.மீ"},{"id":"D","text":"5 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 6 செ.மீ. பரப்பளவு = \\( \\frac{lr}{2} \\Rightarrow 60 = \\frac{20 \\times r}{2} \\Rightarrow 60 = 10r \\Rightarrow r = 6 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q37","subject":"SAT_MATHS","topic":"Unit 7","questionText":"இரண்டு வட்டங்களின் ஆரங்கள் 19 செ.மீ. மற்றும் 9 செ.மீ. ஆக உள்ளன. இவ்விரு வட்டங்களின் சுற்றளவுகளின் கூடுதலுக்குச் சமமான சுற்றளவுள்ள ஒரு வட்டத்தின் ஆரத்தைக் கண்டுபிடி.","options":[{"id":"A","text":"22 செ.மீ"},{"id":"B","text":"25 செ.மீ"},{"id":"C","text":"27 செ.மீ"},{"id":"D","text":"28 செ.மீ"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 28 செ.மீ. புதிய வட்டத்தின் சுற்றளவு = \\( 2\\pi R = 2\\pi r_1 + 2\\pi r_2 \\Rightarrow R = r_1 + r_2 = 19 + 9 = 28 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q38","subject":"SAT_MATHS","topic":"Unit 7","questionText":"42 செ.மீ. விட்டமுள்ள வட்டவடிவ தோசையை சகோதரர்கள் மூவர் சமமாகப் பகிர்ந்து கொள்கின்றனர். ஒவ்வொருவரும் பெறக்கூடிய தோசையின் பரப்பளவு என்ன?","options":[{"id":"A","text":"1848 ச.செ.மீ"},{"id":"B","text":"462 ச.செ.மீ"},{"id":"C","text":"588 ச.செ.மீ"},{"id":"D","text":"308 ச.செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 462 ச.செ.மீ. விட்டம் d = 42 செ.மீ, ஆரம் r = 21 செ.மீ. மொத்தப் பரப்பளவு = \\( \\frac{22}{7} \\times 21 \\times 21 = 1386 \\) ச.செ.மீ. மூவரும் சமமாகப் பிரித்தால், ஒவ்வொருவருக்கும் கிடைக்கும் பரப்பு = \\( \\frac{1386}{3} = 462 \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q39","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வெள்ளிக் கம்பி வளைக்கப்பட்டு சதுரமாக மாற்றும் போது அடைபடும் பகுதியின் பரப்பு 484 ச.மீ. அதே வெள்ளிக் கம்பி வட்டமாக வளைக்கப்படுகிறது எனில், அவ்வட்டத்தின் விட்டம் என்ன? (\\( \\pi=\\frac{22}{7} \\) என்க)","options":[{"id":"A","text":"14 மீ"},{"id":"B","text":"28 மீ"},{"id":"C","text":"24 மீ"},{"id":"D","text":"7 மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 28 மீ. சதுரத்தின் பரப்பு = 484 ச.மீ \\(\\Rightarrow\\) பக்கம் a = 22 மீ. கம்பியின் நீளம் (சுற்றளவு) = \\( 4 \\times 22 = 88 \\) மீ. வட்டத்தின் சுற்றளவு = \\( \\pi d = 88 \\Rightarrow \\frac{22}{7} d = 88 \\Rightarrow d = \\frac{88 \\times 7}{22} = 28 \\) மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q40","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வெள்ளிக் கம்பி வளைத்து ஒரு சதுரமாக மாற்றப்படுகிறது. அச்சதுரத்தின் பரப்பு 121 ச.செ.மீ. அதே கம்பியை வளைத்து ஒரு வட்டமாக மாற்றினால் அந்த வட்டத்தின் ஆரம் என்ன?","options":[{"id":"A","text":"11 செ.மீ"},{"id":"B","text":"7 செ.மீ"},{"id":"C","text":"3.5 செ.மீ"},{"id":"D","text":"14 செ.மீ"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 7 செ.மீ. சதுரத்தின் பரப்பு = 121 ச.செ.மீ \\(\\Rightarrow\\) பக்கம் a = 11 செ.மீ. சுற்றளவு = \\( 4 \\times 11 = 44 \\) செ.மீ. வட்டத்தின் சுற்றளவு = \\( 2 \\pi r = 44 \\Rightarrow 2 \\times \\frac{22}{7} \\times r = 44 \\Rightarrow r = 7 \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q41","subject":"SAT_MATHS","topic":"Unit 7","questionText":"எது தவறான கூற்று?","options":[{"id":"A","text":"வட்டக்கோணப்பகுதியின் மையக்கோணம் இருமடங்கானால் அதன் பரப்பளவு 4 மடங்காகும்."},{"id":"B","text":"வட்டத்தின் விட்டம் இருமடங்கானால் அதன் பரப்பளவு 4 மடங்காகும்."},{"id":"C","text":"சக்கரம் கண்டுபிடிப்புகளின் தொட்டில் எனப்படுகிறது."},{"id":"D","text":"வட்டக்கோணப்பகுதியின் ஆரம் மும்மடங்கானால் வட்டவில்லின் நீளம் மும்மடங்காகும்."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): வட்டக்கோணப்பகுதியின் மையக்கோணம் இருமடங்கானால் அதன் பரப்பளவு 4 மடங்காகும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q42","subject":"SAT_MATHS","topic":"Unit 7","questionText":"சீரான வேகத்தில் நடக்கும் ஒருவர் 150 மீ. ஆரமுள்ள வட்டப் பாதையை 9 நிமிடத்தில் சுற்றி வருகிறார் எனில், 3 நிமிடத்தில் அவர் கடக்கும் தொலைவைக் காண்க. (π = 3.14)","options":[{"id":"A","text":"210 மீ."},{"id":"B","text":"310 மீ."},{"id":"C","text":"314 மீ."},{"id":"D","text":"320 மீ."}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 314 மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q43","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஹரிகரன் என்பவர் 70 செ.மீ. ஆரமுள்ள வட்டவடிவ உணவு மேசையும், தருண் என்பவர் 140 செ.மீ. ஆரமுள்ள கால்வட்ட உணவு மேசையும் வைத்துள்ளனர் எனில், யாருடைய உணவு மேசை அதிக பரப்பளவைக் கொண்டுள்ளது?","options":[{"id":"A","text":"ஹரிகரன்"},{"id":"B","text":"தருண்"},{"id":"C","text":"சம அளவு"},{"id":"D","text":"இவற்றில் எதுவுமில்லை"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): சம அளவு","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q44","subject":"SAT_MATHS","topic":"Unit 7","questionText":"120 மீ. ஆரமுள்ள வட்டமானது 8 சம அளவுள்ள வட்டகோணப் பகுதிகளாகப் பிரிக்கப்படுகிறது. அவை ஒவ்வொன்றின் வில்லின் நீளத்தைக் காண்க.","options":[{"id":"A","text":"\\( 30\\pi \\) மீ."},{"id":"B","text":"\\( 5\\pi \\) மீ."},{"id":"C","text":"\\( 10\\pi \\) மீ."},{"id":"D","text":"\\( 20\\pi \\) மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): \\( 30\\pi \\) மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q45","subject":"SAT_MATHS","topic":"Unit 7","questionText":"7.5 செ.மீ. ஆரமுள்ள ஒரு ஸ்பின்னரானது ஆறு சம அளவுள்ள வட்டக்கோணப்பகுதிகளாகப் பிரிக்கப்பட்டுள்ளது எனில், ஒவ்வொரு வட்டக்கோணப்பகுதியின் பரப்பளவையும் காண்க.","options":[{"id":"A","text":"\\( 9.10\\pi \\) ச.செ.மீ."},{"id":"B","text":"\\( 9.375\\pi \\) ச.செ.மீ."},{"id":"C","text":"\\( 9.500\\pi \\) ச.செ.மீ."},{"id":"D","text":"\\( 9.750\\pi \\) ச.செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( 9.375\\pi \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q46","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்திலிருந்து வெட்டியெடுக்கப்பட்ட 120° உள்ள ஒரு வட்டக் கூறு, \\( 9\\frac{3}{7} \\) சதுர செ.மீ. பரப்பளவு உடையது. அவ்வட்டத்தின் ஆரத்தைக் காண்க.","options":[{"id":"A","text":"1 செ.மீ."},{"id":"B","text":"2 செ.மீ."},{"id":"C","text":"4 செ.மீ."},{"id":"D","text":"3 செ.மீ."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 3 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q47","subject":"SAT_MATHS","topic":"Unit 7","questionText":"2πr அலகுகள் சுற்றளவு உள்ள வட்டத்தின் பரப்பளவும் ஒரு சதுரத்தின் பரப்பளவும் சமம் எனில் சதுரத்தின் சுற்றளவு என்ன?","options":[{"id":"A","text":"\\( 2\\pi r \\) அலகுகள்"},{"id":"B","text":"\\( 4r\\sqrt{\\pi} \\) அலகுகள்"},{"id":"C","text":"\\( 4\\sqrt{\\pi} \\) அலகுகள்"},{"id":"D","text":"\\( 4\\sqrt{\\pi r} \\) அலகுகள்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( 4r\\sqrt{\\pi} \\) அலகுகள்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q48","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டக் கோணப்பகுதியின் ஆரம் மற்றும் பரப்பளவு முறையே 14 செ.மீ. மற்றும் 123.2 ச.செ.மீ. எனில், அதன் மையக்கோணத்தின் அளவு","options":[{"id":"A","text":"144°"},{"id":"B","text":"72°"},{"id":"C","text":"288°"},{"id":"D","text":"216°"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 72°","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q49","subject":"SAT_MATHS","topic":"Unit 7","questionText":"வட்டக் கோணப்பகுதியின் வில்லின் நீளம் 44 செ.மீ. மற்றும் அதன் சுற்றளவு 86 செ.மீ. எனில், வட்டக் கோணப்பகுதியின் மையக்கோணம் ____ டிகிரி ஆகும்.","options":[{"id":"A","text":"120"},{"id":"B","text":"130"},{"id":"C","text":"140"},{"id":"D","text":"150"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 120","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q50","subject":"SAT_MATHS","topic":"Unit 7","questionText":"40 செ.மீ. பக்க அளவுள்ள ஒரு சமபக்க முக்கோணத்தின் ஒரு முனையிலிருந்து 6 செ.மீ. பக்க அளவுள்ள ஒரு சமபக்க முக்கோணம் நீக்கப்படுகிறது எனில், மீதம் உள்ள பகுதியின் சுற்றளவு","options":[{"id":"A","text":"112 செ.மீ."},{"id":"B","text":"116 செ.மீ."},{"id":"C","text":"118 செ.மீ."},{"id":"D","text":"114 செ.மீ."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 114 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q51","subject":"SAT_MATHS","topic":"Unit 7","questionText":"இரண்டு இணைகரங்களை ஒன்றாக இணைத்து உருவாக்கப்பட்டக் கூட்டுவடிவத்தின் பரப்பளவு (படத்தில் கொடுக்கப்பட்டுள்ளது)","questionImage":"/assets/satmaths/image/unit7/image/unit7/q51.png","options":[{"id":"A","text":"24 ச.செ.மீ."},{"id":"B","text":"48 ச.செ.மீ."},{"id":"C","text":"30 ச.செ.மீ."},{"id":"D","text":"32 ச.செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 48 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q52","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழ்க்கண்ட முடிவுகளில் எந்த முடிவை மேற்கண்ட படங்களின் மூலம் எடுக்கலாம்?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q52.png","options":[{"id":"A","text":"மூன்று படங்களின் பரப்பளவு ஒன்றுக்கொன்று வேறுபாடாக உள்ளது."},{"id":"B","text":"மூன்று படங்களின் பரப்பளவுகள் சமமாக உள்ளது."},{"id":"C","text":"மூன்று படங்களின் சுற்றளவுகளும் சமமாக உள்ளது."},{"id":"D","text":"முதலாம் மற்றும் இரண்டாம் படங்களின் சுற்றளவு சமம்."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): மூன்று படங்களின் பரப்பளவுகள் சமமாக உள்ளது.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q53","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழ்க்கண்ட கூட்டு வடிவத்தின் பரப்பு (படத்தில் கொடுக்கப்பட்டுள்ளது)","questionImage":"/assets/satmaths/image/unit7/image/unit7/q53.png","options":[{"id":"A","text":"32 மீ²"},{"id":"B","text":"16 மீ²"},{"id":"C","text":"24 மீ²"},{"id":"D","text":"64 மீ²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 24 மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q54","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட படத்தில் உள்ள சதுரம் மற்றும் வட்டம் ஆகியவற்றின் சுற்றளவுகளின் வித்தியாசம் என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q54.png","options":[{"id":"A","text":"56 cm"},{"id":"B","text":"12 cm"},{"id":"C","text":"14 cm"},{"id":"D","text":"44 cm"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 12 cm","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q55","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட ABCD என்ற செவ்வகத்தில் ED = BF எனில், நிழலிடப்பட்ட பகுதியின் பரப்பளவு காண்க.","questionImage":"/assets/satmaths/image/unit7/image/unit7/q55.png","options":[{"id":"A","text":"1920 cm²"},{"id":"B","text":"480 cm²"},{"id":"C","text":"1440 cm²"},{"id":"D","text":"1240 cm²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 1440 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q56","subject":"SAT_MATHS","topic":"Unit 7","questionText":"''a'' அலகு பக்க அளவுள்ள ஒரு சதுரத்திலிருந்து மிகப்பெரிய வட்டத்தை வெட்டி எடுத்தால் மீதமுள்ள பகுதியின் பரப்பளவு","options":[{"id":"A","text":"\\( \\frac{11}{14}a^2 \\) ச.அ."},{"id":"B","text":"\\( \\frac{3}{14}a^2 \\) ச.அ."},{"id":"C","text":"\\( \\frac{14}{3}a^2 \\) ச.அ."},{"id":"D","text":"\\( \\pi a^2 \\) ச.அ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( \\frac{3}{14}a^2 \\) ச.அ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q57","subject":"SAT_MATHS","topic":"Unit 7","questionText":"''a'' அலகு பக்க அளவுள்ள ஒரு சதுரத்திலிருந்து வெட்டியெடுக்கப்படும் மிகப்பெரிய வட்டத்தின் பரப்பு என்ன?","options":[{"id":"A","text":"\\( \\frac{3}{14}a^2 \\) ச.அ."},{"id":"B","text":"\\( \\frac{14}{11}a^2 \\) ச.அ."},{"id":"C","text":"\\( \\frac{14}{3}a^2 \\) ச.அ."},{"id":"D","text":"\\( \\frac{11}{14}a^2 \\) ச.அ."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): \\( \\frac{11}{14}a^2 \\) ச.அ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q58","subject":"SAT_MATHS","topic":"Unit 7","questionText":"படத்தில் உள்ள நிழலிட்ட பகுதியின் பரப்பளவு","questionImage":"/assets/satmaths/image/unit7/image/unit7/q58.png","options":[{"id":"A","text":"94 செ.மீ²"},{"id":"B","text":"90 செ.மீ²"},{"id":"C","text":"88 செ.மீ²"},{"id":"D","text":"308 செ.மீ²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 88 செ.மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q59","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழே கொடுக்கப்பட்டுள்ள கூட்டு உருவத்தின் பரப்பு மற்றும் சுற்றளவு காண்க (அலகுகளில்).","questionImage":"/assets/satmaths/image/unit7/image/unit7/q59.png","options":[{"id":"A","text":"155, 46"},{"id":"B","text":"156, 45"},{"id":"C","text":"112, 46"},{"id":"D","text":"112, 44"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 112, 46","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q60","subject":"SAT_MATHS","topic":"Unit 7","questionText":"படத்தில் உள்ள வடிவத்தின் சுற்றளவு","questionImage":"/assets/satmaths/image/unit7/image/unit7/q60.png","options":[{"id":"A","text":"30 செ.மீ."},{"id":"B","text":"38 செ.மீ."},{"id":"C","text":"48 செ.மீ."},{"id":"D","text":"35 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 30 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q61","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட வடிவத்தின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q61.png","options":[{"id":"A","text":"40.25 ச.செ.மீ."},{"id":"B","text":"50.75 ச.செ.மீ."},{"id":"C","text":"27.93 ச.செ.மீ."},{"id":"D","text":"21.5 ச.செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 50.75 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q62","subject":"SAT_MATHS","topic":"Unit 7","questionText":"படத்தில் நிழலிடப்பட்டுள்ள பகுதியின் பரப்பளவு","questionImage":"/assets/satmaths/image/unit7/image/unit7/q62.png","options":[{"id":"A","text":"27.93 ச.செ.மீ."},{"id":"B","text":"40.25 ச.செ.மீ."},{"id":"C","text":"20.5 ச.செ.மீ."},{"id":"D","text":"21.5 ச.செ.மீ."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 21.5 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q63","subject":"SAT_MATHS","topic":"Unit 7","questionText":"நிழலிடப்படாத பகுதியின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q63.png","options":[{"id":"A","text":"175 ச.செ.மீ."},{"id":"B","text":"165 ச.செ.மீ."},{"id":"C","text":"145 ச.செ.மீ."},{"id":"D","text":"இவற்றில் எதுவுமில்லை"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): இவற்றில் எதுவுமில்லை","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q64","subject":"SAT_MATHS","topic":"Unit 7","questionText":"பக்கம் 4 செ.மீ., உள்ள சமபக்க முக்கோணத்தின் பரப்பளவைக் காண்க.","options":[{"id":"A","text":"\\( \\sqrt{3} \\) ச.செ.மீ."},{"id":"B","text":"\\( 2\\sqrt{3} \\) ச.செ.மீ."},{"id":"C","text":"\\( 3\\sqrt{3} \\) ச.செ.மீ."},{"id":"D","text":"\\( 4\\sqrt{3} \\) ச.செ.மீ."}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): \\( 4\\sqrt{3} \\) ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q65","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கூட்டு உருவத்தின் சுற்றளவு மற்றும் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q65.png","options":[{"id":"A","text":"28 செ.மீ., 33 ச.செ.மீ."},{"id":"B","text":"36 செ.மீ., 45 ச.செ.மீ."},{"id":"C","text":"60 செ.மீ., 96 ச.செ.மீ."},{"id":"D","text":"30 செ.மீ., 49 ச.செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 36 செ.மீ., 45 ச.செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q66","subject":"SAT_MATHS","topic":"Unit 7","questionText":"சமபக்க முக்கோணத்தின் உயரம் \\( 4\\sqrt{3} \\) செ.மீ. எனில், அதன் பக்க அளவு","options":[{"id":"A","text":"8 செ.மீ."},{"id":"B","text":"16 செ.மீ."},{"id":"C","text":"4 செ.மீ."},{"id":"D","text":"\\( 2\\sqrt{3} \\) செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 8 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q67","subject":"SAT_MATHS","topic":"Unit 7","questionText":"15 மீ. x 8 மீ. என்ற அளவுகள் கொண்ட செவ்வக வடிவ நிலத்தின் 4 மூலைகளிலும், அதன் நடுவிலும் 3 மீ. நீளமுள்ள கயிற்றால் பசுக்கள் கட்டப்பட்டுள்ளன எனில், எந்த பசுவாலும் புற்கள் மேயாத பகுதியின் பரப்பளவைக் காண்க.","options":[{"id":"A","text":"63 மீ²"},{"id":"B","text":"63.48 மீ²"},{"id":"C","text":"62.40 மீ²"},{"id":"D","text":"70 மீ²"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 63.48 மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q68","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட படமானது ஓர் அரைவட்டத்தின் மேல் ஒரு முக்கோணம் சரியாகப் பொருந்துமாறு அமைக்கப்பட்டுள்ளது. எனில் இக்கூட்டு வடிவத்தின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q68.png","options":[{"id":"A","text":"112 cm²"},{"id":"B","text":"224 cm²"},{"id":"C","text":"264 cm²"},{"id":"D","text":"342 cm²"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 224 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q69","subject":"SAT_MATHS","topic":"Unit 7","questionText":"படத்தில் நிழலிடப்படாத பகுதியின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q69.png","options":[{"id":"A","text":"120 cm²"},{"id":"B","text":"24 cm²"},{"id":"C","text":"72 cm²"},{"id":"D","text":"96 cm²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 72 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q70","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட படமானது ஓர் அரைவட்டமும் ஓர் இருசமபக்க முக்கோணமும் சேர்த்து உருவாக்கப் பட்டுள்ளது. எனில் இக்கூட்டு வடிவத்தின் சுற்றளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q70.png","options":[{"id":"A","text":"8+14π"},{"id":"B","text":"2(7+2π)"},{"id":"C","text":"176/7"},{"id":"D","text":"2(7+4π)"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 2(7+2π)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q71","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட நிழலிடப்பட்ட பகுதியின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q71.png","options":[{"id":"A","text":"38.5 cm²"},{"id":"B","text":"10.5 cm²"},{"id":"C","text":"49 cm²"},{"id":"D","text":"14π cm²"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 10.5 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q72","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் ஆரம் \\( 1\\frac{1}{2} \\) மடங்கு அதிகரித்தால் கிடைக்கும் புதிய வட்டத்தின் பரப்பளவு ____ மடங்கு அதிகரிக்கும்.","options":[{"id":"A","text":"\\( 2\\frac{1}{4} \\)"},{"id":"B","text":"3"},{"id":"C","text":"\\( \\frac{3}{2} \\)"},{"id":"D","text":"4"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): \\( 2\\frac{1}{4} \\)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q73","subject":"SAT_MATHS","topic":"Unit 7","questionText":"14 cm பக்க அளவுள்ள ஒரு சதுரத்தில் இருந்து வெட்டி எடுக்கப்படும் மிகப்பெரிய வட்டத்தின் பரப்பு","options":[{"id":"A","text":"154 cm²"},{"id":"B","text":"196 cm²"},{"id":"C","text":"164 cm²"},{"id":"D","text":"128 cm²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 154 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q74","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட கால்வட்டத்தில் நிழலிடப்பட்ட பகுதியின் பரப்பளவு?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q74.png","options":[{"id":"A","text":"24.5 cm²"},{"id":"B","text":"38.5 cm²"},{"id":"C","text":"28 cm²"},{"id":"D","text":"10.5 cm²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 24.5 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q75","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு காரின் கண்ணாடி சரிவக வடிவில் உள்ளது. அதன் துடைப்பானின் (wiper) நீளம் 70 cm ஆகும். எனில் துடைப்பானால் சுத்தம் செய்ய முடியாத பகுதியின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q75.png","options":[{"id":"A","text":"2100 cm²"},{"id":"B","text":"10800 cm²"},{"id":"C","text":"7700 cm²"},{"id":"D","text":"3100 cm²"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 3100 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q76","subject":"SAT_MATHS","topic":"Unit 7","questionText":"படத்தில் உள்ளவாறு ஒரு பள்ளியின் விளையாட்டு மைதானம் அமைந்துள்ளது. எனில் அதன் சுற்றளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q76.png","options":[{"id":"A","text":"460 m"},{"id":"B","text":"640 m"},{"id":"C","text":"220 m"},{"id":"D","text":"840 m"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 460 m","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q77","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட படத்தில் சதுரத்தின் பக்க அளவு 10 cm எனில், நிழல் இடப்பட்ட பகுதியின் பரப்பு?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q77.png","options":[{"id":"A","text":"42.86 cm²"},{"id":"B","text":"42.86 cm²"},{"id":"C","text":"57.14 cm²"},{"id":"D","text":"67.14 cm²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 57.14 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q78","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட படத்தில் சதுரத்தின் பக்க அளவு 7 cm எனில், நிழல் இடப்பட்ட பகுதியின் பரப்பு?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q78.png","options":[{"id":"A","text":"21 cm²"},{"id":"B","text":"28 cm²"},{"id":"C","text":"35 cm²"},{"id":"D","text":"14 cm²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 21 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q79","subject":"SAT_MATHS","topic":"Unit 7","questionText":"படத்தில் கொடுக்கப்பட்டுள்ள கூட்டு வடிவத்தின் சுற்றளவு 36 செ.மீ. எனில், அதன் பக்கம் ''a'' ஐக் காண்க.","questionImage":"/assets/satmaths/image/unit7/image/unit7/q79.png","options":[{"id":"A","text":"3.5 செ.மீ."},{"id":"B","text":"3 செ.மீ."},{"id":"C","text":"4 செ.மீ."},{"id":"D","text":"6 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 3.5 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q80","subject":"SAT_MATHS","topic":"Unit 7","questionText":"படத்தில் நிழலிடப்பட்ட பகுதியின் பரப்பளவு என்ன?","questionImage":"/assets/satmaths/image/unit7/image/unit7/q80.png","options":[{"id":"A","text":"24 cm²"},{"id":"B","text":"154 cm²"},{"id":"C","text":"54 cm²"},{"id":"D","text":"44 cm²"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 44 cm²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q81","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு கனச் செவ்வகத்தின் மூன்று பரிமாணங்கள்","options":[{"id":"A","text":"அடிப்பக்கம், உயரம், குத்துயரம்"},{"id":"B","text":"நீளம், உயரம், ஆரம்"},{"id":"C","text":"நீளம், அகலம், உயரம்"},{"id":"D","text":"அடிப்பக்கம், உயரம், விட்டம்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): நீளம், அகலம், உயரம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q82","subject":"SAT_MATHS","topic":"Unit 7","questionText":"இரண்டுக்கு மேற்பட்ட விளிம்புகள் சந்திக்கும் புள்ளி","options":[{"id":"A","text":"முகப்பு"},{"id":"B","text":"மேல்பக்கம்"},{"id":"C","text":"விளிம்பு"},{"id":"D","text":"உச்சி"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): உச்சி","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q83","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு கனச்சதுரத்திற்கு எத்தனை முகங்கள் உள்ளன?","options":[{"id":"A","text":"6"},{"id":"B","text":"12"},{"id":"C","text":"8"},{"id":"D","text":"10"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 6","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q84","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு திண்ம உருளையின் குறுக்குவெட்டுத்தோற்றம்","options":[{"id":"A","text":"முக்கோணம்"},{"id":"B","text":"சாய்சதுரம்"},{"id":"C","text":"வட்டம்"},{"id":"D","text":"கனசதுரம்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): வட்டம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q85","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு 3-D வடிவத்தின் வலையானது ஆறு சதுர வடிவத் தளங்களைப் பெற்றிருந்தால், அது _____ என்று அழைக்கப்படுகிறது.","options":[{"id":"A","text":"சதுரம்"},{"id":"B","text":"உருளை"},{"id":"C","text":"கனச்செவ்வகம்"},{"id":"D","text":"கனச்சதுரம்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): கனச்சதுரம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q86","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரே அளவுள்ள வட்ட வடிவத் தாள்களை ஒன்றன் மீது ஒன்றை அடுக்குவதால் உருவாகும் முப்பரிமாண உருவம்","options":[{"id":"A","text":"கோளம்"},{"id":"B","text":"கூம்பு"},{"id":"C","text":"அரைக்கோளம்"},{"id":"D","text":"உருளை"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): உருளை","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q87","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரே அளவுள்ள சதுர வடிவத் தாள்களை ஒன்றன் மீது ஒன்றை அடுக்குவதால் உருவாகும் முப்பரிமாண உருவம்","options":[{"id":"A","text":"கோளம்"},{"id":"B","text":"கூம்பு"},{"id":"C","text":"கனசதுரம்"},{"id":"D","text":"கனச்செவ்வகம்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): கனச்செவ்வகம் (அல்லது கனசதுரம், உயரத்தைப் பொறுத்து).","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q88","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழ்க்கண்டவற்றில் எது முப்பரிமாண வடிவம்?","options":[{"id":"A","text":"செவ்வகம்"},{"id":"B","text":"வட்டம்"},{"id":"C","text":"கனச்சதுரம்"},{"id":"D","text":"சதுரம்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): கனச்சதுரம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q89","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழ்க்கண்டவற்றில் எது முப்பரிமாண வடிவம்?","options":[{"id":"A","text":"ஐங்கோணம்"},{"id":"B","text":"அறுகோணம்"},{"id":"C","text":"முக்கோணப்பிரமீடு"},{"id":"D","text":"பலகோணம்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): முக்கோணப்பிரமீடு","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q90","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு கனச் சதுரமானது ____ ஐப் பெற்றிருக்கும்.","options":[{"id":"A","text":"6 முகங்கள் 8 விளிம்புகள் 10 உச்சிகள்"},{"id":"B","text":"6 முகங்கள் 8 விளிம்புகள் 12 உச்சிகள்"},{"id":"C","text":"6 முகங்கள் 12 விளிம்புகள் 10 உச்சிகள்"},{"id":"D","text":"6 முகங்கள் 12 விளிம்புகள் 8 உச்சிகள்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 6 முகங்கள் 12 விளிம்புகள் 8 உச்சிகள்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q91","subject":"SAT_MATHS","topic":"Unit 7","questionText":"பொருத்துக: (a) உருளை (b) கனச்செவ்வகம் (c) முக்கோணப் பட்டகம் (d) சதுரப் பிரமீடு","options":[{"id":"A","text":"a-ii, b-i, c-iv, d-iii"},{"id":"B","text":"a-b, b-d, c-a, d-c (தவறான வடிவம்)"},{"id":"C","text":"a-i, b-ii, c-iii, d-iv (சரியான பொருத்தம்)"},{"id":"D","text":"i-b, ii-a, iii-d, iv-c (ஆவணப் பொருத்தம்)"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (1): ஆவணத்தின்படி i-b, ii-a, iii-d, iv-c","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q92","subject":"SAT_MATHS","topic":"Unit 7","questionText":"பொருத்துக (F, V, E அடிப்படையில் வடிவங்கள்)","options":[{"id":"A","text":"III, I, IV, II"},{"id":"B","text":"I, III, IV, V"},{"id":"C","text":"V, I, II, IV"},{"id":"D","text":"III, IV, I, II"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): III, IV, I, II","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q93","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஆய்லர் சூத்திரம்","options":[{"id":"A","text":"F + V - E = 2"},{"id":"B","text":"F + E - V = 2"},{"id":"C","text":"F + V - 2 = E"},{"id":"D","text":"E + F - V = 2"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): F + V - E = 2","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q94","subject":"SAT_MATHS","topic":"Unit 7","questionText":"முக்கோணப் பட்டகத்தின் முகங்கள், உச்சிகள் மற்றும் விளிம்புகளின் எண்ணிக்கை","options":[{"id":"A","text":"7, 3, 8"},{"id":"B","text":"6, 5, 9"},{"id":"C","text":"5, 6, 9"},{"id":"D","text":"4, 3, 5"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 5, 6, 9","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q95","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு முப்பரிமாண உருவத்தில் 12 முகங்கள் 28 முனைகள் எனில், விளிம்புகளின் எண்ணிக்கை","options":[{"id":"A","text":"18"},{"id":"B","text":"38"},{"id":"C","text":"42"},{"id":"D","text":"16"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 38","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q96","subject":"SAT_MATHS","topic":"Unit 7","questionText":"பின்வரும் விவரங்களில் எது ஆய்லர் சூத்திரத்திற்குப் பொருந்தாது?","options":[{"id":"A","text":"F=6, V=8, E=12"},{"id":"B","text":"F=4, V=4, E=6"},{"id":"C","text":"F=10, V=6, E=12"},{"id":"D","text":"F=32, V=60, E=90"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): F=10, V=6, E=12","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q97","subject":"SAT_MATHS","topic":"Unit 7","questionText":"சரியான முகப்புத் தோற்றம், மேல்பக்கத் தோற்றம் மற்றும் பக்கவாட்டுத் தோற்றம் காண்க.","questionImage":"/assets/satmaths/image/unit7/image/unit8/q97.png","options":[{"id":"A","text":"விருப்பம் 1"},{"id":"B","text":"விருப்பம் 2"},{"id":"C","text":"விருப்பம் 3"},{"id":"D","text":"விருப்பம் 4"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q98","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஆயிலர் சூத்திரத்தைப் பயன்படுத்தி அட்டவணையில் உள்ள x, y மற்றும் z இன் மதிப்புகளைக் காண்க.","options":[{"id":"A","text":"16, 12, 30"},{"id":"B","text":"8, 6, 10"},{"id":"C","text":"8, 6, 30"},{"id":"D","text":"18, 14, 32"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 8, 6, 30","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q99","subject":"SAT_MATHS","topic":"Unit 7","questionText":"செவ்வகப் பிரமீட்டில் விளிம்புகளின் எண்ணிக்கை","options":[{"id":"A","text":"5"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"8"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 8","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q100","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கூம்பிற்கு எத்தனை உச்சிகள் உள்ளன?","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"0"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 1","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q101","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரே ஒரு சமதளப் பரப்பு கொண்ட உருவம் எது?","options":[{"id":"A","text":"கூம்பு"},{"id":"B","text":"கனசெவ்வகம்"},{"id":"C","text":"உருளை"},{"id":"D","text":"முக்கோணப் பட்டகம்"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): கூம்பு","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q102","subject":"SAT_MATHS","topic":"Unit 7","questionText":"சரியாக இரண்டு சமதளப் பரப்புகள் கொண்ட உருவம் எது?","options":[{"id":"A","text":"கூம்பு"},{"id":"B","text":"கனசதுரம்"},{"id":"C","text":"உருளை"},{"id":"D","text":"பிரமீடு"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): உருளை","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q103","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழ்க்கண்டவற்றில் எது அதிக உச்சிகளைக் கொண்டது?","options":[{"id":"A","text":"கூம்பு"},{"id":"B","text":"உருளை"},{"id":"C","text":"கனசெவ்வகம்"},{"id":"D","text":"பிரமீடு"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): கனசெவ்வகம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q104","subject":"SAT_MATHS","topic":"Unit 7","questionText":"படத்தில் உள்ள திண்ம உருவத்தைக் கொடுக்கப்பட்ட கோட்டைக் கொண்டு வெட்டினால் கிடைப்பது","questionImage":"/assets/satmaths/image/unit7/image/unit8/q104.png","options":[{"id":"A","text":"விருப்பம் 1"},{"id":"B","text":"விருப்பம் 2"},{"id":"C","text":"விருப்பம் 3"},{"id":"D","text":"விருப்பம் 4"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q105","subject":"SAT_MATHS","topic":"Unit 7","questionText":"பொருத்துக: a) கனசதுரம் b) உருளை c) கோளம் d) கூம்பு","options":[{"id":"A","text":"a-ii b-iii c-iv d-i"},{"id":"B","text":"a-iv b-i c-ii d-iii"},{"id":"C","text":"a-ii b-i c-iv d-iii"},{"id":"D","text":"a-ii b-i c-iii d-iv"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): a-ii b-i c-iii d-iv","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q106","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழ்க்கண்டவற்றுள் எது கனசதுரத்தின் இரு பரிமாண வலை அன்று?","questionImage":"/assets/satmaths/image/unit7/image/unit8/q106.png","options":[{"id":"A","text":"வடிவம் 1"},{"id":"B","text":"வடிவம் 2"},{"id":"C","text":"வடிவம் 3"},{"id":"D","text":"வடிவம் 4"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q107","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழ்க்கண்டவற்றுள் சரியான கூற்று எது?","options":[{"id":"A","text":"ஒரு கூம்பு இரண்டு உச்சிகளைக் கொண்டது."},{"id":"B","text":"ஒரு கனசதுரம் 8 உச்சிகளைக் கொண்டது."},{"id":"C","text":"உருளை ஒரே ஒரு முனையைக் கொண்டது."},{"id":"D","text":"ஒரு கனசெவ்வகம் 10 முகங்களைக் கொண்டது."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): ஒரு கனசதுரம் 8 உச்சிகளைக் கொண்டது.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q108","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட வடிவங்களை மேற்புறத் தோற்றமாகவும் (T) முகப்புத் தோற்றமாகவும் (F) கொண்ட உருவம் எது?","questionImage":"/assets/satmaths/image/unit7/image/unit8/q108.png","options":[{"id":"A","text":"உருளை"},{"id":"B","text":"கூம்பு"},{"id":"C","text":"பிரமீடு"},{"id":"D","text":"கனசெவ்வகம்"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): உருளை","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q109","subject":"SAT_MATHS","topic":"Unit 7","questionText":"மூன்று செவ்வகங்கள், இரண்டு முக்கோணங்கள் ஆகியவற்றை முகங்களாகக் கொண்ட முப்பரிமாண உருவம் எது?","options":[{"id":"A","text":"உருளை"},{"id":"B","text":"முக்கோணப் பட்டகம்"},{"id":"C","text":"பிரமீடு"},{"id":"D","text":"கனசெவ்வகம்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): முக்கோணப் பட்டகம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q110","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு முப்பரிமாண உருவத்திற்கு 25 முனைகள், 12 முகங்கள் எனில், விளிம்புகளின் எண்ணிக்கை என்ன?","options":[{"id":"A","text":"40"},{"id":"B","text":"15"},{"id":"C","text":"35"},{"id":"D","text":"10"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 35","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q111","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு முப்பரிமாண உருவம் 18 விளிம்புகள் கொண்டது. எனில், உச்சிகள் மற்றும் முகங்களின் கூடுதல் என்ன?","options":[{"id":"A","text":"30"},{"id":"B","text":"20"},{"id":"C","text":"16"},{"id":"D","text":"32"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 20","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q112","subject":"SAT_MATHS","topic":"Unit 7","questionText":"2cm x 2cm x 2cm பரிமாணமுடைய இரு கனசதுரங்களை இணைத்து உருவாக்கப்படும் கனசெவ்வகத்தின் பரிமாணம் என்ன?","options":[{"id":"A","text":"4cm x 4cm x 4cm"},{"id":"B","text":"8cm x 8cm x 8cm"},{"id":"C","text":"6cm x 4cm x 2cm"},{"id":"D","text":"4cm x 2cm x 2cm"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 4cm x 2cm x 2cm","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q113","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு முப்பரிமாண உருவத்தின் விளிம்புகளின் எண்ணிக்கையிலிருந்து முனைகளின் எண்ணிக்கையைக் கழித்தால் 7 கிடைக்கும் எனில், முகங்களின் எண்ணிக்கை என்ன?","options":[{"id":"A","text":"5"},{"id":"B","text":"9"},{"id":"C","text":"11"},{"id":"D","text":"13"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 9","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q114","subject":"SAT_MATHS","topic":"Unit 7","questionText":"2 cm பக்க அளவுள்ள கனசதுரத்தின் அனைத்து விளிம்புகளின் மொத்த நீளம்","options":[{"id":"A","text":"30 cm"},{"id":"B","text":"24 cm"},{"id":"C","text":"12 cm"},{"id":"D","text":"16 cm"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 24 cm","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q115","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட படத்தின் பரப்பளவைக் காண்க.","questionImage":"/assets/satmaths/image/unit7/image/unit8/q115.png","options":[{"id":"A","text":"\\( 24\\sqrt{3} \\) செ.மீ²"},{"id":"B","text":"\\( 48\\sqrt{3} \\) செ.மீ²"},{"id":"C","text":"\\( 72\\sqrt{3} \\) செ.மீ²"},{"id":"D","text":"36 செ.மீ²"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( 48\\sqrt{3} \\) செ.மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q116","subject":"SAT_MATHS","topic":"Unit 7","questionText":"21 செ.மீ. பக்க அளவுள்ள ஒரு சதுரத்தினுள் வரையக்கூடிய மிகப்பெரிய வட்டத்தின் பரப்பளவு காண்க.","options":[{"id":"A","text":"346.5 செ.மீ²"},{"id":"B","text":"345 செ.மீ²"},{"id":"C","text":"348 செ.மீ²"},{"id":"D","text":"348.5 செ.மீ²"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 346.5 செ.மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q117","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்ட வடிவ சுவர்க்கடிகாரத்தின் நிமிட முள்ளின் நீளம் 3.5 செ.மீ. எனில், அது ஒரு மணி நேரத்தில் சுற்றி வரும் இடத்தின் பரப்பு","options":[{"id":"A","text":"64.85 செ.மீ²"},{"id":"B","text":"38.50 செ.மீ²"},{"id":"C","text":"12.25 செ.மீ²"},{"id":"D","text":"21.05 செ.மீ²"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 38.50 செ.மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q118","subject":"SAT_MATHS","topic":"Unit 7","questionText":"\\( (\\frac{\\pi}{2}+2) \\) ஐ சுற்றளவாகக் கொண்ட கால் வட்டக்கோணப்பகுதியின் வட்டத்தின் ஆரம்","options":[{"id":"A","text":"1"},{"id":"B","text":"r"},{"id":"C","text":"2"},{"id":"D","text":"4"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 1","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q119","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு படமானது அரைவட்டப்பகுதி, ஒரு சதுரத்தின் மேல் அமைந்துள்ளது போல் உள்ளது. அரைவட்டத்தின் விட்டம் சதுரத்தின் பக்கத்துடன் சரியாக பொருந்துமாறு உள்ளது. அரைவட்டப்பகுதியின் ஆரம் ''r'' எனில் படத்தின் சுற்றளவு","questionImage":"/assets/satmaths/image/unit7/image/unit8/q119.png","options":[{"id":"A","text":"\\( \\pi r+6r \\)"},{"id":"B","text":"\\( \\pi r+8r \\)"},{"id":"C","text":"\\( \\pi r+4r \\)"},{"id":"D","text":"\\( \\pi r+3r \\)"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): \\( \\pi r+6r \\)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q120","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஓர் அரைவட்டத்தின் பரப்பளவு 84 செ.மீ² எனில், அவ்வட்டத்தின் பரப்பளவு","options":[{"id":"A","text":"144 செ.மீ²"},{"id":"B","text":"42 செ.மீ²"},{"id":"C","text":"168 செ.மீ²"},{"id":"D","text":"288 செ.மீ²"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): 168 செ.மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q121","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் விட்டம் 84 செ.மீ. எனில், அதன் கால்வட்டத்தின் சுற்றளவு","options":[{"id":"A","text":"150 செ.மீ."},{"id":"B","text":"120 செ.மீ."},{"id":"C","text":"21 செ.மீ."},{"id":"D","text":"200 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 150 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q122","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் காற்பகுதியில் அமையும் கோணம்","options":[{"id":"A","text":"90°"},{"id":"B","text":"180°"},{"id":"C","text":"270°"},{"id":"D","text":"360°"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 90°","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q123","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழ்க்காணும் படத்தின் பரப்பளவு","questionImage":"/assets/satmaths/image/unit7/image/unit7/q123.png","options":[{"id":"A","text":"273"},{"id":"B","text":"278"},{"id":"C","text":"812"},{"id":"D","text":"616"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 273","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q124","subject":"SAT_MATHS","topic":"Unit 7","questionText":"6 செ.மீ. அளவுள்ள மூலைவிட்டத்திலிருந்து சதுரத்தின் பரப்பளவு","options":[{"id":"A","text":"20 செ.மீ²"},{"id":"B","text":"36 செ.மீ²"},{"id":"C","text":"30 செ.மீ²"},{"id":"D","text":"18 செ.மீ²"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 18 செ.மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q125","subject":"SAT_MATHS","topic":"Unit 7","questionText":"எந்த ஒரு வட்டத்திலும் ஆரத்திற்குச் சமமான நாண் மையத்தில் _______ கோணத்தை உண்டாக்கும்.","options":[{"id":"A","text":"30°"},{"id":"B","text":"60°"},{"id":"C","text":"90°"},{"id":"D","text":"120°"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 60°","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q126","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஓர் அரைவட்டத்தின் மையக்கோணத்தின் அளவு","options":[{"id":"A","text":"90°"},{"id":"B","text":"360°"},{"id":"C","text":"270°"},{"id":"D","text":"180°"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): 180°","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q127","subject":"SAT_MATHS","topic":"Unit 7","questionText":"308 செ.மீ² பரப்பு கொண்ட ஒரு அரைவட்டத்தினை முழு வட்டமாக மாற்றினால், அதன் சுற்றளவு","options":[{"id":"A","text":"156 செ.மீ."},{"id":"B","text":"88 செ.மீ."},{"id":"C","text":"44 செ.மீ."},{"id":"D","text":"616 செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 88 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q128","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு இரு சமபக்க செங்கோண முக்கோணத்தின் கர்ணம் \\( 10\\sqrt{2} \\) செ.மீ. எனில், அதன் பரப்பு","options":[{"id":"A","text":"100 செ.மீ²"},{"id":"B","text":"50 செ.மீ²"},{"id":"C","text":"25 செ.மீ²"},{"id":"D","text":"200 செ.மீ²"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 50 செ.மீ²","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q129","subject":"SAT_MATHS","topic":"Unit 7","questionText":"A, B மற்றும் C ஆகியவை அரைவட்டங்களாக இருப்பின் மொத்த படத்தின் சுற்றளவு","questionImage":"/assets/satmaths/image/unit7/image/unit7/q129.png","options":[{"id":"A","text":"\\( 42\\pi \\)"},{"id":"B","text":"\\( 10.5\\pi \\)"},{"id":"C","text":"\\( 21\\pi \\)"},{"id":"D","text":"\\( 31.5\\pi \\)"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): \\( 21\\pi \\)","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q130","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கீழ்க்காணும் கூற்றுகளில் தவறான கூற்று எது?","options":[{"id":"A","text":"சமபக்க முக்கோணம் என்பது 3 பக்கங்கள் கொண்ட ஒழுங்குப் பல கோணமாகும்."},{"id":"B","text":"சதுரம் என்பது 4 பக்கங்கள் கொண்ட ஒழுங்குப் பல கோணமாகும்."},{"id":"C","text":"செவ்வகம் என்பது 4 பக்கங்கள் கொண்ட ஒழுங்குப் பல கோணமாகும்."},{"id":"D","text":"நாற்கரம் என்பது 4 பக்கங்கள் கொண்ட ஒழுங்கற்ற பல கோணமாகும்."}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): செவ்வகம் என்பது 4 பக்கங்கள் கொண்ட ஒழுங்குப் பல கோணமாகும்.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q131","subject":"SAT_MATHS","topic":"Unit 7","questionText":"நிழலிட்ட பகுதியின் பரப்பளவு","questionImage":"/assets/satmaths/image/unit7/image/unit7/q131.png","options":[{"id":"A","text":"100"},{"id":"B","text":"78.5"},{"id":"C","text":"21.5"},{"id":"D","text":"40"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): 78.5","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q132","subject":"SAT_MATHS","topic":"Unit 7","questionText":"அரைவட்டத்தின் சுற்றளவு","options":[{"id":"A","text":"\\( (\\pi+2)r \\) அலகுகள்"},{"id":"B","text":"\\( (\\pi+2) \\) அலகுகள்"},{"id":"C","text":"\\( 2(\\pi+2) \\) அலகுகள்"},{"id":"D","text":"இவற்றில் எதுவுமில்லை"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): \\( (\\pi+2)r \\) அலகுகள்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q133","subject":"SAT_MATHS","topic":"Unit 7","questionText":"10 செ.மீ. நீளமுள்ள சமபக்க முக்கோணத்தின் குத்துக்கோட்டின் நீளம்","options":[{"id":"A","text":"\\( \\sqrt{3} \\) செ.மீ."},{"id":"B","text":"\\( 5\\sqrt{3} \\) செ.மீ."},{"id":"C","text":"5 செ.மீ."},{"id":"D","text":"\\( \\sqrt{5} \\) செ.மீ."}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): \\( 5\\sqrt{3} \\) செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q134","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கால்வட்டம் என்பது வட்டத்தின் _____ ஒரு பங்கு ஆகும்.","options":[{"id":"A","text":"இரண்டில்"},{"id":"B","text":"நான்கில்"},{"id":"C","text":"மூன்றில்"},{"id":"D","text":"ஐந்தில்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): நான்கில்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q135","subject":"SAT_MATHS","topic":"Unit 7","questionText":"பலகோணத்தின் பக்கங்களும், கோணங்களும் சமமாக இருப்பின் அது ஓர்","options":[{"id":"A","text":"குவிந்த பலகோணம்"},{"id":"B","text":"குழிவுப் பலகோணம்"},{"id":"C","text":"ஒழுங்கற்ற பலகோணம்"},{"id":"D","text":"ஒழுங்குப் பலகோணம்"}],"correctOption":"D","explanation":"சரியான விடை விருப்பம் (4): ஒழுங்குப் பலகோணம்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q136","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கொடுக்கப்பட்ட படத்தின் சுற்றளவு","questionImage":"/assets/satmaths/image/unit7/image/unit7/q136.png","options":[{"id":"A","text":"32 செ.மீ."},{"id":"B","text":"20 செ.மீ."},{"id":"C","text":"36 செ.மீ."},{"id":"D","text":"30 செ.மீ."}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): 32 செ.மீ.","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q137","subject":"SAT_MATHS","topic":"Unit 7","questionText":"கால்வட்டத்தின் சுற்றளவு","options":[{"id":"A","text":"\\( (\\pi+2)r \\) அலகுகள்"},{"id":"B","text":"\\( (\\pi+2)d \\) அலகுகள்"},{"id":"C","text":"\\( (\\frac{\\pi}{2}+2)r \\) அலகுகள்"},{"id":"D","text":"\\( (\\frac{\\pi}{2}+2)a \\) அலகுகள்"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): \\( (\\frac{\\pi}{2}+2)r \\) அலகுகள்","marks":1,"negativeMarks":0},{"id":"unit-satmaths-7-q138","subject":"SAT_MATHS","topic":"Unit 7","questionText":"ஒரு வட்டத்தின் இரண்டு ஆரங்களாலும், அந்த ஆரங்களால் வட்ட பரிதியில் வெட்டப்படும் வில்லாலும் அடைபடும் சமதளப்பகுதி","options":[{"id":"A","text":"மையக்கோணம்"},{"id":"B","text":"வட்டக்கோணப்பகுதி"},{"id":"C","text":"வட்டத்துண்டு"},{"id":"D","text":"வட்டவில்"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): வட்டக்கோணப்பகுதி","marks":1,"negativeMarks":0}]', datetime('now'));
INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('SAT_MATHS_8', 'SAT_MATHS', 8, '[{"id":"unit-satmaths-8-q1","subject":"SAT_MATHS","topic":"Unit 8","questionText":"வெவ்வேறு எண் மதிப்புகளை ஏற்கக்கூடியது எது?","options":[{"id":"A","text":"மாறி"},{"id":"B","text":"கோவை"},{"id":"C","text":"ஒத்த உறுப்பு"},{"id":"D","text":"மாறிலி"}],"correctOption":"A","explanation":"சரியான விடை விருப்பம் (1): மாறி","marks":1,"negativeMarks":0},{"id":"unit-satmaths-8-q2","subject":"SAT_MATHS","topic":"Unit 8","questionText":"மாறி என்பதன் பொருள்","options":[{"id":"A","text":"சில மதிப்புகளை மட்டும் ஏற்கக் கூடியது"},{"id":"B","text":"நிலையான மதிப்பைக் கொண்டது"},{"id":"C","text":"வேறுபட்ட மதிப்புகளை ஏற்கக் கூடியது"},{"id":"D","text":"8 மதிப்புகளை மட்டும் ஏற்கக் கூடியது"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): வேறுபட்ட மதிப்புகளை ஏற்கக் கூடியது","marks":1,"negativeMarks":0},{"id":"unit-satmaths-8-q3","subject":"SAT_MATHS","topic":"Unit 8","questionText":"16x - 7 என்னும் கோவையின் மாறி","options":[{"id":"A","text":"16"},{"id":"B","text":"x"},{"id":"C","text":"16x"},{"id":"D","text":"-7"}],"correctOption":"B","explanation":"சரியான விடை விருப்பம் (2): x","marks":1,"negativeMarks":0},{"id":"unit-satmaths-8-q4","subject":"SAT_MATHS","topic":"Unit 8","questionText":"2y - 6 என்னும் கோவையின் மாறிலி உறுப்பு","options":[{"id":"A","text":"2y"},{"id":"B","text":"2"},{"id":"C","text":"-6"},{"id":"D","text":"6"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): -6","marks":1,"negativeMarks":0},{"id":"unit-satmaths-8-q5","subject":"SAT_MATHS","topic":"Unit 8","questionText":"-5pqr என்ற உறுப்பில் உள்ள மாறிகள்","options":[{"id":"A","text":"-5p மற்றும் -5qr"},{"id":"B","text":"-q, -p மற்றும் -r"},{"id":"C","text":"p, q, r"},{"id":"D","text":"இவற்றில் எதுவுமில்லை"}],"correctOption":"C","explanation":"சரியான விடை விருப்பம் (3): p, q, r","marks":1,"negativeMarks":0},{"id":"unit-satmaths-8-q6","subject":"SAT_MATHS","topic":"Unit 8","que