correctOption":"A","explanation":"a-ii b-v c-iv d-i e-iii","marks":1,"negativeMarks":0},{"id":"unit-satscience-16-q65","subject":"SAT_SCIENCE","topic":"Unit 16","questionText":"ஒப்புமை தருக. பருத்தி : இயற்கை : : _________ : செயற்கை","options":[{"id":"A","text":"பாலியெஸ்டர்"},{"id":"B","text":"பட்டு"},{"id":"C","text":"பருத்தி"},{"id":"D","text":"கம்பளி"}],"correctOption":"A","explanation":"ஒப்புமை தருக. பருத்தி : இயற்கை : : பாலியெஸ்டர் : செயற்கை","marks":1,"negativeMarks":0},{"id":"unit-satscience-16-q66","subject":"SAT_SCIENCE","topic":"Unit 16","questionText":"ஒப்புமை தருக. PLA கரண்டி : மட்கும் : நெகிழிக் கரண்டி : _________","options":[{"id":"A","text":"மட்கும்"},{"id":"B","text":"மட்காது"},{"id":"C","text":"உருகும்"},{"id":"D","text":"இறுகும்"}],"correctOption":"B","explanation":"ஒப்புமை தருக. PLA கரண்டி : மட்கும் : நெகிழிக் கரண்டி : மட்காது","marks":1,"negativeMarks":0},{"id":"unit-satscience-16-q67","subject":"SAT_SCIENCE","topic":"Unit 16","questionText":"மட்கிப் போகும் தன்மை உடைய பிளாஸ்டிக் பொருளின் வணிகப் பெயர் (NMMS 2018)","options":[{"id":"A","text":"பாலிஹைட்ராக்சி பியூட்டீரேட்"},{"id":"B","text":"ஆல்காலிஜன்ஸ்"},{"id":"C","text":"பாலிவினைல் குளோரைடு"},{"id":"D","text":"நெகிழி"}],"correctOption":"A","explanation":"பாலிஹைட்ராக்சி பியூட்டீரேட்","marks":1,"negativeMarks":0},{"id":"unit-satscience-16-q68","subject":"SAT_SCIENCE","topic":"Unit 16","questionText":"பொருத்துக (NMMS 2020 21)\n(a) இயற்கை பலபடிகள் i. செல்லுலோஸ்\n(b) செயற்கை பலபடிகள் ii. தோல்\n(c) புரத பலபடிகள் iii. மனித உடல்\n(d) கார்போஹைட்ரேட் பலபடிகள் iv. பிளாஸ்டிக்","options":[{"id":"A","text":"a-iii, b-iv, c-ii, d-i"},{"id":"B","text":"a-i, b-iii, c-ii, d-iv"},{"id":"C","text":"a-ii, b-ii, c-i, d-iv"},{"id":"D","text":"a-iv, b-ii, c-i, d-iii"}],"correctOption":"A","explanation":"a-iii, b-iv, c-ii, d-i","marks":1,"negativeMarks":0},{"id":"unit-satscience-16-q69","subject":"SAT_SCIENCE","topic":"Unit 16","questionText":"நெகிழி உண்ணும் பாக்டீரியா (NMMS 2020-21)","options":[{"id":"A","text":"அசட்டோபாக்டர்"},{"id":"B","text":"நைட்ரோசோமோனாஸ்"},{"id":"C","text":"ஐடெனல்லா சகீயன்சிஸ்"},{"id":"D","text":"சால்மோனெல்லா"}],"correctOption":"C","explanation":"ஐடெனல்லா சகீயன்சிஸ்","marks":1,"negativeMarks":0}]', datetime('now'));
INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('SAT_SCIENCE_17', 'SAT_SCIENCE', 17, '[{"id":"unit-satscience-17-q1","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ORS ன் விரிவாக்கம்","options":[{"id":"A","text":"Oral Rehydration Solution"},{"id":"B","text":"Oral Resolution Solution"},{"id":"C","text":"Oral Rehydration Solvent"},{"id":"D","text":"Oral Resolution Solvent"}],"correctOption":"A","explanation":"Oral Rehydration Solution","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q2","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ORS எந்த நோயாளிகளுக்கு உகந்தது?","options":[{"id":"A","text":"எய்ட்ஸ்"},{"id":"B","text":"புற்று நோய்"},{"id":"C","text":"காலரா"},{"id":"D","text":"இதய நோய்"}],"correctOption":"C","explanation":"காலரா","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q3","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ORS ல் அடங்கியுள்ளது","options":[{"id":"A","text":"உப்பு"},{"id":"B","text":"சர்க்கரை"},{"id":"C","text":"நீர்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"அனைத்தும்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q4","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ORS ல் உப்பு சேர்க்கக் காரணம்","options":[{"id":"A","text":"உப்புச் சுவைக்காக"},{"id":"B","text":"உப்பில் உள்ள CI⁻ அயனி உடலில் சேர்வதற்காக"},{"id":"C","text":"உப்பில் உள்ள Na⁺ அயனி உடலில் சேர்வதற்காக"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"C","explanation":"உப்பில் உள்ள Na⁺ அயனி உடலில் சேர்வதற்காக","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q5","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ORS ல் குளுக்கோஸ் சேர்க்கக் காரணம்","options":[{"id":"A","text":"உடல் உப்பு மற்றும் நீரை உறிஞ்ச"},{"id":"B","text":"உடல் குளுகோஸை உறிஞ்ச"},{"id":"C","text":"குளுக்கோஸில் உள்ள C அணு உடலில் சேர்வதற்காக"},{"id":"D","text":"குளுக்கோஸில் உள்ள H அணு உடலில் சேர்வதற்காக"}],"correctOption":"A","explanation":"உடல் உப்பு மற்றும் நீரை உறிஞ்ச","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q6","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"காலரா நோயாளிகளுக்கு ORS பயன்படுத்தக் காரணம் எது?","options":[{"id":"A","text":"உடலில் நீரிழப்பை அதிகரிக்கச் செய்ய"},{"id":"B","text":"உடலில் நீரிழப்பைக் குறைக்க"},{"id":"C","text":"உடலின் நீர்ச்சமநிலையைப் பாதுகாக்க"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"C","explanation":"காலரா நோயாளிகளுக்கு ORS பயன்படுத்தக் காரணம் உடலின் நீர்ச்சமநிலையைப் பாதுகாக்க ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q7","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"நமது வயிற்றில் சுரக்கும் அமிலம்","options":[{"id":"A","text":"NaCl"},{"id":"B","text":"HCl"},{"id":"C","text":"H2SO4"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"B","explanation":"HCl","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q8","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"நமது இரைப்பையில் ஏற்படும் அதிகப்படியான அமிலத்தன்மையைக் கட்டுப்படுத்த காரங்களைச் சேர்க்கிறோம். இது நமக்கு எந்த வேதிவினையை நினைவூட்டுகிறது?","options":[{"id":"A","text":"ஆக்ஸிஜனேற்ற வினை"},{"id":"B","text":"ஆக்ஸிஜனொடுக்க வினை"},{"id":"C","text":"ஹைட்ரஜனேற்ற வினை"},{"id":"D","text":"நடுநிலையாக்கல் வினை"}],"correctOption":"D","explanation":"நடுநிலையாக்கல் வினை","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q9","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"Mg(OH)2 காரத்தை அமில நீக்கியாக பயன்படுத்துகிறோம். ஆனால் NaOH, KOH போன்ற காரங்களை அமிலநீக்கியாக நாம் பயன்படுத்தாதற்கான காரணம்","options":[{"id":"A","text":"Mg(OH)2 வலுமிகுந்த காரம், NaOH, KOH வலுகுறைந்த காரம்"},{"id":"B","text":"Mg(OH)2 வலுகுறைந்த காரம், NaOH, KOH வலுமிகுந்த காரம்"},{"id":"C","text":"Mg(OH)2 விலை அதிகம்"},{"id":"D","text":"இவை எதுவும் இல்லை"}],"correctOption":"B","explanation":"Mg(OH)2 வலுகுறைந்த காரம், NaOH, KOH வலுமிகுந்த காரம்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q10","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பின்வருவனவற்றுள் அமிலநீக்கி (Antacid) எது?","options":[{"id":"A","text":"NaHCO₃"},{"id":"B","text":"CaCO₃"},{"id":"C","text":"Mg(OH)₂"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"பின்வருவனவற்றுள் அமிலநீக்கி (Antacid) அனைத்தும் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q11","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பின்வருவனவற்றுள் எது அமிலநீக்கி அல்ல?","options":[{"id":"A","text":"NaHCO₃"},{"id":"B","text":"Al(OH)₃"},{"id":"C","text":"MgCO₃"},{"id":"D","text":"HCl"}],"correctOption":"D","explanation":"HCl","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q12","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"சில நூற்றாண்டுகட்கு முன்பு சிறு காயங்கள் கூட மரணத்தை ஏற்படுத்தக் காரணம்","options":[{"id":"A","text":"நோய் உண்டாக்கும் கிருமிகள் அதிகமிருந்தது"},{"id":"B","text":"நுண்ணுயிர்க்கொல்லிகள் கண்டறியப்படாமல் இருந்தது"},{"id":"C","text":"நோய் உண்டாக்கும் கிருமிகள் வலுமிக்கதாக இருந்தது"},{"id":"D","text":"மக்களின் அறியாமை"}],"correctOption":"B","explanation":"நுண்ணுயிர்க்கொல்லிகள் கண்டறியப்படாமல் இருந்தது","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q13","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஆண்டிபயோடிக் எனப்படும் நுண்ணுயிர்க்கொல்லிகளைக் கண்டறிந்தவர்","options":[{"id":"A","text":"திலீப்"},{"id":"B","text":"ராபர்ட் ஹூக்"},{"id":"C","text":"அலெக்ஸாண்டர் ஃபிளமிங்"},{"id":"D","text":"ராபர்ட் பிரௌன்"}],"correctOption":"C","explanation":"அலெக்ஸாண்டர் ஃபிளமிங்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q14","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"கூற்று 1: அலெக்ஸாண்டர் ஃபிளமிங் நிமோனியா, தொண்டைவலிக்குக் காரணமான ஸ்டெஃபிளோகாகஸ் பாக்டீரியாவை ஆராய்ந்து வந்தார். \nகூற்று 2: பாக்டீரியாவின் வளர்ச்சியை பூஞ்சைகள் கட்டுப்படுத்தியிருந்தது. \nகூற்று 3: பெனிசிலியம் நோடேட்டம் எனும் பூஞ்சையே பாக்டீரியங்களின் வளர்ச்சியைக் கட்டுப்படுத்தியது.","options":[{"id":"A","text":"அனைத்து கூற்றுகளும் சரி"},{"id":"B","text":"கூற்று 3 மட்டும் தவறு"},{"id":"C","text":"கூற்று 1 மட்டும் சரி"},{"id":"D","text":"கூற்று 1, 3 சரி"}],"correctOption":"A","explanation":"அனைத்து கூற்றுகளும் சரி","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q15","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பெனிசிலியம் நோடேட்டம் எனும் பூஞ்சையிலிருந்து பிரித்தெடுக்கப்பட்ட நுண்ணுயிர் எதிர்ப்பொருள் எது?","options":[{"id":"A","text":"ஆண்டிபயோடிக்"},{"id":"B","text":"பெனிசிலியம்"},{"id":"C","text":"பெனிசிலின்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"C","explanation":"பெனிசிலியம் நோடேட்டம் எனும் பூஞ்சையிலிருந்து பிரித்தெடுக்கப்பட்ட நுண்ணுயிர் எதிர்ப்பொருள் பெனிசிலின் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q16","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":" உலகின் முதல் நுண்ணுயிர் எதிர்ப்பொருள் எது?","options":[{"id":"A","text":"பெனிசிலியம் நோடேட்டம்"},{"id":"B","text":"பெனிசிலியம்"},{"id":"C","text":"பெனிசிலின்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"C","explanation":" உலகின் முதல் நுண்ணுயிர் எதிர்ப்பொருள் பெனிசிலின் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q17","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"செயற்கை முறையில் தயாரிக்கப்பட்ட நுண்ணுயிர் எதிர்ப்பொருள் எது?","options":[{"id":"A","text":"டெட்ரா சைக்ளின்"},{"id":"B","text":"அமினோ கிளைகோசைடு"},{"id":"C","text":"குளோரோ ஃபினிக்கால்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"செயற்கை முறையில் தயாரிக்கப்பட்ட நுண்ணுயிர் எதிர்ப்பொருள் அனைத்தும் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q18","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"கூற்று: அதிகளவு நுண்ணுயிர் எதிர்ப்பிகளை பயன்படுத்தக் கூடாது. \nகாரணம்: தொடர்ந்து பயன்படுத்தினால் எதிர்ப்பியின் செயல்திறன் குறையும்.","options":[{"id":"A","text":"கூற்று சரி. ஆனால் காரணம் தவறு"},{"id":"B","text":"கூற்று சரி. காரணம் கூற்றை விளக்குகிறது"},{"id":"C","text":"கூற்று தவறு. காரணம் சரி"},{"id":"D","text":"கூற்று சரி. காரணம் கூற்றை விளக்கவில்லை"}],"correctOption":"B","explanation":"கூற்று சரி. காரணம் கூற்றை விளக்குகிறது","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q19","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"தொடக்கத்தில் கொசுவிரட்டி என விளம்பரங்களில் வந்த நிலையில், தற்போது கொசுவைக் கொல்லும் என விளம்பரப்படுத்தப்படுவது ஏன்?","options":[{"id":"A","text":"கொசுவிரட்டிகளின் வீரியம் அதிகரிக்கப்பட்டுள்ளது"},{"id":"B","text":"கொசுவிரட்டிகளின் வீரியம் குறைக்கப்பட்டுள்ளது"},{"id":"C","text":"கொசுக்களை அழிப்பதற்காக"},{"id":"D","text":"விளம்பர நோக்கத்திற்காக"}],"correctOption":"A","explanation":"கொசுவிரட்டிகளின் வீரியம் அதிகரிக்கப்பட்டுள்ளது","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q20","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஆண்டிபயோடிக்குகளால் கட்டுப்படுத்தமுடியாதவை எவை?","options":[{"id":"A","text":"பாக்டீரியா"},{"id":"B","text":"வைரஸ்"},{"id":"C","text":"இரண்டும் சரி"},{"id":"D","text":"இரண்டும் தவறு"}],"correctOption":"B","explanation":"ஆண்டிபயோடிக்குகளால் கட்டுப்படுத்தமுடியாதவை வைரஸ் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q21","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"வலி என்ற மனவெழுச்சி ஏற்படும் இடம் எது?","options":[{"id":"A","text":"அடிபட்ட இடம்"},{"id":"B","text":"நரம்பு மண்டலம்"},{"id":"C","text":"மூளை"},{"id":"D","text":"இதயம்"}],"correctOption":"C","explanation":"வலி என்ற மனவெழுச்சி ஏற்படும் இடம் மூளை ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q22","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"வலி நிவாரணிகள் (Analgesics) என்பது","options":[{"id":"A","text":"வலியைக் குறைக்கிறது"},{"id":"B","text":"வலியைக் அதிகரிக்கிறது"},{"id":"C","text":"வலி தொடர்பான செய்திகள் மூளைக்கு செல்லாமல் கட்டுப்படுத்துகிறது"},{"id":"D","text":"1 மற்றும் 3"}],"correctOption":"C","explanation":"வலி தொடர்பான செய்திகள் மூளைக்கு செல்லாமல் கட்டுப்படுத்துகிறது","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q23","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"இயற்கை வலி நிவாரணி","options":[{"id":"A","text":"புதினா"},{"id":"B","text":"கேட்னிப்"},{"id":"C","text":"ஆஸ்பிரின்"},{"id":"D","text":"1 மற்றும் 2"}],"correctOption":"D","explanation":"1 மற்றும் 2","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q24","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"1860 ல் ஆல்பர்ட் நீமான் என்பவரால் கோகோ இலையிலிருந்து பெறப்பட்ட மயக்கமூட்டி","options":[{"id":"A","text":"புதினா"},{"id":"B","text":"கோகைன்"},{"id":"C","text":"ஆஸ்பிரின்"},{"id":"D","text":"பாராசிட்டமால்"}],"correctOption":"B","explanation":"கோகைன்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q25","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"உடல் வெப்பத் தனிப்பிகள் (Antipyretic) _____ என்ற வேதிப்பொருளின் அளவை _____ செய்து உடல் வெப்பத்தைக் கட்டுப்படுத்துகிறது.","options":[{"id":"A","text":"பைரோஜன், குறைக்க"},{"id":"B","text":"பைரோஜன், அதிகரிக்க"},{"id":"C","text":"புரோஸ்டாகிளான்டின், குறைக்க"},{"id":"D","text":"புரோஸ்டாகிளான்டின், அதிகரிக்க"}],"correctOption":"C","explanation":"உடல் வெப்பத் தனிப்பிகள் (Antipyretic) புரோஸ்டாகிளான்டின், குறைக்க என்ற வேதிப்பொருளின் அளவை புரோஸ்டாகிளான்டின், குறைக்க செய்து உடல் வெப்பத்தைக் கட்டுப்படுத்துகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q26","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"தொற்றுநோய் ஏற்படுத்தும் கிருமிகளை அழிப்பவைகளை _____ என அழைக்கிறோம்.","options":[{"id":"A","text":"உடல் வெப்பத்தனிப்பி"},{"id":"B","text":"கிருமிநீக்கி"},{"id":"C","text":"கிருமி நாசினி"},{"id":"D","text":"வலிநீக்கி"}],"correctOption":"C","explanation":"தொற்றுநோய் ஏற்படுத்தும் கிருமிகளை அழிப்பவைகளை கிருமி நாசினி என அழைக்கிறோம்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q27","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பின்வருவனவற்றுள் கிருமி நாசினி எது?","options":[{"id":"A","text":"குளியல் சோப்பு"},{"id":"B","text":"அயடோஃபார்ம், எத்தனால்"},{"id":"C","text":"ஃபீனலிக் சேர்மங்கள், போரிக் அமிலம்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"பின்வருவனவற்றுள் கிருமி நாசினி அனைத்தும் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q28","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பின்வருவனவற்றுள் இயற்கை கிருமி நாசினி எது?","options":[{"id":"A","text":"பூண்டு, மஞ்சள்"},{"id":"B","text":"கற்றாழை"},{"id":"C","text":"வெங்காயம், முள்ளங்கி"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"பின்வருவனவற்றுள் இயற்கை கிருமி நாசினி அனைத்தும் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q29","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"கிருமி நாசினிகளை எவ்வாறு பயன்படுத்த வேண்டும்?","options":[{"id":"A","text":"உடலின் மேற்பூச்சாக மட்டும்"},{"id":"B","text":"உடலின் உட்பகுதியில் மட்டும்"},{"id":"C","text":"உடலுக்கு உள்ளே மற்றும் வெளியே"},{"id":"D","text":"மாத்திரை வடிவில்"}],"correctOption":"A","explanation":"உடலின் மேற்பூச்சாக மட்டும்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q30","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஒவ்வாமை என்பது","options":[{"id":"A","text":"வலி"},{"id":"B","text":"ஓர் உணர்வு"},{"id":"C","text":"உடலின் எதிர்வினை"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"C","explanation":"உடலின் எதிர்வினை","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q31","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஒவ்வாமையை தோற்றுவிப்பவை","options":[{"id":"A","text":"மகரந்தத் துகள்கள்"},{"id":"B","text":"தூசு, புகை"},{"id":"C","text":"வாசனைப் பொருள்கள்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"அனைத்தும்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q32","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஒவ்வாமை நீக்கமருந்து (Antihistamine) எது?","options":[{"id":"A","text":"டிஃபென் ஹைட்ரமைன்"},{"id":"B","text":"குளோர் பெனிரமைன்"},{"id":"C","text":"சிமெடிடின்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"ஒவ்வாமை நீக்கமருந்து (Antihistamine) அனைத்தும் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q33","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பொருத்துக: a) அமிலநீக்கி b) நுண்ணுயிர்க்கொல்லி c) வலி நிவாரணி d) உடல் வெப்பத் தணிப்பி \n i) பெனிசிலின் ii) ஆஸ்பிரின் iii) Mg(OH)2 iv) கோடீன்","options":[{"id":"A","text":"a-ii, b-i, c-iv, d-iii"},{"id":"B","text":"a-iii, b-i, c-iv, d-ii"},{"id":"C","text":"a-iv, b-i, c-ii, d-iii"},{"id":"D","text":"a-i, b-iii, c-iv, d-ii"}],"correctOption":"B","explanation":"a-iii, b-i, c-iv, d-ii","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q34","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"எரிதல் என்பது","options":[{"id":"A","text":"இயற்பியல் மாற்றம்"},{"id":"B","text":"மீள் மாற்றம்"},{"id":"C","text":"வேதிவினை"},{"id":"D","text":"பேரிடர்"}],"correctOption":"C","explanation":"வேதிவினை","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q35","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"எரிவெப்பநிலை என்பது","options":[{"id":"A","text":"ஒரு பொருள் தீப்பற்றத் தேவையான குறைந்தபட்ச வெப்பநிலை"},{"id":"B","text":"ஒரு பொருள் தீப்பற்றத் தேவையான அதிகபட்ச வெப்பநிலை"},{"id":"C","text":"இரண்டும் சரி"},{"id":"D","text":"இரண்டும் தவறு"}],"correctOption":"A","explanation":"ஒரு பொருள் தீப்பற்றத் தேவையான குறைந்தபட்ச வெப்பநிலை","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q36","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஹைட்ரோ கார்பன்கள் ஆக்ஸிஜன் துணையுடன் எரிந்து எதை வெளிப்படுத்துகிறது?","options":[{"id":"A","text":"கார்பன் டை ஆக்ஸைடு"},{"id":"B","text":"நீர்"},{"id":"C","text":"வெப்ப ஆற்றல்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"அனைத்தும்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q37","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஹைட்ரோ கார்பன்கள் ஆக்ஸிஜன் துணையுடன் எரிதல் வினை, உயிரினங்களின் எச்செயல்பாட்டுடன் ஒத்துப் போகிறது?","options":[{"id":"A","text":"கழிவு நீக்கம்"},{"id":"B","text":"செரிமானம்"},{"id":"C","text":"இரத்த சுழற்சி"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"B","explanation":"செரிமானம்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q38","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பின்வருவனவற்றுள் எந்த இணை எரியும்?","options":[{"id":"A","text":"CH₄, CO₂"},{"id":"B","text":"CH₄, O₂"},{"id":"C","text":"CO₂, O₂"},{"id":"D","text":"LPG, CO₂"}],"correctOption":"B","explanation":"CH₄, O₂","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q39","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஒரு பொருள் உடனடியாக தீப்பற்றுகிறது எனில்","options":[{"id":"A","text":"எரியும் தன்மை இருப்பதால்"},{"id":"B","text":"ஆக்ஸிஜன் மிகுதியாக கிடைத்திருப்பதால்"},{"id":"C","text":"எரிவெப்பநிலை குறைவாக இருப்பதால்"},{"id":"D","text":"எரிதலைக் கட்டுப்படுத்தும் கார்பன் டை ஆக்ஸைடு இல்லாதிருப்பதால்"}],"correctOption":"C","explanation":"எரிவெப்பநிலை குறைவாக இருப்பதால்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q40","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"மண்ணெண்ணெய் தீப்பற்ற நேரம் பிடிக்க, பெட்ரோல் உடனடியாகத் தீப்பற்றுகிறதே ஏன்?","options":[{"id":"A","text":"மண்ணெண்ணெயின் எரிவெப்பநிலை, பெட்ரோலை விட குறைவு"},{"id":"B","text":"மண்ணெண்ணெயின் எரிவெப்பநிலை, பெட்ரோலை விட அதிகம்"},{"id":"C","text":"மண்ணெண்ணெயின் எரியும் தன்மை, பெட்ரோலை விட குறைவு"},{"id":"D","text":"மண்ணெண்ணெயின் எரியும் தன்மை, பெட்ரோலை விட அதிகம்"}],"correctOption":"B","explanation":"மண்ணெண்ணெயின் எரிவெப்பநிலை, பெட்ரோலை விட அதிகம்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q41","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"சூரியக் கதிர்களின் முன்னிலையில் குவிவில்லையின் கீழ் வைக்கப்பட்ட காகிதம் தீப்பற்றுகிறதே ஏன்?","options":[{"id":"A","text":"சூரியனின் வெப்ப ஆற்றலால் எரிகிறது"},{"id":"B","text":"ஆக்ஸிஜன் நன்கு கிடைப்பதால் எரிகிறது"},{"id":"C","text":"சூரியனின் வெப்ப ஆற்றலால் காகிதம் தனது எரிவெப்பநிலையை அடைந்து எரிகிறது"},{"id":"D","text":"காகிதம் எரியும் தன்மையுடையதால் எரிகிறது"}],"correctOption":"C","explanation":"சூரியனின் வெப்ப ஆற்றலால் காகிதம் தனது எரிவெப்பநிலையை அடைந்து எரிகிறது","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q42","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பொருத்துக: a) வெண்மை சுடர் b) அடர் சிவப்பு சுடர் c) ஊதா சுடர் d) மஞ்சள் சுடர் \n i) லித்தியம் உப்பு ii) எப்சம் உப்பு iii) NaCl iv) KCl","options":[{"id":"A","text":"a-ii, b-i, c-iv, d-iii"},{"id":"B","text":"a-iii, b-i, c-iv, d-ii"},{"id":"C","text":"a-iv, b-i, c-ii, d-iii"},{"id":"D","text":"a-i, b-ii, c-iv, d-ii"}],"correctOption":"A","explanation":"a-ii, b-i, c-iv, d-iii","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q43","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பொருத்துக: a) செங்கல் சிவப்பு சுடர் b) ஆரஞ்சு சுடர் c) பச்சை சுடர் d) சிவப்பு சுடர் \n i) CaCl2 ii) போராக்ஸ் பவுடர் iii) SrCl2 iv) பிளீச்சிங் பவுடர்","options":[{"id":"A","text":"a-ii, b-i, c-iv, d-iii"},{"id":"B","text":"a-iii, b-i, c-iv, d-ii"},{"id":"C","text":"a-iv, b-i, c-ii, d-iii"},{"id":"D","text":"a-i, b-iii, c-iv, d-ii"}],"correctOption":"C","explanation":"a-iv, b-i, c-ii, d-iii","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q44","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பின்வருவனவற்றுள் தவறான கூற்று எது?","options":[{"id":"A","text":"சுடர் என்பது எரியக்கூடிய பொருளின் எரிதல் மண்டலமாகும்"},{"id":"B","text":"எரியும் பொழுது ஆவியாகும் பொருள்கள் சுடரை உருவாக்குகிறது"},{"id":"C","text":"எரியும் பொழுது ஆவியாகாத பொருள்கள் சுடரை உருவாக்குவதில்லை"},{"id":"D","text":"சுடர் எப்பொழுதும் கீழ்நோக்கியே இருக்கும்"}],"correctOption":"D","explanation":"சுடர் எப்பொழுதும் கீழ்நோக்கியே இருக்கும்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q45","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"சுடரின் மிகுந்த வெப்பமான பகுதி எது?","options":[{"id":"A","text":"சுடரின் வெளிப்பகுதி"},{"id":"B","text":"சுடரின் உட்பகுதி"},{"id":"C","text":"சுடரின் நடுப்பகுதி"},{"id":"D","text":"சுடரின் அனைத்துப் பகுதி"}],"correctOption":"A","explanation":"சுடரின் மிகுந்த வெப்பமான பகுதி சுடரின் வெளிப்பகுதி ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q46","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"சுடரின் ஒளிரா பகுதி எது?","options":[{"id":"A","text":"சுடரின் வெளிப்பகுதி"},{"id":"B","text":"சுடரின் உட்பகுதி"},{"id":"C","text":"சுடரின் நடுப்பகுதி"},{"id":"D","text":"சுடரின் அனைத்துப் பகுதி"}],"correctOption":"A","explanation":"சுடரின் ஒளிரா பகுதி சுடரின் வெளிப்பகுதி ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q47","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"சுடரின் எரியாத பகுதி எது?","options":[{"id":"A","text":"சுடரின் வெளிப்பகுதி"},{"id":"B","text":"சுடரின் உட்பகுதி"},{"id":"C","text":"சுடரின் நடுப்பகுதி"},{"id":"D","text":"சுடரின் அனைத்துப் பகுதி"}],"correctOption":"B","explanation":"சுடரின் எரியாத பகுதி சுடரின் உட்பகுதி ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q48","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"எரியும்போது சுடரினை உருவாக்காத பொருள் எது?","options":[{"id":"A","text":"மெழுகுவர்த்தி"},{"id":"B","text":"நிலக்கரி"},{"id":"C","text":"விறகு"},{"id":"D","text":"காகிதம்"}],"correctOption":"B","explanation":"எரியும்போது சுடரினை உருவாக்காத பொருள் நிலக்கரி ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q49","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"சுடர் எப்பொழுதும் மேல்நோக்கியே இருக்கக் காரணம்","options":[{"id":"A","text":"மிகக்குறைந்த புவி ஈர்ப்புவிசை"},{"id":"B","text":"சுடரின் மேற்பகுதியில் உள்ள காற்றின் குறைவான அடர்த்தியால்"},{"id":"C","text":"சுடரின் மேற்பகுதியில் உள்ள காற்றின் அதிக அடர்த்தியால்"},{"id":"D","text":"தவறு. சுடர் எப்பொழுதும் கீழ்நோக்கியே இருக்கும்"}],"correctOption":"B","explanation":"சுடரின் மேற்பகுதியில் உள்ள காற்றின் குறைவான அடர்த்தியால்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q50","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"கலோரி மதிப்பு என்பது","options":[{"id":"A","text":"1 லிட்டர் எரிபொருள் எரியும் பொழுது வெளிப்படும் வெப்ப ஆற்றல்"},{"id":"B","text":"1 மிலி எரிபொருள் எரியும் பொழுது வெளிப்படும் வெப்ப ஆற்றல்"},{"id":"C","text":"1 கிகி எரிபொருள் எரியும் பொழுது வெளிப்படும் வெப்ப ஆற்றலின் அளவாகும்"},{"id":"D","text":"1 டன் எரிபொருள் எரியும் பொழுது வெளிப்படும் வெப்ப ஆற்றல்"}],"correctOption":"C","explanation":"1 கிகி எரிபொருள் எரியும் பொழுது வெளிப்படும் வெப்ப ஆற்றலின் அளவாகும்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q51","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"5 kg எரிபொருளானது எரிந்து 20000 kJ வெப்பத்தை வெளியிடுகிறது எனில், அதன் கலோரி மதிப்பு","options":[{"id":"A","text":"4000 kg/kJ"},{"id":"B","text":"4000 kJ/kg"},{"id":"C","text":"4000 J/kg"},{"id":"D","text":"4000 kJ/ kg¹"}],"correctOption":"B","explanation":"4000 kJ/kg","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q52","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பின்வருவனவற்றுள் அதிக கலோரி மதிப்பு கொண்ட எரிபொருள் எது?","options":[{"id":"A","text":"நிலக்கரி"},{"id":"B","text":"பெட்ரோல்"},{"id":"C","text":"ஹைட்ரஜன்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"C","explanation":"பின்வருவனவற்றுள் அதிக கலோரி மதிப்பு கொண்ட எரிபொருள் ஹைட்ரஜன் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q53","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பின்வருவனவற்றுள் எரிதலின் வகை எது?","options":[{"id":"A","text":"வேகமாக எரிதல்"},{"id":"B","text":"மெதுவாக எரிதல்"},{"id":"C","text":"தன்னிச்சையாக எரிதல்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"பின்வருவனவற்றுள் எரிதலின் வகை அனைத்தும் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q54","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"எளிதில் தீப்பற்றும் திறன் அடிப்படையில் வரிசைப்படுத்துக.","options":[{"id":"A","text":"LPG > மரம் > பாஸ்பரஸ்"},{"id":"B","text":"மரம் > பாஸ்பரஸ் > LPG"},{"id":"C","text":"பாஸ்பரஸ் > LPG > மரம்"},{"id":"D","text":"LPG > பாஸ்பரஸ் > மரம்"}],"correctOption":"C","explanation":"பாஸ்பரஸ் > LPG > மரம்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q55","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஒரு நல்ல எரிபொருளின் பண்பு அல்லாதது எது?","options":[{"id":"A","text":"மிதமான வேகத்தில் எரிய வேண்டும்"},{"id":"B","text":"மிதமான வெப்ப ஆற்றலை வெளியிட வேண்டும்"},{"id":"C","text":"சுற்றுச்சூழலை மாசுபடுத்தக்கூடாது"},{"id":"D","text":"எளிதாக கிடைக்க வேண்டும்"}],"correctOption":"B","explanation":"ஒரு நல்ல எரிபொருளின் பண்பு அல்லாதது மிதமான வெப்ப ஆற்றலை வெளியிட வேண்டும் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q56","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"தீயைக் கட்டுப்படுத்த எச்செயலை மேற்கொள்ளலாம்?","options":[{"id":"A","text":"எரிபொருளின் எரியும் தன்மையை மாற்றலாம்"},{"id":"B","text":"ஆக்ஸிஜனை தடை செய்யலாம்"},{"id":"C","text":"எரிவெப்பநிலையை குறைக்கும் வகையில் வெப்பத்தைக் குறைக்கலாம்"},{"id":"D","text":"2 மற்றும் 3"}],"correctOption":"D","explanation":"2 மற்றும் 3","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q57","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"அதிக மின்னழுத்தம் பயன்படுத்தப்படும் இடங்களில் ஏற்படும் மின்சாரத் தீயை அணைக்க கீழ்க்கண்டவற்றுள் எதனைப் பயன்படுத்தலாம்?","options":[{"id":"A","text":"உலர் தூள்"},{"id":"B","text":"ஈரமான இரசாயனம்"},{"id":"C","text":"நீர்"},{"id":"D","text":"நுரை"}],"correctOption":"A","explanation":"உலர் தூள்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q58","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பெட்ரோல் ஏற்றிச் செல்லும் டாங்கர்களில் ஏற்படும் தீயை அணைக்க கீழ்க்கண்டவற்றுள் எதனைப் பயன்படுத்தலாம்?","options":[{"id":"A","text":"உலர் தூள்"},{"id":"B","text":"CO₂"},{"id":"C","text":"நுரை"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"அனைத்தும்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q59","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"தவறான இணையைத் தேர்ந்தெடு:","options":[{"id":"A","text":"நீர் அணைப்பான் - காகிதத்தில் எரியும் தீ"},{"id":"B","text":"கார்பன் டை ஆக்ஸைடு அணைப்பான் - மின்சாரத் தீ"},{"id":"C","text":"நுரை - மின்சாரத் தீ"},{"id":"D","text":"உலர் தூள் அணைப்பான் - மின்சாரத் தீ"}],"correctOption":"C","explanation":"நுரை - மின்சாரத் தீ","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q60","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பின்வருவனவற்றுள் தீ அணைப்பான் வகை எது?","options":[{"id":"A","text":"காற்றழுத்த நீர் அணைப்பான்"},{"id":"B","text":"கார்பன் டை ஆக்ஸைடு அணைப்பான்"},{"id":"C","text":"உலர் இரசாயனத் தூள் அணைப்பான்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"பின்வருவனவற்றுள் தீ அணைப்பான் வகை அனைத்தும் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q61","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பொருத்துக: a) நீர் b) நுரை c) CO2 d) உலர் தூள் e) ஈரமான இரசாயனம் \n i) மரம், பெட்ரோல் ii) கொழுப்பு iii) பெட்ரோல், மீத்தேன், மின் சாதனம் iv) மரம், காகிதம் v) பெட்ரோல்","options":[{"id":"A","text":"a-ii, b-i, c-iv, d-iii, e-v"},{"id":"B","text":"a-iii, b-i, c-iv, d-i, e-v"},{"id":"C","text":"a-iv, b-v, c-iii, d-i, e-ii"},{"id":"D","text":"a-i, b-iii, c-iv, d-ii, e-v"}],"correctOption":"C","explanation":"a-iv, b-v, c-iii, d-i, e-ii","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q62","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"கூற்று: எண்ணெய் தீயை அணைக்க நீரைப் பயன்படுத்தக்கூடாது. \nகாரணம் 1: எண்ணெயும் நீரும் ஒன்றோடொன்று கலந்து நன்கு எரியும். \nகாரணம் 2: நீரின் அடர்த்தி எண்ணெயை விட அதிகம். நீர் அடியில் சென்று தீயை மேலும் பரவச் செய்யும்.","options":[{"id":"A","text":"கூற்று சரி. காரணம் 1, 2 கூற்றை விளக்குகிறது"},{"id":"B","text":"கூற்று சரி. காரணம் 1 கூற்றை விளக்குகிறது"},{"id":"C","text":"கூற்று சரி. காரணம் 2 கூற்றை விளக்குகிறது"},{"id":"D","text":"கூற்று தவறு"}],"correctOption":"C","explanation":"கூற்று சரி. காரணம் 2 கூற்றை விளக்குகிறது","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q63","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"எரிபொருள் வெளியிடும் வெப்ப ஆற்றலை குறிப்பிட உதவுவது எது?","options":[{"id":"A","text":"கலோரி மதிப்பு"},{"id":"B","text":"ஆக்டேன் எண்"},{"id":"C","text":"சீட்டேன் எண்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"A","explanation":"எரிபொருள் வெளியிடும் வெப்ப ஆற்றலை குறிப்பிட உதவுவது கலோரி மதிப்பு ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q64","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பொருத்துக: a) ஆண்டி பைரடிக் b) வலி நிவாரணி c) அமிலநீக்கி d) பாஸ்பரஸ் e) கார்பன் டை ஆக்ஸைடு \n i) தன்னிச்சையான எரிதல் ii) உடல் வெப்பநிலையைக் குறைக்கும் iii) தீ அணைப்பான் iv) மெக்னீசியம் ஹைட்ராக்ஸைடு v) வலியைக் குறைக்கும்","options":[{"id":"A","text":"a-ii, b-v, c-iv, d-i, e-iii"},{"id":"B","text":"a-iii, b-iv, c-i, d-v, e-ii"},{"id":"C","text":"a-i, b-ii, c-iv, d-iii, e-v"},{"id":"D","text":"a-i, b-iii, c-iv, d-i, e-v"}],"correctOption":"A","explanation":"a-ii, b-v, c-iv, d-i, e-iii","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q65","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"ஒப்புமை தருக. சுடரின் உள்மண்டலம் : கருப்பு :: சுடரின் வெளிமண்டலம் :","options":[{"id":"A","text":"நீலம்"},{"id":"B","text":"மஞ்சள்"},{"id":"C","text":"ஊதா"},{"id":"D","text":"பச்சை"}],"correctOption":"A","explanation":"நீலம்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q66","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"திரவ பெட்ரோலிய வாயுவில் உள்ள புரோப்பேன் மற்றும் பியூட்டேன் கலவையின் விகிதாச்சாரம் (NMMS 2015-2016)","options":[{"id":"A","text":"50: 50"},{"id":"B","text":"25: 75"},{"id":"C","text":"40: 60"},{"id":"D","text":"15: 85"}],"correctOption":"D","explanation":"15: 85","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q67","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"சுற்றுச்சூழலை பாதிக்காத எரிபொருள் எது? (NMMS 2018)","options":[{"id":"A","text":"LPG"},{"id":"B","text":"CNG"},{"id":"C","text":"சாண எரிவாயு"},{"id":"D","text":"நிலக்கரி வாயு"}],"correctOption":"B","explanation":"சுற்றுச்சூழலை பாதிக்காத எரிபொருள் CNG ஆகும். (NMMS 2018)","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q68","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"பெட்ரோலுடன் எந்த ஆல்கஹாலைக் கலந்து பயன்படுத்தலாம் என மத்திய அரசு தற்போது அனுமதியளித்துள்ளது? (NMMS-2016)","options":[{"id":"A","text":"புரப்பனால்"},{"id":"B","text":"பியூட்டனால்"},{"id":"C","text":"எத்தனால்"},{"id":"D","text":"மெத்தனால்"}],"correctOption":"C","explanation":"எத்தனால்","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q69","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"திரவப் பெட்ரோலிய வாயு என்பது (NMMS 2019-2020)","options":[{"id":"A","text":"ஆக்ஸிஜன் 35% புரோப்பேன் 65%"},{"id":"B","text":"மீத்தேன் 45% பியூட்டேன் 55%"},{"id":"C","text":"புரோப்பேன் 15% பியூட்டேன் 85%"},{"id":"D","text":"ஆக்ஸிஜன் 25% ஹைட்ரஜன் 75%"}],"correctOption":"C","explanation":"புரோப்பேன் 15% பியூட்டேன் 85%","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q70","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"சுற்றுச்சூழலைப் பாதிக்காத வாயு (NMMS 2019-2020)","options":[{"id":"A","text":"இயற்கை வாயு"},{"id":"B","text":"கார்பன்டை ஆக்ஸைடு வாயு"},{"id":"C","text":"கார்பன் மோனாக்சைடு வாயு"},{"id":"D","text":"நைட்ரஜன் வாயு"}],"correctOption":"A","explanation":"இயற்கை வாயு","marks":1,"negativeMarks":0},{"id":"unit-satscience-17-q71","subject":"SAT_SCIENCE","topic":"Unit 17","questionText":"LPG உடன் சேர்க்கப்பட்ட மந்த வாயு, வாயு கசிவினை கண்டறியப் பயன்படுகிறது. (NMMS-2014)","options":[{"id":"A","text":"மெத்தில் ஆல்கஹால்"},{"id":"B","text":"மெத்தில் மெர்காப்டன்"},{"id":"C","text":"எத்தில் மெர்காப்டன்"},{"id":"D","text":"எத்தில் ஆல்கஹால்"}],"correctOption":"C","explanation":"எத்தில் மெர்காப்டன்","marks":1,"negativeMarks":0}]', datetime('now'));
INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('SAT_SCIENCE_18', 'SAT_SCIENCE', 18, '[{"id":"unit-satscience-18-q1","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"உலகில் இயற்கையின் மிகப்பெரிய கொடையாக ________ ஐ கருதலாம்","options":[{"id":"A","text":"தாவரங்கள்"},{"id":"B","text":"விலங்குகள்"},{"id":"C","text":"மனிதர்கள்"},{"id":"D","text":"பூச்சிகள்"}],"correctOption":"B","explanation":"உலகில் இயற்கையின் மிகப்பெரிய கொடையாக விலங்குகள் ஐ கருதலாம்","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q2","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பிறந்த குழந்தைகள் அல்லது குட்டிகளின் முக்கிய ஆதார ஊட்டச்சத்து உணவு ________.","options":[{"id":"A","text":"புரதம்"},{"id":"B","text":"கார்போஹைட்ரேட்"},{"id":"C","text":"நீர்"},{"id":"D","text":"பால்"}],"correctOption":"D","explanation":"பிறந்த குழந்தைகள் அல்லது குட்டிகளின் முக்கிய ஆதார ஊட்டச்சத்து உணவு பால்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q3","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பாலில் உள்ள முக்கிய ஊட்டச்சத்துக்கள் ________.","options":[{"id":"A","text":"புரதம் மற்றும் கார்போஹைட்ரேட்"},{"id":"B","text":"புரதம் மற்றும் கால்சியம்"},{"id":"C","text":"கால்சியம் மற்றும் கொழுப்பு"},{"id":"D","text":"புரதம் மற்றும் கொழுப்பு"}],"correctOption":"B","explanation":"பாலில் உள்ள முக்கிய ஊட்டச்சத்துக்கள் புரதம் மற்றும் கால்சியம்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q4","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பெண் பறவையினங்கள் முட்டையிடுவது ________.","options":[{"id":"A","text":"உணவுக்காக"},{"id":"B","text":"இளம்உயிர்கள் உருவாவதற்கு"},{"id":"C","text":"அடிப்படை செயல்பாட்டிற்காக"},{"id":"D","text":"அடைகாத்தலுக்காக"}],"correctOption":"B","explanation":"பெண் பறவையினங்கள் முட்டையிடுவது இளம்உயிர்கள் உருவாவதற்கு.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q5","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"புரதச்சத்து மிக்க உணவு ________ வளர்ச்சிக்கு உதவுகிறது.","options":[{"id":"A","text":"உடல் வளர்ச்சி மற்றும் மூளை வளர்ச்சி"},{"id":"B","text":"உடல் வளர்ச்சி மற்றும் மனவளர்ச்சி"},{"id":"C","text":"மூளை வளர்ச்சி மற்றும் தசை வளர்ச்சி"},{"id":"D","text":"எலும்பு வளர்ச்சி மற்றும் மூளை வளர்ச்சி"}],"correctOption":"A","explanation":"புரதச்சத்து மிக்க உணவு உடல் வளர்ச்சி மற்றும் மூளை வளர்ச்சி வளர்ச்சிக்கு உதவுகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q6","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"தேனீக்கள் மலர்களிலிருந்து ________ என்ற இனிப்புச்சாற்றை சேகரித்து அதை தேனாக மாற்றி தேன் கூட்டில் சேகரிக்கிறது.","options":[{"id":"A","text":"வெக்டார்"},{"id":"B","text":"தேனடை"},{"id":"C","text":"நெக்டார்"},{"id":"D","text":"மல்பெரி"}],"correctOption":"C","explanation":"தேனீக்கள் மலர்களிலிருந்து நெக்டார் என்ற இனிப்புச்சாற்றை சேகரித்து அதை தேனாக மாற்றி தேன் கூட்டில் சேகரிக்கிறது.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q7","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கீழ்க்கண்டவற்றுள் எவை வேலைக்காரத் தேனீக்களின் வேலை இல்லை?","options":[{"id":"A","text":"தேனை சேகரித்தல்"},{"id":"B","text":"இளந்தேனீக்களை வளர்த்தல்"},{"id":"C","text":"தேன்கூட்டினை சேதமடையாமல் பாதுகாத்தல்"},{"id":"D","text":"இனப்பெருக்கம் செய்தல்"}],"correctOption":"D","explanation":"இனப்பெருக்கம் செய்தல்","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q8","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கோழிகளுக்கு உருவாகும் ________ நோய் வைரஸால் ஏற்படுகிறது.","options":[{"id":"A","text":"ஆஸ்பர்ஜில்லஸ் நோய்"},{"id":"B","text":"சால்மோனெல்லோசிஸ்"},{"id":"C","text":"ராணிக்கெட் நோய்"},{"id":"D","text":"பூஞ்சை நோய்"}],"correctOption":"C","explanation":"கோழிகளுக்கு உருவாகும் ராணிக்கெட் நோய் நோய் வைரஸால் ஏற்படுகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q9","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"________ உரோமம் ஓவியம் தீட்டும் தூரிகையை உருவாக்கப்பயன்படுகிறது.","options":[{"id":"A","text":"ஆடு"},{"id":"B","text":"குதிரை"},{"id":"C","text":"முயல்"},{"id":"D","text":"நாய்"}],"correctOption":"B","explanation":"குதிரை உரோமம் ஓவியம் தீட்டும் தூரிகையை உருவாக்கப்பயன்படுகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q10","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"இவற்றில் எதிலிருந்து கம்பளி இழைகள் எடுக்கப்படுவது இல்லை?","options":[{"id":"A","text":"முயல்"},{"id":"B","text":"யாக்"},{"id":"C","text":"அல்பாகா"},{"id":"D","text":"கக்கூன்"}],"correctOption":"D","explanation":"கக்கூன்","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q11","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கம்பளியை உருவாக்கும் பின்வரும் நிலைகளை வரிசைப்படுத்துக.","options":[{"id":"A","text":"1) தரம் பிரித்தல் 2) கழுவுதல் 3) கத்தரித்தல் 4) நூற்றல் 5) சிக்கெடுத்தல்"},{"id":"B","text":"1) கத்தரித்தல் 2) தரம் பிரித்தல் 3) கழுவுதல் 4) சிக்கெடுத்தல் 5) நூற்றல்"},{"id":"C","text":"1) சிக்கெடுத்தல் 2) கத்தரித்தல் 3) தரம் பிரித்தல் 4) நூற்றல் 5) கழுவுதல்"},{"id":"D","text":"1) கத்தரித்தல் 2) கழுவுதல் 3) தரம் பிரித்தல் 4) சிக்கெடுத்தல் 5) நூற்றல்"}],"correctOption":"B","explanation":"1) கத்தரித்தல் 2) தரம் பிரித்தல் 3) கழுவுதல் 4) சிக்கெடுத்தல் 5) நூற்றல்","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q12","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பட்டுப்பூச்சிகளை வளர்ப்பதும் பட்டு இழைகளை உருவாக்குவதும் ________ என அழைக்கப்படுகிறது.","options":[{"id":"A","text":"ஹார்ட்டி கல்சர்"},{"id":"B","text":"புளோரிகல்சர்"},{"id":"C","text":"அக்ரிகல்சர்"},{"id":"D","text":"செரிகல்சர்"}],"correctOption":"D","explanation":"பட்டுப்பூச்சிகளை வளர்ப்பதும் பட்டு இழைகளை உருவாக்குவதும் செரிகல்சர் என அழைக்கப்படுகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q13","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பிரித்தெடுப்பவரின் நோய் என்றழைக்கப்படுவது ________.","options":[{"id":"A","text":"ஆஸ்துமா"},{"id":"B","text":"ஆந்த்ராக்ஸ்"},{"id":"C","text":"டைபாய்டு"},{"id":"D","text":"காலரா"}],"correctOption":"B","explanation":"பிரித்தெடுப்பவரின் நோய் என்றழைக்கப்படுவது ஆந்த்ராக்ஸ்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q14","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கூற்று: விலங்குகளின் உரோமங்களிலிருந்து இழைகள் எடுக்கப்படுகின்றன.\nகாரணம்: ஆடு, யாக் அல்பாகா மற்றும் முயல் கம்பளி இழைகளை தருகின்றன.","options":[{"id":"A","text":"கூற்றும் காரணமும் சரி"},{"id":"B","text":"கூற்று சரி, காரணம் தவறு"},{"id":"C","text":"கூற்று தவறு காரணம் சரி"},{"id":"D","text":"கூற்றும் காரணமும் தவறு"}],"correctOption":"A","explanation":"கூற்றும் காரணமும் சரி","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q15","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"காய வைத்த கம்பளி இழைகளை ஆலைகளில் இட்டு மெல்லிய கம்பி போன்ற இழைகளாக மாற்ற வேண்டும் இவைகளை தட்டையான தாளாக மாற்றுவது ________ எனப்படும்.","options":[{"id":"A","text":"பந்து"},{"id":"B","text":"கழுவுதல்"},{"id":"C","text":"வலை"},{"id":"D","text":"பிசின்"}],"correctOption":"C","explanation":"காய வைத்த கம்பளி இழைகளை ஆலைகளில் இட்டு மெல்லிய கம்பி போன்ற இழைகளாக மாற்ற வேண்டும் இவைகளை தட்டையான தாளாக மாற்றுவது வலை எனப்படும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q16","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பட்டுப்பூச்சியின் வளர்ச்சி நிலைகள் வரிசைப்படுத்துக.","options":[{"id":"A","text":"i. முட்டை ii. கூட்டுப்புழு(கக்கூன்) iii. லார்வா iv. பட்டுப்பூச்சி"},{"id":"B","text":"i. கூட்டுப்புழு ii. முட்டை iii. லார்வா iv. பட்டுப்பூச்சி"},{"id":"C","text":"i. முட்டை ii. லார்வா iii. கூட்டுப்புழு iv. பட்டுப்பூச்சி"},{"id":"D","text":"i. பட்டுப்பூச்சி ii. முட்டை iii. லார்வா iv. கூட்டுப்புழு"}],"correctOption":"C","explanation":"i. முட்டை ii. லார்வா iii. கூட்டுப்புழு iv. பட்டுப்பூச்சி","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q17","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"இழைகளிலேயே மிகவும் வலிமையான இழை ________.","options":[{"id":"A","text":"கம்பளி"},{"id":"B","text":"பட்டு இழை"},{"id":"C","text":"சணல்"},{"id":"D","text":"பருத்தி இழை"}],"correctOption":"B","explanation":"இழைகளிலேயே மிகவும் வலிமையான இழை பட்டு இழை.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q18","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பாக்டீரியாவால் பாதிக்கப்பட்ட விலங்குகளின் உரோமம் மற்றும் அங்கு வாழும் விலங்குகளைக் கையாளுவோர்க்கு ________ என்ற நோய் ஏற்படுகிறது.","options":[{"id":"A","text":"நிமோனியா"},{"id":"B","text":"ஆஸ்துமா"},{"id":"C","text":"பேசில்லஸ்"},{"id":"D","text":"ஆந்த்ராக்ஸ்"}],"correctOption":"D","explanation":"பாக்டீரியாவால் பாதிக்கப்பட்ட விலங்குகளின் உரோமம் மற்றும் அங்கு வாழும் விலங்குகளைக் கையாளுவோர்க்கு ஆந்த்ராக்ஸ் என்ற நோய் ஏற்படுகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q19","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"அகிம்சை பட்டை உருவாக்கியவர் ________.","options":[{"id":"A","text":"குசுமா ராஜய்யா"},{"id":"B","text":"சீனர்"},{"id":"C","text":"இந்தியர்"},{"id":"D","text":"எகிப்தியர்"}],"correctOption":"A","explanation":"அகிம்சை பட்டை உருவாக்கியவர் குசுமா ராஜய்யா.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q20","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பெனிசிலின், சிப்ரோஃப்ளோக்சின் மருந்துகள் எந்த நோயை குணப்படுத்தப் பயன்படுத்தப்படுகிறது?","options":[{"id":"A","text":"டைபாய்டு"},{"id":"B","text":"காலரா"},{"id":"C","text":"நிமோனியா"},{"id":"D","text":"ஆந்த்ராக்ஸ்"}],"correctOption":"D","explanation":"ஆந்த்ராக்ஸ்","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q21","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கீழ்க்கண்டவற்றுள் கம்பளி வகையில் இல்லாதது எது?","options":[{"id":"A","text":"மல்பெரி"},{"id":"B","text":"அல்பாகா பைபர்"},{"id":"C","text":"மோகிர் காஷ்மீரே"},{"id":"D","text":"ஆட்டுக்குட்டி கம்பளி"}],"correctOption":"A","explanation":"கீழ்க்கண்டவற்றுள் கம்பளி வகையில் இல்லாதது மல்பெரி ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q22","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"இந்திய அரசு விலங்குகளைப் பாதுகாக்க ________ ம் ஆண்டு நான்கு புதிய சட்டங்களை இயற்றியது.","options":[{"id":"A","text":"1950"},{"id":"B","text":"1960"},{"id":"C","text":"1970"},{"id":"D","text":"1955"}],"correctOption":"B","explanation":"இந்திய அரசு விலங்குகளைப் பாதுகாக்க 1960 ம் ஆண்டு நான்கு புதிய சட்டங்களை இயற்றியது.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q23","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"விலங்குகளின் இனப்பெருக்கத்தை ஆய்வுசெய்தல் அவற்றின் பராமரிப்பு பற்றி படிக்கும் பிரிவிற்கு ________ என்று பெயர்.","options":[{"id":"A","text":"விலங்கு பாதுகாப்பு"},{"id":"B","text":"விலங்கு வளர்ப்பு"},{"id":"C","text":"உயிரினப்பாதுகாப்பு"},{"id":"D","text":"புளூகிராஸ்"}],"correctOption":"B","explanation":"விலங்குகளின் இனப்பெருக்கத்தை ஆய்வுசெய்தல் அவற்றின் பராமரிப்பு பற்றி படிக்கும் பிரிவிற்கு விலங்கு வளர்ப்பு என்று பெயர்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q24","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பொருத்துக:\ni. கூட்டுப்புழு - a. கோழிப்பண்ணை\nii. அமைதிப்பட்டு - b. தேன்\niii. பிராய்லர் - c. ஆந்திரபிரதேசம்\niv. இனிப்பான திரவம் - d. பட்டுப்பூச்சி","options":[{"id":"A","text":"i - b, ii - c, iii - a, iv - d"},{"id":"B","text":"i - d, ii - c, iii - a, iv - b"},{"id":"C","text":"i - d, ii - b, iii - a, iv - c"},{"id":"D","text":"i - c, ii - a, iii - d, iv - b"}],"correctOption":"B","explanation":"i - d, ii - c, iii - a, iv - b","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q25","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கூற்று: பெனிசிலின் மற்றும் சிப்ரோஃப்ளோக்சாசின்.\nகாரணம்: இந்த மருந்துகள் பசு அம்மையைக் குணமாக்கும்.","options":[{"id":"A","text":"கூற்று சரி காரணம் தவறு"},{"id":"B","text":"கூற்று தவறு காரணம் சரி"},{"id":"C","text":"கூற்றும் தவறு காரணமும் தவறு"},{"id":"D","text":"கூற்றும் சரி, காரணமும் சரி"}],"correctOption":"A","explanation":"கூற்று சரி காரணம் தவறு","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q26","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"ஒப்புமைப்படுத்துக:\n1. நீர் : குழாய் : : மின்சாரம் : ________\n2. பாக்டீரியா : சால்மோனெல்லோசிஸ், வைரஸ்: ________","options":[{"id":"A","text":"i. கம்பி ii. ராணிக்கெட் நோய்"},{"id":"B","text":"i. ஒயர் ii. பூஞ்சை நோய்"},{"id":"C","text":"i. கம்பி ii. ஆஸ்பர்ஜில்லஸ் நோய்"},{"id":"D","text":"i. கம்பளி ii. கேப்ரி லோ"}],"correctOption":"A","explanation":"ஒப்புமைப்படுத்துக:\n1. நீர் : குழாய் : : மின்சாரம் : i. கம்பி ii. ராணிக்கெட் நோய்\n2. பாக்டீரியா : சால்மோனெல்லோசிஸ், வைரஸ்: i. கம்பி ii. ராணிக்கெட் நோய்","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q27","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பட்டுப்புழு ________ நாட்களில் பட்டு இழைகளை உற்பத்தி செய்யும்.","options":[{"id":"A","text":"6 நாட்களில்"},{"id":"B","text":"ஐந்து நாட்கள்"},{"id":"C","text":"7 நாட்களில்"},{"id":"D","text":"4 நாட்களில்"}],"correctOption":"B","explanation":"பட்டுப்புழு ஐந்து நாட்கள் நாட்களில் பட்டு இழைகளை உற்பத்தி செய்யும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q28","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பால் உற்பத்தியில் முதலிடம் வகிக்கும் நாடு எது?","options":[{"id":"A","text":"இந்தியா"},{"id":"B","text":"நியூசிலாந்து"},{"id":"C","text":"கனடா"},{"id":"D","text":"சீனா"}],"correctOption":"D","explanation":"பால் உற்பத்தியில் முதலிடம் வகிக்கும் நாடு சீனா ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q29","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கீழ்கண்டவற்றுள் எவற்றிலிருந்து உரோமம் பெறப்படுவது இல்லை?","options":[{"id":"A","text":"லாமா"},{"id":"B","text":"வெள்ளாடு"},{"id":"C","text":"செம்மறி ஆடு"},{"id":"D","text":"வரையாடு"}],"correctOption":"D","explanation":"வரையாடு","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q30","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கீழ்க்கண்டவற்றுள் எவை இழு விலங்கு அல்ல?","options":[{"id":"A","text":"குதிரை"},{"id":"B","text":"காளைமாடு"},{"id":"C","text":"யானை"},{"id":"D","text":"ஜெர்ஸி"}],"correctOption":"D","explanation":"ஜெர்ஸி","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q31","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"விலங்குகளிடமிருந்து பெறப்படும் ஆபரண பொருள் ________.","options":[{"id":"A","text":"தங்கம்"},{"id":"B","text":"வைரம்"},{"id":"C","text":"முத்து"},{"id":"D","text":"வெள்ளி"}],"correctOption":"C","explanation":"விலங்குகளிடமிருந்து பெறப்படும் ஆபரண பொருள் முத்து.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q32","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"விலங்குகளைப் பாதுகாக்கும் அமைப்பு எது?","options":[{"id":"A","text":"ப்ளூ கிராஸ்"},{"id":"B","text":"ரெட் கிராஸ்"},{"id":"C","text":"கிரீன் கிராஸ்"},{"id":"D","text":"ஒயிட் கிராஸ்"}],"correctOption":"A","explanation":"விலங்குகளைப் பாதுகாக்கும் அமைப்பு ப்ளூ கிராஸ் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q33","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"இழைகளின் ராணி என அழைக்கப்படுவது ________.","options":[{"id":"A","text":"சணல்"},{"id":"B","text":"கம்பளி"},{"id":"C","text":"பட்டு"},{"id":"D","text":"பருத்தி"}],"correctOption":"C","explanation":"இழைகளின் ராணி என அழைக்கப்படுவது பட்டு.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q34","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"முட்டை உற்பத்தியில் தமிழ்நாட்டில் முதலில் உள்ள இடத்தில் உள்ள மாவட்டம் எது?","options":[{"id":"A","text":"நாமக்கல்"},{"id":"B","text":"சேலம்"},{"id":"C","text":"ஈரோடு"},{"id":"D","text":"கோவை"}],"correctOption":"A","explanation":"முட்டை உற்பத்தியில் தமிழ்நாட்டில் முதலில் உள்ள இடத்தில் உள்ள மாவட்டம் நாமக்கல் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q35","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கூற்று: யானை, ஆடு, கோழி, மீன் போன்றவற்றில் தவறான ஒன்று யானை.\nகாரணம்: யானையைத் தவிர ஆடு, கோழி, மீன் போன்றவை உணவு தரும் விலங்குகள்.","options":[{"id":"A","text":"கூற்றும் காரணமும் சரி"},{"id":"B","text":"கூற்று சரி, காரணம் தவறு"},{"id":"C","text":"கூற்று தவறு, காரணம் சரி"},{"id":"D","text":"இரண்டும் தவறு"}],"correctOption":"A","explanation":"கூற்றும் காரணமும் சரி","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q36","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"மிருதுவான மற்றும் விலை உயர்ந்த சால்வை எந்த விலங்கிலிருந்து பெறப்படுகின்றது?","options":[{"id":"A","text":"லாமா"},{"id":"B","text":"அங்கோரா"},{"id":"C","text":"சடை எருமை"},{"id":"D","text":"பஷ்மினா"}],"correctOption":"D","explanation":"பஷ்மினா","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q37","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"பட்டு உற்பத்தியில் முதலிடத்தில் உள்ள நாடு எது?","options":[{"id":"A","text":"இந்தியா"},{"id":"B","text":"சீனா"},{"id":"C","text":"ரஷ்யா"},{"id":"D","text":"அமெரிக்கா"}],"correctOption":"B","explanation":"பட்டு உற்பத்தியில் முதலிடத்தில் உள்ள நாடு சீனா ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q38","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"தாவரத்தின் இனப்பெருக்கத்திற்கு பெரிதும் உதவும் விலங்கு எது?","options":[{"id":"A","text":"புலி"},{"id":"B","text":"ஆடு"},{"id":"C","text":"தேனீக்கள்"},{"id":"D","text":"மைனா"}],"correctOption":"C","explanation":"தாவரத்தின் இனப்பெருக்கத்திற்கு பெரிதும் உதவும் விலங்கு தேனீக்கள் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q39","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"வெள்ளி புரட்சி என்பது எதைக் குறிக்கும்?","options":[{"id":"A","text":"பால் உற்பத்தி"},{"id":"B","text":"பட்டு உற்பத்தி"},{"id":"C","text":"பருத்தி உற்பத்தி"},{"id":"D","text":"முட்டை உற்பத்தி"}],"correctOption":"D","explanation":"முட்டை உற்பத்தி","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q40","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"அதிக தேனைக் கொடுக்கும் தேனீ இனம் ________.","options":[{"id":"A","text":"ஏபிஸ் டார்சேட்டா"},{"id":"B","text":"ஏபிஸ் புளோரியா"},{"id":"C","text":"ஏபிஸ் இண்டிகா"},{"id":"D","text":"ஏபிஸ் மெல்லிபெரா"}],"correctOption":"D","explanation":"அதிக தேனைக் கொடுக்கும் தேனீ இனம் ஏபிஸ் மெல்லிபெரா.","marks":1,"negativeMarks":0},{"id":"unit-satscience-18-q41","subject":"SAT_SCIENCE","topic":"Unit 18","questionText":"கீழ்க்கண்டவற்றுள் எது பட்டு வகை அல்ல?","options":[{"id":"A","text":"மல்பெரி பட்டு"},{"id":"B","text":"எரி பட்டு"},{"id":"C","text":"காஞ்சி பட்டு"},{"id":"D","text":"