INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('SAT_SCIENCE_8', 'SAT_SCIENCE', 8, '[{"id":"unit-satscience-8-q1","subject":"SAT_SCIENCE","topic":"Unit 8","questionText":"ஆற்றலின் இயற்கை மூலம் எது?","options":[{"id":"A","text":"சூரியன்"},{"id":"B","text":"உரசும் உலோகங்கள்"},{"id":"C","text":"வானொலி"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"A","explanation":"ஆற்றலின் இயற்கை மூலம் சூரியன் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-8-q2","subject":"SAT_SCIENCE","topic":"Unit 8","questionText":"கீழ்க்கண்ட எந்நிகழ்வுகளில் உராய்வின் மூலம் வெப்பம் உருவாகிறது?","options":[{"id":"A","text":"கைகள் உரசுதல்"},{"id":"B","text":"உரசும் உலோகங்கள்"},{"id":"C","text":"மரக்கிளைகள் உரசுதல்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"அனைத்தும்","marks":1,"negativeMarks":0},{"id":"unit-satscience-8-q3","subject":"SAT_SCIENCE","topic":"Unit 8","questionText":"கீழ்க்கண்ட எந்நிகழ்வுகளில் வேதிமாற்றத்தினால் வெப்பம் உருவாகிறது?","options":[{"id":"A","text":"மரக்கட்டை எரிதல்"},{"id":"B","text":"சூரியன்"},{"id":"C","text":"பெட்ரோல் வாகனத்தின் இயக்கம்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"அனைத்தும்","marks":1,"negativeMarks":0},{"id":"unit-satscience-8-q4","subject":"SAT_SCIENCE","topic":"Unit 8","questionText":"மின்வெப்ப விளைவினால் இயங்கும் கருவி எது?","options":[{"id":"A","text":"மின் சூடேற்றி"},{"id":"B","text":"மின் சலவைப்பெட்டி"},{"id":"C","text":"மின் வெப்பக்கலன்"},{"id":"D","text":"அனைத்தும்"}],"correctOption":"D","explanation":"மின்வெப்ப விளைவினால் இயங்கும் கருவி அனைத்தும் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satscience-8-q5","subject":"SAT_SCIENCE","topic":"Unit 8","questionText":"பின்வருவனவற்றுள் வெப்ப மூலங்கள் அல்லாதது எது?","options":[{"id":"A","text":"சூரியன்"},{"id":"B","text":"உரசும் உலோகங்கள்"},{"id":"C","text":"வானொலி"},{"id":"D","text":"விறகு"}],"correctOption":"C","explanation":"பின்வருவனவற்றுள் வெப்ப மூலங்கள் அல்லாதது வானொலி ஆகும்.","marks":1,