veMarks":0},{"id":"unit-satsocial-15-q32","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"கீழ்க்கண்டவற்றில் எது அலையற்ற கடற்கரை என அழைக்கப்படுகிறது?","options":[{"id":"A","text":"இராமேஸ்வரம்"},{"id":"B","text":"மெரினா"},{"id":"C","text":"சில்வர்"},{"id":"D","text":"எலியட்"}],"correctOption":"A","explanation":"இராமேஸ்வரம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q33","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"கீழ்க்கண்டவற்றில் சுற்றுலாவின் எதிர்மறை தாக்கம் எது?","options":[{"id":"A","text":"நேரடியான நிதி"},{"id":"B","text":"சுற்றுச்சூழல் மேலாண்மை"},{"id":"C","text":"சுற்றுச்சூழல் பாதுகாப்பு"},{"id":"D","text":"திடக்கழிவு மற்றும் குப்பைகள்"}],"correctOption":"D","explanation":"கீழ்க்கண்டவற்றில் சுற்றுலாவின் எதிர்மறை தாக்கம் திடக்கழிவு மற்றும் குப்பைகள் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q34","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"கீழ்க்கண்டவற்றில் சுற்றுலாவின் நேர்மறை தாக்கம் எது?","options":[{"id":"A","text":"நிலச் சீரழிவு"},{"id":"B","text":"நீர் வளங்கள் சீரழிவு"},{"id":"C","text":"காற்று மற்றும் ஒலி மாசு"},{"id":"D","text":"சுற்றுச்சூழல் விழிப்புணர்வு"}],"correctOption":"D","explanation":"கீழ்க்கண்டவற்றில் சுற்றுலாவின் நேர்மறை தாக்கம் சுற்றுச்சூழல் விழிப்புணர்வு ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q35","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்துக.\ni. வாரணாசி (காசி) - a) தமிழ்நாடு\nii. வைஷ்ணவி தேவி கோவில் - b) பஞ்சாப்\niii. அமிர்தசரஸ் - c) ஜம்மு காஷ்மீர்\niv. காஞ்சிபுரம் - d) உத்தரப்பிரதேசம்","options":[{"id":"A","text":"i - d, ii - c, iii - b, iv - a"},{"id":"B","text":"i - c, ii - d, iii - a, iv - b"},{"id":"C","text":"i - c, ii - a, iii - d, iv - b"},{"id":"D","text":"i - b, ii - a, iii - d, iv - c"}],"correctOption":"A","explanation":"i - d, ii - c, iii - b, iv - a","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q36","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்துக.\ni. தாழையார் நீர்வீழ்ச்சி - a) ஆந்திரப்பிரதேசம்\nii. ஜோக் நீர்வீழ்ச்சி - b) தமிழ்நாடு\niii. அதிரப்பள்ளி நீர்வீழ்ச்சி - c) கர்நாடகம்\niv. தலக்கோணம் நீர்வீழ்ச்சி - d) கேரளா","options":[{"id":"A","text":"i - a, ii - b, iii - d, iv - c"},{"id":"B","text":"i - a, ii - d, iii - b, iv - c"},{"id":"C","text":"i - b, ii - a, iii - d, iv - c"},{"id":"D","text":"i - b, ii - c, iii - d, iv - a"}],"correctOption":"D","explanation":"i - b, ii - c, iii - d, iv - a","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q37","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்துக.\ni. கூந்தன்குளம் - a) குஜராத்\nii. குமரகம் - b) மகாராஷ்டிரா\niii. மயானி - c) தமிழ்நாடு\niv. நல்சரோவர் - d) கேரளா","options":[{"id":"A","text":"i - b, ii - c, iii - d, iv - a"},{"id":"B","text":"i - c, ii - d, iii - b, iv - a"},{"id":"C","text":"i - d, ii - b, iii - c, iv - a"},{"id":"D","text":"i - b, ii - d, iii - c, iv - a"}],"correctOption":"B","explanation":"i - c, ii - d, iii - b, iv - a","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q38","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்துக.\ni. முதுமலை - a) திருநெல்வேலி\nii. கோடியக்கரை - b) கோயம்புத்தூர்\niii. இந்திராகாந்தி - c) நாகப்பட்டினம்\niv. களக்காடு - d) நீலகிரி","options":[{"id":"A","text":"i - a, ii - b, iii - c, iv - d"},{"id":"B","text":"i - d, ii - c, iii - b, iv - a"},{"id":"C","text":"i - d, ii - b, iii - c, iv - d"},{"id":"D","text":"i - a, ii - c, iii - b, iv - d"}],"correctOption":"B","explanation":"i - d, ii - c, iii - b, iv - a","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q39","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்துக.\ni. கிண்டி - a) நீலகிரி\nii. மன்னார் வளைகுடா - b) சென்னை\niii. இந்திராகாந்தி - c) இராமநாதபுரம்\niv. முக்கூர்த்தி - d) கோயம்புத்தூர்","options":[{"id":"A","text":"i - a, ii - d, iii - c, iv - b"},{"id":"B","text":"i - a, ii - c, iii - d, iv - b"},{"id":"C","text":"i - a, ii - c, iii - b, iv - d"},{"id":"D","text":"i - b, ii - c, iii - d, iv - a"}],"correctOption":"D","explanation":"i - b, ii - c, iii - d, iv - a","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q40","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்துக.\ni. மெரினா - a) தொல்பொருள்\nii. கன்னியாகுமரி - b) நீர் விளையாட்டு\niii. மகாபலிபுரம் - c) மிக நீண்ட கடற்கரை\niv. சில்வர் - d) பல வண்ண மணல்கள்","options":[{"id":"A","text":"i - b, ii - c, iii - d, iv - a"},{"id":"B","text":"i - b, ii - d, iii - c, iv - b"},{"id":"C","text":"i - d, ii - a, iii - b, iv - b"},{"id":"D","text":"i - c, ii - d, iii - a, iv - b"}],"correctOption":"D","explanation":"i - c, ii - d, iii - a, iv - b","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q41","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்துக.\ni. தனுஷ்கோடி - a) மகாராஷ்டிரா\nii. தர்கார்லி - b) கர்நாடகம்\niii. ஓம் - c) கேரளா\niv. மராரி - d) தமிழ்நாடு","options":[{"id":"A","text":"i - a, ii - c, iii - d, iv - c"},{"id":"B","text":"i - d, ii - c, iii - b, iv - a"},{"id":"C","text":"i - b, ii - c, iii - a, iv - d"},{"id":"D","text":"i - d, ii - a, iii - b, iv - c"}],"correctOption":"D","explanation":"i - d, ii - a, iii - b, iv - c","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q42","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்துக.\ni. மலைகளின் ராணி - a) கொடைக்கானல்\nii. ஏழைகளின் ஊட்டி - b) ஊட்டி\niii. தெற்கின் கைலாஷ் - c) ஏற்காடு\niv. மலைகளின் இளவரசி - d) வெள்ளியங்கிரி","options":[{"id":"A","text":"i - b, ii - c, iii - d, iv - a"},{"id":"B","text":"i - a, ii - c, iii - d, iv - b"},{"id":"C","text":"i - b, ii - d, iii - c, iv - a"},{"id":"D","text":"i - d, ii - b, iii - c, iv - a"}],"correctOption":"A","explanation":"i - b, ii - c, iii - d, iv - a","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q43","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்துக.\ni. ஒகேனக்கல் - a) தென்காசி\nii. கும்பக்கரை - b) நாமக்கல்\niii. குற்றாலம் - c) தர்மபுரி\niv. ஆகாய கங்கை - d) தேனி","options":[{"id":"A","text":"i - b, ii - c, iii - d, iv - a"},{"id":"B","text":"i - d, ii - c, iii - b, iv - a"},{"id":"C","text":"i - c, ii - d, iii - b, iv - a"},{"id":"D","text":"i - c, ii - d, iii - a, iv - b"}],"correctOption":"D","explanation":"i - c, ii - d, iii - a, iv - b","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q44","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"சுற்றுலாவின் முக்கியக்கூறுகளான A3 உடன் தொடர்பற்றதைத் தேர்ந்தெடுக்கவும்.","options":[{"id":"A","text":"ஈர்ப்புத் தலங்கள்"},{"id":"B","text":"எளிதில் அணுகும் தன்மை"},{"id":"C","text":"சேவை வசதிகள்"},{"id":"D","text":"பயண காப்பீடு"}],"correctOption":"D","explanation":"பயண காப்பீடு","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q45","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பின்வரும் சூழல் சுற்றுலாவில் தவறானவற்றைத் தேர்ந்தெடு.","options":[{"id":"A","text":"அமேசான் மழைக்காடுகள்"},{"id":"B","text":"ஆப்பிரிக்க வனப்பயணம்"},{"id":"C","text":"இமயமலையில் மலையேற்றம்"},{"id":"D","text":"இந்தியாவின் தாஜ்மஹால்"}],"correctOption":"D","explanation":"இந்தியாவின் தாஜ்மஹால்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q46","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"சரியான இணையைத் தேர்ந்தெடு.","options":[{"id":"A","text":"மேற்கு வங்காளம் - டார்ஜிலிங்"},{"id":"B","text":"ஜம்மு காஷ்மீர் - மூணாறு"},{"id":"C","text":"மேகாலயா - ஸ்ரீநகர்"},{"id":"D","text":"கேரளா - ஷில்லாங்"}],"correctOption":"A","explanation":"மேற்கு வங்காளம் - டார்ஜிலிங்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q47","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"சரியான இணையைத் தேர்ந்தெடு.","options":[{"id":"A","text":"தாழையார் நீர்வீழ்ச்சி - தமிழ்நாடு"},{"id":"B","text":"ஜோக் நீர்வீழ்ச்சி - கர்நாடகம்"},{"id":"C","text":"தலக்கோணம் நீர்வீழ்ச்சி - ஆந்திரா"},{"id":"D","text":"மேற்கண்ட அனைத்தும்"}],"correctOption":"D","explanation":"மேற்கண்ட அனைத்தும்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q48","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"தவறான இணையைக் கண்டறிக.","options":[{"id":"A","text":"கிர் தேசிய பூங்கா - குஜராத்"},{"id":"B","text":"சுந்தரவன தேசிய பூங்கா - மேற்கு வங்காளம்"},{"id":"C","text":"கான்ஹா தேசிய பூங்கா - மத்திய பிரதேசம்"},{"id":"D","text":"மேற்கண்ட எதுவுமில்லை"}],"correctOption":"D","explanation":"மேற்கண்ட எதுவுமில்லை","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q49","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"தவறான கூற்றைக் கண்டறிக.","options":[{"id":"A","text":"தனுஷ்கோடியில் கடல் நீர் நீலரத்தின நிறத்தில் காணப்படும்"},{"id":"B","text":"மராரி கடற்கரை கோவாவில் அமைந்துள்ளது."},{"id":"C","text":"மகாராஷ்டிராவின் தர்கார்லி கடற்கரை சாகச விளையாட்டுகளுக்கு ஏற்றது."},{"id":"D","text":"கேரளாவின் வற்கலை கடற்கரை சூரியன் மறையும் காட்சியைக் காண ஏதுவான கடல் ஓங்கல் பாறைகளைக் கொண்டது."}],"correctOption":"B","explanation":"மராரி கடற்கரை கோவாவில் அமைந்துள்ளது.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q50","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"சரியான இணையைத் தேர்ந்தெடு.","options":[{"id":"A","text":"மலைகளின் இளவரசி – ஊட்டி"},{"id":"B","text":"மலைகளின் ராணி – ஏற்காடு"},{"id":"C","text":"தெற்கின் கைலாஷ் – வெள்ளியங்கிரி"},{"id":"D","text":"ஏழைகளின் ஊட்டி – கோத்தகிரி"}],"correctOption":"C","explanation":"தெற்கின் கைலாஷ் – வெள்ளியங்கிரி","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q51","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"வரலாற்றுச் சுற்றுலாவில் பொருந்தாததைத் தேர்ந்தெடுக்கவும்.","options":[{"id":"A","text":"கம்போடியாவின் அங்கோர்வாட்"},{"id":"B","text":"பிரம்மபுத்திரா நதியின் கட்டுமர மிதவை பயணம்"},{"id":"C","text":"இந்தியாவின் தாஜ்மஹால்"},{"id":"D","text":"எகிப்தின் பிரமிடுகள்"}],"correctOption":"B","explanation":"பிரம்மபுத்திரா நதியின் கட்டுமர மிதவை பயணம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q52","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருந்தாததைக் கண்டறிக.","options":[{"id":"A","text":"கொடைக்கானல்"},{"id":"B","text":"ஊட்டி"},{"id":"C","text":"ஷில்லாங்"},{"id":"D","text":"மெரினா"}],"correctOption":"D","explanation":"மெரினா","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q53","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருந்தாததைக் கண்டறிக.","options":[{"id":"A","text":"ஒகேனக்கல் நீர்வீழ்ச்சி"},{"id":"B","text":"குரங்கு நீர்வீழ்ச்சி"},{"id":"C","text":"சுருளி நீர்வீழ்ச்சி"},{"id":"D","text":"அதிரப்பள்ளி நீர்வீழ்ச்சி"}],"correctOption":"D","explanation":"அதிரப்பள்ளி நீர்வீழ்ச்சி","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q54","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருந்தாததைக் கண்டறிக.","options":[{"id":"A","text":"முதுமலை வனவிலங்கு சரணாலயம்"},{"id":"B","text":"முண்டந்துறை வனவிலங்கு சரணாலயம்"},{"id":"C","text":"களக்காடு வனவிலங்கு சரணாலயம்"},{"id":"D","text":"பத்ரா வனவிலங்கு சரணாலயம்"}],"correctOption":"D","explanation":"பத்ரா வனவிலங்கு சரணாலயம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q55","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருந்தாததைக் கண்டறிக.","options":[{"id":"A","text":"வேடந்தாங்கல்"},{"id":"B","text":"காரைவெட்டி"},{"id":"C","text":"குமரகம்"},{"id":"D","text":"வேட்டங்குடி"}],"correctOption":"C","explanation":"குமரகம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q56","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருந்தாததைக் கண்டறிக.","options":[{"id":"A","text":"முக்கூர்த்தி தேசிய பூங்கா"},{"id":"B","text":"காசிரங்கா தேசிய பூங்கா"},{"id":"C","text":"இந்திராகாந்தி தேசிய பூங்கா"},{"id":"D","text":"கிண்டி தேசிய பூங்கா"}],"correctOption":"B","explanation":"காசிரங்கா தேசிய பூங்கா","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q57","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"கீழ்க்கண்ட சமயச் சுற்றுலாவில் பொருந்தாததைக் கண்டறிக.","options":[{"id":"A","text":"காசி"},{"id":"B","text":"ஜெருசலேம்"},{"id":"C","text":"மெக்கா"},{"id":"D","text":"எகிப்தின் பிரமிடுகள்"}],"correctOption":"D","explanation":"எகிப்தின் பிரமிடுகள்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q58","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"சுற்றுலா வகைகளில் மிகப்பழமையானது ________.","options":[{"id":"A","text":"சமயச்சுற்றுலா"},{"id":"B","text":"வரலாற்றுச் சுற்றுலா"},{"id":"C","text":"சாகசச் சுற்றுலா"},{"id":"D","text":"பொழுதுபோக்குச் சுற்றுலா"}],"correctOption":"A","explanation":"சுற்றுலா வகைகளில் மிகப்பழமையானது சமயச்சுற்றுலா.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q59","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பின்வருவனவற்றில் இந்தியாவில் இல்லாத கடற்கரை எது?","options":[{"id":"A","text":"கோவா"},{"id":"B","text":"கொச்சி"},{"id":"C","text":"கோவளம்"},{"id":"D","text":"மியாமி"}],"correctOption":"D","explanation":"பின்வருவனவற்றில் இந்தியாவில் இல்லாத கடற்கரை மியாமி ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q60","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"எந்த மாவட்டத்தில் குற்றாலம் நீர்வீழ்ச்சி அமைந்துள்ளது?","options":[{"id":"A","text":"தர்மபுரி"},{"id":"B","text":"திருநெல்வேலி"},{"id":"C","text":"நாமக்கல்"},{"id":"D","text":"தேனி"}],"correctOption":"B","explanation":"திருநெல்வேலி","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q61","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"சுற்றுலாவின் மூன்று கூறுகளையும் ஒன்றாக இணைக்கும் கோட்பாடு ________,","options":[{"id":"A","text":"A1"},{"id":"B","text":"கடற்கரை"},{"id":"C","text":"நீர்வீழ்ச்சி"},{"id":"D","text":"A3"}],"correctOption":"D","explanation":"சுற்றுலாவின் மூன்று கூறுகளையும் ஒன்றாக இணைக்கும் கோட்பாடு A3,","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q62","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"காஸ்ட்ரோனமி என்பது சுற்றுலாவின் ________ அம்சத்தைக் குறிக்கின்றது","options":[{"id":"A","text":"அமைதி"},{"id":"B","text":"கலாச்சாரம்"},{"id":"C","text":"அணுகுமுறை"},{"id":"D","text":"பொழுதுபோக்கு"}],"correctOption":"B","explanation":"காஸ்ட்ரோனமி என்பது சுற்றுலாவின் கலாச்சாரம் அம்சத்தைக் குறிக்கின்றது","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q63","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"சுருளி நீர்வீழ்ச்சி ________ என்றும் அழைக்கப்படுகிறது.","options":[{"id":"A","text":"ஆகாய கங்கை"},{"id":"B","text":"கிளியூர்"},{"id":"C","text":"குரங்கு"},{"id":"D","text":"மேகமலை"}],"correctOption":"D","explanation":"சுருளி நீர்வீழ்ச்சி மேகமலை என்றும் அழைக்கப்படுகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q64","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"இரண்டாவது அழகிய நீண்ட கடற்கரை ________.","options":[{"id":"A","text":"கோவளம்"},{"id":"B","text":"சில்வர்"},{"id":"C","text":"மெரினா"},{"id":"D","text":"எலியட்"}],"correctOption":"C","explanation":"இரண்டாவது அழகிய நீண்ட கடற்கரை மெரினா.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q65","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"TAAI என்பதன் விரிவாக்கம் ________.","options":[{"id":"A","text":"Travel Agents Association of India"},{"id":"B","text":"Tamil Nadu Agri Association of Idea"},{"id":"C","text":"Tamil Nadu Agents Alumina of India"},{"id":"D","text":"Tamil Nadu Association Audio Instrument"}],"correctOption":"A","explanation":"TAAI என்பதன் விரிவாக்கம் Travel Agents Association of India.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q66","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"கீழ்க்கண்டவற்றுள் எது சரியாக பொருந்தவில்லை?","options":[{"id":"A","text":"அகுதா கடற்கரை - கோவா"},{"id":"B","text":"குரங்கு அருவி - கோயமுத்தூர்"},{"id":"C","text":"இயற்கையின் சொர்க்கம் - ஜவ்வாது"},{"id":"D","text":"டார்ஜிலிங் - உயர் விளிம்பு"}],"correctOption":"D","explanation":"டார்ஜிலிங் - உயர் விளிம்பு","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q67","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்தமானதைத் தேர்ந்தெடுக்க\nகூற்று: சுற்றுலா என்பது மக்களின் சமுதாய வாழ்க்கை முறைக்கு ஓர் இன்றியமையாத செயலாக விளங்குகிறது.\nகாரணம்: சுற்றுலா நாட்டின் சமூக, கலாச்சார, கல்வி மற்றும் பொருளாதாரத் துறையில் நேரடி தாக்கத்தை ஏற்படுத்துகிறது.","options":[{"id":"A","text":"கூற்றும் சரி, காரணமும் சரி"},{"id":"B","text":"கூற்று, காரணம் சரி ஆனால் கூற்றைக் காரணம் சரியாக விளக்கவில்லை"},{"id":"C","text":"கூற்று தவறு, காரணம் சரி"},{"id":"D","text":"கூற்று, காரணமும் தவறானவை"}],"correctOption":"A","explanation":"கூற்றும் சரி, காரணமும் சரி","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q68","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"கூற்றை ஆராய்க.\nகூற்று: வெளிநாட்டு சுற்றுலாப் பயணிகள் கலங்கட் கடற்கரையில் குவிகிறார்கள்\nகாரணம்: கலங்கட் கடற்கரையானது இரு மணல் திட்டுகளுக்கு இடையே அமைந்துள்ளது.","options":[{"id":"A","text":"கூற்று, காரணம் சரி"},{"id":"B","text":"கூற்று சரி, காரணம் தவறு"},{"id":"C","text":"கூற்று தவறு காரணம் சரி"},{"id":"D","text":"கூற்றும் காரணமும் தவறு"}],"correctOption":"B","explanation":"கூற்று சரி, காரணம் தவறு","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q69","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருந்தாத இணையைத் தேர்ந்தெடுக்க","options":[{"id":"A","text":"கம்போடியா - அங்கோர்வாட்"},{"id":"B","text":"காசி - வாரணாசி"},{"id":"C","text":"பிரமிடுகள் - எகிப்து"},{"id":"D","text":"தாஜ்மஹால் - நேபாளம்"}],"correctOption":"D","explanation":"தாஜ்மஹால் - நேபாளம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q70","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"தவறான இணையைத் தேர்ந்தெடுக்க","options":[{"id":"A","text":"நைனிடால் - உத்தரகாண்ட்"},{"id":"B","text":"டார்ஜிலிங் - மேற்கு வங்காளம்"},{"id":"C","text":"மூணாறு - ஆந்திரப்பிரதேசம்"},{"id":"D","text":"ஸ்ரீநகர் - ஜம்மு காஷ்மீர்"}],"correctOption":"C","explanation":"மூணாறு - ஆந்திரப்பிரதேசம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q71","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"கிறிஸ்தவர்கள் மேற்கொள்ளும் புனிதப் பயண தலம் எது?","options":[{"id":"A","text":"டெல்லி"},{"id":"B","text":"மெக்கா"},{"id":"C","text":"காசி"},{"id":"D","text":"ஜெருசலேம்"}],"correctOption":"D","explanation":"கிறிஸ்தவர்கள் மேற்கொள்ளும் புனிதப் பயண தலம் ஜெருசலேம் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q72","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"சுற்றுச்சூழல் சுற்றுலாவிற்கு எடுத்துக்காட்டு ________.","options":[{"id":"A","text":"எகிப்து பிரமிடுகள்"},{"id":"B","text":"முஸ்லீம்களின் மெக்கா பயணம்"},{"id":"C","text":"ஆப்பிரிக்க வனப்பயணம்"},{"id":"D","text":"விண்வீழ் விளையாட்டு"}],"correctOption":"C","explanation":"சுற்றுச்சூழல் சுற்றுலாவிற்கு எடுத்துக்காட்டு ஆப்பிரிக்க வனப்பயணம்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q73","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"தமிழ்நாட்டின் புகழ்பெற்ற சமயச் சுற்றுலா தலங்களில் ஒன்று ________.","options":[{"id":"A","text":"காஞ்சிபுரம்"},{"id":"B","text":"அமிர்தசரஸ்"},{"id":"C","text":"வாரணாசி"},{"id":"D","text":"சாரநாத்"}],"correctOption":"A","explanation":"தமிழ்நாட்டின் புகழ்பெற்ற சமயச் சுற்றுலா தலங்களில் ஒன்று காஞ்சிபுரம்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q74","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"வைஷ்ணவிதேவி கோவில் அமைந்துள்ள மாநிலம் எது?","options":[{"id":"A","text":"தமிழ்நாடு"},{"id":"B","text":"பஞ்சாப்"},{"id":"C","text":"கோவா"},{"id":"D","text":"ஜம்மு காஷ்மீர்"}],"correctOption":"D","explanation":"வைஷ்ணவிதேவி கோவில் அமைந்துள்ள மாநிலம் ஜம்மு காஷ்மீர் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q75","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"டார்ஜிலிங் எந்த மாநிலத்தின் மலைவாழிடம் ஆகும்?","options":[{"id":"A","text":"மேற்கு வங்காளம்"},{"id":"B","text":"கேரளா"},{"id":"C","text":"தமிழ்நாடு"},{"id":"D","text":"பீகார்"}],"correctOption":"A","explanation":"மேற்கு வங்காளம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q76","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"குதிரைவால் போன்ற அமைப்பில் உள்ள நீர்வீழ்ச்சியின் பெயர் எது?","options":[{"id":"A","text":"தாழையார் நீர்வீழ்ச்சி"},{"id":"B","text":"ஜோக் நீர்வீழ்ச்சி"},{"id":"C","text":"தலக்கோணம் நீர்வீழ்ச்சி"},{"id":"D","text":"நோகாலிகாய் நீர்வீழ்ச்சி"}],"correctOption":"A","explanation":"குதிரைவால் போன்ற அமைப்பில் உள்ள நீர்வீழ்ச்சியின் பெயர் தாழையார் நீர்வீழ்ச்சி ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q77","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"கொண்டை ஊசி வளைவுகளுடன் கூடிய வாகன போக்குவரத்து பகுதி எது?","options":[{"id":"A","text":"ஆனைமலை"},{"id":"B","text":"மேகமலை"},{"id":"C","text":"கொல்லிமலை"},{"id":"D","text":"ஏலகிரி"}],"correctOption":"C","explanation":"கொண்டை ஊசி வளைவுகளுடன் கூடிய வாகன போக்குவரத்து பகுதி கொல்லிமலை ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q78","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"உயர்ந்த மேகங்கள் குவியும் பகுதி ________ என அழைக்கப்படுகிறது","options":[{"id":"A","text":"ஜவ்வாதுமலை"},{"id":"B","text":"மேகமலை"},{"id":"C","text":"ஆனைமலை"},{"id":"D","text":"கொல்லிமலை"}],"correctOption":"B","explanation":"உயர்ந்த மேகங்கள் குவியும் பகுதி மேகமலை என அழைக்கப்படுகிறது","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q79","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"ஒகேனக்கல் நீர்வீழ்ச்சி அமைந்துள்ள மாவட்டம் எது?","options":[{"id":"A","text":"சென்னை"},{"id":"B","text":"குற்றாலம்"},{"id":"C","text":"ஊட்டி"},{"id":"D","text":"தர்மபுரி"}],"correctOption":"D","explanation":"ஒகேனக்கல் நீர்வீழ்ச்சி அமைந்துள்ள மாவட்டம் தர்மபுரி ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q80","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"இந்திராகாந்தி வனவிலங்கு சரணாலயம் அமைந்துள்ள மாவட்டம் எது?","options":[{"id":"A","text":"நீலகிரி"},{"id":"B","text":"நாகப்பட்டினம்"},{"id":"C","text":"கோயம்புத்தூர்"},{"id":"D","text":"திருநெல்வேலி"}],"correctOption":"C","explanation":"இந்திராகாந்தி வனவிலங்கு சரணாலயம் அமைந்துள்ள மாவட்டம் கோயம்புத்தூர் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q81","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"கோவளம் கடற்கரை அமைந்துள்ள மாவட்டம் எது?","options":[{"id":"A","text":"காஞ்சிபுரம்"},{"id":"B","text":"சென்னை"},{"id":"C","text":"ராமேஸ்வரம்"},{"id":"D","text":"கடலூர்"}],"correctOption":"A","explanation":"கோவளம் கடற்கரை அமைந்துள்ள மாவட்டம் காஞ்சிபுரம் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q82","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"அமைதியான மற்றும் ஆழமற்ற கடற்கரை என அழைக்கப்படுவது எது?","options":[{"id":"A","text":"எலியட் கடற்கரை"},{"id":"B","text":"சில்வர் கடற்கரை"},{"id":"C","text":"முட்டுக்காடு கடற்கரை"},{"id":"D","text":"கன்னியாகுமரி கடற்கரை"}],"correctOption":"C","explanation":"அமைதியான மற்றும் ஆழமற்ற கடற்கரை என அழைக்கப்படுவது முட்டுக்காடு கடற்கரை ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q83","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"இந்தியாவின் சுற்றுலாத் தலங்களில் அதிக வருமானம் தரும் மாநிலம் ________.","options":[{"id":"A","text":"கேரளா"},{"id":"B","text":"தமிழ்நாடு"},{"id":"C","text":"குஜராத்"},{"id":"D","text":"கர்நாடகா"}],"correctOption":"B","explanation":"இந்தியாவின் சுற்றுலாத் தலங்களில் அதிக வருமானம் தரும் மாநிலம் தமிழ்நாடு.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q84","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பல்லவர்கால சிற்பங்களைக் கண்டுகளிக்க மக்கள் செல்லும் கடற்கரை ________.","options":[{"id":"A","text":"மெரினா"},{"id":"B","text":"மகாபலிபுரம்"},{"id":"C","text":"கோவளம்"},{"id":"D","text":"கன்னியாகுமரி"}],"correctOption":"B","explanation":"பல்லவர்கால சிற்பங்களைக் கண்டுகளிக்க மக்கள் செல்லும் கடற்கரை மகாபலிபுரம்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q85","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"முக்கடல் சந்திப்பை _______ கடற்கரைக்குச் சென்றால் காணலாம்.","options":[{"id":"A","text":"கன்னியாகுமரி"},{"id":"B","text":"மெரினா"},{"id":"C","text":"கோவளம்"},{"id":"D","text":"எலியட்"}],"correctOption":"A","explanation":"முக்கடல் சந்திப்பை கன்னியாகுமரி கடற்கரைக்குச் சென்றால் காணலாம்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q86","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பொருத்தமானதைத் தேர்ந்தெடுக்க\nகூற்று 1: கிழக்குத் தொடர்ச்சி மலையில் ஆகாய கங்கை நீர்வீழ்ச்சியும், கிளியூர் நீர்வீழ்ச்சியும் உள்ளன.\nகூற்று 2: மேற்குத் தொடர்ச்சி மலையில் மணிமுத்தாறு அருவியும், வெள்ளி அருவியும் உள்ளன.","options":[{"id":"A","text":"கூற்று 1 தவறு 2 சரி"},{"id":"B","text":"கூற்று 1 சரி 2 தவறு"},{"id":"C","text":"கூற்று 1 மற்றும் 2 தவறு"},{"id":"D","text":"1 மற்றும் 2 சரி"}],"correctOption":"D","explanation":"1 மற்றும் 2 சரி","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q87","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"பின்வருவனவற்றுள் சூழல் சுற்றுலாவிற்கு தொடர்புடையது எது?","options":[{"id":"A","text":"ஜெருசலேம்"},{"id":"B","text":"அங்கோர்வாட்"},{"id":"C","text":"பிரம்மபுத்ரா நதியின் கட்டுமர மிதவை நதிப்பயணம்"},{"id":"D","text":"அமேசான் மழைக்காடுகள்"}],"correctOption":"D","explanation":"பின்வருவனவற்றுள் சூழல் சுற்றுலாவிற்கு தொடர்புடையது அமேசான் மழைக்காடுகள் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-15-q88","subject":"SAT_SOCIAL","topic":"Unit 15","questionText":"IATA என்பதன் விரிவாக்கம் ________.","options":[{"id":"A","text":"International Aviation Travel Association"},{"id":"B","text":"International Air Transportation Association"},{"id":"C","text":"International Aviation and Tourism Association"},{"id":"D","text":"International Air Travel Agency"}],"correctOption":"B","explanation":"IATA என்பதன் விரிவாக்கம் International Air Transportation Association.","marks":1,"negativeMarks":0}]', datetime('now'));
INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('SAT_SOCIAL_16', 'SAT_SOCIAL', 16, '[{"id":"unit-satsocial-16-q1","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்காணும் வாக்கியங்களில் சரியானது எது?","options":[{"id":"A","text":"முதலமைச்சர் என்பவர் எதிர்க்கட்சித் தலைவர்."},{"id":"B","text":"தமிழ்நாட்டில் ஈரவைச் சட்டமன்றம் செயல்படுகிறது."},{"id":"C","text":"உயர் நீதிமன்றம் மாநில அரசின் உச்சபட்ச நீதி அமைப்பு."},{"id":"D","text":"மாநில அரசின் மூன்று முக்கிய நிர்வாகப் பிரிவுகள் கிராமம், நகரம், மாநிலம்."}],"correctOption":"C","explanation":"கீழ்க்காணும் வாக்கியங்களில் சரியானது உயர் நீதிமன்றம் மாநில அரசின் உச்சபட்ச நீதி அமைப்பு. ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q2","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"இந்தியாவிலுள்ள மொத்த மாநிலங்களின் எண்ணிக்கை ________.","options":[{"id":"A","text":"26"},{"id":"B","text":"28"},{"id":"C","text":"27"},{"id":"D","text":"30"}],"correctOption":"B","explanation":"இந்தியாவிலுள்ள மொத்த மாநிலங்களின் எண்ணிக்கை 28.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q3","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"பொருத்துக.\ni. ஆளுநர் - அ. 9\nii. முதலமைச்சர் - ஆ. தலைமைச் செயலகம்\niii. யூனியன் பிரதேசங்கள் - இ. மாநிலத்தின் தலைவர்\niv. புனித ஜார்ஜ் கோட்டை - ஈ. பெரும்பான்மைக் கட்சித் தலைவர்","options":[{"id":"A","text":"i – அ, ii – ஆ, iii – இ, iv – ஈ"},{"id":"B","text":"i – இ, ii – ஈ, iii – அ, iv - ஆ"},{"id":"C","text":"i – ஈ, ii - ஆ, iii – அ, iv - இ"},{"id":"D","text":"i – இ, ii – அ, iii – ஈ, iv - ஆ"}],"correctOption":"B","explanation":"i – இ, ii – ஈ, iii – அ, iv - ஆ","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q4","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"தவறான இணையைக் கண்டுபிடி.","options":[{"id":"A","text":"சட்டமன்றப் பேரவை - கீழவை"},{"id":"B","text":"சட்டமன்ற மேலவை - மேலவை"},{"id":"C","text":"ஆளுநர் - மாநில அரசின் தலைவர்"},{"id":"D","text":"முதலமைச்சர் - எதிர்க்கட்சித் தலைவர்"}],"correctOption":"D","explanation":"முதலமைச்சர் - எதிர்க்கட்சித் தலைவர்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q5","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"உயர் நீதிமன்ற நீதிபதிகளை நியமிப்பதில் பங்கு பெறாதவர் யார்?","options":[{"id":"A","text":"ஆளுநர்"},{"id":"B","text":"உச்ச நீதிமன்றத் தலைமை நீதிபதி"},{"id":"C","text":"முதலமைச்சர்"},{"id":"D","text":"குடியரசுத்தலைவர்"}],"correctOption":"C","explanation":"உயர் நீதிமன்ற நீதிபதிகளை நியமிப்பதில் பங்கு பெறாதவர் முதலமைச்சர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q6","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்ட கூற்றுகளில் தவறானவற்றைத் தேர்ந்தெடுக்கவும்.\n(i) சட்டமன்றத்தில் உறுப்பினர்களின் கேள்விகளுக்கு அமைச்சர்கள் பதிலளிப்பர்.\n(ii) மாநிலத்திலுள்ள பல்கலைக்கழகங்களின் வேந்தராக முதலமைச்சர் செயல்படுகிறார்.\n(iii) ஒரு மாநிலத்தின் ஆளுநர், பிரதமரால் நியமிக்கப்படுகிறார்.\n(iv) உயர் நீதிமன்ற நீதிபதிகள் ஓய்வு பெறும் வயது 62.","options":[{"id":"A","text":"i மற்றும் ii"},{"id":"B","text":"iii மற்றும் iv"},{"id":"C","text":"i மற்றும் iv"},{"id":"D","text":"ii மற்றும் iii"}],"correctOption":"D","explanation":"ii மற்றும் iii","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q7","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநிலச் சட்டமன்ற உறுப்பினர்கள் கீழ்க்கண்டவர்களுள் யாரைத் தேர்ந்தெடுப்பதில் பங்கு பெறுகின்றனர்?\n(i) குடியரசுத் தலைவர்\n(ii) துணைக் குடியரசுத் தலைவர்\n(iii) ராஜ்ஜிய சபா உறுப்பினர்கள்\n(iv) சட்ட மேலவை உறுப்பினர்கள்","options":[{"id":"A","text":"i, ii மற்றும் iii சரி"},{"id":"B","text":"i மற்றும் iii சரி"},{"id":"C","text":"i, iii மற்றும் iv சரி"},{"id":"D","text":"i, ii, iii மற்றும் iv சரி"}],"correctOption":"C","explanation":"i, iii மற்றும் iv சரி","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q8","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஈரவைச் சட்டமன்றம் இல்லாத மாநிலம் எது?","options":[{"id":"A","text":"கர்நாடகம்"},{"id":"B","text":"பீகார்"},{"id":"C","text":"தெலுங்கானா"},{"id":"D","text":"கேரளா"}],"correctOption":"D","explanation":"ஈரவைச் சட்டமன்றம் இல்லாத மாநிலம் கேரளா ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q9","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கூற்று: இந்தியா கூட்டாட்சி முறை அரசாங்கத்தைக் கொண்டது.\nகாரணம்: இந்திய அரசியலமைப்பின் அதிகாரம், மத்திய மற்றும் மாநில அரசுகளுக்கிடையே பகிர்ந்தளிக்கப்பட்டுள்ளது.","options":[{"id":"A","text":"கூற்று சரி, கூற்றிற்கான விளக்கமும் சரியானது."},{"id":"B","text":"கூற்று சரி, கூற்றிற்கான விளக்கம் சரியல்ல."},{"id":"C","text":"கூற்று சரி, விளக்கம் தவறு."},{"id":"D","text":"கூற்று மற்றும் விளக்கம் தவறு."}],"correctOption":"A","explanation":"கூற்று சரி, கூற்றிற்கான விளக்கமும் சரியானது.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q10","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஈரவை என்பதற்குச் சரியான விளக்கத்தைத் தேர்ந்தெடு.","options":[{"id":"A","text":"இரு முதலமைச்சர்களைக் கொண்ட சட்டமன்றம்."},{"id":"B","text":"ஆண் மற்றும் பெண் உறுப்பினர்களைக் கொண்ட சட்டமன்றம்."},{"id":"C","text":"மேலவை மற்றும் கீழவையைக் கொண்ட சட்டமன்றம்."},{"id":"D","text":"கவர்னரைத் தலைவராகவும், சட்டமன்ற உறுப்பினர்களையும் கொண்ட அவை."}],"correctOption":"C","explanation":"மேலவை மற்றும் கீழவையைக் கொண்ட சட்டமன்றம்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q11","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநிலச் சட்டப்பேரவையின் உறுப்பினராவதற்குக் குறைந்தபட்ச வயது ________.","options":[{"id":"A","text":"18"},{"id":"B","text":"21"},{"id":"C","text":"25"},{"id":"D","text":"30"}],"correctOption":"C","explanation":"மாநிலச் சட்டப்பேரவையின் உறுப்பினராவதற்குக் குறைந்தபட்ச வயது 25.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q12","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநில அரசு என்பது ________.","options":[{"id":"A","text":"மாநில அரசின் துறைகள்"},{"id":"B","text":"சட்டமன்றம்"},{"id":"C","text":"(1) மற்றும் (2)"},{"id":"D","text":"இவற்றில் எதுவுமில்லை"}],"correctOption":"C","explanation":"மாநில அரசு என்பது (1) மற்றும் (2).","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q13","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநில அரசு நிர்வாகத்தின் ஒட்டுமொத்தத் தலைவர் ________.","options":[{"id":"A","text":"குடியரசுத் தலைவர்"},{"id":"B","text":"பிரதமர்"},{"id":"C","text":"முதலமைச்சர்"},{"id":"D","text":"ஆளுநர்"}],"correctOption":"D","explanation":"மாநில அரசு நிர்வாகத்தின் ஒட்டுமொத்தத் தலைவர் ஆளுநர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q14","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"முதலமைச்சர் மற்றும் ஏனைய அமைச்சர்களை நியமிப்பவர் ________.","options":[{"id":"A","text":"கவர்னர்"},{"id":"B","text":"பிரதமர்"},{"id":"C","text":"குடியரசுத் தலைவர்"},{"id":"D","text":"தேர்தல் ஆணையர்"}],"correctOption":"A","explanation":"முதலமைச்சர் மற்றும் ஏனைய அமைச்சர்களை நியமிப்பவர் கவர்னர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q15","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்காணும் வாக்கியங்களில் தவறானதைத் தேர்ந்தெடு.","options":[{"id":"A","text":"சட்டமன்ற உறுப்பினர்கள் மக்களுடைய பிரதிநிதிகள் அல்லர்."},{"id":"B","text":"ஆளுங்கட்சி சட்டமன்ற உறுப்பினர்களைச் சாராத அனைத்து அரசியல் கட்சியைச் சார்ந்த சட்டமன்ற உறுப்பினர்கள் எதிர்க்கட்சி உறுப்பினர்கள் என்று அழைக்கப்படுவர்."},{"id":"C","text":"அரசு செயல்படுவதற்குச் சட்டமன்ற உறுப்பினர்கள் பொறுப்புடையவர்கள் ஆவார்கள்."},{"id":"D","text":"ச.ம.உ என்பதன் விரிவாக்கம் சட்டமன்ற உறுப்பினர் (MLA) ஆகும்."}],"correctOption":"A","explanation":"சட்டமன்ற உறுப்பினர்கள் மக்களுடைய பிரதிநிதிகள் அல்லர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q16","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"உயர் நீதிமன்றத் தலைமை நீதிபதி ஓய்வு பெறும் வயது ________.","options":[{"id":"A","text":"58"},{"id":"B","text":"64"},{"id":"C","text":"62"},{"id":"D","text":"60"}],"correctOption":"C","explanation":"உயர் நீதிமன்றத் தலைமை நீதிபதி ஓய்வு பெறும் வயது 62.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q17","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஆளுநரின் பதவிக்காலம் ________.","options":[{"id":"A","text":"1 ஆண்டு"},{"id":"B","text":"5 ஆண்டுகள்"},{"id":"C","text":"6 ஆண்டுகள்"},{"id":"D","text":"3 ஆண்டுகள்"}],"correctOption":"B","explanation":"ஆளுநரின் பதவிக்காலம் 5 ஆண்டுகள்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q18","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநில அரசுப் பல்கலைக்கழகங்களின் வேந்தராகத் திகழ்பவர் ________.","options":[{"id":"A","text":"முதல்வர்"},{"id":"B","text":"கல்வியாளர்"},{"id":"C","text":"நீதிபதி"},{"id":"D","text":"ஆளுநர்"}],"correctOption":"D","explanation":"மாநில அரசுப் பல்கலைக்கழகங்களின் வேந்தராகத் திகழ்பவர் ஆளுநர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q19","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"தேர்தல்களை நடத்துவதும் அவற்றைக்காண்காணிக்கும் பணியைச் செய்வதுமான அமைப்பு?","options":[{"id":"A","text":"செயலாட்சிக் குழு"},{"id":"B","text":"தேர்தல் ஆணையம்"},{"id":"C","text":"சட்டமன்றம்"},{"id":"D","text":"நீதித்துறை"}],"correctOption":"B","explanation":"தேர்தல் ஆணையம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q20","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஆங்கிலேயர்களால் இந்தியாவில் கட்டப்பட்ட முதல் கோட்டை ________.","options":[{"id":"A","text":"வில்லியம் கோட்டை"},{"id":"B","text":"மும்பை கோட்டை"},{"id":"C","text":"லூயிஸ் கோட்டை"},{"id":"D","text":"புனித ஜார்ஜ் கோட்டை"}],"correctOption":"D","explanation":"ஆங்கிலேயர்களால் இந்தியாவில் கட்டப்பட்ட முதல் கோட்டை புனித ஜார்ஜ் கோட்டை.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q21","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"இந்தியாவில் எத்தனை மாநிலங்களில் சட்டமன்ற மேலவை உள்ளது?","options":[{"id":"A","text":"5"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"8"}],"correctOption":"B","explanation":"6","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q22","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"சட்டமன்ற மேலவை உறுப்பினர்களின் பதவிக்காலம் ________.","options":[{"id":"A","text":"3 ஆண்டுகள்"},{"id":"B","text":"5 ஆண்டுகள்"},{"id":"C","text":"6 ஆண்டுகள்"},{"id":"D","text":"7 ஆண்டுகள்"}],"correctOption":"C","explanation":"சட்டமன்ற மேலவை உறுப்பினர்களின் பதவிக்காலம் 6 ஆண்டுகள்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q23","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாறுபட்ட ஒன்றைக் கண்டுபிடி.","options":[{"id":"A","text":"மகாராஷ்டிரா"},{"id":"B","text":"தெலுங்கானா"},{"id":"C","text":"தமிழ்நாடு"},{"id":"D","text":"பீகார்"}],"correctOption":"C","explanation":"தமிழ்நாடு","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q24","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநிலத்தின் கீழவை எவ்வாறு அழைக்கப்படுகிறது?","options":[{"id":"A","text":"பிரபுக்கள் அவை"},{"id":"B","text":"சட்டமன்றப் பேரவை"},{"id":"C","text":"சட்டமன்ற மேலவை"},{"id":"D","text":"பொது அவை"}],"correctOption":"B","explanation":"சட்டமன்றப் பேரவை","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q25","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"யாருடைய ஒப்புதலுடன் மாநில அரசின் வரவு செலவுத் திட்டம் சட்டப்பேரவையில் அறிமுகப்படுத்தப்படும்?","options":[{"id":"A","text":"முதலமைச்சர்"},{"id":"B","text":"பிரதமர்"},{"id":"C","text":"ஆளுநர்"},{"id":"D","text":"நிதி அமைச்சர்"}],"correctOption":"C","explanation":"ஆளுநர்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q26","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"முதலமைச்சர் என்பவர் ________.","options":[{"id":"A","text":"பெரும்பான்மைக் கட்சியின் தலைவர்"},{"id":"B","text":"எதிர்க்கட்சித் தலைவர்"},{"id":"C","text":"(1) மற்றும் (2)"},{"id":"D","text":"இவற்றில் எதுவுமில்லை"}],"correctOption":"A","explanation":"முதலமைச்சர் என்பவர் பெரும்பான்மைக் கட்சியின் தலைவர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q27","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநில அரசின் மூன்று முக்கிய நிர்வாகப் பிரிவுகள் ________.","options":[{"id":"A","text":"மேயர், ஆளுநர், சட்டமன்ற உறுப்பினர்"},{"id":"B","text":"ஊராட்சி, நகராட்சி, மாநகராட்சி"},{"id":"C","text":"கிராமம், நகரம், மாநிலம்"},{"id":"D","text":"சட்டமன்றம், நிர்வாகத்துறை, நீதித்துறை"}],"correctOption":"D","explanation":"மாநில அரசின் மூன்று முக்கிய நிர்வாகப் பிரிவுகள் சட்டமன்றம், நிர்வாகத்துறை, நீதித்துறை.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q28","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநில அரசின் உச்சபட்ச நீதி அமைப்பு ________.","options":[{"id":"A","text":"உச்ச நீதிமன்றம்"},{"id":"B","text":"உயர் நீதிமன்றம்"},{"id":"C","text":"சட்டமன்றம்"},{"id":"D","text":"மாவட்ட நீதிமன்றம்"}],"correctOption":"B","explanation":"மாநில அரசின் உச்சபட்ச நீதி அமைப்பு உயர் நீதிமன்றம்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q29","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ச. ம. உ என்பதன் விரிவாக்கம் ________.","options":[{"id":"A","text":"சட்டமன்ற உறுப்பினர்"},{"id":"B","text":"சட்டமன்ற உரிமை"},{"id":"C","text":"சமத்துவ மக்கள் உறுப்பினர்"},{"id":"D","text":"சட்டமன்ற உள்ளாட்சி"}],"correctOption":"A","explanation":"ச. ம. உ என்பதன் விரிவாக்கம் சட்டமன்ற உறுப்பினர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q30","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஒரு குறிப்பிட்ட பகுதியைச் சேர்ந்த வாக்காளர்களால் தேர்ந்தெடுக்கப்படுபவர் ________ ஆவார்.","options":[{"id":"A","text":"முதலமைச்சர்"},{"id":"B","text":"பிரதமர்"},{"id":"C","text":"சட்டமன்ற உறுப்பினர்"},{"id":"D","text":"ஆளுநர்"}],"correctOption":"C","explanation":"ஒரு குறிப்பிட்ட பகுதியைச் சேர்ந்த வாக்காளர்களால் தேர்ந்தெடுக்கப்படுபவர் சட்டமன்ற உறுப்பினர் ஆவார்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q31","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"சட்டமன்றத்திற்குத் தேர்ந்தெடுக்கப்பட்ட உறுப்பினர் ஆளும் கட்சியைச் சாராதவராக இருப்பின் ________ என்று அழைக்கப்படுவார்.","options":[{"id":"A","text":"எதிர்க்கட்சித் தலைவர்"},{"id":"B","text":"எதிர்க்கட்சி உறுப்பினர்"},{"id":"C","text":"நிர்வாகி"},{"id":"D","text":"மேயர்"}],"correctOption":"B","explanation":"சட்டமன்றத்திற்குத் தேர்ந்தெடுக்கப்பட்ட உறுப்பினர் ஆளும் கட்சியைச் சாராதவராக இருப்பின் எதிர்க்கட்சி உறுப்பினர் என்று அழைக்கப்படுவார்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q32","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஒரு மாநிலத்தின் ஆளுநர் யாரால் நியமிக்கப்படுகிறார்?","options":[{"id":"A","text":"குடியரசுத் தலைவர்"},{"id":"B","text":"துணைக் குடியரசுத் தலைவர்"},{"id":"C","text":"பிரதம மந்திரி"},{"id":"D","text":"முதலமைச்சர்"}],"correctOption":"A","explanation":"குடியரசுத் தலைவர்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q33","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்காணும் வாக்கியங்களில் தவறானது எது?","options":[{"id":"A","text":"ஆளுநராக இந்தியக் குடிமகனாக இருத்தல் வேண்டும்."},{"id":"B","text":"25 வயது நிரம்பியவராக இருத்தல் வேண்டும்."},{"id":"C","text":"நல்ல மனநலமுடையவராக இருத்தல் வேண்டும்."},{"id":"D","text":"இலாபம் தரும் எந்தப் பதவியிலும் இருத்தல் கூடாது."}],"correctOption":"B","explanation":"கீழ்க்காணும் வாக்கியங்களில் தவறானது 25 வயது நிரம்பியவராக இருத்தல் வேண்டும். ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q34","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநில அமைச்சரவைக் குழுவின் தலைவர் ________.","options":[{"id":"A","text":"ஆளுநர்"},{"id":"B","text":"முதலமைச்சர்"},{"id":"C","text":"சபாநாயகர்"},{"id":"D","text":"உள்துறை அமைச்சர்"}],"correctOption":"B","explanation":"மாநில அமைச்சரவைக் குழுவின் தலைவர் முதலமைச்சர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q35","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநிலச் சட்டமன்றக் கூட்டத்தைக் கூட்டவும், ஒத்திவைக்கவும் அதிகாரம் பெற்றவர் ________.","options":[{"id":"A","text":"உள்துறை அமைச்சர்"},{"id":"B","text":"குடியரசுத் தலைவர்"},{"id":"C","text":"சபாநாயகர்"},{"id":"D","text":"ஆளுநர்"}],"correctOption":"D","explanation":"மாநிலச் சட்டமன்றக் கூட்டத்தைக் கூட்டவும், ஒத்திவைக்கவும் அதிகாரம் பெற்றவர் ஆளுநர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q36","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாவட்ட நீதிபதிகள் ________ ஆல் நியமிக்கப்படுகிறார்.","options":[{"id":"A","text":"உச்ச நீதிமன்றத் தலைமை நீதிபதி"},{"id":"B","text":"மாவட்ட ஆட்சித் தலைவர்"},{"id":"C","text":"முதலமைச்சர்"},{"id":"D","text":"ஆளுநர்"}],"correctOption":"D","explanation":"மாவட்ட நீதிபதிகள் ஆளுநர் ஆல் நியமிக்கப்படுகிறார்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q37","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஆளுநர் ஒரு மாநிலத்தின் ________ ஆவார்.","options":[{"id":"A","text":"செயலாளர்"},{"id":"B","text":"தலைவர்"},{"id":"C","text":"நீதிபதி"},{"id":"D","text":"அங்கம்"}],"correctOption":"B","explanation":"ஆளுநர் ஒரு மாநிலத்தின் தலைவர் ஆவார்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q38","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்டவற்றைப் பொருத்துக.\na. ஆளுநர் – i. கீழவை\nb. முதலமைச்சர் – ii. பெயரளவுத் தலைவர்\nc. சட்டமன்றப் பேரவை – iii. மேலவை\nd. சட்டமன்ற மேலவை – iv. உண்மையான தலைவர்","options":[{"id":"A","text":"a - ii, b – iv, c – i, d – iii"},{"id":"B","text":"a – iii, b – i, c – ii, d - iv"},{"id":"C","text":"a – iii, b – ii, c – i, d – iv"},{"id":"D","text":"a – iv, b – iii, c – i, d - ii"}],"correctOption":"A","explanation":"a - ii, b – iv, c – i, d – iii","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q39","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"பின்வருவனவற்றில் ஈரவைச் சட்டமன்றம் கொண்ட மாநிலம் எது?","options":[{"id":"A","text":"தமிழ்நாடு"},{"id":"B","text":"கேரளா"},{"id":"C","text":"கர்நாடகம்"},{"id":"D","text":"ஒரிசா"}],"correctOption":"C","explanation":"பின்வருவனவற்றில் ஈரவைச் சட்டமன்றம் கொண்ட மாநிலம் கர்நாடகம் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q40","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"எந்தச் சட்டப்பிரிவு மாநிலத்தில் குடியரசுத் தலைவர் ஆட்சியை ஏற்படுத்துகிறது?","options":[{"id":"A","text":"சட்டம் 354"},{"id":"B","text":"சட்டம் 256"},{"id":"C","text":"சட்டம் 357"},{"id":"D","text":"சட்டம் 356"}],"correctOption":"D","explanation":"சட்டம் 356","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q41","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"________ ஒப்புதலுக்குப் பின்னரே பண மசோதா சட்டமன்றத்தில் கொண்டு வர முடியும்.","options":[{"id":"A","text":"ஆளுநர்"},{"id":"B","text":"குடியரசுத் தலைவர்"},{"id":"C","text":"முதலமைச்சர்"},{"id":"D","text":"நீதிபதி"}],"correctOption":"A","explanation":"ஆளுநர் ஒப்புதலுக்குப் பின்னரே பண மசோதா சட்டமன்றத்தில் கொண்டு வர முடியும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q42","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்டவற்றில் எது தவறான கூற்று?","options":[{"id":"A","text":"மாநில நிர்வாகத் துறையின் உண்மையான தலைவர் முதலமைச்சர்."},{"id":"B","text":"மாநில அமைச்சரவையின் தலைவர் முதலமைச்சர்."},{"id":"C","text":"முதலமைச்சரின் பதவிக்காலம் 6 ஆண்டுகள்."},{"id":"D","text":"உயர் நீதிமன்ற நீதிபதிகள் தவறான நடத்தை, திறமையின்மை காரணமாக நீக்கப்படலாம்."}],"correctOption":"C","explanation":"முதலமைச்சரின் பதவிக்காலம் 6 ஆண்டுகள்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q43","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"சட்டமன்ற மேலவை உறுப்பினராவதற்குத் தகுதியுள்ள வயது?","options":[{"id":"A","text":"18"},{"id":"B","text":"25"},{"id":"C","text":"40"},{"id":"D","text":"30"}],"correctOption":"D","explanation":"30","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q44","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்டவற்றில் எது தவறான கூற்று?","options":[{"id":"A","text":"ஒரு சட்டமன்றத் தொகுதி 1,00,000 அல்லது அதற்கு மேல் மக்கள் தொகையைப் பெற்றிருக்க வேண்டும்."},{"id":"B","text":"ஒருவர் ஒரு சட்டமன்றத் தொகுதியில் மட்டுமே போட்டியிட முடியும்."},{"id":"C","text":"உயர் நீதிமன்றம், சார்நிலை நீதிமன்றத்தில் நிலுவையில் உள்ள ஒரு வழக்கில் தலையிடலாம்."},{"id":"D","text":"உயர் நீதிமன்றம் ஆட்கொணர்வு நீதிப்பேராணையைப் பிறப்பிக்க முடியும்."}],"correctOption":"B","explanation":"ஒருவர் ஒரு சட்டமன்றத் தொகுதியில் மட்டுமே போட்டியிட முடியும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q45","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"பின்வருவனவற்றில் எது சரியாகப் பொருந்தவில்லை?","options":[{"id":"A","text":"உயர் நீதிமன்றம் - கட்டளையிடும் நீதிப்பேராணை"},{"id":"B","text":"பெண் திருமண வயது - 18"},{"id":"C","text":"தமிழ்நாடு சட்டமன்றம் - 236 உறுப்பினர்"},{"id":"D","text":"சட்டமன்ற மேலவை - 30 வயது நிரம்பியவர்"}],"correctOption":"C","explanation":"தமிழ்நாடு சட்டமன்றம் - 236 உறுப்பினர்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q46","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்டவற்றில் எது சரியான கூற்று?","options":[{"id":"A","text":"மாநிலத்தின் உயரிய நீதி அமைப்பு உச்சநீதிமன்றம்."},{"id":"B","text":"தலைமை நீதிபதி 60 வயது வரை பதவியில் இருக்கலாம்."},{"id":"C","text":"மாவட்ட நீதிபதிகளைக் குடியரசுத் தலைவர் நியமனம் செய்கிறார்."},{"id":"D","text":"உயர் நீதிமன்றம் மாநிலத்தில் உள்ள அனைத்துச் சார்நிலை நீதிமன்றங்களைக் கட்டுப்படுத்துகிறது."}],"correctOption":"D","explanation":"உயர் நீதிமன்றம் மாநிலத்தில் உள்ள அனைத்துச் சார்நிலை நீதிமன்றங்களைக் கட்டுப்படுத்துகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q47","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"பொருத்துக.\n(1) ஈரவைச் சட்டமன்றம் – i. குடியரசுத் தலைவர்\n(2) பல்கலைக்கழக வேந்தர் – ii. தமிழ்நாடு\n(3) ஓரவைச் சட்டமன்றம் – iii. ஆளுநர்\n(4) முதல் குடிமகன் – iv. தெலுங்கானா","options":[{"id":"A","text":"(1)-ii, (2)-iii, (3)-i, (4)-iv"},{"id":"B","text":"(1)-iii, (2)-iv, (3)-i, (4)-ii"},{"id":"C","text":"(1)-iv, (2)-iii, (3)-ii, (4)-i"},{"id":"D","text":"(1)-iv, (2)-ii, (3)-iii, (4)-i"}],"correctOption":"C","explanation":"(1)-iv, (2)-iii, (3)-ii, (4)-i","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q48","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"சரியான கூற்றுகளைத் தேர்ந்தெடுக்கவும்.\nஉயர் நீதிமன்றத்தின் நீதிபதி பின்வரும் தகுதிகளைக் கட்டாயம் கொண்டிருத்தல் வேண்டும்.\ni. இந்தியக் குடிமகனாக இருத்தல் வேண்டும்.\nii. இந்தியாவில் ஓராண்டுக் காலம் நீதித்துறை அலுவலராகப் பணியாற்றி இருக்க வேண்டும்.\niii. ஒன்று அல்லது அதற்கு மேற்பட்ட உயர் நீதிமன்றங்களில் வழக்கறிஞராகக் குறைந்தபட்சம் 10 ஆண்டுகள் அனுபவம் பெற்றிருத்தல் வேண்டும்.\niv. வயது வரம்பு 35 க்குள் இருத்தல் வேண்டும்.","options":[{"id":"A","text":"i & ii"},{"id":"B","text":"ii & iii"},{"id":"C","text":"iii & iv"},{"id":"D","text":"i & iii"}],"correctOption":"D","explanation":"i & iii","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q49","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"தவறான கூற்றைத் தேர்ந்தெடுக்கவும்.\nஆளுநரின் அதிகாரம் மற்றும் பணிகள்","options":[{"id":"A","text":"ஆளுநர், முதலமைச்சரையும் ஏனைய அமைச்சர்களையும் நியமிக்கிறார்."},{"id":"B","text":"மாநிலத்திலுள்ள பல்கலைக்கழகங்களின் வேந்தராக ஆளுநர் செயல்படுகிறார்."},{"id":"C","text":"சட்டமன்றத்திற்கு ஓர் ஆங்கிலோ இந்திய உறுப்பினரை நியமனம் செய்யும் அதிகாரத்தைப் பெற்றுள்ளார்."},{"id":"D","text":"மாநிலச் சட்ட மேலவைக்கு அறிவியல், இலக்கியம், கலை, சமூக சேவை கூட்டுறவு இயக்கம் ஆகிய துறைகளில் சிறப்பாகப் பங்காற்றிய அறிஞர்களில் 5/6 அளவிற்குப் பிரதிநிதித்துவ அடிப்படையில் நியமிக்கிறார்."}],"correctOption":"D","explanation":"மாநிலச் சட்ட மேலவைக்கு அறிவியல், இலக்கியம், கலை, சமூக சேவை கூட்டுறவு இயக்கம் ஆகிய துறைகளில் சிறப்பாகப் பங்காற்றிய அறிஞர்களில் 5/6 அளவிற்குப் பிரதிநிதித்துவ அடிப்படையில் நியமிக்கிறார்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q50","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"பொருத்துக.\na. நிர்வாகம் - i. சட்டங்களை நிலைநாட்டல்.\nb. சட்டமன்றம் - ii. சட்டங்களைச் செயல்படுத்துதல்.\nc. நீதித்துறை - iii. சட்டங்களை இயற்றுதல்","options":[{"id":"A","text":"a – ii, b – iii, c – i"},{"id":"B","text":"a – iii, b – ii, c – i"},{"id":"C","text":"a – ii, b – i, c – iii"},{"id":"D","text":"a – i, b – iii, c – ii"}],"correctOption":"A","explanation":"a – ii, b – iii, c – i","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q51","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"சட்டமன்றக் கீழவை உறுப்பினர்கள் யாரால் தேர்ந்தெடுக்கப்படுகின்றனர்?","options":[{"id":"A","text":"மேலவை உறுப்பினர்கள்"},{"id":"B","text":"பாராளுமன்ற உறுப்பினர்கள்"},{"id":"C","text":"நியமனம் செய்யப்படுபவர்"},{"id":"D","text":"மக்கள்"}],"correctOption":"D","explanation":"மக்கள்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q52","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"இந்தியாவின் தலைநகரம் ________.","options":[{"id":"A","text":"சென்னை"},{"id":"B","text":"மும்பை"},{"id":"C","text":"புதுடெல்லி"},{"id":"D","text":"கல்கத்தா"}],"correctOption":"C","explanation":"இந்தியாவின் தலைநகரம் புதுடெல்லி.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q53","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"தேர்தலில் வாக்களிக்கத் தேவையான குறைந்தபட்ச வயது ________.","options":[{"id":"A","text":"25"},{"id":"B","text":"18"},{"id":"C","text":"30"},{"id":"D","text":"35"}],"correctOption":"B","explanation":"தேர்தலில் வாக்களிக்கத் தேவையான குறைந்தபட்ச வயது 18.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q54","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"முதலமைச்சராக எத்தனை வயது பூர்த்தி அடைந்திருக்க வேண்டும்?","options":[{"id":"A","text":"21"},{"id":"B","text":"23"},{"id":"C","text":"25"},{"id":"D","text":"30"}],"correctOption":"C","explanation":"25","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q55","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"பல்கலைக்கழகத் துணை வேந்தர்களை நியமிப்பவர் ________.","options":[{"id":"A","text":"ஆளுநர்"},{"id":"B","text":"முதலமைச்சர்"},{"id":"C","text":"பதிவாளர்"},{"id":"D","text":"உயர் நீதிமன்ற நீதிபதி"}],"correctOption":"A","explanation":"பல்கலைக்கழகத் துணை வேந்தர்களை நியமிப்பவர் ஆளுநர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q56","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"யூனியன் பிரதேசங்களின் தலைவர் யார்?","options":[{"id":"A","text":"குடியரசுத் தலைவர்"},{"id":"B","text":"ஆளுநர்"},{"id":"C","text":"பிரதமர்"},{"id":"D","text":"தலைமை நீதிபதி"}],"correctOption":"A","explanation":"யூனியன் பிரதேசங்களின் தலைவர் குடியரசுத் தலைவர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q57","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"பாராளுமன்ற உறுப்பினர்களை ________ என அழைக்கின்றனர்.","options":[{"id":"A","text":"M.L.A."},{"id":"B","text":"P.M."},{"id":"C","text":"C.M."},{"id":"D","text":"M.P."}],"correctOption":"D","explanation":"பாராளுமன்ற உறுப்பினர்களை M.P. என அழைக்கின்றனர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q58","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"திருமணம் / விவாகரத்துத் தொடர்பான பிரச்சினைகளுக்குத் தீர்வு காணும் அமைப்பு ஏது?","options":[{"id":"A","text":"சட்டமன்றம்"},{"id":"B","text":"உயர் நீதிமன்றம்"},{"id":"C","text":"குடும்ப நல நீதிமன்றம்"},{"id":"D","text":"உச்ச நீதிமன்றம்"}],"correctOption":"C","explanation":"குடும்ப நல நீதிமன்றம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q59","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்காணும் கூற்றுகளில் சரியானது எது?","options":[{"id":"A","text":"இந்தியாவிலுள்ள அனைத்து மாநிலங்களிலும் யூனியன் பிரதேசங்களிலும் தனித்தனியாக அரசாங்க அமைப்பு இல்லை."},{"id":"B","text":"சட்டமன்ற உறுப்பினர்கள் ஆளுநரால் நியமிக்கப்படுகின்றனர்."},{"id":"C","text":"செங்கோட்டை சென்னையில் உள்ளது."},{"id":"D","text":"இந்திய அரசியலமைப்பில் மத்திய அரசும், மாநில அரசுகளும் இணைந்தே செயல்படுகின்றன."}],"correctOption":"D","explanation":"இந்திய அரசியலமைப்பில் மத்திய அரசும், மாநில அரசுகளும் இணைந்தே செயல்படுகின்றன.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q60","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"மாநில அரசின் எதிர்பாரா செலவின நிதி யாருடைய கட்டுப்பாட்டில் இருக்கும்?","options":[{"id":"A","text":"ஆளுநர்"},{"id":"B","text":"முதலமைச்சர்"},{"id":"C","text":"குடியரசுத் தலைவர்"},{"id":"D","text":"பிரதமர்"}],"correctOption":"A","explanation":"ஆளுநர்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q61","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஆளுநர்: ____________ :: சட்டமன்ற உறுப்பினர் : நாடாளுமன்ற உறுப்பினர்","options":[{"id":"A","text":"சட்ட மேலவை உறுப்பினர்"},{"id":"B","text":"ஜனாதிபதி"},{"id":"C","text":"முதலமைச்சர்"},{"id":"D","text":"உயர் நீதிமன்ற நீதிபதி"}],"correctOption":"B","explanation":"ஆளுநர்: ஜனாதிபதி :: சட்டமன்ற உறுப்பினர் : நாடாளுமன்ற உறுப்பினர்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q62","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஒரு மாநிலச் சட்டமன்றத்தின் நிலையான அவை","options":[{"id":"A","text":"மக்களவை"},{"id":"B","text":"சட்டமன்றப் பேரவை"},{"id":"C","text":"சட்டமன்ற மேலவை"},{"id":"D","text":"மாநிலங்களவை"}],"correctOption":"C","explanation":"சட்டமன்ற மேலவை","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q63","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"சட்டமன்றக் கூட்டத்திற்குத் தலைமை ஏற்பவர் யார்?","options":[{"id":"A","text":"ஆளுநர்"},{"id":"B","text":"முதலமைச்சர்"},{"id":"C","text":"சபாநாயகர்"},{"id":"D","text":"சட்டத்துறை அமைச்சர்"}],"correctOption":"C","explanation":"சட்டமன்றக் கூட்டத்திற்குத் தலைமை ஏற்பவர் சபாநாயகர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q64","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"முதலமைச்சர் சட்டமன்ற உறுப்பினராக இல்லாவிட்டால் எத்தனை மாதத்திற்குள் சட்டமன்ற உறுப்பினராகத் தேர்ந்தெடுக்கப்பட வேண்டும்?","options":[{"id":"A","text":"3"},{"id":"B","text":"5"},{"id":"C","text":"6"},{"id":"D","text":"10"}],"correctOption":"C","explanation":"6","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q65","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்ட குழுவில் பொருந்தாதது எது?","options":[{"id":"A","text":"லோக்சபா"},{"id":"B","text":"மாநிலங்களவை"},{"id":"C","text":"ராஜ்யசபா"},{"id":"D","text":"நாடாளுமன்ற மேலவை"}],"correctOption":"A","explanation":"கீழ்க்கண்ட குழுவில் பொருந்தாதது லோக்சபா ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q66","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்ட நிகழ்வுகளை வரிசைப்படுத்துக.\ni. மசோதாவில் திருத்தங்கள் மேற்கொள்ளப்படுகின்றன.\nii. மசோதா மீது விவாதங்கள் நடைபெறுகின்றன.\niii. மசோதா நிறைவேறுகிறது.\niv. ஆளுநர் கையொப்பத்துடன் சட்டமாகிறது.\nv. சட்டப்பேரவையில் மசோதா அறிமுகப்படுத்தப்படுகிறது.","options":[{"id":"A","text":"v, i, ii, iii, iv"},{"id":"B","text":"v, ii, i, iii, iv"},{"id":"C","text":"v, i, ii, iv, iii"},{"id":"D","text":"ii, v, i, ii, iii"}],"correctOption":"B","explanation":"v, ii, i, iii, iv","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q67","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"உயர் நீதிமன்றமானது கீழ்க்கண்ட எதைக் கண்காணிக்க முடியாது?","options":[{"id":"A","text":"இராணுவ நீதிமன்றம்"},{"id":"B","text":"சார்நிலை நீதிமன்றம்"},{"id":"C","text":"மாவட்ட நீதிமன்றம்"},{"id":"D","text":"இவற்றில் எதுவுமில்லை"}],"correctOption":"A","explanation":"உயர் நீதிமன்றமானது கீழ்க்கண்ட எதைக் கண்காணிக்க முடிஇராணுவ நீதிமன்றம் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q68","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஆவணங்களைத் தாக்கல் செய்ய வலியுறுத்தும் நீதிப்பேராணை, தகுதிமுறை வினவும் நீதிப்பேராணை ஆகியவற்றைப் பிறப்பிக்கத் தகுதியான அமைப்பு","options":[{"id":"A","text":"சட்டமன்றம்"},{"id":"B","text":"நாடாளுமன்றம்"},{"id":"C","text":"உயர் நீதிமன்றம்"},{"id":"D","text":"உச்ச நீதிமன்றம்"}],"correctOption":"C","explanation":"உயர் நீதிமன்றம்","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q69","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"அமைச்சரவையின் செயல்பாடுகளில் திருப்தி ஏற்படாவிட்டால்","options":[{"id":"A","text":"காவல்நிலையத்தில் புகார் செய்யலாம்."},{"id":"B","text":"தீர்ப்பாயங்களில் முறையிடலாம்."},{"id":"C","text":"தேர்தல் ஆணையத்தில் நிரூபித்துப் பதவி நீக்கம் செய்யலாம்."},{"id":"D","text":"சட்டமன்றத்தில் நம்பிக்கை இல்லாத் தீர்மானத்தை இயற்றி நீக்கம் செய்யலாம்."}],"correctOption":"D","explanation":"சட்டமன்றத்தில் நம்பிக்கை இல்லாத் தீர்மானத்தை இயற்றி நீக்கம் செய்யலாம்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q70","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"சட்டமேலவையின் உறுப்பினர்களில் _______ பங்கு உறுப்பினர்கள் _______ ஆண்டுகளுக்கு ஒருமுறை ஓய்வு பெறுவர்.","options":[{"id":"A","text":"1/2, 3"},{"id":"B","text":"1/3, 2"},{"id":"C","text":"1/3, 6"},{"id":"D","text":"1/6, 6"}],"correctOption":"B","explanation":"சட்டமேலவையின் உறுப்பினர்களில் 1/3, 2 பங்கு உறுப்பினர்கள் 1/3, 2 ஆண்டுகளுக்கு ஒருமுறை ஓய்வு பெறுவர்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q71","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"இவற்றில் ஆளுநரால் நியமிக்கப்படாத பணியிடம் எது?","options":[{"id":"A","text":"அரசுத் தலைமை வழக்கறிஞர்"},{"id":"B","text":"அரசுப் பணியாளர் தேர்வாணையத் தலைவர்"},{"id":"C","text":"மாநிலத் தலைமைத் தேர்தல் ஆணையர்"},{"id":"D","text":"வட்டாட்சியர்"}],"correctOption":"D","explanation":"இவற்றில் ஆளுநரால் நியமிக்கப்படாத பணியிடம் வட்டாட்சியர் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q72","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கூற்று 1: ஆளுநருக்கு அவசரநிலைச் சட்டத்தைப் பிறப்பிக்கும் அதிகாரம் உண்டு.\nகூற்று 2: மாநில அரசின் எதிர்பாரா செலவின நிதி முதலமைச்சரின் கட்டுப்பாட்டில் இருக்கும்.","options":[{"id":"A","text":"கூற்று 1 மட்டும் சரி"},{"id":"B","text":"கூற்று 2 மட்டும் சரி"},{"id":"C","text":"இரண்டும் சரி"},{"id":"D","text":"இரண்டும் தவறு"}],"correctOption":"A","explanation":"கூற்று 1 மட்டும் சரி","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q73","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"இவற்றில் எது முதலமைச்சரின் கடமை அன்று?","options":[{"id":"A","text":"மாநில அரசின் கொள்கைகளை உருவாக்குதல்."},{"id":"B","text":"பல்வேறு துறைகளைக் கண்காணித்து ஆலோசனை வழங்குதல்."},{"id":"C","text":"மத்திய அரசு மற்றும் மாநில அரசிற்கிடையே உறவைப் பராமரித்தல்."},{"id":"D","text":"மாநில உயர் அதிகாரிகளை நியமிக்க ஆளுநருக்கு ஆலோசனை வழங்குதல்."}],"correctOption":"C","explanation":"மத்திய அரசு மற்றும் மாநில அரசிற்கிடையே உறவைப் பராமரித்தல்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q74","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்டவற்றுள் தவறானதைத் தேர்ந்தெடு.\n(a) சட்டமன்ற மேலவையில் மூன்றில் ஒரு பங்கு உறுப்பினர்கள் சட்டமன்ற உறுப்பினர்களால் தேர்ந்தெடுக்கப்படுகின்றனர்.\n(b) பன்னிரண்டில் ஒரு பங்கு உறுப்பினர்கள் பட்டதாரிகளால் தேர்ந்தெடுக்கப்படுகின்றனர்.\n(c) ஆறில் ஒரு பங்கு உறுப்பினர்கள் மாநில முதலமைச்சரால் நியமனம் செய்யப்படுகின்றனர்.\n(d) சட்டமன்ற மேலவை உறுப்பினர்களின் பதவிக்காலம் ஆறு ஆண்டுகளாகும்.","options":[{"id":"A","text":"a மற்றும் b"},{"id":"B","text":"c மற்றும் d"},{"id":"C","text":"c மட்டும்"},{"id":"D","text":"a மற்றும் d"}],"correctOption":"B","explanation":"c மற்றும் d","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q75","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"அரசியலமைப்புச் சட்டப்படி சட்டமேலவை மற்றும் சட்டப்பேரவையில் இருக்கவேண்டிய குறைந்தபட்ச உறுப்பினர்களின் எண்ணிக்கை _______, ________.","options":[{"id":"A","text":"40, 60"},{"id":"B","text":"60, 40"},{"id":"C","text":"60, மூன்றில் ஒரு பங்கு"},{"id":"D","text":"40, 500"}],"correctOption":"A","explanation":"அரசியலமைப்புச் சட்டப்படி சட்டமேலவை மற்றும் சட்டப்பேரவையில் இருக்கவேண்டிய குறைந்தபட்ச உறுப்பினர்களின் எண்ணிக்கை 40, 60, 40, 60.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q76","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"ஒரு மாநிலத்தின் சட்டப்பேரவையில் 450 உறுப்பினர்கள் இருப்பார்களானால், அம்மாநிலச் சட்டமேலவையில் இருக்க வேண்டிய அதிகபட்ச உறுப்பினர்களின் எண்ணிக்கை ________.","options":[{"id":"A","text":"225"},{"id":"B","text":"226"},{"id":"C","text":"150"},{"id":"D","text":"450"}],"correctOption":"C","explanation":"ஒரு மாநிலத்தின் சட்டப்பேரவையில் 450 உறுப்பினர்கள் இருப்பார்களானால், அம்மாநிலச் சட்டமேலவையில் இருக்க வேண்டிய அதிகபட்ச உறுப்பினர்களின் எண்ணிக்கை 150.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q77","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"அரசியலமைப்புச் சட்டப்படி, ஒரு மாநிலத்தின் சட்டப்பேரவையில் இருக்க வேண்டிய அதிகபட்ச உறுப்பினர்களின் எண்ணிக்கை ________.","options":[{"id":"A","text":"234"},{"id":"B","text":"500"},{"id":"C","text":"545"},{"id":"D","text":"250"}],"correctOption":"B","explanation":"அரசியலமைப்புச் சட்டப்படி, ஒரு மாநிலத்தின் சட்டப்பேரவையில் இருக்க வேண்டிய அதிகபட்ச உறுப்பினர்களின் எண்ணிக்கை 500.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q78","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்டவற்றில் எது தவறான கூற்று?","options":[{"id":"A","text":"மாநிலத்தின் சட்டமன்றம், அரசியலமைப்பைத் திருத்தும் சில நேர்வுகளில் பங்கேற்கிறது."},{"id":"B","text":"உயர்நீதிமன்றம், வழக்குகள் பற்றிய பதிவேடுகளின் ஆதாரச் சான்றாக உள்ள பதிவுறு நீதிமன்றமாக விளங்குகிறது."},{"id":"C","text":"சட்டங்களை நடைமுறைப்படுத்துவது அமைச்சரவையின் பணியாகும்."},{"id":"D","text":"உயர் நீதிமன்றம், அமைச்சரவையின் மீது கட்டுப்பாட்டினைச் செலுத்துகிறது."}],"correctOption":"D","explanation":"உயர் நீதிமன்றம், அமைச்சரவையின் மீது கட்டுப்பாட்டினைச் செலுத்துகிறது.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q79","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"கீழ்க்கண்ட கூற்றுகளை ஆராய்க.\ni. அங்கீகரிக்கப்படாத கட்சியின் வேட்பாளர்கள் சுயேச்சை வேட்பாளர்கள் என அழைக்கப்படுகின்றனர்.\nii. சட்டமன்ற அனுமதி இல்லாமல் மாநில அரசு வரி விதிக்க இயலாது.\niii. மாநிலத்தின் நிதியைக் கட்டுப்படுத்தும் அமைப்பு உயர் நீதிமன்றம்.","options":[{"id":"A","text":"ii சரி மற்றவை தவறு"},{"id":"B","text":"i தவிர அனைத்தும் சரி"},{"id":"C","text":"அனைத்தும் தவறு"},{"id":"D","text":"iii தவறு i, ii சரி"}],"correctOption":"A","explanation":"ii சரி மற்றவை தவறு","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q80","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"தமிழ்நாட்டின் தற்போதைய ஆளுநர் _______.","options":[{"id":"A","text":"திரு.பன்வாரிலால் புரோகித்"},{"id":"B","text":"திரு.R.N.ரவி"},{"id":"C","text":"திரு.ராம்நாத் கோவிந்த்"},{"id":"D","text":"வெங்கையா நாயுடு"}],"correctOption":"B","explanation":"தமிழ்நாட்டின் தற்போதைய ஆளுநர் திரு.R.N.ரவி.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q81","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"தமிழ்நாட்டின் தற்போதைய முதலமைச்சர் _______.","options":[{"id":"A","text":"திரு.மு.க.ஸ்டாலின்"},{"id":"B","text":"திரு.உதயநிதி ஸ்டாலின்"},{"id":"C","text":"திரு.K.பழனிச்சாமி"},{"id":"D","text":"திரு. ஓ.பன்னீர் செல்வம்"}],"correctOption":"A","explanation":"தமிழ்நாட்டின் தற்போதைய முதலமைச்சர் திரு.மு.க.ஸ்டாலின்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q82","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"சென்னை உயர் நீதிமன்றத்தின் தற்போதைய தலைமை நீதிபதி _______.","options":[{"id":"A","text":"திரு.மீனா குமாரி"},{"id":"B","text":"திரு.கிருபாகரன்"},{"id":"C","text":"திரு. H.A. பாப்பட"},{"id":"D","text":"திரு.சஞ்சீப் பானர்ஜி"}],"correctOption":"D","explanation":"சென்னை உயர் நீதிமன்றத்தின் தற்போதைய தலைமை நீதிபதி திரு.சஞ்சீப் பானர்ஜி.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-16-q83","subject":"SAT_SOCIAL","topic":"Unit 16","questionText":"தமிழ்நாட்டின் தற்போதைய சபாநாயகர் _______.","options":[{"id":"A","text":"திரு.மு.அப்பாவு"},{"id":"B","text":"திரு.D.ஜெயக்குமார்"},{"id":"C","text":"திரு.ப.தனபால்"},{"id":"D","text":"திரு.அன்பில் மகேஷ் பொய்யாமொழி"}],"correctOption":"A","explanation":"தமிழ்நாட்டின் தற்போதைய சபாநாயகர் திரு.மு.அப்பாவு.","marks":1,"negativeMarks":0}]', datetime('now'));
INSERT OR REPLACE INTO unit_bank (key, subject, unit_number, questions, updated_at) VALUES ('SAT_SOCIAL_17', 'SAT_SOCIAL', 17, '[{"id":"unit-satsocial-17-q1","subject":"SAT_SOCIAL","topic":"Unit 17","questionText":"கீழ்க்கண்டவற்றில் அச்சு ஊடகத்தின் கீழ் வருவது எது?","options":[{"id":"A","text":"வானொலி"},{"id":"B","text":"தொலைக்காட்சி"},{"id":"C","text":"செய்தித்தாள்"},{"id":"D","text":"இணையதளம்"}],"correctOption":"C","explanation":"கீழ்க்கண்டவற்றில் அச்சு ஊடகத்தின் கீழ் வருவது செய்தித்தாள் ஆகும்.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-17-q2","subject":"SAT_SOCIAL","topic":"Unit 17","questionText":"கீழ்க்கண்டவற்றில் ஒலிபரப்பு ஊடகம் என்பது ________.","options":[{"id":"A","text":"இதழ்கள்"},{"id":"B","text":"அறிக்கைகள்"},{"id":"C","text":"நாளிதழ்"},{"id":"D","text":"வானொலி"}],"correctOption":"D","explanation":"கீழ்க்கண்டவற்றில் ஒலிபரப்பு ஊடகம் என்பது வானொலி.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-17-q3","subject":"SAT_SOCIAL","topic":"Unit 17","questionText":"உலகினை மக்களின் அருகாமையில் கொண்டு வந்த ஊடகம் ________.","options":[{"id":"A","text":"தட்டச்சு"},{"id":"B","text":"தொலைபேசி"},{"id":"C","text":"தொலைக்காட்சி"},{"id":"D","text":"இவற்றில் ஏதுமில்லை"}],"correctOption":"C","explanation":"உலகினை மக்களின் அருகாமையில் கொண்டு வந்த ஊடகம் தொலைக்காட்சி.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-17-q4","subject":"SAT_SOCIAL","topic":"Unit 17","questionText":"வெகுஜன ஊடகம் என்பது ________.","options":[{"id":"A","text":"வானொலி"},{"id":"B","text":"தொலைக்காட்சி"},{"id":"C","text":"1 மற்றும் 2"},{"id":"D","text":"இவற்றில் ஏதுமில்லை"}],"correctOption":"C","explanation":"வெகுஜன ஊடகம் என்பது 1 மற்றும் 2.","marks":1,"negativeMarks":0},{"id":"unit-satsocial-17-q5","subject":"SAT_SOCIAL","topic":"Unit 17","questionText":"ஊடகம் ஏன் சுதந்திரமாக செயல்பட வேண்டும்?","options":[{"id":"A","text":"நிறைய பணம் ஈட்ட"},{"id":"B","text":"நிறுவனத்தை ஊக்கப்படுத்த"},{"id":"C","text":"நடுநிலையான தகவலை தருவதற்கு"},{"id":"D","text":"இவற்றில் ஏதுமில்லை"}],"correctOption":"